_BOOT_WARNINGS = []


def _cargar_dotenv(ruta: str = ".env") -> None:
    """Carga secretos desde un archivo .env (sin dependencias externas).
    Las variables ya presentes en el entorno (ej. los -e de Docker) mandan."""
    try:
        _p = os.path.join(os.path.dirname(os.path.abspath(__file__)), ruta)
        if not os.path.isfile(_p):
            return
        with open(_p, "r", encoding="utf-8") as _f:
            for _linea in _f:
                _linea = _linea.strip()
                if not _linea or _linea.startswith("#") or "=" not in _linea:
                    continue
                _k, _, _v = _linea.partition("=")
                _k = _k.strip()
                _v = _v.strip().strip('"').strip("'")
                if _k and _k not in os.environ:
                    os.environ[_k] = _v
    except Exception:
        pass


_cargar_dotenv()

