COOKIE_ENCRYPTION_NOTICE = "Las cookies se guardan cifradas y solo el bot puede acceder a su contenido."
_cookie_secret_seed = f"{TOKEN_DISCORD}:{CLAVE_GROQ}:{CLAVE_OPENROUTER}:{os.path.abspath(__file__)}"
COOKIE_FERNET = Fernet(base64.urlsafe_b64encode(hashlib.sha256(_cookie_secret_seed.encode("utf-8", errors="ignore")).digest()))


def _legacy_cookie_b64_to_text(cookie_b64: str) -> str:
    return base64.b64decode(cookie_b64).decode("utf-8", errors="ignore")


def _cookie_text_to_b64(cookie_text: str) -> str:
    return COOKIE_FERNET.encrypt(cookie_text.encode("utf-8", errors="ignore")).decode("utf-8")


def _cookie_b64_to_text(cookie_b64: str) -> str:
    try:
        return COOKIE_FERNET.decrypt(cookie_b64.encode("utf-8")).decode("utf-8", errors="ignore")
    except (InvalidToken, ValueError, TypeError):
        return _legacy_cookie_b64_to_text(cookie_b64)


