DEFAULT_YTDLP_COOKIES = []


def _cargar_ytdlp_cookies():
    """Carga cookies de YouTube desde ytdlp_cookies.json (gitignored)."""
    ruta = os.path.join(PROJECT_ROOT, "ytdlp_cookies.json")
    if not os.path.isfile(ruta):
        return []
    try:
        with open(ruta, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception as e:
        _BOOT_WARNINGS.append(f"No se pudieron cargar ytdlp_cookies.json: {e}")
        return []


DEFAULT_YTDLP_COOKIES = _cargar_ytdlp_cookies()

