# Interceptar print para capturar en buffer
_orig_print = print
def print(*args, **kwargs):
    msg = " ".join(str(a) for a in args)
    console_buffer.append(f"[{datetime.datetime.now().strftime('%H:%M:%S')}] {msg}")
    _orig_print(*args, **kwargs)

