def _console_log(tag: str, message: str, level: str = "INFO", **extra):
    extra_txt = " | ".join(f"{k}={v}" for k, v in extra.items() if v is not None and v != "")
    line = f"[{level}][{tag}] {message}"
    if extra_txt:
        line += f" | {extra_txt}"
    print(line)


def _guild_owner_label(guild: discord.Guild) -> str:
    owner = getattr(guild, "owner", None)
    if owner:
        return f"{owner} (`{owner.id}`)"
    owner_id = getattr(guild, "owner_id", None)
    return f"<@{owner_id}> (`{owner_id}`)" if owner_id else "No disponible"


def _guild_features_text(guild: discord.Guild) -> str:
    features = list(getattr(guild, "features", []) or [])
    if not features:
        return "Sin flags destacadas"
    return ", ".join(features[:8])


def _guild_snapshot(guild: discord.Guild) -> Dict[str, Any]:
    members = guild.member_count or 0
    text_channels = len(getattr(guild, "text_channels", []) or [])
    voice_channels = len(getattr(guild, "voice_channels", []) or [])
    categories = len(getattr(guild, "categories", []) or [])
    roles = max(len(getattr(guild, "roles", []) or []) - 1, 0)
    emojis = len(getattr(guild, "emojis", []) or [])
    stickers = len(getattr(guild, "stickers", []) or [])
    boosts = getattr(guild, "premium_subscription_count", 0) or 0
    boost_tier = getattr(guild, "premium_tier", 0) or 0
    verification = str(getattr(guild, "verification_level", "unknown")).replace("_", " ").title()
    locale = getattr(guild, "preferred_locale", None) or "No definido"
    nsfw_level = str(getattr(guild, "nsfw_level", "unknown")).replace("_", " ").title()
    system_channel = getattr(guild, "system_channel", None)
    rules_channel = getattr(guild, "rules_channel", None)
    public_updates_channel = getattr(guild, "public_updates_channel", None)
    return {
        "members": members,
        "text_channels": text_channels,
        "voice_channels": voice_channels,
        "categories": categories,
        "roles": roles,
        "emojis": emojis,
        "stickers": stickers,
        "boosts": boosts,
        "boost_tier": boost_tier,
        "verification": verification,
        "locale": locale,
        "nsfw_level": nsfw_level,
        "features": _guild_features_text(guild),
        "system_channel": system_channel.mention if system_channel else "No configurado",
        "rules_channel": rules_channel.mention if rules_channel else "No configurado",
        "updates_channel": public_updates_channel.mention if public_updates_channel else "No configurado",
    }

