def _base_datos() -> Dict[str, Any]:
    return {"usuarios": {}, "canales": {}, "servers": {}, "giveaways": {}, "user_prefs": {}, "bot_blacklist": {}, "tiers": {}, "ai_feedback": {}, "ai_runtime": {}, "reputacion": {}}
    # Nota: 'scam_hashes' (lista global anti-estafa) NO va aca a proposito: _normalizar_datos
    # resetea a su default cualquier clave de base que no sea dict. Se maneja lazy en _scam_store.


def _normalizar_datos(datos: Dict[str, Any]) -> Dict[str, Any]:
    base = _base_datos()
    if not isinstance(datos, dict):
        return base
    for key, default_value in base.items():
        if key not in datos or not isinstance(datos[key], dict):
            datos[key] = default_value.copy()
    return datos


def cargar_datos() -> Dict[str, Any]:
    base = _base_datos()
    if not os.path.exists(ARCHIVO_DATOS):
        try:
            datos_sqlite = _normalizar_datos(load_snapshot_from_sqlite(ARCHIVO_SQLITE))
            if any(datos_sqlite.get(section) for section in base):
                with open(ARCHIVO_DATOS, "w", encoding='utf-8') as f:
                    json.dump(datos_sqlite, f, indent=4, ensure_ascii=False)
                print("[DB] JSON restaurado desde SQLite.")
                return datos_sqlite
            with open(ARCHIVO_DATOS, "w", encoding='utf-8') as f:
                json.dump(base, f, indent=4, ensure_ascii=False)
            save_snapshot_to_sqlite(ARCHIVO_SQLITE, base)
            return base
        except Exception as e:
            print(f"[DB] Error crear: {e}")
            return base
    try:
        with open(ARCHIVO_DATOS, "r", encoding='utf-8') as f:
            datos = json.load(f)
        datos = _normalizar_datos(datos)
        return datos
    except json.JSONDecodeError:
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        os.rename(ARCHIVO_DATOS, f"{ARCHIVO_DATOS}.bak_{ts}")
        datos_sqlite = _normalizar_datos(load_snapshot_from_sqlite(ARCHIVO_SQLITE))
        if any(datos_sqlite.get(section) for section in base):
            try:
                with open(ARCHIVO_DATOS, "w", encoding='utf-8') as f:
                    json.dump(datos_sqlite, f, indent=4, ensure_ascii=False)
                print("[DB] JSON corrupto. Backup creado y restaurado desde SQLite.")
                return datos_sqlite
            except Exception as restore_error:
                print(f"[DB] No pude restaurar desde SQLite: {restore_error}")
        print(f"[DB] JSON corrupto. Backup creado.")
        return base
    except Exception as e:
        print(f"[DB] Error lectura: {e}")
        datos_sqlite = _normalizar_datos(load_snapshot_from_sqlite(ARCHIVO_SQLITE))
        if any(datos_sqlite.get(section) for section in base):
            print("[DB] Usando snapshot de SQLite por error de lectura.")
            return datos_sqlite
        return base

def guardar_datos(datos: Dict[str, Any]) -> None:
    datos = _normalizar_datos(datos)
    try:
        tmp = ARCHIVO_DATOS + ".tmp"
        with open(tmp, "w", encoding='utf-8') as f:
            json.dump(datos, f, indent=4, ensure_ascii=False)
        os.replace(tmp, ARCHIVO_DATOS)
    except Exception as e:
        print(f"[DB] Error guardado: {e}")
    try:
        save_snapshot_to_sqlite(ARCHIVO_SQLITE, datos)
    except Exception as e:
        print(f"[DB] Error sync SQLite: {e}")


def _load_runtime_state() -> None:
    global user_prefs, bot_blacklist, kofi_activos, ai_runtime_state
    datos = cargar_datos()
    raw_prefs = datos.get("user_prefs", {})
    raw_blacklist = datos.get("bot_blacklist", {})
    raw_tiers = datos.get("tiers", {})
    user_prefs = {
        int(uid): value for uid, value in raw_prefs.items()
        if str(uid).isdigit() and isinstance(value, dict)
    }
    bot_blacklist = {
        int(uid): value for uid, value in raw_blacklist.items()
        if str(uid).isdigit() and isinstance(value, dict)
    }
    kofi_activos = {
        int(uid): value for uid, value in raw_tiers.items()
        if str(uid).isdigit() and isinstance(value, dict)
    }
    raw_ai = datos.get("ai_runtime", {})
    if isinstance(raw_ai, dict):
        ai_runtime_state.update(raw_ai)
    if ai_runtime_state.get("provider") not in (AI_PROVIDER_OPENROUTER, AI_PROVIDER_GROQ):
        ai_runtime_state["provider"] = AI_PROVIDER_OPENROUTER


def _save_runtime_state() -> None:
    datos = cargar_datos()
    datos["user_prefs"] = {str(uid): prefs for uid, prefs in user_prefs.items() if isinstance(prefs, dict)}
    datos["bot_blacklist"] = {str(uid): info for uid, info in bot_blacklist.items() if isinstance(info, dict)}
    datos["tiers"] = {str(uid): info for uid, info in kofi_activos.items() if isinstance(info, dict)}
    datos["ai_runtime"] = dict(ai_runtime_state)
    guardar_datos(datos)

def get_config(guild_id: int) -> Optional[Dict[str, Any]]:
    datos = cargar_datos()
    cfg = datos["servers"].get(str(guild_id))
    if cfg:
        for k, v in ESTRUCTURA_SERVER.items():
            if k not in cfg:
                cfg[k] = v
    return cfg

def update_server_config(guild_id: int, key: str, value: Any) -> None:
    datos = cargar_datos()
    sid = str(guild_id)
    if sid not in datos["servers"]:
        datos["servers"][sid] = ESTRUCTURA_SERVER.copy()
    for k, v in ESTRUCTURA_SERVER.items():
        if k not in datos["servers"][sid]:
            datos["servers"][sid][k] = v
    datos["servers"][sid][key] = value
    guardar_datos(datos)

