def _es_lenguaje_simple(guild_id) -> bool:
    """True si este server usa lenguaje fácil (default). False si activó lenguaje técnico."""
    try:
        cfg = get_config(guild_id) or {}
        return not cfg.get("lenguaje_tecnico", False)
    except Exception:
        return True


def _simplificar(texto: str, guild_id) -> str:
    """Reemplaza jerga técnica por palabras fáciles si el server usa lenguaje simple."""
    if not texto or not _es_lenguaje_simple(guild_id):
        return texto
    out = texto
    for tec, simple in _GLOSARIO_SIMPLE.items():
        out = re.sub(re.escape(tec), simple, out, flags=re.IGNORECASE)
    return out


def _es_premium_guild(guild) -> bool:
    """True si el servidor es Premium: su dueño tiene un tier de apoyo activo (o es el owner del bot)."""
    try:
        owner_id = getattr(guild, "owner_id", None)
        if owner_id == OWNER_ID:
            return True
        return owner_id in kofi_activos
    except Exception:
        return False


# ==============================================================================
# SISTEMA DE XP / NIVELES (estilo Arcane) - apagado por default
# ==============================================================================
_xp: Dict[int, Dict[int, int]] = {}   # guild_id -> {user_id: xp_total}
_xp_cd: Dict[tuple, float] = {}       # (guild_id, user_id) -> ultimo_ts
_xp_dirty = False


def _xp_to_next(level: int) -> int:
    """XP para pasar de `level` a `level+1` (curva tipo Arcane/Mee6)."""
    return 5 * level * level + 50 * level + 100


def _total_xp_for_level(level: int) -> int:
    total = 0
    for i in range(level):
        total += _xp_to_next(i)
    return total


def _level_from_total(total: int) -> int:
    level, need = 0, 0
    while True:
        step = _xp_to_next(level)
        if total < need + step:
            return level
        need += step
        level += 1
        if level > 1000:
            return level


def _cargar_xp() -> None:
    global _xp
    try:
        raw = cargar_datos().get("xp", {}) or {}
        _xp = {int(g): {int(u): int(v) for u, v in users.items()} for g, users in raw.items()}
    except Exception as e:
        print(f"[XP] No pude cargar: {e}")
        _xp = {}


def _flush_xp() -> None:
    global _xp_dirty
    if not _xp_dirty:
        return
    try:
        datos = cargar_datos()
        datos["xp"] = {str(g): {str(u): v for u, v in users.items()} for g, users in _xp.items()}
        guardar_datos(datos)
        _xp_dirty = False
    except Exception as e:
        print(f"[XP] No pude guardar: {e}")


async def _procesar_xp(msg) -> None:
    """Suma XP por mensaje (con cooldown) y maneja subidas de nivel."""
    global _xp_dirty
    if msg.author.bot or not msg.guild:
        return
    cfg = get_config(msg.guild.id) or {}
    if not cfg.get("sistema_xp"):
        return
    excl = {int(c) for c in cfg.get("xp_canales_excluidos", []) if str(c).isdigit()}
    if msg.channel.id in excl:
        return
    key = (msg.guild.id, msg.author.id)
    now = time.time()
    if now - _xp_cd.get(key, 0) < 60:   # cooldown de 60s como Arcane
        return
    _xp_cd[key] = now
    g = _xp.setdefault(msg.guild.id, {})
    antes = g.get(msg.author.id, 0)
    despues = antes + random.randint(15, 25)
    g[msg.author.id] = despues
    _xp_dirty = True
    if _level_from_total(despues) > _level_from_total(antes):
        await _anunciar_subida_nivel(msg, cfg, _level_from_total(despues))


async def _anunciar_subida_nivel(msg, cfg, nivel: int) -> None:
    rol_dado = None
    rol_id = (cfg.get("xp_roles", {}) or {}).get(str(nivel))
    if rol_id:
        rol = msg.guild.get_role(int(rol_id))
        if rol and rol not in msg.author.roles:
            if _rol_verif_peligroso(rol):
                pass
            else:
                try:
                    await msg.author.add_roles(rol, reason="Recompensa por nivel de XP")
                    rol_dado = rol
                except Exception:
                    pass
    if cfg.get("xp_anuncio", True):
        canal = msg.guild.get_channel(int(cfg["xp_canal"])) if cfg.get("xp_canal") else msg.channel
        try:
            txt = f"🎉 {msg.author.mention} subió al **nivel {nivel}**!"
            if rol_dado:
                txt += f"\n🎁 Ganaste el rol {rol_dado.mention}."
            await canal.send(txt, allowed_mentions=discord.AllowedMentions(users=True, roles=False))
        except Exception:
            pass


def _barra_progreso(actual: int, total: int, segmentos: int = 12) -> str:
    if total <= 0:
        total = 1
    llenos = max(0, min(segmentos, round(actual / total * segmentos)))
    return "🟩" * llenos + "⬛" * (segmentos - llenos) + f"  {int(actual/total*100)}%"


def get_usuario(user_id: int) -> Dict[str, Any]:
    datos = cargar_datos()
    uid = str(user_id)
    if uid not in datos["usuarios"]:
        datos["usuarios"][uid] = ESTRUCTURA_USUARIO.copy()
        guardar_datos(datos)
    user_data = datos["usuarios"][uid]
    for k, v in ESTRUCTURA_USUARIO.items():
        if k not in user_data:
            user_data[k] = v
    return user_data

def update_usuario(user_id: int, key: str, value: Any) -> None:
    datos = cargar_datos()
    uid = str(user_id)
    if uid not in datos["usuarios"]:
        datos["usuarios"][uid] = ESTRUCTURA_USUARIO.copy()
    datos["usuarios"][uid][key] = value
    guardar_datos(datos)

