def get_prefix(bot_instance, message):
    if not message.guild:
        return "l!"
    cfg = get_config(message.guild.id)
    if cfg and cfg.get("prefix"):
        return cfg["prefix"]
    return "l!"


async def obtener_mensaje_referenciado(message: discord.Message) -> Optional[discord.Message]:
    """Obtiene el mensaje citado (fetch si hace falta). Evita fallos cuando solo hay imagen y no hay cache."""
    if not message.reference:
        return None
    ref = message.reference.resolved
    if isinstance(ref, discord.Message):
        return ref
    if message.reference.cached_message:
        return message.reference.cached_message
    try:
        return await message.channel.fetch_message(message.reference.message_id)
    except Exception:
        return None


_cmd_invocation_audit: Dict[int, str] = {}
_uwu_deleted_messages: set[int] = set()

def es_staff(ctx_or_interaction) -> bool:
    if not hasattr(ctx_or_interaction, 'guild') or not ctx_or_interaction.guild:
        return False
    user = getattr(ctx_or_interaction, 'author', None) or getattr(ctx_or_interaction, 'user', None)
    if not user:
        return False
    if user.id == OWNER_ID:
        return True
    if user.id == ctx_or_interaction.guild.owner_id:
        return True
    if user.guild_permissions.administrator:
        return True
    config = get_config(ctx_or_interaction.guild.id)
    if config:
        for rol_id in config.get("roles_staff", []):
            if discord.utils.get(user.roles, id=rol_id) is not None:
                return True
    return False

def server_permitido(guild_id: int) -> bool:
    """La IA y comandos avanzados estan disponibles en todos los servidores (sin l!allow)."""
    return True

def convertir_duracion(s: str) -> Optional[int]:
    if not s:
        return None
    unidades = {'s': 1, 'm': 60, 'h': 3600, 'd': 86400, 'w': 604800}
    if s.isdigit():
        return int(s)
    match = re.match(r'^(\d+)([smhdw])$', s.lower())
    if match:
        return int(match.group(1)) * unidades[match.group(2)]
    return None

def formato_tiempo(segundos: int) -> str:
    if segundos < 60:    return f"{segundos}s"
    elif segundos < 3600: return f"{segundos//60}m {segundos%60}s"
    elif segundos < 86400: return f"{segundos//3600}h {(segundos%3600)//60}m"
    else:                 return f"{segundos//86400}d {(segundos%86400)//3600}h"


def _fix_mojibake_text(value: Any) -> Any:
    if not isinstance(value, str) or not value:
        return value
    text = value
    replacements = {
        "\u00a0": " ",
        "’": "'",
        "“": '"',
        "”": '"',
    }
    for bad, good in replacements.items():
        text = text.replace(bad, good)
    return text


def _clean_embed_payload(value: Any) -> Any:
    if isinstance(value, dict):
        return {k: _clean_embed_payload(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_clean_embed_payload(v) for v in value]
    return _fix_mojibake_text(value)


_orig_embed_to_dict = discord.Embed.to_dict


def _latambot_embed_to_dict(self):
    payload = _orig_embed_to_dict(self)
    return _clean_embed_payload(payload)


discord.Embed.to_dict = _latambot_embed_to_dict

_orig_messageable_send = discord.abc.Messageable.send


async def _latambot_messageable_send(self, *args, **kwargs):
    if args:
        args = list(args)
        if isinstance(args[0], str):
            args[0] = _fix_mojibake_text(args[0])
    if isinstance(kwargs.get("content"), str):
        kwargs["content"] = _fix_mojibake_text(kwargs["content"])
    return await _orig_messageable_send(self, *args, **kwargs)


discord.abc.Messageable.send = _latambot_messageable_send


