def _validate_member_action(ctx, member: discord.Member, action_label: str) -> Optional[str]:
    if member.id == ctx.author.id:
        return f"No puedes {action_label}te a ti mismo."
    if member.id == bot.user.id:
        return f"No voy a dejar que me intentes {action_label}."
    if member.id == ctx.guild.owner_id:
        return f"No puedes {action_label} al owner del servidor."
    if ctx.author.id != ctx.guild.owner_id and ctx.author.top_role <= member.top_role:
        return f"No puedes {action_label} a alguien con un rol igual o superior al tuyo."
    if ctx.guild.me.top_role <= member.top_role:
        return f"Mi rol es demasiado bajo para {action_label} a ese usuario."
    return None


async def _log_staff_action(
    guild: discord.Guild,
    *,
    title: str,
    color,
    actor=None,
    target=None,
    reason: str = "",
    fields: List[tuple[str, str, bool]] = None,
    notify_owner: bool = False,
    tag: str = "ACTION",
):
    embed = _make_embed(f"{EMOJI_ADMIN} {_EMOJI_LIDER_RE.sub('', title or '')}", color=color)
    if guild is not None:
        embed.add_field(name="Servidor", value=f"{guild.name} (`{guild.id}`)", inline=True)
    if actor is not None:
        actor_roles = ""
        try:
            roles = [r.name for r in getattr(actor, "roles", []) if r.name != "@everyone"][-3:]
            if roles:
                actor_roles = f"\nRoles: {', '.join(roles)}"
        except Exception:
            pass
        embed.add_field(name="Staff", value=f"{actor} (`{actor.id}`){actor_roles}", inline=True)
    if target is not None:
        target_label = f"{target} (`{target.id}`)" if hasattr(target, "id") else str(target)
        embed.add_field(name="Objetivo", value=target_label, inline=True)
    if reason:
        embed.add_field(name="Motivo", value=_clip_text(reason, 900), inline=False)
    for name, value, inline in fields or []:
        embed.add_field(name=name, value=_clip_text(str(value), 900), inline=inline)
    _brand_footer(embed, extra=tag)
    await enviar_log(guild, embed)
    _console_log(tag, title, guild_id=guild.id if guild else None, actor=getattr(actor, "id", None), target=getattr(target, "id", None), reason=reason[:120] if reason else "")
    try:
        asyncio.create_task(_pi_archive_post("/v1/archive/log", {"tag": tag, "title": title, "guild_id": guild.id if guild else 0, "actor": getattr(actor, "id", None), "reason": (reason or "")[:500]}))
    except Exception:
        pass
    if notify_owner:
        canal_notif = await _get_notif_channel()
        if canal_notif:
            try:
                await canal_notif.send(embed=embed)
            except Exception as e:
                _console_log("NOTIF_LOG", "No se pudo replicar log al server de notif", level="ERROR", error=e)



