def _is_blacklisted_user(user_id: int) -> bool:
    return user_id != OWNER_ID and user_id in bot_blacklist


def _collapse_repeated_lines(text: str, max_repeat: int = 4) -> str:
    lines = []
    for raw_line in (text or "").splitlines():
        line = raw_line.strip()
        if not line:
            continue
        if len(lines) >= max_repeat and all(prev == line for prev in lines[-max_repeat:]):
            continue
        lines.append(line)
    return "\n".join(lines)


def _sanitize_ai_prompt_text(text: str, max_chars: int = ASK_MAX_CHARS) -> str:
    cleaned = re.sub(r"\s+", " ", (text or "")).strip()
    cleaned = _collapse_repeated_lines(cleaned)
    return cleaned[:max_chars].strip()


FOLLOWUP_HINTS = (
    "y eso", "y si", "entonces", "o sea", "osea", "eso", "eso como", "eso por que",
    "por que", "porque", "como asi", "explica mas", "explicalo mas", "seguí", "sigue",
    "dale mas", "mas detalle", "profundiza", "desarrolla", "amplia", "amplía",
)

INVENTED_TRANSLATION_HINTS = (
    "salchicha", "perro", "perrito", "gato", "gatito", "alien", "robot",
    "fantasma", "pirata", "dragon", "dragón", "meme", "otaku", "turrito",
)

COMMON_LANGUAGE_NAMES = {
    "es", "espanol", "español", "ingles", "inglés", "en", "portugues", "portugués", "pt",
    "frances", "francés", "fr", "aleman", "alemán", "de", "italiano", "it", "japones",
    "japonés", "ja", "coreano", "ko", "chino", "zh", "arabe", "árabe", "ar", "ruso", "ru",
}


def _is_followup_prompt(text: str, *, reply_to_bot: bool = False) -> bool:
    if reply_to_bot:
        return True
    low = (text or "").strip().lower()
    if not low:
        return False
    if len(low.split()) <= 5 and re.search(r"\b(y|eso|entonces|tambien|también|ahi|ahí|asi|así|por que|porque|como)\b", low):
        return True
    return any(hint in low for hint in FOLLOWUP_HINTS)


def _build_ai_messages(ctx_key, user_prompt: str, *, reply_to_bot: bool = False, reply_context: str = "") -> List[Dict[str, str]]:
    history = memoria_contexto.get(ctx_key)
    base: List[Dict[str, str]] = []
    if _is_followup_prompt(user_prompt, reply_to_bot=reply_to_bot) and isinstance(history, list):
        base.extend(history[-4:])
    if reply_context:
        base.append({
            "role": "user",
            "content": (
                "Ten en cuenta este mensaje citado solo si sirve para responder mejor:\n"
                f"{_clip_text(reply_context, 900)}"
            ),
        })
    base.append({"role": "user", "content": user_prompt})
    return base


def _remember_ai_exchange(ctx_key, user_prompt: str, response: str) -> None:
    if ctx_key not in memoria_contexto or not isinstance(memoria_contexto.get(ctx_key), list):
        memoria_contexto[ctx_key] = []
    memoria_contexto[ctx_key].append({"role": "user", "content": _clip_text(user_prompt, 1500)})
    memoria_contexto[ctx_key].append({"role": "assistant", "content": _clip_text(response, 2500)})
    memoria_contexto[ctx_key] = memoria_contexto[ctx_key][-4:]


