def _pick_groq_model(*, imagen_url: str = None, historial_mensajes: List = None) -> str:
    if imagen_url:
        return MODELO_VISION
    for item in (historial_mensajes or [])[-3:]:
        content = item.get("content", "") if isinstance(item, dict) else str(item)
        text = ""
        if isinstance(content, list):
            text = " ".join(
                part.get("text", "")
                for part in content
                if isinstance(part, dict) and part.get("type") == "text"
            )
        else:
            text = str(content)
        if "[usa los emojis:" in text.lower() or _contains_unicode_emoji(text):
            return MODELO_VISION
    return MODELO_PRINCIPAL


def _is_invented_translation_target(idioma: str) -> bool:
    objetivo = re.sub(r"\s+", " ", (idioma or "").strip().lower())
    if not objetivo:
        return False
    if objetivo in COMMON_LANGUAGE_NAMES:
        return False
    return " " in objetivo or any(token in objetivo for token in INVENTED_TRANSLATION_HINTS)


def _make_translation_prompt(idioma: str, texto: str) -> str:
    objetivo = re.sub(r"\s+", " ", (idioma or "").strip())
    if _is_invented_translation_target(objetivo):
        return (
            AI_TASK_PROMPTS["traducir"] + "\n\n"
            f"Convierte el texto a un idioma inventado llamado `{objetivo}`. "
            "Tiene que sonar consistente, jugueton y entendible por contexto, como si existiera de verdad. "
            "No expliques el chiste ni aclares reglas. Responde solo con la version traducida.\n\n"
            f"{texto[:1500]}"
        )
    return (
        AI_TASK_PROMPTS["traducir"] + "\n\n"
        f"Traduce el siguiente texto al {objetivo}. "
        "Conserva tono, estructura y emojis si aportan significado. "
        "Responde solo con la traduccion.\n\n"
        f"{texto[:1500]}"
    )


def _contains_unicode_emoji(text: str) -> bool:
    return bool(re.search(r"[\U0001F300-\U0001FAFF\u2600-\u27BF]", text or ""))


def _build_mentioned_users_hint(users: List[discord.abc.User]) -> str:
    if not users:
        return ""
    parts = []
    for user in users[:8]:
        display = getattr(user, "display_name", None) or getattr(user, "name", "usuario")
        username = getattr(user, "name", display)
        parts.append(f"{display} (@{username})")
    return "Usuarios mencionados: " + ", ".join(parts)


def _append_user_context(prompt: str, users: List[discord.abc.User]) -> str:
    hint = _build_mentioned_users_hint(users)
    if not hint:
        return prompt
    return f"{prompt}\n\n{hint}"


def _store_ai_feedback(*, guild_id: int, user_id: int, question: str, answer: str, useful: bool, note: str = "", source: str = "ask") -> str:
    datos = cargar_datos()
    feedback = datos.get("ai_feedback", {})
    feedback_id = f"{int(time.time() * 1000)}_{user_id}_{random.randint(1000, 9999)}"
    feedback[feedback_id] = {
        "guild_id": guild_id,
        "user_id": user_id,
        "question": _clip_text(question or "", 800),
        "answer": _clip_text(answer or "", 1600),
        "useful": bool(useful),
        "note": _clip_text((note or "").strip(), 400),
        "source": source,
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }
    datos["ai_feedback"] = feedback
    guardar_datos(datos)
    return feedback_id


def _build_ai_feedback_guidance(limit: int = 4) -> str:
    datos = cargar_datos()
    feedback_map = datos.get("ai_feedback", {})
    if not isinstance(feedback_map, dict) or not feedback_map:
        return ""
    items = sorted(
        (item for item in feedback_map.values() if isinstance(item, dict)),
        key=lambda item: item.get("created_at", ""),
        reverse=True,
    )
    negative_notes = []
    for item in items:
        note = (item.get("note") or "").strip()
        if item.get("useful") is False and note:
            negative_notes.append(_clip_text(note, 120))
        if len(negative_notes) >= limit:
            break
    if not negative_notes:
        return ""
    joined = " | ".join(dict.fromkeys(negative_notes))
    return f"Feedback reciente de usuarios sobre respuestas del bot: {joined}. Ajusta la respuesta si aplica."


def _find_banned_word(text: str, banned_words: List[str]) -> Optional[str]:
    spaced_text, compact_text = _banword_forms(text)
    if not spaced_text and not compact_text:
        return None
    for raw_word in banned_words or []:
        spaced_word, compact_word = _banword_forms(raw_word)
        if not compact_word:
            continue
        if spaced_word and spaced_word in spaced_text:
            return raw_word
        if compact_word in compact_text:
            return raw_word
        pattern = r"[^a-z0-9]{0,6}".join(re.escape(ch) for ch in compact_word)
        if re.search(pattern, _banword_normalize(text)):
            return raw_word
    return None


def _detect_bad_ai_request(text: str) -> Optional[str]:
    raw = (text or "").strip()
    low = raw.lower()
    if not low:
        return "No hay nada para responder."
    if len(raw) > ASK_MAX_CHARS:
        return f"Tu mensaje es demasiado largo para la IA. Dejalo en {ASK_MAX_CHARS} caracteres o menos."

    repeat_match = re.search(r"\b(di|dec[ii]|repite|repeti|spam|flood)\b.{0,80}\b((?:\d[\d\s\.,_]*)\d)\b.{0,20}\b(veces|times)\b", low)
    if repeat_match:
        repeat_raw = re.sub(r"[^\d]", "", repeat_match.group(2))
        if repeat_raw.isdigit() and int(repeat_raw) >= 20:
            return "No voy a generar spam ni repetir texto decenas de veces. Pideme una respuesta normal."

    abuse_patterns = [
        r"ignora (todas|estas|las) instrucciones",
        r"olvida (todas|estas|las) instrucciones",
        r"revela (tu|el) prompt",
        r"muestra (tu|el) prompt",
        r"actua como si no tuvieras reglas",
        r"haz mention a todos",
        r"menciona a todos",
        r"escribe solo la misma frase",
    ]
    for pattern in abuse_patterns:
        if re.search(pattern, low):
            return "Ese pedido intenta forzar una salida basura o saltarse reglas. Reformulalo normal y te respondo."
    return None


def _finalize_ai_text(text: str) -> str:
    cleaned = (text or "").strip()
    if not cleaned:
        return ""
    words = re.findall(r"\S+", cleaned.lower())
    if len(words) >= 40:
        unique_ratio = len(set(words)) / max(len(words), 1)
        if unique_ratio < 0.18:
            return "Eso iba a salir repetitivo o inutil, asi que lo corte. Si quieres, reformula la pregunta y te respondo bien."
    return cleaned

async def intentar_escribir(canal):
    try:
        async with canal.typing():
            await asyncio.sleep(0.1)
    except:
        pass

async def enviar_respuesta_inteligente(ctx_or_msg, texto: str, *, question: str = "", user_id: int = 0, guild_id: int = 0, source: str = "ask"):
    """
    Manda la respuesta de la IA.
    - Usa embed para que se vea limpio y no haya footer duplicado.
    - Para Message: responde con reply pero sin citar el contenido previo.
    - Para TextChannel/Context: send normal.
    """
    if not texto:
        return

    # Limpiar el texto de cualquier mencion de usuario que el modelo haya generado
    # (evita que el bot mencione al usuario original en la respuesta)
    import re as _re
    texto = _re.sub(r"<@!?\d+>", "", texto).strip()

    # Construir embed con la respuesta
    embed = discord.Embed(description=texto, color=discord.Color.blurple())
    embed.set_footer(text="LatamBOT | https://ko-fi.com/latambot")
    feedback_view = None
    if user_id and guild_id:
        feedback_view = AIOpinionView(guild_id=guild_id, user_id=user_id, question=question, answer=texto, source=source)

    # Si el texto es muy largo, dividir en campos
    if len(texto) > 4096:
        partes = [texto[i:i+4000] for i in range(0, len(texto), 4000)]
        for idx, parte in enumerate(partes):
            e = discord.Embed(description=parte, color=discord.Color.blurple())
            if idx == len(partes) - 1:
                e.set_footer(text="LatamBOT | https://ko-fi.com/latambot")
            if isinstance(ctx_or_msg, discord.Message):
                if idx == 0:
                    await ctx_or_msg.reply(embed=e, mention_author=False, view=feedback_view)
                else:
                    await ctx_or_msg.channel.send(embed=e)
            elif isinstance(ctx_or_msg, discord.TextChannel):
                await ctx_or_msg.send(embed=e, view=feedback_view if idx == 0 else None)
            else:
                await ctx_or_msg.send(embed=e, view=feedback_view if idx == 0 else None)
            await asyncio.sleep(0.3)
        return

    if isinstance(ctx_or_msg, discord.Message):
        await ctx_or_msg.reply(embed=embed, mention_author=False, view=feedback_view)
    elif isinstance(ctx_or_msg, discord.TextChannel):
        await ctx_or_msg.send(embed=embed, view=feedback_view)
    else:
        await ctx_or_msg.send(embed=embed, view=feedback_view)

# ==============================================================================
# MODLOG - cada sancion es un CASO numerado, consultable y editable
# ==============================================================================
CASO_TIPOS = {
    "warn":      ("⚠️", "Advertencia", COLOR_ADVERTENCIA),
    "timeout":   ("🔇", "Silencio (timeout)", COLOR_ADVERTENCIA),
    "untimeout": ("🔊", "Silencio retirado", COLOR_EXITO),
    "kick":      ("👢", "Expulsion", COLOR_PELIGRO),
    "ban":       ("🔨", "Baneo", COLOR_PELIGRO),
    "unban":     ("🕊️", "Desbaneo", COLOR_EXITO),
    "automod":   ("🤖", "AutoMod", COLOR_ADVERTENCIA),
}


def _casos_guild(datos: Dict[str, Any], guild_id: int) -> Dict[str, Any]:
    return datos.setdefault("casos", {}).setdefault(str(guild_id), {})


def _canal_modlog(guild):
    cfg = get_config(guild.id) or {}
    cid = cfg.get("modlog_canal") or cfg.get("canal_logs")
    return guild.get_channel(int(cid)) if cid else None


def _embed_caso(guild, caso: Dict[str, Any]) -> discord.Embed:
    emoji, etiqueta, color = CASO_TIPOS.get(caso.get("tipo", "warn"), ("📋", "Caso", COLOR_INFO))
    embed = discord.Embed(
        title=f"{emoji} Caso #{caso['numero']} · {etiqueta}",
        color=discord.Color(color),
        timestamp=datetime.datetime.fromisoformat(caso["creado"]),
    )
    embed.add_field(name="Usuario", value=f"<@{caso['usuario']}>\n`{caso['usuario']}`", inline=True)
    embed.add_field(name="Moderador", value=f"<@{caso['moderador']}>", inline=True)
    if caso.get("duracion"):
        embed.add_field(name="Duracion", value=caso["duracion"], inline=True)
    if caso.get("puntos"):
        embed.add_field(name="Puntos", value=f"+{caso['puntos']} (total: {caso.get('puntos_total', '?')})", inline=True)
    embed.add_field(name="Motivo", value=_clip_text(caso.get("motivo") or "Sin motivo", 1000), inline=False)
    if caso.get("editado_por"):
        embed.add_field(
            name="Motivo editado",
            value=f"Por <@{caso['editado_por']}> · <t:{int(datetime.datetime.fromisoformat(caso['editado_en']).timestamp())}:R>",
            inline=False,
        )
    embed.set_footer(text=f"{guild.name} · usa l!caso {caso['numero']} para verlo")
    return embed


async def crear_caso(guild, tipo: str, usuario, moderador, motivo: str = "",
                     duracion: str = "", puntos: int = 0, puntos_total: int = 0) -> Optional[int]:
    """Registra una sancion como caso numerado y la publica en el modlog. Devuelve el nº de caso."""
    cfg = get_config(guild.id) or {}
    if not cfg.get("modlog_activo", True):
        return None
    datos = cargar_datos()
    casos = _casos_guild(datos, guild.id)
    numero = max([int(n) for n in casos.keys()] or [0]) + 1
    caso = {
        "numero": numero,
        "tipo": tipo,
        "usuario": getattr(usuario, "id", usuario),
        "usuario_tag": str(usuario),
        "moderador": getattr(moderador, "id", moderador),
        "motivo": motivo or "Sin motivo",
        "duracion": duracion,
        "puntos": puntos,
        "puntos_total": puntos_total,
        "creado": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        "mensaje_id": None,
        "editado_por": None,
        "editado_en": None,
    }
    casos[str(numero)] = caso
    guardar_datos(datos)

    canal = _canal_modlog(guild)
    if canal and canal.permissions_for(guild.me).send_messages:
        try:
            msg = await canal.send(embed=_embed_caso(guild, caso))
            datos = cargar_datos()
            _casos_guild(datos, guild.id)[str(numero)]["mensaje_id"] = msg.id
            guardar_datos(datos)
        except Exception as e:
            print(f"[MODLOG] No pude publicar el caso #{numero}: {e}")
    return numero


async def _refrescar_caso(guild, caso: Dict[str, Any]) -> None:
    """Reedita el embed del caso en el modlog cuando cambia (ej: motivo editado)."""
    if not caso.get("mensaje_id"):
        return
    canal = _canal_modlog(guild)
    if not canal:
        return
    try:
        msg = await canal.fetch_message(int(caso["mensaje_id"]))
        await msg.edit(embed=_embed_caso(guild, caso))
    except Exception:
        pass


# ── Warns con PUNTOS + acciones automaticas por umbral ────────────────────────
def _warn_data(datos: Dict[str, Any], guild_id: int, user_id: int) -> Dict[str, Any]:
    g = datos.setdefault("warns", {}).setdefault(str(guild_id), {})
    return g.setdefault(str(user_id), {"puntos": 0, "historial": []})


def _warn_puntos_vigentes(cfg: Dict[str, Any], data: Dict[str, Any]) -> int:
    """Suma los puntos que no caducaron (warn_expira_dias; 0 = nunca caducan)."""
    dias = int(cfg.get("warn_expira_dias", 0) or 0)
    if dias <= 0:
        return int(data.get("puntos", 0) or 0)
    limite = time.time() - dias * 86400
    total = 0
    for h in data.get("historial", []):
        try:
            ts = datetime.datetime.fromisoformat(h["fecha"]).timestamp()
        except Exception:
            continue
        if ts >= limite:
            total += int(h.get("puntos", 0) or 0)
    return total


async def aplicar_warn(guild, usuario, moderador, motivo: str, puntos: Optional[int] = None):
    """Suma puntos, crea el caso y dispara la accion automatica si cruza un umbral.
    Devuelve (puntos_total, texto_accion_aplicada)."""
    cfg = get_config(guild.id) or {}
    if puntos is None:
        # Motivo predefinido con puntos fijos (l!warnmotivo), si existe
        puntos = int((cfg.get("warn_motivos") or {}).get((motivo or "").strip().lower(),
                                                          cfg.get("warn_puntos_default", 1)) or 1)
    puntos = max(1, min(100, int(puntos)))

    datos = cargar_datos()
    data = _warn_data(datos, guild.id, usuario.id)
    data["puntos"] = int(data.get("puntos", 0) or 0) + puntos
    data["historial"].append({
        "puntos": puntos,
        "motivo": motivo or "Sin motivo",
        "moderador": moderador.id,
        "fecha": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    })
    data["historial"] = data["historial"][-50:]
    guardar_datos(datos)
    total = _warn_puntos_vigentes(cfg, data)

    await crear_caso(guild, "warn", usuario, moderador, motivo, puntos=puntos, puntos_total=total)

    # Accion automatica: se aplica la del umbral mas alto que el usuario haya cruzado
    accion_txt = ""
    acciones = sorted(
        [a for a in (cfg.get("warn_acciones") or []) if int(a.get("puntos", 0)) <= total],
        key=lambda a: int(a.get("puntos", 0)),
        reverse=True,
    )
    if acciones:
        act = acciones[0]
        tipo = (act.get("accion") or "").lower()
        try:
            if tipo == "timeout":
                mins = int(act.get("minutos", 60) or 60)
                await usuario.timeout(datetime.timedelta(minutes=mins), reason=f"Auto: {total} puntos de warn")
                accion_txt = f"🔇 Silenciado {mins} min (llegó a {total} puntos)"
                await crear_caso(guild, "timeout", usuario, bot.user, f"Automatico: {total} puntos de warn", duracion=f"{mins} min")
            elif tipo == "kick":
                await usuario.kick(reason=f"Auto: {total} puntos de warn")
                accion_txt = f"👢 Expulsado (llegó a {total} puntos)"
                await crear_caso(guild, "kick", usuario, bot.user, f"Automatico: {total} puntos de warn")
            elif tipo == "ban":
                await usuario.ban(reason=f"Auto: {total} puntos de warn", delete_message_days=0)
                accion_txt = f"🔨 Baneado (llegó a {total} puntos)"
                await crear_caso(guild, "ban", usuario, bot.user, f"Automatico: {total} puntos de warn")
        except discord.Forbidden:
            accion_txt = "⚠️ No pude aplicar la sancion automatica (permisos/jerarquia)."
        except Exception as e:
            accion_txt = f"⚠️ Error en la sancion automatica: {_safe_exc_text(e)}"

    try:
        emb = discord.Embed(
            title=f"Advertencia en {guild.name}",
            description=f"**Motivo:** {motivo or 'Sin motivo'}",
            color=discord.Color(COLOR_ADVERTENCIA),
        )
        emb.add_field(name="Puntos de esta advertencia", value=f"+{puntos}", inline=True)
        emb.add_field(name="Total acumulado", value=str(total), inline=True)
        if accion_txt:
            emb.add_field(name="Sancion aplicada", value=accion_txt, inline=False)
        await usuario.send(embed=emb)
    except Exception:
        pass

    return total, accion_txt


async def registrar_infraccion(guild, usuario, motivo: str):
    d = cargar_datos()
    uid = str(usuario.id)
    if uid not in d["usuarios"]:
        d["usuarios"][uid] = ESTRUCTURA_USUARIO.copy()
    d["usuarios"][uid]["warns"] = d["usuarios"][uid].get("warns", 0) + 1
    total = d["usuarios"][uid]["warns"]
    guardar_datos(d)
    accion_extra = ""
    if total >= 5:
        try:
            await usuario.timeout(datetime.timedelta(days=3), reason="AutoMod: 5 warns")
            accion_extra = "\nSancion Automatica: Silenciado 3 dias."
        except Exception as e:
            accion_extra = f"\nError sancion: {e}"
    try:
        embed_dm = discord.Embed(title=f"Advertencia en {guild.name}", color=discord.Color.orange())
        embed_dm.add_field(name="Razon", value=motivo)
        embed_dm.add_field(name="Total Warns", value=str(total))
        await usuario.send(embed=embed_dm)
    except:
        pass
    return total, accion_extra


# ── AutoMod: filtro de palabras con rapidfuzz (anti-evasión) ────────────────
def _normalizar_texto(t: str) -> str:
    """minúsculas + sin acentos + colapsa separadores y repeticiones (b.a.d / b a d / baaad → bad)."""
    t = unicodedata.normalize("NFKD", t or "").encode("ascii", "ignore").decode("ascii").lower()
    t = re.sub(r"[^a-z0-9]+", "", t)          # saca espacios/puntos/guiones entre letras
    t = re.sub(r"(.)\1{2,}", r"\1", t)         # colapsa 3+ repeticiones (puuuta → puta)
    return t


def _detectar_palabra_prohibida(texto: str, bloqueadas):
    """Devuelve la palabra prohibida detectada (o None). Atrapa evasiones con rapidfuzz."""
    if not bloqueadas or not texto or _rfuzz is None:
        return None
    compacto = _normalizar_texto(texto)
    if not compacto:
        return None
    for mala in bloqueadas:
        m = _normalizar_texto(mala)
        if not m:
            continue
        if m in compacto:
            return mala
        if len(m) >= 4 and _rfuzz.partial_ratio(m, compacto) >= 88:
            return mala
    return None


# ── Utilidades de formato (humanize) ────────────────────────────────────────
def _h_numero(n) -> str:
    """1234567 → '1,2 millones' (o fallback con separador de miles)."""
    try:
        if _humanize is not None and abs(int(n)) >= 1_000_000:
            return _humanize.intword(int(n))
        return f"{int(n):,}".replace(",", ".")
    except Exception:
        return str(n)


def _h_tiempo(dt) -> str:
    """datetime → 'hace 3 horas' (naturaltime); fallback al formato relativo de Discord."""
    try:
        if _humanize is not None:
            ahora = datetime.datetime.now(dt.tzinfo) if dt.tzinfo else datetime.datetime.now()
            return _humanize.naturaltime(ahora - dt)
    except Exception:
        pass
    try:
        return discord.utils.format_dt(dt, "R")
    except Exception:
        return str(dt)


async def enviar_log(guild, embed: discord.Embed):
    if not guild:
        return False
    cfg = get_config(guild.id)
    if not (cfg and cfg.get("canal_logs")):
        return False
    canal = guild.get_channel(cfg["canal_logs"])
    if not canal:
        _console_log("GUILD_LOG", "Canal de logs configurado pero no encontrado", level="ERROR", guild_id=guild.id, channel_id=cfg.get("canal_logs"))
        return False
    perms = canal.permissions_for(guild.me)
    if not perms.send_messages or not perms.embed_links:
        _console_log("GUILD_LOG", "Sin permisos para enviar logs", level="ERROR", guild_id=guild.id, channel_id=canal.id, send_messages=perms.send_messages, embed_links=perms.embed_links)
        return False
    try:
        payload = embed.copy()
        if not payload.timestamp:
            payload.timestamp = datetime.datetime.now(datetime.timezone.utc)
        if not payload.footer or not payload.footer.text:
            payload.set_footer(text=f"{guild.name} | Guild ID {guild.id}")
        title_low = (payload.title or "").lower()
        burst_titles = ("mute", "silenciado", "desmuteado", "timeout")
        if any(token in title_low for token in burst_titles):
            key = (guild.id, payload.title or "Log")
            now_ts = time.time()
            summary_parts = []
            for field in payload.fields[:5]:
                summary_parts.append(f"**{field.name}:** {field.value}")
            if payload.description:
                summary_parts.insert(0, payload.description)
            entry = _clip_text(" | ".join(str(x).replace("\n", " ") for x in summary_parts if x), 900)
            buf = _guild_log_burst_buffer.get(key)
            if buf and now_ts - buf.get("updated", 0) <= LOG_BURST_SECONDS and buf.get("count", 0) < LOG_BURST_MAX:
                buf["count"] += 1
                buf["updated"] = now_ts
                buf["entries"].append(entry)
                try:
                    old = await canal.fetch_message(buf["message_id"])
                    merged = discord.Embed(
                        title=f"{payload.title} ({buf['count']} eventos)",
                        description="\n".join(f"`{idx}.` {line}" for idx, line in enumerate(buf["entries"], start=1))[:3900],
                        color=payload.color,
                        timestamp=datetime.datetime.now(datetime.timezone.utc),
                    )
                    merged.set_footer(text=f"{guild.name} | logs agrupados por actividad repetida")
                    await old.edit(embed=merged)
                    return True
                except Exception:
                    _guild_log_burst_buffer.pop(key, None)
            msg = await canal.send(embed=payload)
            _guild_log_burst_buffer[key] = {"message_id": msg.id, "updated": now_ts, "count": 1, "entries": [entry]}
            return True
        await canal.send(embed=payload)
        return True
    except Exception as e:
        _console_log("GUILD_LOG", "No pude enviar el log al canal del servidor", level="ERROR", guild_id=guild.id, channel_id=canal.id, error=e)
        return False

async def refrescar_sticky(canal):
    """Reenvía el sticky al fondo del canal cada vez que alguien escribe."""
    cid = canal.id
    if cid not in sticky_contenido:
        return
    # Borrar el sticky anterior silenciosamente
    if cid in sticky_mensajes:
        try:
            old_msg = await canal.fetch_message(sticky_mensajes[cid])
            await old_msg.delete()
        except:
            pass
        sticky_mensajes.pop(cid, None)
    # Construir embed mejorado
    data = sticky_contenido[cid]
    titulo = data.get("titulo", "Mensaje fijado") if isinstance(data, dict) else "Mensaje fijado"
    texto  = data.get("texto", data) if isinstance(data, dict) else data
    color  = data.get("color", discord.Color.yellow().value) if isinstance(data, dict) else discord.Color.yellow().value
    embed = discord.Embed(
        title=f"📌  {titulo}",
        description=texto,
        color=discord.Color(color)
    )
    embed.set_footer(text="📌 Mensaje fijado | LatamBOT")
    nuevo = await canal.send(embed=embed)
    sticky_mensajes[cid] = nuevo.id

