async def _raid_castigar(member, channel, guild, motivo: str, detalle: str = "") -> bool:
    """Escalado anti-raid (estilo DustyBot): la 1ª ofensa solo avisa; al reincidir
    (>= raid_max_ofensas en 5 min) se silencia con timeout. Devuelve True si silenció."""
    cfg = get_config(guild.id) or {}
    ahora = time.time()
    dq = _raid_ofensas[guild.id][member.id]
    dq[:] = [t for t in dq if ahora - t < RAID_VENTANA_OFENSAS]
    dq.append(ahora)
    maxof = max(1, int(cfg.get("raid_max_ofensas", 2) or 2))
    mins = max(1, int(cfg.get("raid_mute_min", 10) or 10))
    castigar = len(dq) >= maxof
    if castigar:
        dq.clear()
        try:
            await member.timeout(datetime.timedelta(minutes=mins), reason=f"AutoMod raid: {motivo}")
        except Exception:
            pass
    try:
        if castigar:
            await channel.send(f"🛡️ {member.mention} silenciado {mins} min por **{motivo}** (reincidencia).", delete_after=10)
        else:
            await channel.send(f"⚠️ {member.mention} - **{motivo}**. Si seguís, te silencio.", delete_after=8)
    except Exception:
        pass
    try:
        await registrar_infraccion(guild, member, f"AutoMod: {motivo}")
        embed = discord.Embed(
            title="🛡️ Anti-raid · " + ("silenciado" if castigar else "aviso"),
            color=discord.Color.red() if castigar else discord.Color.orange(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.add_field(name="Usuario", value=f"{member} (`{member.id}`)", inline=True)
        embed.add_field(name="Canal", value=getattr(channel, "mention", str(channel)), inline=True)
        embed.add_field(name="Motivo", value=motivo + (f"\n{detalle}" if detalle else ""), inline=False)
        embed.add_field(name="Acción", value=(f"Timeout {mins} min") if castigar else "Aviso (1ª ofensa)", inline=True)
        await enviar_log(guild, embed)
    except Exception:
        pass
    return castigar


async def check_spam(msg) -> bool:
    cfg = get_config(msg.guild.id)
    if not cfg or not cfg.get("sistema_antispam", True):
        return False
    if es_staff(msg):
        return False
    ahora = time.time()
    gid, uid = msg.guild.id, msg.author.id
    _cfg_spam = get_config(gid) or {}
    _umbral = _cfg_spam.get("antispam_umbral", SPAM_THRESHOLD)
    _ventana = _cfg_spam.get("antispam_ventana", SPAM_WINDOW)
    spam_tracker[gid][uid] = [t for t in spam_tracker[gid][uid] if ahora - t < _ventana]
    spam_tracker[gid][uid].append(ahora)
    if len(spam_tracker[gid][uid]) >= _umbral:
        spam_tracker[gid][uid].clear()
        try:
            await msg.delete()
        except Exception:
            pass
        # escalado gradual: 1ª vez avisa, reincidencia = timeout
        await _raid_castigar(msg.author, msg.channel, msg.guild, "spam", f"{_umbral}+ mensajes en {_ventana}s")
        return True
    return False

