def _check_admin(interaction: discord.Interaction) -> bool:
    """Verifica si el usuario puede usar el dashboard de setup.
    Acepta: owner del bot, owner del server, administrador, manage_guild, o rol de staff configurado."""
    user = interaction.user
    if user.id == OWNER_ID:
        return True
    if not interaction.guild:
        return False
    if user.id == interaction.guild.owner_id:
        return True
    if user.guild_permissions.administrator or user.guild_permissions.manage_guild:
        return True
    cfg = get_config(interaction.guild_id)
    if cfg:
        for rol_id in cfg.get("roles_staff", []):
            if discord.utils.get(user.roles, id=rol_id) is not None:
                return True
    return False


def _check_admin_ctx(ctx) -> bool:
    """Version de _check_admin para comandos de texto (ctx en vez de interaction)."""
    if ctx.author.id == OWNER_ID:
        return True
    if not ctx.guild:
        return False
    if ctx.author.id == ctx.guild.owner_id:
        return True
    if ctx.author.guild_permissions.administrator or ctx.author.guild_permissions.manage_guild:
        return True
    cfg = get_config(ctx.guild.id)
    if cfg:
        for rol_id in cfg.get("roles_staff", []):
            if discord.utils.get(ctx.author.roles, id=rol_id) is not None:
                return True
    return False

def _estado(val) -> str:
    return "✅" if val else "❌"

def _canal_fmt(val) -> str:
    return f"<#{val}>" if val else "`-`"

def _rol_fmt(val) -> str:
    return f"<@&{val}>" if val else "`-`"

def _hex_color(value: str, fallback: tuple[int, int, int]) -> tuple[int, int, int]:
    raw = (value or "").strip().lstrip("#")
    if len(raw) != 6 or not re.fullmatch(r"[0-9a-fA-F]{6}", raw):
        return fallback
    return tuple(int(raw[i:i + 2], 16) for i in (0, 2, 4))


def _welcome_text(template: str, member: discord.Member) -> str:
    return (template or "").replace("{user}", member.display_name).replace("{server}", member.guild.name).replace("{count}", str(member.guild.member_count))


async def _member_avatar_image(member: discord.Member, size: int = 192) -> Image.Image:
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(str(member.display_avatar.with_size(256).with_format("png").url), timeout=aiohttp.ClientTimeout(total=8)) as resp:
                data = await resp.read()
        avatar = Image.open(io.BytesIO(data)).convert("RGBA")
    except Exception:
        avatar = Image.new("RGBA", (size, size), (88, 101, 242, 255))
    avatar = ImageOps.fit(avatar, (size, size))
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    avatar.putalpha(mask)
    return avatar


def _font(size: int, bold: bool = False) -> ImageFont.FreeTypeFont:
    candidates = [
        "arialbd.ttf" if bold else "arial.ttf",
        "DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
    ]
    for path in candidates:
        try:
            return ImageFont.truetype(path, size)
        except Exception:
            continue
    return ImageFont.load_default()


def _fit_text(draw: ImageDraw.ImageDraw, text: str, max_width: int, start_size: int, *, bold: bool = False) -> ImageFont.FreeTypeFont:
    size = start_size
    while size > 18:
        font = _font(size, bold=bold)
        bbox = draw.textbbox((0, 0), text, font=font)
        if bbox[2] - bbox[0] <= max_width:
            return font
        size -= 2
    return _font(size, bold=bold)


async def _build_welcome_image_bytes(member: discord.Member, cfg: Dict[str, Any]) -> io.BytesIO:
    width, height = 1000, 360
    bg = _hex_color(cfg.get("bienvenida_color_fondo"), (32, 36, 58))
    text_color = _hex_color(cfg.get("bienvenida_color_texto"), (255, 255, 255))
    accent = _hex_color(cfg.get("bienvenida_color_acento"), (88, 101, 242))
    img = Image.new("RGB", (width, height), bg)
    draw = ImageDraw.Draw(img)
    for x in range(width):
        ratio = x / max(width - 1, 1)
        color = tuple(int(bg[i] * (1 - ratio) + accent[i] * ratio * 0.45) for i in range(3))
        draw.line((x, 0, x, height), fill=color)
    draw.rounded_rectangle((28, 28, width - 28, height - 28), radius=28, outline=accent, width=4)
    avatar = await _member_avatar_image(member)
    img.paste(avatar, (64, 84), avatar)
    draw.ellipse((56, 76, 264, 284), outline=accent, width=6)
    title = _welcome_text(cfg.get("bienvenida_titulo", "Bienvenido/a {user}"), member)
    subtitle = _welcome_text(cfg.get("bienvenida_subtitulo", "Ya somos {count} en {server}"), member)
    title_font = _fit_text(draw, title, 650, 54, bold=True)
    subtitle_font = _fit_text(draw, subtitle, 650, 34)
    draw.text((310, 112), title, font=title_font, fill=text_color)
    draw.text((312, 188), subtitle, font=subtitle_font, fill=(230, 233, 255))
    draw.text((312, 250), member.guild.name, font=_font(24, bold=True), fill=accent)
    out = io.BytesIO()
    img.save(out, format="PNG", optimize=True)
    out.seek(0)
    return out


async def _send_honeypot_warning(channel: discord.TextChannel) -> None:
    """Mensaje para HUMANOS: explica que es una trampa anti-estafa (transparencia).
    El nombre y el topic del canal quedan disimulados aparte, que es lo que evita
    que los bots de estafa lo detecten (escanean nombre/topic, no leen los mensajes)."""
    embed = _make_embed(
        f"{EMOJI_ADMIN} Canal anti-estafa - no escribir",
        "Este canal es una **trampa contra bots de estafa** 🪤.\n\n"
        "Si sos una **persona real**, no escribas acá: los bots o cuentas que spammeen "
        "en este canal se **banean automáticamente**.\n\n"
        "Gracias por ayudar a mantener el servidor seguro. 💚",
        COLOR_PRIMARIO,
    )
    try:
        msg = await channel.send(embed=embed)
        try:
            await msg.pin()
        except Exception:
            pass
    except Exception as e:
        _console_log("HONEYPOT", "No pude publicar el aviso anti-estafa", level="ERROR", guild_id=channel.guild.id, channel_id=channel.id, error=e)


def _es_sospechoso_raid(member: discord.Member) -> bool:
    """Heurística: ¿la cuenta parece un raider/bot de estafa? (cuenta nueva, sin roles o recién entrada)."""
    try:
        ahora = datetime.datetime.now(datetime.timezone.utc)
        edad_cuenta = (ahora - member.created_at).days
        sin_roles = len([r for r in member.roles if not r.is_default()]) == 0
        joined = member.joined_at or member.created_at
        recien_entro = (ahora - joined).total_seconds() < 3600  # < 1h en el server
        return edad_cuenta < 14 or (sin_roles and recien_entro)
    except Exception:
        return True  # ante la duda, tratarlo como sospechoso (es un honeypot)


async def _ban_honeypot_member(guild: discord.Guild, member: discord.Member) -> None:
    try:
        await guild.ban(member, reason="Honeypot anti-estafas: escribio en el canal trampa.", delete_message_seconds=600)
    except TypeError:
        await guild.ban(member, reason="Honeypot anti-estafas: escribio en el canal trampa.", delete_message_days=1)


