# CANALES DE VOZ DE ESTADISTICAS (arriba de todo)
# ──────────────────────────────────────────────────────────────────────────────
STATS_VOICE_DISPONIBLES = {
    "miembros": "👥 Miembros: {humanos}",
    "bots":     "🤖 Bots: {bots}",
    "boosts":   "🚀 Boosts: {boosts}",
    "canales":  "📚 Canales: {canales}",
    "total":    "📊 Total: {total}",
}


def _stats_voice_valores(guild: discord.Guild) -> dict:
    total = guild.member_count or len(guild.members)
    bots = sum(1 for m in guild.members if m.bot)
    return {
        "humanos": max(0, total - bots),
        "bots": bots,
        "boosts": guild.premium_subscription_count or 0,
        "canales": len(guild.channels),
        "total": total,
    }


def _stats_voice_nombres(guild: discord.Guild) -> dict:
    v = _stats_voice_valores(guild)
    return {tipo: plantilla.format(**v) for tipo, plantilla in STATS_VOICE_DISPONIBLES.items()}


async def _refrescar_stats_voice(guild: discord.Guild, cfg: dict) -> None:
    canales = cfg.get("stats_voice_canales", {}) or {}
    if not canales:
        return
    nombres = _stats_voice_nombres(guild)
    for tipo, cid in list(canales.items()):
        ch = guild.get_channel(int(cid)) if cid else None
        if not isinstance(ch, discord.VoiceChannel):
            continue
        nuevo = nombres.get(tipo)
        if nuevo and ch.name != nuevo:
            try:
                await ch.edit(name=nuevo, reason="Actualizacion de stats")
            except Exception:
                pass  # rate limit de Discord (2 edits / 10 min por canal): se reintenta al proximo ciclo


async def _crear_stats_voice(guild: discord.Guild, tipos=None):
    """Crea (o recrea) la categoria + canales de voz de stats arriba de todo. Devuelve (canales, error)."""
    me = guild.me
    if not me.guild_permissions.manage_channels:
        return None, "Me falta el permiso **Gestionar Canales**."
    tipos = [t for t in (tipos or ["miembros", "bots", "boosts"]) if t in STATS_VOICE_DISPONIBLES] or ["miembros"]
    cfg = get_config(guild.id) or {}

    # Borrar canales/categoria previos si existian
    viejos = cfg.get("stats_voice_canales", {}) or {}
    for cid in list(viejos.values()):
        ch = guild.get_channel(int(cid)) if cid else None
        if ch:
            try:
                await ch.delete(reason="Recreando stats de voz")
            except Exception:
                pass
    cat_id = cfg.get("stats_voice_categoria")
    cat_vieja = guild.get_channel(int(cat_id)) if cat_id else None
    if isinstance(cat_vieja, discord.CategoryChannel):
        try:
            await cat_vieja.delete(reason="Recreando stats de voz")
        except Exception:
            pass

    cat = await guild.create_category("📊 Estadísticas", reason="Stats de voz")
    try:
        await cat.edit(position=0)  # arriba de todo
    except Exception:
        pass
    overwrites = {guild.default_role: discord.PermissionOverwrite(connect=False, view_channel=True)}
    nombres = _stats_voice_nombres(guild)
    canales = {}
    for tipo in tipos:
        try:
            ch = await guild.create_voice_channel(nombres.get(tipo, tipo), category=cat, overwrites=overwrites, reason="Stats de voz")
            canales[tipo] = ch.id
        except Exception:
            pass
    update_server_config(guild.id, "stats_voice_categoria", cat.id)
    update_server_config(guild.id, "stats_voice_canales", canales)
    update_server_config(guild.id, "stats_voice_tipos", tipos)
    update_server_config(guild.id, "stats_voice_activa", True)
    return canales, None


async def _eliminar_stats_voice(guild: discord.Guild):
    cfg = get_config(guild.id) or {}
    for cid in list((cfg.get("stats_voice_canales", {}) or {}).values()):
        ch = guild.get_channel(int(cid)) if cid else None
        if ch:
            try:
                await ch.delete(reason="Stats de voz desactivadas")
            except Exception:
                pass
    cat_id = cfg.get("stats_voice_categoria")
    cat = guild.get_channel(int(cat_id)) if cat_id else None
    if isinstance(cat, discord.CategoryChannel):
        try:
            await cat.delete(reason="Stats de voz desactivadas")
        except Exception:
            pass
    update_server_config(guild.id, "stats_voice_canales", {})
    update_server_config(guild.id, "stats_voice_categoria", None)
    update_server_config(guild.id, "stats_voice_activa", False)


