async def _broadcast_deprecacion_staff() -> tuple:
    """Manda el aviso A al canal de staff de cada server. Devuelve (enviados, sin_canal, fallidos)."""
    enviados, sin_canal, fallidos = 0, 0, 0
    for guild in list(bot.guilds):
        cfg = get_config(guild.id) or {}
        cid = cfg.get("canal_staff")
        if not cid:
            sin_canal += 1
            continue
        canal = guild.get_channel(int(cid)) if str(cid).isdigit() else None
        if not canal or not canal.permissions_for(guild.me).send_messages:
            fallidos += 1
            continue
        try:
            await canal.send(embed=_embed_aviso_staff())
            enviados += 1
        except Exception:
            fallidos += 1
        await asyncio.sleep(1.2)  # cortesía anti rate-limit
    return enviados, sin_canal, fallidos


