class AutoConfigSelect(discord.ui.View):
    """Vista con checkboxes para elegir que autoconfigurar."""
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.select(
        cls=discord.ui.Select,
        placeholder="Selecciona que crear (podes elegir varios)...",
        min_values=1,
        max_values=8,
        options=[
            discord.SelectOption(label="Rol Staff (LatamStaff)", value="rol_staff", emoji="👮", description="Crea el rol LatamStaff", default=True),
            discord.SelectOption(label="Categoria + Canal de Logs", value="logs", emoji="📜", description="Crea latam-logs", default=True),
            discord.SelectOption(label="Canal Staff privado", value="canal_staff", emoji="🛡️", description="Crea latam-staff", default=True),
            discord.SelectOption(label="Sistema de Confesiones", value="confesiones", emoji="🤫", description="Crea canales de confesiones", default=True),
            discord.SelectOption(label="Categoria de Tickets", value="tickets", emoji="🎫", description="Crea la categoria tickets", default=True),
            discord.SelectOption(label="Anti-Spam + Logs de Joins", value="sistemas", emoji="🛡️", description="Activa sistemas basicos", default=True),
            discord.SelectOption(label="Canal de Verificacion", value="verificacion", emoji="✅", description="Crea canal y embed de verificacion"),
            discord.SelectOption(label="Canal Honeypot", value="honeypot", emoji="🪤", description="Crea canal trampa anti-estafas con aviso"),
        ]
    )
    async def seleccionar(self, i: discord.Interaction, select: discord.ui.Select):
        pass  # solo registra seleccion

    @discord.ui.button(label="🪄 Configurar Seleccionado", style=discord.ButtonStyle.blurple, row=1)
    async def confirmar(self, i: discord.Interaction, b: discord.ui.Button):
        if not _check_admin(i):
            await i.response.send_message("Solo administradores.", ephemeral=True)
            return
        # Obtener seleccion del select
        selects = [item for item in self.children if isinstance(item, discord.ui.Select)]
        seleccionados = selects[0].values if selects and selects[0].values else []
        await i.response.defer(ephemeral=True)
        await _autoconfigurar(i, set(seleccionados))

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.secondary, row=1)
    async def volver(self, i: discord.Interaction, b: discord.ui.Button):
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))


