class SetupRolModal(discord.ui.Modal):
    def __init__(self, config_key: str, titulo: str, guild_id: int):
        super().__init__(title=titulo)
        self.config_key = config_key
        self.guild_id = guild_id
        self.valor = discord.ui.TextInput(
            label="ID del rol (clic derecho → Copiar ID)",
            placeholder="Ej: 1234567890123456789",
            max_length=25
        )
        self.add_item(self.valor)

    async def on_submit(self, i: discord.Interaction):
        try:
            rol_id = int(self.valor.value.strip())
            rol = i.guild.get_role(rol_id)
            if not rol:
                await i.response.send_message(
                    embed=discord.Embed(description="No encontre ese rol. Verifica el ID.", color=discord.Color(COLOR_PELIGRO)),
                    ephemeral=True
                )
                return
            update_server_config(self.guild_id, self.config_key, rol_id)
            cfg = get_config(self.guild_id) or {}
            await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
            await i.followup.send(
                embed=discord.Embed(description=f"✅ Configurado: {rol.mention}", color=discord.Color(COLOR_EXITO)),
                ephemeral=True
            )
        except ValueError:
            await i.response.send_message(
                embed=discord.Embed(description="ID invalido. Solo numeros.", color=discord.Color(COLOR_PELIGRO)),
                ephemeral=True
            )


