def _build_rol_options(guild, pagina: int = 0, page_size: int = 23):
    """Construye opciones de SelectOption para roles, con paginacion."""
    roles = [r for r in reversed(guild.roles) if r.name != "@everyone"]
    total_pages = max(1, math.ceil(len(roles) / page_size))
    pagina = max(0, min(pagina, total_pages - 1))
    inicio = pagina * page_size
    chunk = roles[inicio:inicio + page_size]
    opciones = [
        discord.SelectOption(
            label=r.name[:90],
            value=str(r.id),
            description=f"{len(r.members)} miembros • pos {r.position}"
        )
        for r in chunk
    ]
    return opciones, total_pages, pagina


class _RolSelectorPaginado(discord.ui.View):
    """Selector de rol con paginacion para servidores grandes."""
    def __init__(self, config_key: str, guild_id: int, guild, pagina: int = 0, multi: bool = False, titulo: str = "Seleccionar Rol"):
        super().__init__(timeout=None)
        self.config_key = config_key
        self.guild_id = guild_id
        self.guild = guild
        self.pagina = pagina
        self.multi = multi
        self.titulo = titulo
        opciones, self.total_pages, self.pagina = _build_rol_options(guild, pagina)
        if opciones:
            sel = discord.ui.Select(
                placeholder=f"Elige el rol... (pag {self.pagina+1}/{self.total_pages})",
                options=opciones,
                min_values=1,
                max_values=min(len(opciones), 5) if multi else 1,
                row=0
            )
            sel.callback = self._on_select
            self.add_item(sel)

    async def _on_select(self, i: discord.Interaction):
        ids = [int(v) for v in i.data["values"]]
        if self.multi:
            cfg = get_config(self.guild_id) or {}
            lista = list(cfg.get(self.config_key, []))
            for rid in ids:
                if rid in lista:
                    lista.remove(rid)
                else:
                    lista.append(rid)
            update_server_config(self.guild_id, self.config_key, lista)
            roles_txt = " ".join(f"<@&{r}>" for r in lista) or "`-`"
            await i.response.send_message(
                embed=discord.Embed(description=f"✅ Roles actualizados:\n{roles_txt}", color=discord.Color(COLOR_EXITO)),
                ephemeral=True
            )
        else:
            rol_id = ids[0]
            update_server_config(self.guild_id, self.config_key, rol_id)
            cfg = get_config(self.guild_id) or {}
            await i.response.edit_message(embed=_setup_embed_principal(cfg, self.guild), view=SetupMainView(owner_id=i.user.id))
            await i.followup.send(
                embed=discord.Embed(description=f"✅ Rol configurado: <@&{rol_id}>", color=discord.Color(COLOR_EXITO)),
                ephemeral=True
            )

    @discord.ui.button(label="◀️ Anterior", style=discord.ButtonStyle.secondary, row=1)
    async def anterior(self, i: discord.Interaction, b):
        if self.pagina <= 0:
            await i.response.defer(); return
        view = _RolSelectorPaginado(self.config_key, self.guild_id, self.guild, self.pagina - 1, self.multi, self.titulo)
        embed = discord.Embed(title=self.titulo, description=f"Pagina {self.pagina}/{view.total_pages}", color=COLOR_PRIMARIO)
        await i.response.edit_message(embed=embed, view=view)

    @discord.ui.button(label="Siguiente ▶️", style=discord.ButtonStyle.secondary, row=1)
    async def siguiente(self, i: discord.Interaction, b):
        if self.pagina >= self.total_pages - 1:
            await i.response.defer(); return
        view = _RolSelectorPaginado(self.config_key, self.guild_id, self.guild, self.pagina + 1, self.multi, self.titulo)
        embed = discord.Embed(title=self.titulo, description=f"Pagina {self.pagina + 2}/{view.total_pages}", color=COLOR_PRIMARIO)
        await i.response.edit_message(embed=embed, view=view)

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.danger, row=1)
    async def volver(self, i: discord.Interaction, b):
        cfg = get_config(self.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, self.guild), view=SetupMainView(owner_id=i.user.id))


