class WelcomeImageModal(discord.ui.Modal):
    def __init__(self, guild_id: int, cfg: Dict[str, Any]):
        super().__init__(title="Imagen de bienvenida")
        self.guild_id = guild_id
        self.titulo = discord.ui.TextInput(label="Titulo", default=cfg.get("bienvenida_titulo", "Bienvenido/a {user}")[:100], max_length=100)
        self.subtitulo = discord.ui.TextInput(label="Subtitulo", default=cfg.get("bienvenida_subtitulo", "Ya somos {count} en {server}")[:100], max_length=120)
        self.fondo = discord.ui.TextInput(label="Color fondo HEX", default=cfg.get("bienvenida_color_fondo", "#20243a")[:7], max_length=7)
        self.texto = discord.ui.TextInput(label="Color texto HEX", default=cfg.get("bienvenida_color_texto", "#ffffff")[:7], max_length=7)
        self.acento = discord.ui.TextInput(label="Color acento HEX", default=cfg.get("bienvenida_color_acento", "#5865F2")[:7], max_length=7)
        for item in (self.titulo, self.subtitulo, self.fondo, self.texto, self.acento):
            self.add_item(item)

    async def on_submit(self, i: discord.Interaction):
        update_server_config(self.guild_id, "bienvenida_titulo", self.titulo.value.strip() or "Bienvenido/a {user}")
        update_server_config(self.guild_id, "bienvenida_subtitulo", self.subtitulo.value.strip() or "Ya somos {count} en {server}")
        update_server_config(self.guild_id, "bienvenida_color_fondo", self.fondo.value.strip() or "#20243a")
        update_server_config(self.guild_id, "bienvenida_color_texto", self.texto.value.strip() or "#ffffff")
        update_server_config(self.guild_id, "bienvenida_color_acento", self.acento.value.strip() or "#5865F2")
        update_server_config(self.guild_id, "bienvenida_imagen_activa", True)
        cfg = get_config(self.guild_id) or {}
        await i.response.edit_message(embed=_embed_bienvenida_info(cfg), view=ConfigBienvenidaView(self.guild_id))


def _embed_bienvenida_info(cfg: Dict[str, Any]) -> discord.Embed:
    embed = discord.Embed(title="Bienvenida y despedida", color=COLOR_INFO)
    embed.add_field(name="Bienvenida", value=f"Canal: {_canal_fmt(cfg.get('bienvenida_canal'))}\nMsg: `{cfg.get('bienvenida_mensaje','-')[:120]}`", inline=False)
    embed.add_field(name="Imagen", value=f"{_estado(cfg.get('bienvenida_imagen_activa'))} Activa\nTitulo: `{cfg.get('bienvenida_titulo','-')[:80]}`\nSubtitulo: `{cfg.get('bienvenida_subtitulo','-')[:80]}`", inline=False)
    embed.add_field(name="Despedida", value=f"Canal: {_canal_fmt(cfg.get('despedida_canal'))}\nMsg: `{cfg.get('despedida_mensaje','-')[:120]}`", inline=False)
    embed.set_footer(text="Variables: {user} {server} {count}")
    return embed


