def _embed_verificacion_info(cfg, guild) -> discord.Embed:
    embed = discord.Embed(title="✅ Verificacion", color=COLOR_EXITO if cfg.get("verificacion_activa") else COLOR_PELIGRO)
    embed.add_field(name="Estado", value=_estado(cfg.get("verificacion_activa")), inline=True)
    embed.add_field(name="Canal", value=_canal_fmt(cfg.get("verificacion_canal")), inline=True)
    embed.add_field(name="Rol", value=_rol_fmt(cfg.get("verificacion_rol")), inline=True)
    embed.add_field(name="Titulo", value=cfg.get("verificacion_titulo", "-"), inline=False)
    embed.add_field(name="Descripcion", value=cfg.get("verificacion_descripcion", "-")[:100], inline=False)
    embed.set_footer(text="Todo se configura desde este panel de setup")
    return embed


# ── HELPERS DE SELECCION ──────────────────────────────────────────────────────

class _RolSelect(discord.ui.Select):
    def __init__(self, config_key: str, guild_id: int, multi: bool, opciones: list):
        self.config_key = config_key
        self.guild_id = guild_id
        self.multi = multi
        super().__init__(
            placeholder="Elige el rol...",
            options=opciones,
            min_values=1,
            max_values=min(len(opciones), 5) if multi else 1,
            row=0
        )

    async def callback(self, i: discord.Interaction):
        ids = [int(v) for v in self.values]
        if self.multi:
            cfg = get_config(self.guild_id) or {}
            lista = list(cfg.get(self.config_key, []))
            for rid in ids:
                if rid not in lista:
                    lista.append(rid)
            update_server_config(self.guild_id, self.config_key, lista)
            roles_txt = " ".join(f"<@&{r}>" for r in lista)
            cfg = get_config(self.guild_id) or {}
            await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
            await i.followup.send(
                embed=discord.Embed(description=f"✅ Roles de staff actualizados:\n{roles_txt}", color=discord.Color(COLOR_EXITO)),
                ephemeral=True
            )
        else:
            update_server_config(self.guild_id, self.config_key, ids[0])
            cfg = get_config(self.guild_id) or {}
            await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
            await i.followup.send(
                embed=discord.Embed(description=f"✅ Rol configurado: <@&{ids[0]}>", color=discord.Color(COLOR_EXITO)),
                ephemeral=True
            )


class _RolSelectView(discord.ui.View):
    def __init__(self, config_key: str, opciones: list, guild_id: int, multi: bool = False):
        super().__init__(timeout=None)
        self.add_item(_RolSelect(config_key, guild_id, multi, opciones))

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.secondary, row=1)
    async def volver(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))


class _SimpleSelect(discord.ui.Select):
    def __init__(self, config_key: str, guild_id: int, opciones: list, placeholder: str):
        self.config_key = config_key
        self.guild_id = guild_id
        super().__init__(placeholder=placeholder, options=opciones, row=0)

    async def callback(self, i: discord.Interaction):
        val = self.values[0]
        update_server_config(self.guild_id, self.config_key, val)
        if self.config_key == "modo" and val == "GEN":
            update_server_config(self.guild_id, "sistema_gen", True)
        cfg = get_config(self.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
        await i.followup.send(
            embed=discord.Embed(description=f"✅ `{self.config_key}` → `{val}`", color=discord.Color(COLOR_EXITO)),
            ephemeral=True
        )


class _SelectSimpleView(discord.ui.View):
    def __init__(self, config_key: str, opciones: list, guild_id: int, placeholder: str = "Elige..."):
        super().__init__(timeout=None)
        self.add_item(_SimpleSelect(config_key, guild_id, opciones, placeholder))

