# ── MAIN SETUP VIEW ───────────────────────────────────────────────────────────

class SetupMainView(discord.ui.View):
    def __init__(self, owner_id: int = None):
        super().__init__(timeout=None)
        self.owner_id = owner_id
        for item in list(self.children):
            label = getattr(item, "label", "") or ""
            if "Autoconfig" in label:
                self.remove_item(item)

    async def interaction_check(self, i: discord.Interaction) -> bool:
        if self.owner_id and i.user.id != self.owner_id:
            await i.response.send_message(
                embed=discord.Embed(
                    description="❌ Solo quien ejecutó `l!setup` puede usar este panel.\nAbrí el tuyo con `l!setup`.",
                    color=discord.Color(COLOR_PELIGRO)
                ),
                ephemeral=True
            )
            return False
        return True

    async def _denied(self, i):
        await i.response.send_message(
            embed=discord.Embed(description="Solo administradores.", color=discord.Color(COLOR_PELIGRO)),
            ephemeral=True
        )

    # Row 0 - accion principal
    @discord.ui.button(label="🪄 Autoconfigurar", style=discord.ButtonStyle.blurple, row=0)
    async def autosetup_btn(self, i: discord.Interaction, b):
        if not _check_admin(i): await self._denied(i); return
        embed = discord.Embed(
            title="🪄 Autoconfiguración",
            description="Selecciona que queres crear/activar y presiona el boton:",
            color=COLOR_PRIMARIO
        )
        await i.response.edit_message(embed=embed, view=AutoConfigSelect())

