def _embed_stats_voice(guild: discord.Guild) -> discord.Embed:
    cfg = get_config(guild.id) or {}
    activa = cfg.get("stats_voice_activa")
    tipos = cfg.get("stats_voice_tipos", ["miembros", "bots", "boosts"])
    v = _stats_voice_valores(guild)
    embed = discord.Embed(
        title="📊 Canales de voz de estadísticas",
        description=(
            "Crea canales de voz **arriba de todo** que muestran estadísticas del server "
            "(se actualizan solos cada ~10 min). Nadie puede conectarse a ellos.\n\n"
            f"**Estado:** {_estado(activa)}\n"
            f"**Mostrando:** {', '.join(tipos) if tipos else '-'}"
        ),
        color=discord.Color(COLOR_PRIMARIO),
    )
    embed.add_field(name="Vista previa", value=(
        f"👥 Miembros: {v['humanos']}\n🤖 Bots: {v['bots']}\n🚀 Boosts: {v['boosts']}\n"
        f"📚 Canales: {v['canales']}\n📊 Total: {v['total']}"
    ), inline=False)
    embed.set_footer(text="Activar = crea los canales | Stats = elegí cuáles mostrar")
    return embed


class ConfigStatsVoiceView(discord.ui.View):
    def __init__(self, guild_id: int):
        super().__init__(timeout=None)
        self.guild_id = guild_id

    @discord.ui.button(label="Activar / Crear", style=discord.ButtonStyle.success, row=0)
    async def activar(self, i: discord.Interaction, b):
        if not _check_admin(i):
            await i.response.send_message("Solo administradores.", ephemeral=True); return
        await i.response.defer()
        cfg = get_config(i.guild_id) or {}
        tipos = cfg.get("stats_voice_tipos", ["miembros", "bots", "boosts"])
        canales, error = await _crear_stats_voice(i.guild, tipos)
        if error:
            await i.followup.send(embed=discord.Embed(description=f"❌ {error}", color=discord.Color(COLOR_PELIGRO)), ephemeral=True)
            return
        await i.edit_original_response(embed=_embed_stats_voice(i.guild), view=ConfigStatsVoiceView(i.guild_id))
        await i.followup.send(embed=discord.Embed(description=f"✅ Creé **{len(canales)}** canales de stats arriba de todo.", color=discord.Color(COLOR_EXITO)), ephemeral=True)

    @discord.ui.button(label="Desactivar / Borrar", style=discord.ButtonStyle.danger, row=0)
    async def desactivar(self, i: discord.Interaction, b):
        if not _check_admin(i):
            await i.response.send_message("Solo administradores.", ephemeral=True); return
        await i.response.defer()
        await _eliminar_stats_voice(i.guild)
        await i.edit_original_response(embed=_embed_stats_voice(i.guild), view=ConfigStatsVoiceView(i.guild_id))
        await i.followup.send(embed=discord.Embed(description="🗑️ Canales de stats eliminados.", color=discord.Color(COLOR_INFO)), ephemeral=True)

    @discord.ui.button(label="Elegir stats", style=discord.ButtonStyle.primary, row=0)
    async def elegir(self, i: discord.Interaction, b):
        if not _check_admin(i):
            await i.response.send_message("Solo administradores.", ephemeral=True); return
        await i.response.send_message(
            embed=discord.Embed(description="Elegí qué estadísticas mostrar y se recrean los canales:", color=discord.Color(COLOR_PRIMARIO)),
            view=_StatsVoiceTipoView(i.guild_id),
            ephemeral=True,
        )

    @discord.ui.button(label="🔄 Refrescar nombres", style=discord.ButtonStyle.secondary, row=1)
    async def refrescar(self, i: discord.Interaction, b):
        await i.response.defer()
        cfg = get_config(i.guild_id) or {}
        if cfg.get("stats_voice_activa"):
            await _refrescar_stats_voice(i.guild, cfg)
        await i.edit_original_response(embed=_embed_stats_voice(i.guild), view=ConfigStatsVoiceView(i.guild_id))

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.secondary, row=1)
    async def volver(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))


class _StatsVoiceTipoView(discord.ui.View):
    def __init__(self, guild_id: int):
        super().__init__(timeout=180)
        self.guild_id = guild_id
        cfg = get_config(guild_id) or {}
        actuales = cfg.get("stats_voice_tipos", ["miembros", "bots", "boosts"])
        opciones = [
            discord.SelectOption(label="Miembros (humanos)", value="miembros", emoji="👥", default="miembros" in actuales),
            discord.SelectOption(label="Bots", value="bots", emoji="🤖", default="bots" in actuales),
            discord.SelectOption(label="Boosts", value="boosts", emoji="🚀", default="boosts" in actuales),
            discord.SelectOption(label="Total de canales", value="canales", emoji="📚", default="canales" in actuales),
            discord.SelectOption(label="Total miembros", value="total", emoji="📊", default="total" in actuales),
        ]
        sel = discord.ui.Select(placeholder="Elegí las stats a mostrar...", options=opciones, min_values=1, max_values=len(opciones))
        sel.callback = self._on_select
        self.add_item(sel)

    async def _on_select(self, i: discord.Interaction):
        tipos = list(i.data.get("values", []))
        update_server_config(self.guild_id, "stats_voice_tipos", tipos)
        await i.response.defer()
        cfg = get_config(self.guild_id) or {}
        if cfg.get("stats_voice_activa"):
            await _crear_stats_voice(i.guild, tipos)  # recrea con los nuevos tipos
        await i.followup.send(
            embed=discord.Embed(description=f"✅ Stats actualizadas: {', '.join(tipos)}", color=discord.Color(COLOR_EXITO)),
            ephemeral=True,
        )


