class ConfigMascotasView(discord.ui.View):
    def __init__(self, guild: discord.Guild):
        super().__init__(timeout=None)
        self.guild = guild

    def _embed(self) -> discord.Embed:
        cfg = get_config(self.guild.id) or {}
        embed = discord.Embed(title="🐾 Mascotas automáticas", color=COLOR_INFO)
        embed.add_field(name="Canal", value=_canal_fmt(cfg.get("canal_mascotas")), inline=True)
        embed.add_field(name="Estado", value="✅ Activado" if cfg.get("sistema_mascotas_auto") else "❌ Desactivado", inline=True)
        embed.add_field(name="Tipo", value=cfg.get("mascotas_tipo", "gatos"), inline=True)
        embed.add_field(name="Intervalo", value=f"{int(cfg.get('mascotas_intervalo_min', 180))} min", inline=True)
        embed.set_footer(text="Usa este panel para elegir canal, tipo y frecuencia.")
        return embed

    @discord.ui.button(label="Activar / Desactivar", style=discord.ButtonStyle.success, row=0)
    async def toggle(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        nuevo = not cfg.get("sistema_mascotas_auto", False)
        update_server_config(i.guild_id, "sistema_mascotas_auto", nuevo)
        if nuevo and not cfg.get("mascotas_ultimo_envio"):
            update_server_config(i.guild_id, "mascotas_ultimo_envio", datetime.datetime.now(datetime.timezone.utc).isoformat())
        await i.response.edit_message(embed=self._embed(), view=self)

    @discord.ui.button(label="Elegir canal", style=discord.ButtonStyle.primary, row=0)
    async def channel(self, i: discord.Interaction, b):
        await i.response.edit_message(
            embed=_build_channel_picker_embed(self.guild, "canal_mascotas", 0),
            view=_ChannelPickerView(self.guild, "canal_mascotas", 0),
        )

    @discord.ui.button(label="Cambiar tipo", style=discord.ButtonStyle.secondary, row=1)
    async def tipo(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        order = ["gatos", "perros", "mix"]
        actual = cfg.get("mascotas_tipo", "gatos")
        nuevo = order[(order.index(actual) + 1) % len(order)] if actual in order else "gatos"
        update_server_config(i.guild_id, "mascotas_tipo", nuevo)
        await i.response.edit_message(embed=self._embed(), view=self)

    @discord.ui.button(label="Cambiar intervalo", style=discord.ButtonStyle.secondary, row=1)
    async def intervalo(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        order = [30, 60, 180, 360, 720, 1440]
        actual = int(cfg.get("mascotas_intervalo_min", 180) or 180)
        nuevo = order[(order.index(actual) + 1) % len(order)] if actual in order else 180
        update_server_config(i.guild_id, "mascotas_intervalo_min", nuevo)
        await i.response.edit_message(embed=self._embed(), view=self)

    @discord.ui.button(label="Enviar prueba", style=discord.ButtonStyle.secondary, row=2)
    async def test(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        channel_id = cfg.get("canal_mascotas")
        canal = i.guild.get_channel(channel_id) if channel_id else None
        if not canal:
            await i.response.send_message(embed=_make_error_embed("Falta canal", "No hay canal de mascotas configurado.", "Elige un canal desde este mismo panel."), ephemeral=True)
            return
        await i.response.defer(ephemeral=True)
        ok = await _send_pet_drop_to_channel(canal, cfg)
        if ok:
            await i.followup.send("Prueba enviada.", ephemeral=True)
        else:
            await i.followup.send(embed=_make_error_embed("No pude enviar la prueba", "Falló la publicación de mascotas.", "Revisa permisos del canal o la conexión a los servicios externos."), ephemeral=True)

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.secondary, row=3)
    async def volver(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))


