def _build_channel_options(guild: discord.Guild, pagina: int = 0, page_size: int = 24):
    canales = sorted(
        guild.text_channels,
        key=lambda c: ((c.category.position if c.category else -1), c.position, c.name.lower())
    )
    total_pages = max(1, math.ceil(len(canales) / page_size)) if canales else 1
    pagina = max(0, min(pagina, total_pages - 1))
    start = pagina * page_size
    chunk = canales[start:start + page_size]
    options = []
    for canal in chunk:
        categoria = canal.category.name[:45] if canal.category else "Sin categoria"
        options.append(discord.SelectOption(label=canal.name[:90], value=str(canal.id), description=categoria))
    return options, total_pages, pagina


def _build_channel_picker_embed(guild: discord.Guild, config_key: str, pagina: int) -> discord.Embed:
    labels = {
        "canal_general": "Canal general",
        "canal_staff": "Canal staff",
        "canal_logs": "Canal de logs",
        "bienvenida_canal": "Canal de bienvenida",
        "despedida_canal": "Canal de despedida",
        "confesion_input": "Input de confesiones",
        "confesion_public": "Confesiones publicas",
        "verificacion_canal": "Canal de verificacion",
        "canal_anuncios_global": "Canal de anuncios global",
        "canal_highlights": "Canal de highlights",
        "canal_mascotas": "Canal de mascotas",
        "honeypot_canal": "Canal honeypot",
    }
    actual = _canal_fmt((get_config(guild.id) or {}).get(config_key))
    embed = discord.Embed(
        title=f"Elegir canal: {labels.get(config_key, config_key)}",
        description="Selecciona un canal de la lista. Si el servidor es grande, cambia de pagina desde aqui mismo.",
        color=COLOR_PRIMARIO,
    )
    embed.add_field(name="Actual", value=actual, inline=False)
    embed.set_footer(text=f"Pagina {pagina + 1}")
    return embed


class _ChannelPickerSelect(discord.ui.Select):
    def __init__(self, guild: discord.Guild, config_key: str, pagina: int = 0):
        self.guild = guild
        self.config_key = config_key
        options, total_pages, pagina = _build_channel_options(guild, pagina)
        self.total_pages = total_pages
        self.pagina = pagina
        super().__init__(
            placeholder=f"Elige un canal (pag {pagina + 1}/{total_pages})",
            options=options or [discord.SelectOption(label="Sin canales", value="0", description="No hay canales de texto")],
            min_values=1,
            max_values=1,
            row=0,
        )
        self.disabled = not bool(options)

    async def callback(self, i: discord.Interaction):
        if not _check_admin(i):
            await i.response.send_message("Solo administradores.", ephemeral=True)
            return
        cid = int(self.values[0])
        if cid <= 0:
            await i.response.send_message("No hay canales disponibles para elegir.", ephemeral=True)
            return
        update_server_config(i.guild_id, self.config_key, cid)
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
        if self.config_key == "honeypot_canal":
            channel = i.guild.get_channel(cid)
            if channel:
                await _send_honeypot_warning(channel)
        await i.followup.send(embed=discord.Embed(description=f"✅ Canal guardado: <#{cid}>", color=discord.Color(COLOR_EXITO)), ephemeral=True)


