class _ModalMencionCanal(discord.ui.Modal, title="Configurar Canal"):
    canal_input = discord.ui.TextInput(
        label="Menciona el canal o pega su ID",
        placeholder="Ej: #general  o  1234567890123456789",
        max_length=100
    )

    def __init__(self, config_key: str, guild_id: int):
        super().__init__()
        self.config_key = config_key
        self.guild_id = guild_id

    async def on_submit(self, i: discord.Interaction):
        valor = self.canal_input.value.strip()
        # Intentar parsear mencion #canal o ID numerico
        canal = None
        import re as _re
        # Formato <#ID>
        m = _re.match(r"<#(\d+)>", valor)
        if m:
            canal = i.guild.get_channel(int(m.group(1)))
        # ID directo
        elif valor.isdigit():
            canal = i.guild.get_channel(int(valor))
        # Nombre con o sin #
        else:
            nombre = valor.lstrip("#").lower()
            canal = discord.utils.find(lambda c: c.name.lower() == nombre, i.guild.text_channels)
        if not canal:
            await i.response.send_message(
                embed=discord.Embed(
                    description=f"❌ No encontre el canal `{valor}`.\nPodes mencionar el canal (#canal), pegar su ID, o escribir su nombre exacto.",
                    color=discord.Color(COLOR_PELIGRO)
                ),
                ephemeral=True
            )
            return
        update_server_config(self.guild_id, self.config_key, canal.id)
        cfg = get_config(self.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))
        if self.config_key == "honeypot_canal":
            await _send_honeypot_warning(canal)
        await i.followup.send(
            embed=discord.Embed(description=f"✅ Canal configurado: {canal.mention}", color=discord.Color(COLOR_EXITO)),
            ephemeral=True
        )

