async def _autoconfigurar(interaction: discord.Interaction, seleccionados: set = None):
    """Autoconfiguracion magica con opciones seleccionables."""
    guild = interaction.guild
    reporte = []
    if seleccionados is None:
        seleccionados = {"rol_staff","logs","canal_staff","confesiones","tickets","sistemas"}

    if "rol_staff" in seleccionados:
        rol_staff = discord.utils.get(guild.roles, name="LatamStaff")
        if not rol_staff:
            try:
                rol_staff = await guild.create_role(name="LatamStaff", color=discord.Color(COLOR_PRIMARIO), hoist=True, mentionable=True)
                reporte.append("✅ Rol `LatamStaff` creado")
            except Exception as e:
                reporte.append(f"❌ Rol: {e}")
        else:
            reporte.append("ℹ️ Rol `LatamStaff` ya existe")
        if rol_staff:
            update_server_config(guild.id, "roles_staff", [rol_staff.id])
    else:
        rol_staff = discord.utils.get(guild.roles, name="LatamStaff")

    overwrites_staff = {
        guild.default_role: discord.PermissionOverwrite(read_messages=False),
        guild.me: discord.PermissionOverwrite(read_messages=True, send_messages=True, embed_links=True),
    }
    if rol_staff:
        overwrites_staff[rol_staff] = discord.PermissionOverwrite(read_messages=True)

    cat_staff = discord.utils.get(guild.categories, name="⚙️ LATAMBOT STAFF")

    if "logs" in seleccionados:
        if not cat_staff:
            cat_staff = await guild.create_category("⚙️ LATAMBOT STAFF", overwrites=overwrites_staff)
            reporte.append("✅ Categoria Staff creada")
        if not discord.utils.get(guild.text_channels, name="latam-logs"):
            c = await guild.create_text_channel("latam-logs", category=cat_staff)
            update_server_config(guild.id, "canal_logs", c.id)
            reporte.append(f"✅ Logs: {c.mention}")

    if "canal_staff" in seleccionados:
        if not cat_staff:
            cat_staff = await guild.create_category("⚙️ LATAMBOT STAFF", overwrites=overwrites_staff)
        if not discord.utils.get(guild.text_channels, name="latam-staff"):
            c = await guild.create_text_channel("latam-staff", category=cat_staff)
            update_server_config(guild.id, "canal_staff", c.id)
            reporte.append(f"✅ Staff Chat: {c.mention}")

    if "confesiones" in seleccionados:
        cat_conf = discord.utils.get(guild.categories, name="🤫 CONFESIONES") or await guild.create_category("🤫 CONFESIONES")
        if not discord.utils.get(guild.text_channels, name="confiesate-aqui"):
            c = await guild.create_text_channel("confiesate-aqui", category=cat_conf)
            update_server_config(guild.id, "confesion_input", c.id)
            reporte.append(f"✅ Input Confesiones: {c.mention}")
        if not discord.utils.get(guild.text_channels, name="confesiones-publicas"):
            c = await guild.create_text_channel("confesiones-publicas", category=cat_conf)
            update_server_config(guild.id, "confesion_public", c.id)
            reporte.append(f"✅ Confesiones Publicas: {c.mention}")

    if "tickets" in seleccionados:
        if not discord.utils.get(guild.categories, name="🎫 TICKETS"):
            cat_t = await guild.create_category("🎫 TICKETS")
            update_server_config(guild.id, "cat_tickets", cat_t.id)
            reporte.append("✅ Categoria Tickets creada")

    if "sistemas" in seleccionados:
        update_server_config(guild.id, "sistema_antispam", True)
        update_server_config(guild.id, "sistema_logs_joins", True)
        reporte.append("✅ Anti-Spam y Logs activados")

    if "verificacion" in seleccionados:
        reporte.append("✅ Verificacion: usa el boton 'Crear Canal+Embed' en la seccion Verificacion")

    if "honeypot" in seleccionados:
        # Canal sigiloso: nombre/topic creíbles (parece de anuncios), NO se delata como trampa
        nombre_hp = random.choice(["avisos-importantes", "novedades-oficial", "info-y-anuncios", "comunicados"])
        canal_hp = discord.utils.get(guild.text_channels, name=nombre_hp)
        if not canal_hp:
            overwrites_hp = {
                guild.default_role: discord.PermissionOverwrite(read_messages=True, send_messages=True),
                guild.me: discord.PermissionOverwrite(read_messages=True, send_messages=True, manage_messages=True),
            }
            canal_hp = await guild.create_text_channel(
                nombre_hp,
                overwrites=overwrites_hp,
                topic="Novedades y anuncios del servidor.",
            )
        update_server_config(guild.id, "honeypot_canal", canal_hp.id)
        await _send_honeypot_warning(canal_hp)
        reporte.append(f"✅ Honeypot: {canal_hp.mention}")

    embed = discord.Embed(
        title="🪄 Autoconfiguración Completada",
        description="\n".join(reporte) if reporte else "Nada seleccionado.",
        color=COLOR_EXITO,
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed.set_footer(text="LatamBOT | Vuelve al dashboard con l!setup")
    await interaction.followup.send(embed=embed, ephemeral=True)


