class RPButtonView(discord.ui.View):
    def __init__(self, accion, autor, victima):
        super().__init__(timeout=None)
        self.accion = accion
        self.autor_original = autor
        self.victima = victima
        self.usado = False

    @discord.ui.button(label="Devolver", style=discord.ButtonStyle.secondary, emoji="↩️")
    async def devolver(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.usado:
            await interaction.response.send_message("Ya se devolvio.", ephemeral=True)
            return
        if interaction.user.id != self.victima.id:
            await interaction.response.send_message("Solo quien la recibio puede devolver!", ephemeral=True)
            return
        self.usado = True
        gif = await _get_rp_gif(self.accion)
        embed = discord.Embed(description=f"{interaction.user.name} le devolvio el {self.accion} a {self.autor_original.name}!", color=discord.Color.teal())
        embed.set_image(url=gif)
        button.disabled = True
        await interaction.response.edit_message(view=self)
        await interaction.followup.send(embed=embed)


class ConfessionReasonModal(discord.ui.Modal, title="Razon del rechazo"):
    razon = discord.ui.TextInput(label="Razon", placeholder="Escribe la razon...", max_length=300)

    def __init__(self, confession_text: str, accion: str, guild_id: int, user_id: int = 0):
        super().__init__()
        self.confession_text = confession_text
        self.accion = accion
        self.guild_id = guild_id
        self.user_id = user_id

    async def on_submit(self, i: discord.Interaction):
        razon_txt = self.razon.value
        cfg = get_config(self.guild_id)
        color_map = {
            "rechazar_razon": discord.Color.orange(),
            "denegar_baneo":  discord.Color.dark_red(),
            "reportar":       discord.Color.red(),
        }
        label_map = {
            "rechazar_razon": "Rechazada con razon",
            "denegar_baneo":  "Denegada y confesarbaneo",
            "reportar":       "Rechazada y reportada",
        }
        embed_result = discord.Embed(
            description=f"**{label_map[self.accion]}** por {i.user.mention}\n**Razon:** {razon_txt}\n\n> {self.confession_text}",
            color=color_map[self.accion]
        )
        if self.accion == "denegar_baneo" and self.user_id:
            # Guardar confesarban con el user_id real (visible solo en el footer del embed)
            gid = i.guild_id
            if gid not in confesion_baneados:
                confesion_baneados[gid] = set()
            confesion_baneados[gid].add(self.user_id)

        if self.accion in ("denegar_baneo", "reportar") and cfg and cfg.get("canal_logs"):
            canal_logs = i.guild.get_channel(cfg["canal_logs"])
            if canal_logs:
                titulo = "🔨 Confesarbaneo Aplicado" if self.accion == "denegar_baneo" else "🚨 Confesion Reportada"
                embed_log = discord.Embed(
                    title=titulo,
                    color=color_map[self.accion],
                    timestamp=datetime.datetime.now(datetime.timezone.utc)
                )
                embed_log.add_field(name="Staff", value=i.user.mention, inline=True)
                embed_log.add_field(name="Razon", value=razon_txt, inline=True)
                embed_log.add_field(name="Contenido", value=self.confession_text[:500], inline=False)
                if self.accion == "denegar_baneo":
                    embed_log.add_field(
                        name="Efecto",
                        value="El usuario NO podra hacer mas confesiones en esta sesion.",
                        inline=False
                    )
                await canal_logs.send(embed=embed_log)
        await i.response.edit_message(embed=embed_result, view=None)


# Contador de confesiones por servidor. Se guarda en la config (`confesion_num`)
# para que la numeracion sobreviva a los reinicios/deploys.
confesion_contador: Dict[int, int] = {}   # cache en memoria (espejo del disco)


def _siguiente_num_confesion(guild_id: int) -> int:
    """Devuelve el proximo numero de confesion y lo persiste en disco."""
    cfg = get_config(guild_id) or {}
    actual = int(cfg.get("confesion_num", 0) or 0)
    # Si en memoria venimos mas adelante (confesiones de esta sesion antes de migrar), respetarlo.
    actual = max(actual, int(confesion_contador.get(guild_id, 0) or 0))
    nuevo = actual + 1
    confesion_contador[guild_id] = nuevo
    try:
        update_server_config(guild_id, "confesion_num", nuevo)
    except Exception as e:
        print(f"[CONFESION] No pude guardar el contador: {e}")
    return nuevo
# Usuarios con confesarban: { guild_id: set(user_id) }
confesion_baneados: Dict[int, set] = {}


class ConfessionReviewView(discord.ui.View):
    def __init__(self, t, uid, numero: int = 0, imagen_url: str = ""):
        super().__init__(timeout=None)
        self.t = t
        self.uid = uid
        self.numero = numero
        self.imagen_url = imagen_url

    def _solo_staff(self, i: discord.Interaction) -> bool:
        if i.user.id == OWNER_ID:
            return True
        if i.user.guild_permissions.administrator:
            return True
        cfg = get_config(i.guild_id)
        if cfg:
            for rol_id in cfg.get("roles_staff", []):
                if discord.utils.get(i.user.roles, id=rol_id):
                    return True
        return False

    @discord.ui.button(label="Aprobar", style=discord.ButtonStyle.green, row=0)
    async def aprobar(self, i: discord.Interaction, b: discord.ui.Button):
        if not self._solo_staff(i):
            await i.response.send_message("Solo el Staff puede revisar confesiones.", ephemeral=True)
            return
        cfg = get_config(i.guild_id)
        if not cfg or not cfg.get("confesion_public"):
            await i.response.send_message("Canal publico no configurado.", ephemeral=True)
            return
        pub = i.guild.get_channel(cfg["confesion_public"])
        if pub:
            num_txt = f" #{self.numero}" if self.numero else ""
            embed_pub = discord.Embed(
                title=f"Confesion Anonima{num_txt}",
                description=self.t,
                color=discord.Color.random()
            )
            if self.imagen_url:
                embed_pub.set_image(url=self.imagen_url)
            embed_pub.set_footer(text="Confesiones | LatamBOT")
            await pub.send(embed=embed_pub, view=ConfessionEntryView())
            embed_result = discord.Embed(
                description=f"**Aprobada** por {i.user.mention}\n\n> {self.t}",
                color=discord.Color.green()
            )
            if self.imagen_url:
                embed_result.set_image(url=self.imagen_url)
            await i.response.edit_message(embed=embed_result, view=None)
        else:
            await i.response.send_message("Canal publico no encontrado.", ephemeral=True)

    @discord.ui.button(label="Rechazar", style=discord.ButtonStyle.red, row=0)
    async def rechazar(self, i: discord.Interaction, b: discord.ui.Button):
        if not self._solo_staff(i):
            await i.response.send_message("Solo el Staff puede revisar confesiones.", ephemeral=True)
            return
        embed_result = discord.Embed(
            description=f"**Rechazada** por {i.user.mention}\n\n> {self.t}",
            color=discord.Color.red()
        )
        await i.response.edit_message(embed=embed_result, view=None)

    @discord.ui.button(label="Rechazar con razonamiento", style=discord.ButtonStyle.secondary, row=0)
    async def rechazar_razon(self, i: discord.Interaction, b: discord.ui.Button):
        if not self._solo_staff(i):
            await i.response.send_message("Solo el Staff puede revisar confesiones.", ephemeral=True)
            return
        await i.response.send_modal(ConfessionReasonModal(self.t, "rechazar_razon", i.guild_id, self.uid))

    @discord.ui.button(label="Denegar y confesarbaneo", style=discord.ButtonStyle.danger, row=1)
    async def denegar_baneo(self, i: discord.Interaction, b: discord.ui.Button):
        if not self._solo_staff(i):
            await i.response.send_message("Solo el Staff puede revisar confesiones.", ephemeral=True)
            return
        await i.response.send_modal(ConfessionReasonModal(self.t, "denegar_baneo", i.guild_id, self.uid))

    @discord.ui.button(label="Rechazar y reportar", style=discord.ButtonStyle.danger, row=1)
    async def rechazar_reportar(self, i: discord.Interaction, b: discord.ui.Button):
        if not self._solo_staff(i):
            await i.response.send_message("Solo el Staff puede revisar confesiones.", ephemeral=True)
            return
        await i.response.send_modal(ConfessionReasonModal(self.t, "reportar", i.guild_id, self.uid))


class GiveawayView(discord.ui.View):
    def __init__(self, giveaway_id: int):
        super().__init__(timeout=None)
        self.giveaway_id = giveaway_id

    @discord.ui.button(label="Participar", style=discord.ButtonStyle.green, custom_id="giveaway_join", emoji="🎉")
    async def participar(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.giveaway_id not in sorteos_activos:
            await interaction.response.send_message("Este sorteo ya termino.", ephemeral=True)
            return
        sorteo = sorteos_activos[self.giveaway_id]
        uid = interaction.user.id
        if uid in sorteo["participantes"]:
            sorteo["participantes"].remove(uid)
            await interaction.response.send_message("Saliste del sorteo.", ephemeral=True)
        else:
            sorteo["participantes"].append(uid)
            await interaction.response.send_message(f"Entraste al sorteo! ({len(sorteo['participantes'])} participantes)", ephemeral=True)


class PollView(discord.ui.View):
    def __init__(self, opciones: List[str], msg_id_ref: int):
        super().__init__(timeout=None)
        self.opciones = opciones
        self.votos: Dict[int, int] = {}
        self.conteo = [0] * len(opciones)
        emojis = ["1️⃣", "2️⃣", "3️⃣", "4️⃣", "5️⃣"]
        for i, opcion in enumerate(opciones[:5]):
            self.add_item(PollButton(i, opcion, emojis[i], self))


class PollButton(discord.ui.Button):
    def __init__(self, idx, opcion, emoji, view_parent):
        super().__init__(label=opcion[:60], emoji=emoji, style=discord.ButtonStyle.secondary)
        self.idx = idx
        self.parent = view_parent

    async def callback(self, interaction: discord.Interaction):
        uid = interaction.user.id
        prev = self.parent.votos.get(uid)
        if prev == self.idx:
            await interaction.response.send_message("Ya votaste por esta opcion.", ephemeral=True)
            return
        if prev is not None:
            self.parent.conteo[prev] -= 1
        self.parent.votos[uid] = self.idx
        self.parent.conteo[self.idx] += 1
        total = sum(self.parent.conteo)
        desc = ""
        for i, op in enumerate(self.parent.opciones):
            pct = (self.parent.conteo[i] / total * 100) if total > 0 else 0
            bar = "█" * int(pct / 10) + "░" * (10 - int(pct / 10))
            desc += f"**{op}**\n`{bar}` {self.parent.conteo[i]} ({pct:.1f}%)\n\n"
        embed = discord.Embed(title="Encuesta en progreso", description=desc, color=discord.Color.blue())
        embed.set_footer(text=f"Total votos: {total}")
        await interaction.response.edit_message(embed=embed)


class TriviaView(discord.ui.View):
    def __init__(self, pregunta_data: dict, autor_id: int):
        super().__init__(timeout=30)
        self.autor_id = autor_id
        self.respondido = False
        self.correcta = pregunta_data["r"]
        ops = list(pregunta_data.get("ops") or [])
        random.shuffle(ops)
        for opcion in ops:
            btn = discord.ui.Button(label=str(opcion)[:80], style=discord.ButtonStyle.secondary)
            btn.callback = self._make_cb(opcion)
            self.add_item(btn)

    def _make_cb(self, op: str):
        async def cb(interaction: discord.Interaction):
            if self.respondido:
                await interaction.response.send_message("Ya respondida.", ephemeral=True)
                return
            self.respondido = True
            if op == self.correcta:
                user_data = get_usuario(interaction.user.id)
                nuevo = user_data.get("monedas", 0) + 50
                update_usuario(interaction.user.id, "monedas", nuevo)
                await interaction.response.edit_message(
                    content=f"✅ Correcto! Respuesta: **{self.correcta}** · +50 monedas",
                    view=None,
                )
            else:
                await interaction.response.edit_message(
                    content=f"❌ Incorrecto. La respuesta era **{self.correcta}**.",
                    view=None,
                )
        return cb


class RulesAcceptView(discord.ui.View):
    def __init__(self, user_id):
        super().__init__(timeout=None)
        self.user_id = user_id

    @discord.ui.button(label="Aceptar Reglas", style=discord.ButtonStyle.green, emoji="✅")
    async def accept(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.user_id:
            await interaction.response.send_message("Solo el dueno del canal puede aceptar.", ephemeral=True)
            return
        await interaction.channel.set_permissions(interaction.user, send_messages=True, read_messages=True)
        button.disabled = True
        button.label = "Reglas Aceptadas"
        await interaction.response.edit_message(view=self)
        await interaction.followup.send("Puedes escribir en tu canal de anuncios!")


class AdRequestView(discord.ui.View):
    def __init__(self, requester: discord.Member):
        super().__init__(timeout=None)
        self.requester = requester

    @discord.ui.button(label="Aprobar", style=discord.ButtonStyle.green, emoji="✅")
    async def approve(self, interaction: discord.Interaction, button: discord.ui.Button):
        guild = interaction.guild
        cfg = get_config(guild.id)
        cat_id = cfg.get("cat_anuncios") if cfg else None
        cat = guild.get_channel(cat_id) if cat_id else discord.utils.get(guild.categories, name="ANUNCIOS USUARIOS")
        if not cat:
            cat = await guild.create_category("ANUNCIOS USUARIOS")
            update_server_config(guild.id, "cat_anuncios", cat.id)
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(send_messages=False),
            self.requester: discord.PermissionOverwrite(read_messages=True, send_messages=False),
            guild.me: discord.PermissionOverwrite(read_messages=True, send_messages=True)
        }
        channel = await guild.create_text_channel(f"anuncios-{self.requester.name}", category=cat, overwrites=overwrites)
        embed_r = discord.Embed(title="Reglas del Canal", color=discord.Color.red(), description="1. No estafas\n2. No NSFW\n3. Sin spam\n4. Respetar ToS Discord\n\n**Acepta para poder escribir.**")
        await channel.send(f"{self.requester.mention} Canal creado!", embed=embed_r, view=RulesAcceptView(self.requester.id))
        await interaction.response.edit_message(content=f"Aprobado por {interaction.user.mention} -> {channel.mention}", view=None, embed=None)

    @discord.ui.button(label="Rechazar", style=discord.ButtonStyle.red, emoji="🚫")
    async def reject(self, interaction: discord.Interaction, button: discord.ui.Button):
        await interaction.response.edit_message(content=f"Rechazado por {interaction.user.mention}.", view=None, embed=None)


