def _build_help_home_embed(prefix: str) -> discord.Embed:
    embed = discord.Embed(
        title="LatamBOT",
        description=(
            f"**Prefix:** `{prefix}`\n"
            f"**Modelo IA:** `{MODELO_PRINCIPAL}`\n"
            f"**Ask:** hasta `{ASK_MAX_CHARS}` caracteres por pedido.\n\n"
            "Abre una categoria desde el menu o usa "
            f"`{prefix}help <comando>` si quieres ver un comando concreto."
        ),
        color=discord.Color(COLOR_PRIMARIO),
    )
    if bot.user and bot.user.avatar:
        embed.set_thumbnail(url=bot.user.avatar.url)
    for category, meta in HELP_CATEGORY_META.items():
        embed.add_field(name=f"{meta['emoji']} {category}", value=meta["intro"], inline=True)
    embed.set_footer(text=f"LatamBOT {BOT_VERSION} | Panel de ayuda")
    return embed


def _build_help_category_embed(category: str, prefix: str, content: str) -> discord.Embed:
    meta = HELP_CATEGORY_META.get(category, {"emoji": "📚", "color": COLOR_PRIMARIO, "intro": "Comandos disponibles."})
    embed = discord.Embed(
        title=f"{meta['emoji']} {category}",
        description=f"{meta['intro']}\n\n{content}",
        color=discord.Color(meta["color"]),
    )
    embed.set_footer(text=f"{prefix}help <comando> | Usa el boton Inicio para volver")
    return embed


