async def tree_global_check(interaction: discord.Interaction) -> bool:
    if interaction.user.id == OWNER_ID:
        return True
    if _is_blacklisted_user(interaction.user.id):
        if not interaction.response.is_done():
            await interaction.response.send_message(
                "No puedes usar LatamBOT desde esta cuenta.",
                ephemeral=True,
        )
        return False
    return True


if hasattr(bot.tree, "check"):
    bot.tree.check(tree_global_check)

