@bot.event
async def on_member_join(member):
    datos = cargar_datos()
    sid = str(member.guild.id)
    cfg = get_config(member.guild.id)
    if not cfg:
        return
    # Roles persistentes: restaurar los roles que tenía al salir
    if cfg.get("roles_persistentes"):
        guardadas = (datos.get("roles_guardados", {}).get(sid, {}) or {}).get(str(member.id))
        if guardadas:
            top = member.guild.me.top_role if member.guild.me else None
            for rid in guardadas:
                rol = member.guild.get_role(rid)
                if rol and not rol.managed and rol != member.guild.default_role and (top is None or rol < top):
                    try:
                        await member.add_roles(rol, reason="Roles persistentes (rejoin)")
                    except Exception:
                        pass
            try:
                datos.get("roles_guardados", {}).get(sid, {}).pop(str(member.id), None)
                guardar_datos(datos)
            except Exception:
                pass
    if cfg.get("autorol_id"):
        rol = member.guild.get_role(cfg["autorol_id"])
        if rol and not _rol_verif_peligroso(rol):
            try:
                await member.add_roles(rol)
            except:
                pass
    if cfg.get("sistema_logs_joins") and cfg.get("bienvenida_canal"):
        canal = member.guild.get_channel(cfg["bienvenida_canal"])
        if canal:
            msg_template = cfg.get("bienvenida_mensaje", "Bienvenido/a {user} al servidor {server}!")
            msg_final = msg_template.replace("{user}", member.mention).replace("{server}", member.guild.name).replace("{count}", str(member.guild.member_count))
            embed = discord.Embed(title=f"{EMOJI_HELLO} ¡Bienvenida!", description=msg_final, color=discord.Color.green())
            embed.set_thumbnail(url=member.display_avatar.url)
            if cfg.get("bienvenida_imagen_activa"):
                try:
                    image = await _build_welcome_image_bytes(member, cfg)
                    embed.set_image(url="attachment://bienvenida.png")
                    await canal.send(embed=embed, file=discord.File(image, filename="bienvenida.png"))
                except Exception as e:
                    _console_log("WELCOME", "No pude generar imagen de bienvenida", level="ERROR", guild_id=member.guild.id, user_id=member.id, error=e)
                    await canal.send(embed=embed)
            else:
                await canal.send(embed=embed)
    # Log avanzado de join
    antiguedad = (datetime.datetime.now(datetime.timezone.utc) - member.created_at).days
    alerta = antiguedad < 7
    color = discord.Color.from_rgb(255, 80, 80) if alerta else discord.Color.green()
    embed_log = discord.Embed(
        title="📥 Nuevo Miembro" + (" ⚠️" if alerta else ""),
        color=color,
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed_log.set_author(name=str(member), icon_url=member.display_avatar.url)
    embed_log.set_thumbnail(url=member.display_avatar.url)
    embed_log.add_field(name="👤 Usuario", value=f"{member.mention}\n`{member} ({member.id})`", inline=True)
    embed_log.add_field(name="📅 Cuenta creada", value=f"<t:{int(member.created_at.timestamp())}:D>\n({antiguedad} dias)", inline=True)
    embed_log.add_field(name="👥 Miembro #", value=str(member.guild.member_count), inline=True)
    if alerta:
        embed_log.add_field(name="⚠️ CUENTA NUEVA", value=f"Cuenta creada hace solo **{antiguedad} dias**. Posible raider/alt.", inline=False)
    if member.bot:
        embed_log.add_field(name="🤖 Bot", value="Este usuario es un bot.", inline=False)
    embed_log.set_footer(text=f"ID: {member.id} | {member.guild.name}")
    await enviar_log(member.guild, embed_log)

    # Reputacion cross-server: si la cuenta tiene antecedentes en la red, avisar al staff
    await _rep_avisar_join(member)

    # ── Auto-borrar invites de l!getinvi ────────────────────────────────────
    codes_a_borrar = [code for code, gid in list(_getinvi_invites.items()) if gid == member.guild.id]
    for code in codes_a_borrar:
        try:
            inv = await member.guild.invites()
            for i in inv:
                if i.code == code:
                    await i.delete()
                    del _getinvi_invites[code]
                    break
        except:
            pass

@bot.event
async def on_member_remove(member):
    cfg = get_config(member.guild.id)
    if not cfg:
        return
    # Roles persistentes: guardar los roles que tenía para restaurarlos si vuelve
    if cfg.get("roles_persistentes"):
        try:
            rids = [r.id for r in getattr(member, "roles", []) if not r.managed and r != member.guild.default_role]
            if rids:
                datos = cargar_datos()
                rg = datos.setdefault("roles_guardados", {})
                rg.setdefault(str(member.guild.id), {})[str(member.id)] = rids
                guardar_datos(datos)
        except Exception as e:
            print(f"[ROLES_PERSIST] {e}")
    if cfg.get("sistema_logs_joins") and cfg.get("despedida_canal"):
        canal = member.guild.get_channel(cfg["despedida_canal"])
        if canal:
            msg_template = cfg.get("despedida_mensaje", "{user} ha abandonado el servidor.")
            msg_final = msg_template.replace("{user}", str(member)).replace("{server}", member.guild.name)
            await canal.send(msg_final)
    # Log avanzado de salida - intentar detectar si fue kick via audit log
    embed_log = discord.Embed(
        title="📤 Miembro Salio",
        color=discord.Color.red(),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed_log.set_author(name=str(member), icon_url=member.display_avatar.url)
    embed_log.set_thumbnail(url=member.display_avatar.url)
    embed_log.add_field(name="👤 Usuario", value=f"{member.mention}\n`{member} ({member.id})`", inline=True)
    tiempo = (datetime.datetime.now(datetime.timezone.utc) - member.joined_at).days if member.joined_at else "?"
    embed_log.add_field(name="⏱️ Tiempo en server", value=f"{tiempo} dias", inline=True)
    roles = [r.mention for r in member.roles if r.name != "@everyone"]
    embed_log.add_field(name=f"🎭 Roles ({len(roles)})", value=" ".join(roles[:10]) + ("..." if len(roles)>10 else "") if roles else "Ninguno", inline=False)
    # Detectar kick
    try:
        async for entry in member.guild.audit_logs(limit=3, action=discord.AuditLogAction.kick):
            if entry.target.id == member.id and (datetime.datetime.now(datetime.timezone.utc) - entry.created_at).seconds < 5:
                embed_log.add_field(name="👢 Kickeado por", value=f"{entry.user.mention}\nRazon: {entry.reason or 'Sin razon'}", inline=False)
                embed_log.title = "👢 Miembro Kickeado"
                embed_log.color = discord.Color.orange()
                break
    except:
        pass
    embed_log.set_footer(text=f"ID: {member.id} | {member.guild.name}")
    await enviar_log(member.guild, embed_log)

@bot.event
async def on_member_ban(guild, user):
    embed_log = discord.Embed(title="🔨 Usuario Baneado", color=discord.Color.dark_red(), timestamp=datetime.datetime.now(datetime.timezone.utc))
    embed_log.add_field(name="Usuario", value=f"{user} (`{user.id}`)", inline=True)
    # Intentar obtener quien ejecuto el ban del audit log
    try:
        async for entry in guild.audit_logs(limit=1, action=discord.AuditLogAction.ban):
            if entry.target.id == user.id:
                embed_log.add_field(name="Baneado por", value=f"{entry.user.mention} (`{entry.user}`)", inline=True)
                if entry.reason:
                    embed_log.add_field(name="Razon", value=entry.reason, inline=False)
                break
    except:
        pass
    embed_log.set_thumbnail(url=user.display_avatar.url)
    embed_log.set_footer(text=f"ID del usuario: {user.id}")
    await enviar_log(guild, embed_log)
    # Reputacion cross-server: registrar el ban (1 por server)
    _motivo_rep = "ban"
    for _f in embed_log.fields:
        if _f.name == "Razon":
            _motivo_rep = _f.value
            break
    _rep_registrar_ban(user.id, str(user), guild, _motivo_rep)

@bot.event
async def on_member_unban(guild, user):
    embed_log = discord.Embed(title="✅ Usuario Desbaneado", color=discord.Color.green(), timestamp=datetime.datetime.now(datetime.timezone.utc))
    embed_log.set_thumbnail(url=user.display_avatar.url)
    embed_log.add_field(name="👤 Usuario", value=f"{user.mention}\n`{user} ({user.id})`", inline=True)
    try:
        async for entry in guild.audit_logs(limit=1, action=discord.AuditLogAction.unban):
            if entry.target.id == user.id:
                embed_log.add_field(name="Por", value=f"{entry.user.mention}", inline=True)
                break
    except:
        pass
    embed_log.set_footer(text=f"ID: {user.id}")
    await enviar_log(guild, embed_log)

@bot.event
async def on_member_update(before, after):
    # ── Deteccion automatica de tiers por rol en server de soporte ────────────
    if after.guild.id == SERVER_SOPORTE_ID and before.roles != after.roles:
        roles_nuevos = [r for r in after.roles if r not in before.roles]
        roles_quitados = [r for r in before.roles if r not in after.roles]

        for rol in roles_nuevos:
            if rol.id in TIER_ROLES:
                tier = TIER_ROLES[rol.id]
                # Activar beneficios
                kofi_activos[after.id] = {
                    "tier": tier,
                    "aceptado_por": "Sistema automático (rol)",
                    "fecha": datetime.datetime.now().isoformat(),
                    "rol_id": rol.id,
                }
                badge = TIER_BADGES.get(tier, "⭐")
                nombre_tier = TIER_NOMBRES.get(tier, tier)
                lims = TIER_LIMITES.get(tier, TIER_LIMITES[None])
                # DM al usuario
                try:
                    embed_dm = discord.Embed(
                        title=f"{badge} ¡Beneficios {nombre_tier} Activados!",
                        description=(
                            f"Tus beneficios de **{nombre_tier}** fueron activados automáticamente.\n\n"
                            f"**Tus límites diarios:**\n"
                            f"• `l!ask` → **{lims[0]}** usos/día\n"
                            f"• `l!ytb` → **{lims[1]}** búsquedas/día\n"
                            f"• `l!buscar` / `l!imagen` / `l!noticias` → **{lims[2]}** usos/día\n\n"
                            f"¡Gracias por apoyar LatamBOT!\n[☕ Ko-Fi](https://ko-fi.com/latambot) • [🎭 Patreon](https://patreon.com/latambot)"
                        ),
                        color=discord.Color.from_rgb(255, 94, 0)
                    )
                    embed_dm.set_footer(text="LatamBOT | Sistema de Tiers")
                    await after.send(embed=embed_dm)
                except:
                    pass
                # Log en canal notif
                canal_notif = await _get_notif_channel()
                if canal_notif:
                    embed_log = discord.Embed(
                        title=f"{badge} Tier Activado: {nombre_tier}",
                        description=f"{after.mention} recibió el rol **{rol.name}** → tier `{tier}` activado automáticamente.",
                        color=discord.Color.from_rgb(255, 94, 0),
                        timestamp=datetime.datetime.now(datetime.timezone.utc)
                    )
                    embed_log.set_thumbnail(url=after.display_avatar.url)
                    embed_log.set_footer(text=f"ID: {after.id}")
                    await canal_notif.send(embed=embed_log)
                _save_runtime_state()
                break

        for rol in roles_quitados:
            if rol.id in TIER_ROLES and after.id in kofi_activos:
                # Verificar que no tenga otro rol de tier activo
                tier_roles_actuales = [r for r in after.roles if r.id in TIER_ROLES]
                if not tier_roles_actuales:
                    # Sin roles de tier - revocar beneficios
                    tier_viejo = kofi_activos.pop(after.id, {}).get("tier", "?")
                    nombre_viejo = TIER_NOMBRES.get(tier_viejo, tier_viejo)
                    try:
                        embed_dm = discord.Embed(
                            title="ℹ️ Beneficios Desactivados",
                            description=(
                                f"Tu tier **{nombre_viejo}** fue desactivado porque el rol fue removido.\n"
                                f"Si crees que es un error, contacta al staff del servidor de soporte."
                            ),
                            color=discord.Color(COLOR_ADVERTENCIA)
                        )
                        await after.send(embed=embed_dm)
                    except:
                        pass
                else:
                    # Tiene otro rol de tier - actualizar al nuevo
                    nuevo_rol = tier_roles_actuales[0]
                    nuevo_tier = TIER_ROLES[nuevo_rol.id]
                    kofi_activos[after.id]["tier"] = nuevo_tier
                _save_runtime_state()
                break

    # Cambio de roles
    if before.roles != after.roles:
        nuevos   = [r for r in after.roles if r not in before.roles]
        removidos = [r for r in before.roles if r not in after.roles]
        if nuevos or removidos:
            embed_log = discord.Embed(title="🎭 Roles Actualizados", color=discord.Color.blue(), timestamp=datetime.datetime.now(datetime.timezone.utc))
            embed_log.set_author(name=str(after), icon_url=after.display_avatar.url)
            embed_log.add_field(name="👤 Usuario", value=f"{after.mention} `({after.id})`", inline=True)
            if nuevos:
                embed_log.add_field(name="✅ Roles Agregados", value=" ".join(r.mention for r in nuevos), inline=False)
            if removidos:
                embed_log.add_field(name="❌ Roles Removidos", value=" ".join(r.mention for r in removidos), inline=False)
            # Quien hizo el cambio
            try:
                async for entry in after.guild.audit_logs(limit=1, action=discord.AuditLogAction.member_role_update):
                    if entry.target.id == after.id and (datetime.datetime.now(datetime.timezone.utc) - entry.created_at).seconds < 5:
                        embed_log.add_field(name="🛡️ Por", value=entry.user.mention, inline=True)
                        break
            except:
                pass
            embed_log.set_footer(text=f"ID: {after.id}")
            await enviar_log(after.guild, embed_log)

    # Timeout / silencio
    if before.timed_out_until != after.timed_out_until:
        if after.timed_out_until:
            embed_log = discord.Embed(title="🔇 Usuario en Timeout", color=discord.Color.orange(), timestamp=datetime.datetime.now(datetime.timezone.utc))
            embed_log.add_field(name="Usuario", value=after.mention, inline=False)
            embed_log.add_field(name="Hasta", value=f"<t:{int(after.timed_out_until.timestamp())}:R>", inline=True)
        else:
            embed_log = discord.Embed(title="🔊 Timeout Removido", color=discord.Color.green(), timestamp=datetime.datetime.now(datetime.timezone.utc))
            embed_log.add_field(name="Usuario", value=after.mention, inline=False)
        embed_log.set_footer(text=f"ID: {after.id}")
        await enviar_log(after.guild, embed_log)

    # Cambio de apodo
    if before.nick != after.nick:
        embed_log = discord.Embed(title="✏️ Apodo Cambiado", color=discord.Color.blurple(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=after.mention)
        embed_log.add_field(name="Antes", value=before.nick or "*(sin apodo)*")
        embed_log.add_field(name="Despues", value=after.nick or "*(sin apodo)*")
        embed_log.set_footer(text=f"ID: {after.id}")
        await enviar_log(after.guild, embed_log)

    # Nitro boost
    if before.premium_since is None and after.premium_since is not None:
        embed_log = discord.Embed(title="💎 Nuevo Booster!", color=discord.Color.from_rgb(255, 115, 250), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=after.mention, inline=False)
        embed_log.add_field(name="Boosteo el", value=f"<t:{int(after.premium_since.timestamp())}:R>", inline=True)
        embed_log.set_thumbnail(url=after.avatar.url if after.avatar else None)
        await enviar_log(after.guild, embed_log)

@bot.event
async def on_voice_state_update(member, before, after):
    """Log de actividad en canales de voz."""
    guild = member.guild
    embed_log = None

    if before.channel is None and after.channel is not None:
        # Se unio a un canal de voz
        embed_log = discord.Embed(title="🔊 Entro a Voz", color=discord.Color.green(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=member.mention, inline=True)
        embed_log.add_field(name="Canal", value=after.channel.mention, inline=True)
    elif before.channel is not None and after.channel is None:
        # Salio de un canal de voz
        embed_log = discord.Embed(title="🔇 Salio de Voz", color=discord.Color.red(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=member.mention, inline=True)
        embed_log.add_field(name="Canal", value=before.channel.mention, inline=True)
    elif before.channel != after.channel and before.channel and after.channel:
        # Cambio de canal de voz
        embed_log = discord.Embed(title="🔀 Cambio Canal de Voz", color=discord.Color.orange(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=member.mention, inline=False)
        embed_log.add_field(name="Desde", value=before.channel.mention, inline=True)
        embed_log.add_field(name="Hacia", value=after.channel.mention, inline=True)
    elif before.self_mute != after.self_mute:
        estado = "Muteado" if after.self_mute else "Desmuteado"
        embed_log = discord.Embed(title=f"🎙️ Usuario {estado} (mic)", color=discord.Color.greyple(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=member.mention, inline=True)
        if after.channel:
            embed_log.add_field(name="Canal", value=after.channel.mention, inline=True)
    elif before.self_deaf != after.self_deaf:
        estado = "Se quedo sordo" if after.self_deaf else "Quito sordera"
        embed_log = discord.Embed(title=f"🎧 {estado}", color=discord.Color.greyple(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=member.mention, inline=True)

    if embed_log:
        embed_log.set_footer(text=f"ID: {member.id}")
        await enviar_log(guild, embed_log)

