@bot.event
async def on_guild_update(before, after):
    cambios = []
    if before.name != after.name:
        cambios.append(f"**Nombre:** `{before.name}` → `{after.name}`")
    if before.icon != after.icon:
        cambios.append("**Icono:** cambiado")
    if before.banner != after.banner:
        cambios.append("**Banner:** cambiado")
    if before.premium_tier != after.premium_tier:
        cambios.append(f"**Nivel Boost:** {before.premium_tier} → {after.premium_tier}")
    if before.description != after.description:
        cambios.append(f"**Descripcion:** actualizada")
    if before.verification_level != after.verification_level:
        cambios.append(f"**Nivel verificacion:** {before.verification_level} → {after.verification_level}")
    if before.explicit_content_filter != after.explicit_content_filter:
        cambios.append(f"**Filtro contenido:** {before.explicit_content_filter} → {after.explicit_content_filter}")
    if not cambios:
        return
    embed_log = discord.Embed(
        title="🏠 Servidor Actualizado",
        description="\n".join(cambios),
        color=discord.Color.blurple(),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    try:
        async for entry in after.audit_logs(limit=1, action=discord.AuditLogAction.guild_update):
            embed_log.add_field(name="👤 Por", value=entry.user.mention, inline=True)
            break
    except:
        pass
    if after.icon:
        embed_log.set_thumbnail(url=after.icon.url)
    await enviar_log(after, embed_log)

