# Buffer para acumular usos de tuppers en logs
# { guild_id: {"embed_id": int, "canal_log": int, "usos": int, "entries": [str]} }
_tupper_log_buffer: Dict[int, Dict] = {}
TUPPER_LOG_MAX = 10  # mensajes por embed antes de crear uno nuevo


def _looks_like_tupper_trigger(content: str, prefix: str = "l!") -> bool:
    raw = (content or "").strip()
    if not raw or "\n" in raw:
        return False
    if raw.startswith((prefix, "/", "\\", "http://", "https://", "www.")):
        return False
    match = re.match(r"^([^:\n]{1,48})\s*:\s*(.{1,1800})$", raw)
    if not match:
        return False
    name, body = match.group(1).strip(), match.group(2).strip()
    if not name or not body:
        return False
    lowered = name.lower()
    if lowered in {"http", "https", "nota", "edit", "todo", "pd", "ps", "ej", "ejemplo"}:
        return False
    if any(ch in name for ch in "/\\<>@#`"):
        return False
    if "." in name or ":" in name:
        return False
    words = name.split()
    if len(words) > 6:
        return False
    allowed = re.compile(r"^[\w\s'\-\.]{1,48}$", re.UNICODE)
    return bool(allowed.match(name))

@bot.event
async def on_message_delete(message):
    if message.id in _uwu_deleted_messages:
        _uwu_deleted_messages.discard(message.id)
        return
    if not message.guild:
        return

    es_webhook = message.webhook_id is not None
    # Detectar PluralKit específicamente (tiene application_id conocido)
    # PluralKit bot ID: 466378653216014359
    # Tupperbox bot ID: 431544605209788416
    PLURALKIT_ID = 466378653216014359
    TUPPERBOX_ID = 431544605209788416
    es_pluralkit = getattr(message, "application_id", None) in (PLURALKIT_ID, TUPPERBOX_ID)
    es_bot_normal = message.author.bot and not es_webhook and not es_pluralkit

    # ── Detectar Tupper/Pluralkit (webhooks con nombre personalizado) ──────────
    if es_webhook:
        # Guardar en snipe como tupper (para l!snipe)
        # Tupper/PluralKit: el webhook YA tiene el display_name del personaje.
        # El content es el mensaje REAL del usuario, sin prefijo de nombre.
        # NO hay que parsear nada - mostrar tal cual.
        nombre_tupper = message.author.display_name
        contenido_real = message.content or ""

        # Tuppers van a cache SEPARADO para no pisar mensajes normales
        snipe_cache_tupper[message.channel.id] = {
            "author": nombre_tupper,
            "author_avatar": str(message.author.display_avatar.url),
            "author_id": None,
            "content": contenido_real,
            "attachments": [a.url for a in message.attachments],
            "images": [a.url for a in message.attachments if a.content_type and a.content_type.startswith("image/")],
            "time": datetime.datetime.now(),
            "es_tupper": True,
            "webhook_id": message.webhook_id,
        }
        # Log de tupper - acumular en buffer
        cfg = get_config(message.guild.id)
        if cfg and cfg.get("canal_logs"):
            canal_log = message.guild.get_channel(cfg["canal_logs"])
            if canal_log:
                gid = message.guild.id
                entrada = f"🪆 **{message.author.display_name}** en {message.channel.mention}: {_clip_text(message.content or '*(sin texto)*', 500)}"
                if message.attachments:
                    entrada += f" [{len(message.attachments)} adjunto(s)]"

                buf = _tupper_log_buffer.get(gid)
                ahora = datetime.datetime.now(datetime.timezone.utc)

                if buf and buf["usos"] < TUPPER_LOG_MAX:
                    # Editar embed existente
                    buf["entries"].append(entrada)
                    buf["usos"] += 1
                    try:
                        msg_existente = await canal_log.fetch_message(buf["embed_id"])
                        embed_upd = discord.Embed(
                            title=f"🪆 Tuppers Eliminados ({buf['usos']}/{TUPPER_LOG_MAX})",
                            description="\n".join(buf["entries"]),
                            color=discord.Color.from_rgb(180, 120, 255),
                            timestamp=ahora
                        )
                        embed_upd.set_footer(text=f"LatamBOT | Canal: #{message.channel.name}")
                        await msg_existente.edit(embed=embed_upd)
                    except:
                        buf = None  # Si falla la edicion, crear nuevo
                if not buf or buf["usos"] >= TUPPER_LOG_MAX:
                    embed_tupper = discord.Embed(
                        title="🪆 Tuppers Eliminados (1/10)",
                        description=entrada,
                        color=discord.Color.from_rgb(180, 120, 255),
                        timestamp=ahora
                    )
                    embed_tupper.set_footer(text=f"LatamBOT | Canal: #{message.channel.name}")
                    try:
                        nuevo_msg = await canal_log.send(embed=embed_tupper)
                        _tupper_log_buffer[gid] = {
                            "embed_id": nuevo_msg.id,
                            "usos": 1,
                            "entries": [entrada],
                        }
                    except:
                        pass
        return  # No procesar como mensaje normal

    # Ignorar bots normales (no webhooks)
    if es_bot_normal:
        return

    # ── Mensaje normal de usuario ─────────────────────────────────────────────
    snipe_opt_out = user_prefs.get(message.author.id, {}).get("snipe_opt_out", False)

    # Detectar activadores de Tupper/PluralKit:
    # Formatos soportados:
    #   "Nombre:texto"           → sin espacios
    #   "Nombre: texto"          → espacio después de :
    #   "Nombre : texto"         → espacio antes y después de :
    #   "Nombre Apellido: texto" → nombre con espacios
    #   "el tails we: mensaje"   → nombre con articulo
    # Regla: si el mensaje tiene formato "texto_sin_saltos : algo" lo ignoramos
    if _looks_like_tupper_trigger(message.content, (get_config(message.guild.id) or {}).get("prefix", "l!")):
        return

    # Guardar en snipe solo si no está en opt-out (historial hasta SNIPE_HIST_MAX por canal)
    if not snipe_opt_out:
        imagenes = []
        for att in message.attachments:
            if att.content_type and att.content_type.startswith("image/"):
                imagenes.append(att.url)
        stickers = [s.url for s in message.stickers] if message.stickers else []
        cid = message.channel.id
        if cid not in snipe_history:
            snipe_history[cid] = deque(maxlen=SNIPE_HIST_MAX)
        item = {
            "author": str(message.author),
            "author_avatar": str(message.author.display_avatar.url),
            "author_id": message.author.id,
            "content": message.content,
            "attachments": [a.url for a in message.attachments],
            "images": imagenes,
            "stickers": stickers,
            "time": datetime.datetime.now(),
            "es_tupper": False,
            "embeds": message.embeds,
        }
        snipe_history[cid].appendleft(item)
        snipe_optout_markers.pop(cid, None)
        try:
            asyncio.create_task(_pi_archive_post("/v1/archive/snipe", {
                "channel_id": cid,
                "guild_id": message.guild.id,
                "author_id": message.author.id,
                "author": str(message.author),
                "content": message.content or "",
                "author_avatar": str(message.author.display_avatar.url),
                "images": imagenes[:8],
                "attachments": [a.url for a in message.attachments][:8],
            }))
        except Exception:
            pass
    else:
        snipe_optout_markers[message.channel.id] = {
            "time": datetime.datetime.now(),
            "has_attachments": bool(message.attachments),
            "has_text": bool(message.content),
        }

    # ── Log avanzado del servidor ─────────────────────────────────────────────
    if not message.content and not message.attachments and not message.embeds and not message.stickers:
        return

    embed = discord.Embed(
        title="🗑️ Mensaje Eliminado",
        color=discord.Color.red(),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed.set_author(name=str(message.author), icon_url=message.author.display_avatar.url)
    embed.add_field(name="👤 Autor", value=f"{message.author.mention} `({message.author.id})`", inline=True)
    embed.add_field(name="📍 Canal", value=message.channel.mention, inline=True)
    embed.add_field(name="📅 Enviado", value=f"<t:{int(message.created_at.timestamp())}:R>", inline=True)

    if message.content:
        contenido = _clip_text(message.content, 3800)
        embed.description = f"**Contenido completo disponible hasta limite de Discord:**\n```{contenido}```"

    if message.attachments:
        att_txt = "\n".join(
            f"{'🖼️' if (a.content_type or '').startswith('image/') else '📎'} [{a.filename}]({a.url})"
            for a in message.attachments[:6]
        )
        embed.add_field(name=f"📎 Adjuntos ({len(message.attachments)})", value=att_txt, inline=False)
        # Mostrar primera imagen en el embed
        primera_img = next((a for a in message.attachments if (a.content_type or "").startswith("image/")), None)
        if primera_img:
            embed.set_image(url=primera_img.url)

    if message.stickers:
        embed.add_field(name="🎭 Sticker", value=", ".join(s.name for s in message.stickers), inline=True)

    if message.embeds:
        orig = message.embeds[0]
        partes = []
        if orig.title: partes.append(f"**Titulo:** {_clip_text(orig.title, 300)}")
        if orig.description: partes.append(f"**Desc:** {_clip_text(orig.description, 600)}")
        if orig.url: partes.append(f"**URL:** {orig.url}")
        if partes:
            embed.add_field(name="📋 Embed adjunto", value="\n".join(partes), inline=False)
        if orig.image and not message.attachments:
            embed.set_image(url=orig.image.url)

    # Intentar obtener quien borro el mensaje via audit log
    try:
        async for entry in message.guild.audit_logs(limit=3, action=discord.AuditLogAction.message_delete):
            if entry.target.id == message.author.id and (datetime.datetime.now(datetime.timezone.utc) - entry.created_at).seconds < 5:
                embed.add_field(name="🛡️ Eliminado por", value=f"{entry.user.mention} `({entry.user})`", inline=True)
                break
    except:
        pass

    embed.set_footer(text=f"ID mensaje: {message.id} | ID usuario: {message.author.id}")
    await enviar_log(message.guild, embed)


@bot.event
async def on_bulk_message_delete(messages):
    """Loguea los mensajes borrados en un PURGE - de este bot o de otros (Nekotina, Circle, etc.)
    o de un mod borrando en masa. Muestra el contenido de los que estaban en caché."""
    try:
        if not messages:
            return
        guild = messages[0].guild
        if guild is None:
            return
        canal = messages[0].channel
        ahora = datetime.datetime.now(datetime.timezone.utc)
        msgs = sorted(messages, key=lambda m: (m.created_at or ahora))
        lineas, sin_contenido = [], 0
        for m in msgs:
            autor = str(m.author) if m.author else "desconocido"
            txt = (m.content or "").replace("\n", " ").strip()
            adj = f" 📎x{len(m.attachments)}" if m.attachments else ""
            if txt or adj:
                if len(lineas) < 30:
                    hora = discord.utils.format_dt(m.created_at, "t") if m.created_at else ""
                    lineas.append(f"{hora} **{autor}:** {_clip_text(txt, 130)}{adj}")
            else:
                sin_contenido += 1
        restantes = len(msgs) - min(len(lineas), 30) - sin_contenido
        cuerpo = "\n".join(lineas) or "*(sin texto o mensajes viejos no cacheados)*"
        notas = []
        if restantes > 0:
            notas.append(f"… y **{restantes}** con texto más")
        if sin_contenido > 0:
            notas.append(f"**{sin_contenido}** sin texto/no cacheados")
        if notas:
            cuerpo += "\n" + " · ".join(notas)
        embed = _make_embed(
            f"🧹 Purge · {len(msgs)} mensajes borrados",
            f"**Canal:** {canal.mention}\n\n{_clip_text(cuerpo, 3800)}",
            COLOR_ADVERTENCIA,
        )
        _brand_footer(embed, extra=f"{guild.name} · PURGE")
        await enviar_log(guild, embed)
        notif = await _get_notif_channel()
        if notif:
            embed_n = embed.copy()
            embed_n.add_field(name="Servidor", value=f"{guild.name} (`{guild.id}`)", inline=False)
            try:
                await notif.send(embed=embed_n)
            except Exception:
                pass
        try:
            for m in msgs[:SNIPE_HIST_MAX]:
                if m.guild and not user_prefs.get(getattr(m.author, "id", 0), {}).get("snipe_opt_out"):
                    cid = m.channel.id
                    if cid not in snipe_history:
                        snipe_history[cid] = deque(maxlen=SNIPE_HIST_MAX)
                    av = ""
                    try:
                        av = str(m.author.display_avatar.url)
                    except Exception:
                        pass
                    snipe_history[cid].appendleft({
                        "author": str(m.author),
                        "author_avatar": av,
                        "author_id": getattr(m.author, "id", 0),
                        "content": m.content or "",
                        "attachments": [a.url for a in (m.attachments or [])],
                        "images": [a.url for a in (m.attachments or []) if (a.content_type or "").startswith("image/")],
                        "stickers": [],
                        "time": datetime.datetime.now(),
                        "es_tupper": False,
                        "embeds": [],
                    })
            asyncio.create_task(_pi_archive_post("/v1/archive/purge", {
                "guild_id": guild.id,
                "channel_id": canal.id,
                "count": len(msgs),
                "preview": cuerpo[:4000],
            }))
        except Exception as _pe:
            print(f"[BULK_DELETE] archive {_pe}")
    except Exception as e:
        print(f"[BULK_DELETE] {e}")


@bot.event
async def on_message_edit(before, after):
    # Ignorar bots, webhooks/tuppers y cuando el contenido no cambia
    if not before.guild or before.webhook_id or before.author.bot or before.content == after.content:
        return
    cfg = get_config(before.guild.id) or {}
    banned_word = None if after.author.id == OWNER_ID else _find_banned_word(after.content, cfg.get("palabras_prohibidas", []))
    if banned_word:
        try:
            await after.delete()
        except Exception:
            pass
        await _log_staff_action(
            before.guild,
            title="Banword activado tras edicion",
            color=COLOR_PELIGRO,
            actor=after.author,
            target=after.author,
            fields=[
                ("Canal", after.channel.mention, True),
                ("Palabra", banned_word, True),
                ("Antes", _clip_text(before.content or "(vacio)", 500), False),
                ("Despues", _clip_text(after.content or "(vacio)", 500), False),
            ],
            tag="BANWORD_EDIT",
        )
        return
    snipe_opt_out = user_prefs.get(before.author.id, {}).get("snipe_opt_out", False)
    if not snipe_opt_out:
        imagenes_antes = [a.url for a in before.attachments if (a.content_type or "").startswith("image/")]
        esnipe_cache[before.channel.id] = {
            "author": str(before.author),
            "author_avatar": str(before.author.display_avatar.url),
            "author_id": before.author.id,
            "antes": before.content,
            "despues": after.content,
            "images": imagenes_antes,
            "attachments": [a.url for a in before.attachments],
            "time": datetime.datetime.now(),
            "jump_url": after.jump_url,
        }
    embed = discord.Embed(title="✏️ Mensaje Editado", color=discord.Color.orange(), timestamp=datetime.datetime.now(datetime.timezone.utc))
    embed.add_field(name="Autor", value=before.author.mention, inline=True)
    embed.add_field(name="Canal", value=before.channel.mention, inline=True)
    embed.add_field(name="Antes", value=_clip_text(before.content or "*(vacio)*", 1024), inline=False)
    embed.add_field(name="Despues", value=_clip_text(after.content or "*(vacio)*", 1024), inline=False)
    embed.add_field(name="Ver mensaje", value=f"[Ir al mensaje]({after.jump_url})", inline=False)
    embed.set_footer(text=f"ID: {before.id}")
    await enviar_log(before.guild, embed)


def _extraer_contenido_interaccion(interaction) -> str:
    """Extrae 'lo que puso' el usuario: opciones de un slash o valores de un modal."""
    try:
        data = interaction.data or {}
        tipo = interaction.type
        if tipo == discord.InteractionType.application_command:
            partes = []
            def _walk(options):
                for o in (options or []):
                    if o.get("type") in (1, 2):  # subcomando / grupo
                        partes.append(str(o.get("name", "")))
                        _walk(o.get("options"))
                    elif "value" in o:
                        partes.append(f"{o.get('name')}: {o.get('value')}")
            _walk(data.get("options"))
            return " | ".join(p for p in partes if p)
        if tipo == discord.InteractionType.modal_submit:
            vals = []
            for row in (data.get("components") or []):
                for comp in (row.get("components") or []):
                    v = comp.get("value")
                    if v:
                        vals.append(f"**{comp.get('custom_id', 'campo')}:** {v}")
            return "\n".join(vals)
    except Exception:
        pass
    return ""


@bot.listen("on_interaction")
async def _log_toda_interaccion(interaction: discord.Interaction):
    """Registra TODA interaccion (slash, botones, selects, modales) en el server de notif."""
    try:
        tipo = interaction.type
        if tipo == discord.InteractionType.autocomplete:
            return  # demasiado ruidoso

        if tipo == discord.InteractionType.application_command:
            nombre = "/" + (interaction.command.qualified_name if interaction.command else (interaction.data or {}).get("name", "?"))
            etiqueta = "🔹 Slash command"
        elif tipo == discord.InteractionType.component:
            data = interaction.data or {}
            ct = data.get("component_type")
            kind = "Botón" if ct == 2 else ("Menú" if ct in (3, 5, 6, 7, 8) else "Componente")
            nombre = data.get("custom_id", "?")
            if data.get("values"):
                nombre += f" → {', '.join(map(str, data['values']))[:80]}"
            etiqueta = f"🔘 {kind}"
        elif tipo == discord.InteractionType.modal_submit:
            nombre = (interaction.data or {}).get("custom_id", "?")
            etiqueta = "📝 Modal"
        else:
            nombre, etiqueta = str(tipo), "ℹ️ Interacción"

        g = interaction.guild
        es_md = g is None
        usuario = interaction.user
        if es_md:
            etiqueta = f"{etiqueta} · MD"
            _console_log(
                "CMD_MD",
                "Interaccion ejecutada en MD",
                user=f"{usuario} ({getattr(usuario, 'id', '?')})" if usuario else None,
                name=str(nombre)[:120],
            )
        canal_notif = await _get_notif_channel()
        if not canal_notif:
            return
        embed = discord.Embed(
            title=etiqueta,
            description=f"`{str(nombre)[:200]}`",
            color=discord.Color.magenta() if es_md else discord.Color.blurple(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        if usuario:
            embed.add_field(name="Usuario", value=f"{usuario} (`{usuario.id}`)", inline=True)
            embed.set_thumbnail(url=usuario.display_avatar.url)
        embed.add_field(
            name="Servidor",
            value=(f"{g.name} (`{g.id}`)" if g else "MD (mensaje directo)"),
            inline=True,
        )
        if interaction.channel:
            canal_txt = getattr(interaction.channel, "mention", None) or f"#{getattr(interaction.channel, 'name', '?')}"
            embed.add_field(name="Dónde", value=f"{canal_txt} (`{getattr(interaction.channel, 'id', '?')}`)", inline=True)
        # "Lo que puso": opciones de slash o valores del modal
        contenido = _extraer_contenido_interaccion(interaction)
        if contenido:
            embed.add_field(name="📝 Lo que puso", value=contenido[:1024], inline=False)
        embed.set_footer(text=f"LatamBOT {BOT_VERSION}")
        await canal_notif.send(embed=embed)
    except Exception as e:
        # Nunca debe romper la interaccion del usuario
        print(f"[INTERACTION LOG] {e}")


@bot.event
async def on_command_error(ctx, error):
    _metric_bump("command_failures")
    try:
        if ctx.message:
            _cmd_invocation_audit.pop(ctx.message.id, None)
    except Exception:
        pass

    async def _err(titulo, desc, color=discord.Color.red(), solucion=None):
        embed = _make_error_embed(titulo, desc, solucion or "", color=color)
        if solucion:
            embed.add_field(name="💡 Cómo resolverlo", value=solucion, inline=False)
        embed.set_footer(text=f"Comando: {ctx.command} | Pedido por: {ctx.author}")
        try:
            await ctx.send(embed=embed, delete_after=15)
        except:
            pass

    if isinstance(error, commands.CheckFailure):
        await _err("Sin permisos", "No tenes permisos para usar este comando.", discord.Color.orange())
    elif isinstance(error, commands.MissingRequiredArgument):
        cfg = get_config(ctx.guild.id) or {}
        p = cfg.get("prefix", "l!")
        await _err(
            "Argumento faltante",
            f"Falta el argumento `{error.param.name}`.\nUsa `{p}help` para ver el uso correcto.",
            discord.Color.orange()
        )
    elif isinstance(error, commands.BadArgument):
        await _err("Argumento invalido", "Ese dato no me sirve asi. Revisa menciones, IDs o formato.", discord.Color.orange())
    elif isinstance(error, commands.MemberNotFound):
        await _err("Usuario no encontrado", f"No encontre a `{error.argument}` en este servidor.", discord.Color.orange())
    elif isinstance(error, commands.CommandOnCooldown):
        await _err(
            "Comando en espera",
            f"Esperá **{error.retry_after:.1f}s** antes de volver a usar este comando.",
            discord.Color.gold()
        )
    elif isinstance(error, commands.MissingPermissions):
        perms = ", ".join(f"`{p.replace('_',' ').title()}`" for p in error.missing_permissions)
        await _err("❌ Sin Permisos", f"No tenés los permisos necesarios para usar `{ctx.command}`\n**Permisos requeridos:** {perms}", discord.Color.orange(),
            solucion=f"Pedile a un administrador del servidor que te dé los permisos: {perms}")
    elif isinstance(error, commands.BotMissingPermissions):
        perms = ", ".join(f"`{p.replace('_',' ').title()}`" for p in error.missing_permissions)
        await _err("❌ El bot no tiene permisos", f"Necesito los siguientes permisos para ejecutar `{ctx.command}`:\n**Faltantes:** {perms}", discord.Color.orange(),
            solucion=f"Un administrador debe ir a **Configuración → Roles → LatamBOT** y activar: {perms}")
    elif isinstance(error, commands.MissingRequiredArgument):
        await _err("❌ Argumento faltante", f"Falta el argumento `{error.param.name}` para usar `{ctx.command}`.\nUsá `l!help {ctx.command}` para ver cómo usarlo.", discord.Color.orange())
    elif isinstance(error, commands.BadArgument):
        await _err("❌ Argumento inválido", f"Uno de los argumentos que enviaste es inválido.\n`{error}`", discord.Color.orange())
    elif isinstance(error, commands.CommandOnCooldown):
        await _err("⏱️ Cooldown", f"Usaste este comando muy rápido. Esperá **{error.retry_after:.1f} segundos** e intentá de nuevo.", discord.Color.orange())
    elif isinstance(error, commands.CommandNotFound):
        pass  # Ignorar comandos inexistentes silenciosamente
    elif isinstance(error, commands.NoPrivateMessage):
        await _err("Solo en servidores", "Este comando no se puede usar por mensaje privado.", discord.Color.orange())
    elif isinstance(error, commands.DisabledCommand):
        await _err("❌ Comando desactivado", f"El comando `{ctx.command}` está desactivado en este servidor.", discord.Color.orange())
    else:
        tb_str = traceback.format_exc()
        print(f"[ERROR] {ctx.command}: {error}")
        print(tb_str)
        await _err("Error interno", "Paso algo que no estaba previsto. Intenta otra vez en unos segundos.", discord.Color.red())
        # Notificar al server del owner con explicacion de IA
        asyncio.create_task(_notificar_error_critico(ctx, error, tb_str))


@bot.event
async def on_command(ctx):
    """Loggea cada uso de comando al server de notificaciones y al canal de logs del server."""
    _metric_bump("commands_total")
    try:
        # Reconstruir el comando con args
        args_txt = " ".join(str(a) for a in ctx.args[1:] if not isinstance(a, commands.Context)) if ctx.args else ""
        if ctx.kwargs:
            args_txt += " " + " ".join(f"{v}" for k, v in ctx.kwargs.items() if v is not None)
        args_txt = args_txt.strip()
        full_cmd = f"`{ctx.prefix}{ctx.command.qualified_name}`"
        if args_txt:
            full_cmd += f" `{args_txt[:120]}`"
    except:
        full_cmd = f"`{ctx.prefix}{ctx.command}`"

    try:
        if ctx.message and ctx.command:
            _cmd_invocation_audit[ctx.message.id] = full_cmd
    except Exception:
        pass

    # Prefijo en MD / User App: el log de slash ya cubre hybrid via on_interaction.
    if not ctx.guild:
        if getattr(ctx, "interaction", None):
            return
        cmd_label = ctx.command.qualified_name if ctx.command else "?"
        _console_log(
            "CMD_MD",
            "Comando ejecutado en MD",
            user=f"{ctx.author} ({ctx.author.id})",
            command=f"{ctx.prefix}{cmd_label}",
        )
        try:
            canal_notif = await _get_notif_channel()
            if canal_notif:
                embed = discord.Embed(
                    title="📩 Comando ejecutado en MD",
                    description="Alguien usó un comando por mensaje directo / User App.",
                    color=discord.Color.magenta(),
                    timestamp=datetime.datetime.now(datetime.timezone.utc),
                )
                embed.add_field(name="Comando", value=full_cmd, inline=False)
                embed.add_field(name="Usuario", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
                embed.add_field(name="Dónde", value="MD (mensaje directo)", inline=True)
                if ctx.channel:
                    embed.add_field(name="Canal ID", value=f"`{ctx.channel.id}`", inline=True)
                embed.set_thumbnail(url=ctx.author.display_avatar.url)
                embed.set_footer(text=f"LatamBOT {BOT_VERSION}")
                await asyncio.wait_for(canal_notif.send(embed=embed), timeout=6.0)
        except Exception as e:
            _console_log("CMD_LOG_NOTIF", "No se pudo enviar el log de comando MD", level="ERROR", error=e)
        return

    # Log al canal de logs del SERVIDOR (solo comandos de staff/moderacion)
    CMDS_A_LOGGEAR = {
        "ban","kick","mute","unmute","warn","clearwarns","unwarn","setwarn","warnpurge",
        "softban","tempban","massban","unban","purge","clear","nuke","lock","unlock",
        "lockall","unlockall","hide","unhide","slowmode","addrole","removerole",
        "massrole","muteall","unmuteall","dehoist","stripnick","antiraid","banword",
        "unbanword","vcmute","vcunmute","vcdeaf","vckick","move","timeout",
    }
    try:
        if ctx.command and ctx.command.qualified_name in CMDS_A_LOGGEAR:
            snap = _guild_snapshot(ctx.guild)
            embed_server = discord.Embed(
                title=f"🛡️ Comando de Moderacion: `{ctx.prefix}{ctx.command.qualified_name}`",
                color=discord.Color(COLOR_ADVERTENCIA),
                timestamp=datetime.datetime.now(datetime.timezone.utc)
            )
            embed_server.set_author(name=str(ctx.author), icon_url=ctx.author.display_avatar.url)
            embed_server.add_field(name="Comando completo", value=full_cmd, inline=False)
            embed_server.add_field(name="Moderador", value=f"{ctx.author.mention} `({ctx.author.id})`", inline=True)
            embed_server.add_field(name="Canal", value=ctx.channel.mention, inline=True)
            embed_server.add_field(name="Mensaje", value=f"[Abrir]({ctx.message.jump_url})", inline=True)
            embed_server.add_field(name="Servidor", value=f"{snap['members']} miembros | {snap['text_channels']}T/{snap['voice_channels']}V", inline=False)
            embed_server.set_footer(text=f"LatamBOT | ID cmd: {ctx.message.id}")
            await enviar_log(ctx.guild, embed_server)
    except Exception as e:
        print(f"[CMD LOG SERVER] Error: {e}")

    # Log al canal de notificaciones del owner (todos los comandos)
    try:
        canal_notif = await _get_notif_channel()
        if canal_notif:
            embed = discord.Embed(
                title="⌨️ Comando Usado",
                color=discord.Color.blurple(),
                timestamp=datetime.datetime.now(datetime.timezone.utc)
            )
            embed.add_field(name="Comando", value=full_cmd, inline=False)
            embed.add_field(name="Usuario", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
            embed.add_field(name="Servidor", value=f"{ctx.guild.name} (`{ctx.guild.id}`)", inline=True)
            embed.add_field(name="Canal", value=f"#{ctx.channel.name}", inline=True)
            embed.set_thumbnail(url=ctx.author.display_avatar.url)
            snap = _guild_snapshot(ctx.guild)
            embed.title = "Comando ejecutado"
            embed.description = "Registro rapido de uso para seguimiento del bot en produccion."
            embed.add_field(name="Snapshot", value=f"{snap['members']} miembros | {snap['text_channels']}T/{snap['voice_channels']}V | {snap['roles']} roles", inline=False)
            embed.add_field(name="Mensaje", value=f"[Abrir mensaje]({ctx.message.jump_url})", inline=True)
            embed.add_field(name="IA", value="Permitida" if server_permitido(ctx.guild.id) else "Bloqueada", inline=True)
            embed.add_field(name="Detalle", value=f"Canal ID: `{ctx.channel.id}` | Autor admin: {'si' if ctx.author.guild_permissions.administrator else 'no'}", inline=False)
            embed.set_footer(text=f"LatamBOT {BOT_VERSION} | locale: {snap['locale']} | boosts: {snap['boosts']}")
            # Timeout: si el canal notif se cuelga, no queremos saturar el pool HTTP del bot.
            await asyncio.wait_for(canal_notif.send(embed=embed), timeout=6.0)
    except Exception as e:
        _console_log("CMD_LOG_NOTIF", "No se pudo enviar el log de comando al server de notif", level="ERROR", guild_id=ctx.guild.id if ctx.guild else None, error=e)

    try:
        if ctx.guild and ctx.guild.id == SERVER_NOTIF_ID and ctx.command:
            emb_n = discord.Embed(
                title=f"Comando en server notif: `{ctx.command.qualified_name}`",
                color=discord.Color.dark_teal(),
                timestamp=datetime.datetime.now(datetime.timezone.utc),
            )
            emb_n.add_field(name="Invocacion completa", value=full_cmd[:1024], inline=False)
            emb_n.add_field(name="Usuario", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
            emb_n.add_field(name="Canal", value=ctx.channel.mention, inline=True)
            emb_n.add_field(name="Mensaje", value=f"[Abrir]({ctx.message.jump_url})", inline=True)
            await enviar_log(ctx.guild, emb_n)
    except Exception as e:
        _console_log("CMD_LOG_NOTIF_GUILD", "Fallo el log interno del server de notif", level="ERROR", guild_id=ctx.guild.id if ctx.guild else None, error=e)


@bot.event
async def on_command_completion(ctx):
    if not ctx.message:
        return
    full_cmd = _cmd_invocation_audit.pop(ctx.message.id, None)
    if not ctx.guild or ctx.guild.id != SERVER_NOTIF_ID or not full_cmd or not ctx.command:
        return
    await asyncio.sleep(0.4)
    resp_parts = []
    try:
        async for m in ctx.channel.history(limit=25, after=ctx.message, oldest_first=True):
            if m.author.id != bot.user.id:
                continue
            if m.content:
                resp_parts.append(m.content[:900])
            for em in m.embeds:
                frag = " ".join(filter(None, [em.title, (em.description or "")[:500]])).strip()
                if frag:
                    resp_parts.append(f"[embed] {frag}")
            if resp_parts:
                break
    except Exception:
        pass
    if not resp_parts:
        return
    emb_r = discord.Embed(
        title="Respuesta del bot (tras comando)",
        description="\n".join(resp_parts)[:3500],
        color=discord.Color.dark_green(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    emb_r.add_field(name="Comando", value=full_cmd[:1024], inline=False)
    emb_r.set_footer(text="LatamBOT | Log detallado")
    try:
        await enviar_log(ctx.guild, emb_r)
    except Exception:
        pass


@bot.listen("on_interaction")
async def audit_interactions(interaction: discord.Interaction):
    try:
        if not interaction.guild or not interaction.user or interaction.user.bot:
            return
        if interaction.guild.id != SERVER_NOTIF_ID:
            return
        data = interaction.data or {}
        interaction_type = str(getattr(interaction, "type", "unknown")).replace("InteractionType.", "")
        name = data.get("name") or "sin_nombre"
        custom_id = data.get("custom_id") or "sin_custom_id"
        component_type = data.get("component_type")
        location = interaction.channel.mention if interaction.channel else "canal-desconocido"
        detail = []
        if data.get("options"):
            opt_txt = []
            for opt in data.get("options", [])[:8]:
                if not isinstance(opt, dict):
                    continue
                opt_name = str(opt.get("name", "opt"))[:30]
                opt_val = _clip_text(str(opt.get("value", "")), 80)
                opt_txt.append(f"{opt_name}={opt_val}")
            if opt_txt:
                detail.append("opciones: " + ", ".join(opt_txt))
        if data.get("components"):
            detail.append("components=modal_submit")
        summary = "\n".join(detail) if detail else "Sin payload adicional"

        emb = discord.Embed(
            title="Interaccion con el bot",
            color=discord.Color(COLOR_INFO),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        emb.add_field(name="Tipo", value=interaction_type, inline=True)
        emb.add_field(name="Usuario", value=f"{interaction.user} (`{interaction.user.id}`)", inline=True)
        emb.add_field(name="Canal", value=location, inline=True)
        emb.add_field(name="Nombre", value=f"`{name}`", inline=True)
        emb.add_field(name="Custom ID", value=f"`{custom_id}`", inline=True)
        emb.add_field(name="Componente", value=f"`{component_type}`", inline=True)
        emb.add_field(name="Detalle", value=_clip_text(summary, 1000), inline=False)
        await enviar_log(interaction.guild, emb)
        canal_notif = await _get_notif_channel()
        if canal_notif:
            await canal_notif.send(
                f"[INTERACTION] {interaction.guild.name} | {interaction.user} | {interaction_type} | {name} | {custom_id}"
            )
    except Exception as e:
        _console_log("INTERACTION_AUDIT", "No pude registrar una interaccion", level="ERROR", error=e)


def _es_reply_a_embed_del_bot(msg) -> bool:
    """True si el mensaje es una respuesta a un embed enviado por el bot."""
    if not msg.reference:
        return False
    ref = msg.reference.cached_message
    if ref is None:
        return False
    # Si el mensaje referenciado es del bot y tiene embeds -> ignorar para IA/GEN
    return ref.author.id == bot.user.id and bool(ref.embeds)


def _extraer_imagen_de_mensaje(msg) -> Optional[str]:
    """Devuelve la URL de la primera imagen adjunta o embed del mensaje, si existe."""
    # Attachments de imagen directa
    for att in msg.attachments:
        if att.content_type and att.content_type.startswith("image/"):
            return att.url
        ext = att.filename.lower().rsplit(".", 1)[-1] if "." in att.filename else ""
        if ext in ("png", "jpg", "jpeg", "gif", "webp"):
            return att.url
    # Embeds con imagen
    for emb in msg.embeds:
        if emb.image and emb.image.url:
            return emb.image.url
        if emb.thumbnail and emb.thumbnail.url:
            return emb.thumbnail.url
    return None


# Guilds con alguna regla de autoreaccion que incluye bots (evita get_config en cada msg de bot).
_autoreaccion_scan_bots: set = set()
_AUTOREACCION_MAX_REGLAS = 15
_AUTOREACCION_MAX_EMOJIS = 3


def _autoreaccion_update_scan_flag(guild_id: int, cfg: dict) -> None:
    rules = cfg.get("autoreacciones") or []
    need = bool(cfg.get("autoreaccion_activo")) and any(
        isinstance(r, dict) and r.get("activo", True) and r.get("incluir_bots")
        for r in rules
    )
    if need:
        _autoreaccion_scan_bots.add(int(guild_id))
    else:
        _autoreaccion_scan_bots.discard(int(guild_id))


def _autoreaccion_match(rule: dict, msg) -> bool:
    """True si el mensaje cumple el match de la regla."""
    tipo = str(rule.get("match") or "contains")
    if tipo == "attachment":
        if msg.attachments:
            return True
        for emb in (msg.embeds or []):
            if getattr(emb, "image", None) and emb.image.url:
                return True
            if getattr(emb, "thumbnail", None) and emb.thumbnail.url:
                return True
        return False
    texto = msg.content or ""
    patron = str(rule.get("patron") or "")
    if not patron:
        return False
    if tipo == "regex":
        flags = 0 if rule.get("case_sensitive") else re.IGNORECASE
        try:
            return re.search(patron[:200], texto, flags) is not None
        except re.error:
            return False
    # contains (default)
    if rule.get("case_sensitive"):
        return patron in texto
    return patron.casefold() in texto.casefold()


async def _autoreaccion_aplicar(msg, rules: list) -> None:
    """Aplica emojis de las reglas que matchean. No reacciona a si mismo."""
    if not msg.guild or not rules:
        return
    if bot.user and msg.author.id == bot.user.id:
        return
    es_bot = bool(getattr(msg.author, "bot", False))
    emojis_out = []
    seen = set()
    for rule in rules:
        if not isinstance(rule, dict) or not rule.get("activo", True):
            continue
        if es_bot and not rule.get("incluir_bots"):
            continue
        scope = str(rule.get("scope") or "channel")
        if scope == "channel":
            try:
                cid = int(rule.get("canal_id") or 0)
            except (TypeError, ValueError):
                continue
            if cid != msg.channel.id:
                continue
        elif scope != "guild":
            continue
        if not _autoreaccion_match(rule, msg):
            continue
        for em in (rule.get("emojis") or [])[:_AUTOREACCION_MAX_EMOJIS]:
            em = str(em or "").strip()
            if em and em not in seen:
                seen.add(em)
                emojis_out.append(em)
        if len(emojis_out) >= 5:
            break
    for em in emojis_out[:5]:
        try:
            await asyncio.wait_for(msg.add_reaction(em), timeout=3.0)
        except Exception:
            pass


async def _autoreaccion_safe(msg, rules: list) -> None:
    try:
        await _autoreaccion_aplicar(msg, rules)
    except Exception as e:
        _console_log("AUTOREACCION", "Fallo al aplicar", level="ERROR", guild_id=getattr(msg.guild, "id", None), error=e)


@bot.event
async def on_message(msg):
    if not msg.guild:
        return
    # Bots: solo entrar si alguna regla pide incluir_bots (set en memoria).
    if msg.author.bot:
        if msg.guild.id in _autoreaccion_scan_bots:
            try:
                cfg_b = get_config(msg.guild.id) or {}
                if cfg_b.get("autoreaccion_activo"):
                    rules_b = list(cfg_b.get("autoreacciones") or [])
                    if rules_b:
                        await _autoreaccion_aplicar(msg, rules_b)
            except Exception as e:
                _console_log("AUTOREACCION", "Fallo en mensaje de bot", level="ERROR", guild_id=msg.guild.id, error=e)
        return
    cfg = get_config(msg.guild.id) or {}
    if cfg.get("autoreaccion_activo"):
        rules = list(cfg.get("autoreacciones") or [])
        if rules:
            _autoreaccion_update_scan_flag(msg.guild.id, cfg)
            asyncio.create_task(_autoreaccion_safe(msg, rules))
    prefix = cfg.get("prefix", "l!")
    server_mode = cfg.get("modo", "LEGACY")
    es_reply_al_bot = (
        msg.reference is not None
        and msg.reference.cached_message is not None
        and msg.reference.cached_message.author.id == bot.user.id
        and not _es_reply_a_embed_del_bot(msg)
    )

    # ── Blacklist global ───────────────────────────────────────────────────────
    if _is_blacklisted_user(msg.author.id):
        raw = (msg.content or "").strip()
        if raw.startswith(prefix) or bot.user.mentioned_in(msg) or es_reply_al_bot:
            try:
                await msg.reply(
                    embed=discord.Embed(
                        title="Acceso bloqueado",
                        description="No puedes usar comandos ni respuestas de IA desde esta cuenta.",
                        color=discord.Color(COLOR_PELIGRO),
                    ),
                    mention_author=False,
                    delete_after=8,
                )
            except Exception:
                pass
        return

    # Honeypot anti-estafas: cualquier mensaje humano en este canal implica ban.
    if cfg.get("honeypot_canal") and msg.channel.id == int(cfg.get("honeypot_canal")):
        autor_es_staff_hp = (msg.author.id in {OWNER_ID, msg.guild.owner_id}) or getattr(msg.author.guild_permissions, "administrator", False)
        if autor_es_staff_hp:
            # Staff/owner: no banear, borrar en silencio (sin delatar el canal)
            try:
                await msg.delete()
            except Exception:
                pass
            return
        # Seguro anti-baneo-de-humanos: solo banear cuentas con pinta de raid
        if cfg.get("honeypot_solo_sospechosos", True) and not _es_sospechoso_raid(msg.author):
            try:
                await msg.delete()
            except Exception:
                pass
            try:
                await msg.author.send(embed=_make_embed(
                    "Ojo con ese canal",
                    f"En **{msg.guild.name}** ese canal es solo de anuncios, mejor no escribas ahí. Tu mensaje se borró, no te preocupes.",
                    COLOR_ADVERTENCIA,
                ))
            except Exception:
                pass
            return
        try:
            await msg.delete()
        except Exception:
            pass
        try:
            await _ban_honeypot_member(msg.guild, msg.author)
            # Reputacion cross-server: marcar que cayo en el honeypot
            _rep_registrar_honeypot(msg.author.id, str(msg.author), msg.guild)
            # ── Contador de baneos del honeypot ──────────────────────────────
            total_bans = int(cfg.get("honeypot_bans", 0) or 0) + 1
            update_server_config(msg.guild.id, "honeypot_bans", total_bans)
            historial = list(cfg.get("honeypot_baneados", []) or [])
            historial.append({
                "id": msg.author.id,
                "name": str(msg.author),
                "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            })
            update_server_config(msg.guild.id, "honeypot_baneados", historial[-25:])
            await _log_staff_action(
                msg.guild,
                title="Honeypot: usuario baneado",
                color=COLOR_PELIGRO,
                actor=bot.user,
                target=msg.author,
                fields=[
                    ("Canal", msg.channel.mention, True),
                    ("Mensajes borrados", "Ultimos 10 minutos", True),
                    ("Total baneos honeypot", f"**{total_bans}**", True),
                ],
                tag="HONEYPOT",
            )
        except Exception as e:
            await enviar_log(msg.guild, _make_error_embed("Honeypot fallo al banear", f"{msg.author} (`{msg.author.id}`)\n{_safe_exc_text(e)}", _exception_fix_hint(e)))
        return

    # ── Anti-estafa por imagen (dHash contra base compartida) ────────────────
    if cfg.get("scam_activo") and (msg.attachments or msg.embeds) and not es_staff(msg):
        try:
            if await _scam_revisar_mensaje(msg, cfg):
                return  # el mensaje fue borrado/sancionado
        except Exception as e:
            _console_log("ANTISCAM", "Fallo revisando imagen de scam", level="ERROR", guild_id=msg.guild.id, error=e)

    # ── Contador comunitario ─────────────────────────────────────────────────
    if msg.channel.id in _conteo_activo:
        estado = _conteo_activo[msg.channel.id]
        esperado = estado["num"] + 1
        try:
            num = int(msg.content.strip())
            if num == esperado and msg.author.id != estado.get("ultimo"):
                estado["num"] = esperado
                estado["ultimo"] = msg.author.id
                if num % 100 == 0:
                    await msg.add_reaction("🎉")
                elif num % 10 == 0:
                    await msg.add_reaction("✅")
                else:
                    await msg.add_reaction("✅")
            elif msg.author.id == estado.get("ultimo"):
                await msg.add_reaction("❌")
                await msg.channel.send(f"❌ {msg.author.mention} ¡No podés escribir dos números seguidos! El conteo vuelve a **0**.", delete_after=8)
                estado["num"] = 0
                estado["ultimo"] = 0
            else:
                await msg.add_reaction("❌")
                await msg.channel.send(f"❌ {msg.author.mention} ¡Error! Era **{esperado}**. El conteo vuelve a **0**.", delete_after=8)
                estado["num"] = 0
                estado["ultimo"] = 0
        except ValueError:
            pass  # Ignorar mensajes que no son números en canal de contador

    # ── Anti-raid: menciones masivas ──────────────────────────────────────────
    if cfg.get("antiraid_menciones", True) and not es_staff(msg):
        distintas = len({u.id for u in msg.mentions if not u.bot and u.id != msg.author.id})
        if distintas >= int(cfg.get("menciones_max", 8) or 8):
            try:
                await msg.delete()
            except Exception:
                pass
            await _raid_castigar(msg.author, msg.channel, msg.guild, "menciones masivas", f"{distintas} usuarios mencionados en un mensaje")
            return

    # Anti-Spam (funciona para todos)
    if await check_spam(msg):
        return

    # ── Notificaciones por keyword (DM a quien la registró) ────────────────────
    _gmap = _notify_cache.get(msg.guild.id)
    if _gmap and msg.content:
        _texto = msg.content.lower()
        _avisados = set()
        for _w, _users in list(_gmap.items()):
            if _w in _texto and re.search(r"(?<!\w)" + re.escape(_w) + r"(?!\w)", _texto):
                for _uid in _users:
                    if _uid == msg.author.id or _uid in _avisados:
                        continue
                    _m = msg.guild.get_member(_uid)
                    if not _m or not msg.channel.permissions_for(_m).read_messages:
                        continue
                    _avisados.add(_uid)
                    try:
                        await _m.send(embed=_make_embed(
                            f"🔔 Mencionaron «{_w}»",
                            f"En **{msg.guild.name}** · {msg.channel.mention}\n**{msg.author.display_name}:** {_clip_text(msg.content, 300)}\n\n[Ir al mensaje]({msg.jump_url})",
                            COLOR_INFO))
                    except Exception:
                        pass

    # Rastrear actividad del usuario
    hoy = datetime.date.today().isoformat()
    uid = msg.author.id
    if uid not in actividad_usuarios or actividad_usuarios[uid].get("fecha") != hoy:
        actividad_usuarios[uid] = {"mensajes": 0, "fecha": hoy, "guild_id": msg.guild.id}
    actividad_usuarios[uid]["mensajes"] = actividad_usuarios[uid].get("mensajes", 0) + 1

    # AFK
    global afk_usuarios
    if msg.author.id in afk_usuarios:
        del afk_usuarios[msg.author.id]
        try:
            await msg.channel.send(f"👋 {msg.author.mention} volvio. AFK removido.", delete_after=5)
        except:
            pass
    for user in msg.mentions:
        if user.id in afk_usuarios:
            await msg.reply(f"💤 **{user.name}** esta AFK: {afk_usuarios[user.id]}", delete_after=10)

    # XP por mensaje (sistema de niveles; no hace nada si está apagado)
    try:
        await _procesar_xp(msg)
    except Exception as _e:
        print(f"[XP] {_e}")

    raw_parts = (msg.content or "").strip().split(maxsplit=1)
    invoked_name = raw_parts[0][len(prefix):].lower() if raw_parts and raw_parts[0].startswith(prefix) else ""
    staff_banword_command = invoked_name in {"banword", "unbanword", "banwordlist"} and es_staff(msg)
    banned_word = None if msg.author.id == OWNER_ID or staff_banword_command else _find_banned_word(msg.content, cfg.get("palabras_prohibidas", []))
    if banned_word:
        try:
            await msg.delete()
        except Exception:
            pass
        try:
            aviso = discord.Embed(
                title="Mensaje eliminado",
                description=f"{msg.author.mention}, ese mensaje contenia una palabra bloqueada por este servidor.",
                color=discord.Color(COLOR_PELIGRO),
            )
            aviso.add_field(name="Canal", value=msg.channel.mention, inline=True)
            await msg.channel.send(embed=aviso, delete_after=8)
        except Exception:
            pass
        await _log_staff_action(
            msg.guild,
            title="Banword activado",
            color=COLOR_PELIGRO,
            actor=msg.author,
            target=msg.author,
            fields=[
                ("Canal", msg.channel.mention, True),
                ("Palabra", banned_word, True),
                ("Contenido", _clip_text(msg.content or "(sin texto)", 800), False),
            ],
            notify_owner=False,
            tag="BANWORD",
        )
        return


    # ── MODO GEN ──────────────────────────────────────────────────────────────
    # Solo activo cuando el modo del server ES "GEN", sin IA, sin replies a embeds del bot
    if msg.author.id in _get_uwu_targets(msg.guild.id):
        if user_prefs.get(msg.author.id, {}).get("uwu_opt_out", False):
            _set_uwu_state(msg.guild.id, msg.author.id, False)
        elif not msg.content.startswith(prefix):
            if await _relay_uwu_message(msg):
                return

    if (
        server_mode == "GEN"
        and cfg.get("sistema_gen")
        and server_permitido(msg.guild.id)
        and not msg.content.startswith(prefix)
        and not _es_reply_a_embed_del_bot(msg)
    ):
        cid = msg.channel.id
        if cid not in historial_chat_gen:
            historial_chat_gen[cid] = []
        # Solo guardar mensajes con texto real
        if msg.content.strip():
            entry = f"{msg.author.display_name}: {msg.content[:200]}"
            historial_chat_gen[cid].append(entry)
            historial_chat_gen[cid] = historial_chat_gen[cid][-40:]

        contador_gen[cid] = contador_gen.get(cid, 0) + 1
        if contador_gen[cid] >= GEN_INTERVALO:
            contador_gen[cid] = 0
            if historial_chat_gen[cid]:
                collage = generar_collage_gen(historial_chat_gen[cid])
                gif = await _get_rp_gif(random.choice(GIFS_GEN_CATS))
                embed_gen = discord.Embed(
                    description=collage,
                    color=discord.Color.from_rgb(
                        random.randint(80, 255),
                        random.randint(80, 255),
                        random.randint(80, 255)
                    )
                )
                embed_gen.set_image(url=gif)
                embed_gen.set_footer(text="Modo GEN | LatamBOT")
                await msg.channel.send(embed=embed_gen)

    # ── AUTOMOD: filtro de palabras (rapidfuzz, anti-evasión) ──────────────────
    if cfg and cfg.get("automod_palabras") and msg.content and not es_staff(msg):
        mala = _detectar_palabra_prohibida(msg.content, cfg.get("palabras_bloqueadas", []))
        if mala:
            try:
                await msg.delete()
            except Exception:
                pass
            await msg.channel.send(
                f"{msg.author.mention} tu mensaje fue eliminado por contener una palabra no permitida.",
                delete_after=8)
            await registrar_infraccion(msg.guild, msg.author, f"AutoMod palabras: «{mala}»")
            return

    # ── AUTOMODER IA ANUNCIOS ──────────────────────────────────────────────────
    if cfg and cfg.get("sistema_anuncios") and server_permitido(msg.guild.id):
        es_anuncio = msg.channel.name.startswith("anuncios-") or (
            cfg.get("cat_anuncios") and msg.channel.category_id == cfg.get("cat_anuncios")
        )
        if es_anuncio and not es_staff(msg):
            es_inseguro, razon = await analizar_seguridad_anuncio(msg.content)
            if es_inseguro:
                await msg.delete()
                await msg.channel.send(
                    f"{msg.author.mention} Mensaje eliminado por AutoMod IA.\n**Detectado:** {razon}",
                    delete_after=15
                )
                await registrar_infraccion(msg.guild, msg.author, f"AutoMod IA: {razon}")
                return

    # ── STICKY ────────────────────────────────────────────────────────────────
    if msg.channel.id in sticky_contenido:
        asyncio.create_task(refrescar_sticky(msg.channel))

    # ── BOT SILENCIADO ────────────────────────────────────────────────────────
    global bot_silenciado_hasta
    if bot_silenciado_hasta and datetime.datetime.now() < bot_silenciado_hasta:
        return
    else:
        bot_silenciado_hasta = None

    # Modo molesto - corregir mensajes
    await _aplicar_modo_molesto(msg)

    # ── CHATBOT POR MENCION / MENU ────────────────────────────────────────────
    if not msg.content.startswith(prefix) and (bot.user.mentioned_in(msg) or es_reply_al_bot) and not msg.mention_everyone and not _es_reply_a_embed_del_bot(msg):
        texto_vacio = _mention_texto_vacio(msg)
        if texto_vacio:
            emb = discord.Embed(
                title="¿Qué necesitás?",
                description=(
                    "Elegí una opción. Si me escribís algo junto a la mención "
                    "(`@LatamBOT hola`), te respondo con IA directo."
                ),
                color=discord.Color(COLOR_PRIMARIO),
            )
            await msg.reply(
                embed=emb,
                view=MentionActionView(msg),
                mention_author=False,
            )
            return
        await _handle_ia_mencion(msg, es_reply_al_bot)
        return

    # ── TRIGGERS ─────────────────────────────────────────────────────────────
    if cfg and not msg.content.startswith(prefix) and not msg.author.bot:
        triggers = cfg.get("triggers", {})
        if triggers:
            msg_lower = msg.content.lower().strip()
            for palabra, respuesta in triggers.items():
                if palabra in msg_lower:
                    await msg.channel.send(respuesta)
                    break  # Solo un trigger por mensaje

    # Tracking de actividad
    if not msg.author.bot:
        hoy = datetime.date.today().isoformat()
        uid = msg.author.id
        if uid not in actividad_usuarios or actividad_usuarios[uid].get("fecha") != hoy:
            actividad_usuarios[uid] = {"mensajes": 0, "fecha": hoy, "guild_id": msg.guild.id}
        actividad_usuarios[uid]["mensajes"] = actividad_usuarios[uid].get("mensajes", 0) + 1

    # Alias del servidor: reescribe l!<alias> por el comando real antes de procesarlo.
    _al = (cfg.get("alias") or {}) if cfg else {}
    if _al and msg.content.startswith(prefix):
        _resto = msg.content[len(prefix):].lstrip()
        _partes = _resto.split(maxsplit=1)
        if _partes:
            _destino = _al.get(_partes[0].lower())
            if _destino and not bot.get_command(_partes[0].lower()):
                _args = _partes[1] if len(_partes) > 1 else ""
                msg.content = f"{prefix}{_destino} {_args}".rstrip()

    await bot.process_commands(msg)

