@bot.command()
@commands.check(es_staff)
async def clearwarns(ctx, m: discord.Member):
    error = _validate_member_action(ctx, m, "editar el historial de")
    if error:
        await ctx.send(embed=_make_embed("Accion bloqueada", error, COLOR_PELIGRO))
        return
    _set_warn_count(m.id, 0)
    await ctx.send(embed=_make_embed("Warns limpiados", f"Reinicie el historial de {m.mention}.", COLOR_EXITO))
    await _log_staff_action(
        ctx.guild,
        title="Warns limpiados",
        color=COLOR_EXITO,
        actor=ctx.author,
        target=m,
        fields=[("Canal", ctx.channel.mention, True)],
        notify_owner=True,
        tag="WARN_CLEAR",
    )

@bot.command()
@commands.check(es_staff)
async def mute(ctx, m: discord.Member, t: str, *, r="Comportamiento inadecuado"):
    error = _validate_member_action(ctx, m, "silenciar")
    if error:
        await ctx.send(embed=_make_embed("Accion bloqueada", error, COLOR_PELIGRO))
        return
    seg = convertir_duracion(t)
    if not seg:
        await ctx.send(embed=_make_embed("Duracion invalida", "Usa un formato como `10m`, `1h`, `1d` o `7d`.", COLOR_ADVERTENCIA))
        return
    if seg > 28 * 24 * 3600:
        await ctx.send(embed=_make_embed("Duracion demasiado larga", "Discord solo permite timeouts de hasta 28 dias.", COLOR_ADVERTENCIA))
        return
    duracion = datetime.timedelta(seconds=seg)
    fin = int((datetime.datetime.now() + duracion).timestamp())
    try:
        await m.timeout(duracion, reason=r)
        await crear_caso(ctx.guild, "timeout", m, ctx.author, r, duracion=formato_tiempo(seg))
        embed = discord.Embed(title="🔇 Usuario Silenciado", color=discord.Color.dark_grey(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed.set_thumbnail(url=m.display_avatar.url)
        embed.add_field(name="Usuario", value=f"{m.mention} `({m.id})`", inline=True)
        embed.add_field(name="Staff", value=ctx.author.mention, inline=True)
        embed.add_field(name="Duracion", value=f"{formato_tiempo(seg)} | termina <t:{fin}:R>", inline=False)
        embed.add_field(name="Motivo", value=_clip_text(r, 900), inline=False)
        await ctx.send(embed=embed)
        embed_log = discord.Embed(title="🔇 Timeout aplicado", color=discord.Color.dark_grey(), timestamp=datetime.datetime.now(datetime.timezone.utc))
        _metric_bump("moderation_actions")
        await _log_staff_action(
            ctx.guild,
            title="Mute aplicado",
            color=COLOR_ADVERTENCIA,
            actor=ctx.author,
            target=m,
            reason=r,
            fields=[("Duracion", formato_tiempo(seg), True), ("Canal", ctx.channel.mention, True), ("Finaliza", f"<t:{fin}:F>", False)],
            notify_owner=True,
            tag="MUTE",
        )
        embed_log.add_field(name="Usuario", value=f"{m} (`{m.id}`)", inline=True)
        embed_log.add_field(name="Por", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
        embed_log.add_field(name="Duracion", value=formato_tiempo(seg), inline=True)
        embed_log.add_field(name="Razon", value=r, inline=False)
        await enviar_log(ctx.guild, embed_log)
    except discord.Forbidden:
        await ctx.send(embed=_make_embed("Sin permisos", "No pude aplicar el timeout. Revisa jerarquia de roles y permisos del bot.", COLOR_PELIGRO))

@bot.command()
@commands.check(es_staff)
async def unmute(ctx, m: discord.Member):
    try:
        await m.timeout(None)
        embed = discord.Embed(
            title="Usuario Desmuteado",
            description=f"{m.mention} puede hablar nuevamente.",
            color=discord.Color.green()
        )
        embed.set_footer(text=f"Por {ctx.author}")
        await ctx.send(embed=embed)
    except Exception as e:
        embed = discord.Embed(title="Error", description=str(e), color=discord.Color.red())
        await ctx.send(embed=embed)

@bot.command()
@commands.check(es_staff)
async def kick(ctx, m: discord.Member, *, r="Sin razon especificada"):
    """Expulsa a un usuario del servidor."""
    if m.id == ctx.author.id:
        await ctx.send(embed=discord.Embed(description="No puedes expulsarte a ti mismo.", color=discord.Color(COLOR_PELIGRO)))
        return
    error = _validate_member_action(ctx, m, "advertir")
    if error:
        await ctx.send(embed=_make_embed("Accion bloqueada", error, COLOR_PELIGRO))
        return
    if ctx.author.top_role <= m.top_role and ctx.author.id != ctx.guild.owner_id:
        await ctx.send(embed=discord.Embed(description="No puedes expulsar a alguien con rol igual o superior al tuyo.", color=discord.Color(COLOR_PELIGRO)))
        return
    try:
        try:
            await m.send(embed=discord.Embed(
                title=f"👢 Has sido expulsado de {ctx.guild.name}",
                description=f"**Razon:** {r}\n**Moderador:** {ctx.author}",
                color=discord.Color(COLOR_ADVERTENCIA)
            ))
        except:
            pass
        await m.kick(reason=f"{r} | Por: {ctx.author}")
        await crear_caso(ctx.guild, "kick", m, ctx.author, r)
        embed = discord.Embed(title="👢 Usuario Expulsado", color=discord.Color(COLOR_ADVERTENCIA), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed.set_thumbnail(url=m.display_avatar.url)
        embed.add_field(name="Usuario", value=f"{m.mention}\n`{m} ({m.id})`", inline=True)
        embed.add_field(name="Moderador", value=ctx.author.mention, inline=True)
        embed.add_field(name="Razon", value=r, inline=False)
        embed.set_footer(text=f"ID: {m.id}")
        await ctx.send(embed=embed)
        embed_log = discord.Embed(title="👢 Kick ejecutado", color=discord.Color(COLOR_ADVERTENCIA), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario", value=f"{m} (`{m.id}`)", inline=True)
        embed_log.add_field(name="Por", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
        embed_log.add_field(name="Razon", value=r, inline=False)
        await enviar_log(ctx.guild, embed_log)
    except discord.Forbidden:
        await ctx.send(embed=discord.Embed(description="Sin permisos para expulsar.", color=discord.Color(COLOR_PELIGRO)))
@bot.command()
@commands.check(es_staff)
async def softban(ctx, m: discord.Member, *, r="Softban"):
    if ctx.guild.me.top_role <= m.top_role:
        await ctx.send("Mi rol es demasiado bajo.")
        return
    try:
        await m.ban(reason=f"Softban: {r}", delete_message_days=7)
        await ctx.guild.unban(m, reason="Softban completado")
        embed = discord.Embed(
            title="Softban Aplicado",
            description=f"`{m.name}` fue softbaneado. Mensajes de los ultimos 7 dias eliminados.",
            color=discord.Color.dark_orange()
        )
        embed.add_field(name="Razon", value=r)
        embed.add_field(name="Moderador", value=ctx.author.mention)
        await ctx.send(embed=embed)
    except Exception as e:
        await ctx.send(f"Error: {e}")

@bot.command()
@commands.check(es_staff)
async def tempban(ctx, m: discord.Member, t: str, *, r="Baneo temporal"):
    if ctx.guild.me.top_role <= m.top_role:
        await ctx.send("Mi rol es demasiado bajo.")
        return
    seg = convertir_duracion(t)
    if not seg:
        await ctx.send("Ej: `l!tempban @user 7d spam`")
        return
    try:
        try: await m.send(f"Baneo temporal en **{ctx.guild.name}** por {formato_tiempo(seg)}. Razon: {r}")
        except: pass
        await m.ban(reason=f"TempBan ({formato_tiempo(seg)}): {r}", delete_message_days=1)
        embed = discord.Embed(
            title="Baneo Temporal",
            description=f"`{m.name}` baneado por **{formato_tiempo(seg)}**.",
            color=discord.Color.dark_red()
        )
        embed.add_field(name="Razon", value=r)
        embed.add_field(name="Moderador", value=ctx.author.mention)
        await ctx.send(embed=embed)
        await asyncio.sleep(seg)
        try:
            await ctx.guild.unban(m, reason="TempBan expirado")
        except:
            pass
    except Exception as e:
        await ctx.send(f"Error: {e}")

@bot.command()
@commands.check(es_staff)
async def warnings(ctx, m: discord.Member):
    user_data = get_usuario(m.id)
    warns = user_data.get("warns", 0)
    color = discord.Color.green() if warns == 0 else (discord.Color.orange() if warns < 3 else discord.Color.red())
    embed = discord.Embed(title=f"Expediente: {m.name}", color=color)
    embed.add_field(name="Warns", value=f"**{warns}**")
    estado = "Limpio" if warns == 0 else ("Precaucion" if warns < 5 else "Critico")
    embed.add_field(name="Estado", value=estado)
    await ctx.send(embed=embed)

@bot.command()
@commands.has_permissions(administrator=True)
async def nuke(ctx):
    pos = ctx.channel.position
    nuevo = await ctx.channel.clone(reason="Nuke")
    await nuevo.edit(position=pos)
    await ctx.channel.delete()
    await nuevo.send("**Canal Nukeado.**\nhttps://tenor.com/view/ash-baby-gif-5920695394641505768")

@bot.command()
@commands.check(es_staff)
async def announce(ctx, canal: discord.TextChannel, *, mensaje: str):
    embed = discord.Embed(description=mensaje, color=discord.Color.blurple())
    embed.set_author(name=ctx.author.display_name, icon_url=ctx.author.avatar.url if ctx.author.avatar else None)
    embed.set_footer(text=f"Anuncio de {ctx.guild.name}")
    await canal.send(embed=embed)
    await ctx.send(f"Anuncio enviado a {canal.mention}.", delete_after=5)
    try:
        await ctx.message.delete()
    except:
        pass

def _esta_opt_out_snipe(user_id: int) -> bool:
    return bool(user_prefs.get(user_id, {}).get("snipe_opt_out", False))


class SnipeOptInView(discord.ui.View):
    """Botón para que un usuario opted-out vuelva a entrar a snipe (des-opt out)."""
    def __init__(self, user_id: int):
        super().__init__(timeout=180)
        self.user_id = user_id

    @discord.ui.button(label="Reactivar snipe (des-opt out)", emoji="🔓", style=discord.ButtonStyle.success)
    async def desoptout(self, i: discord.Interaction, b):
        if i.user.id != self.user_id:
            await i.response.send_message("Este botón es solo para vos.", ephemeral=True)
            return
        prefs = dict(user_prefs.get(self.user_id, {}))
        prefs["snipe_opt_out"] = False
        user_prefs[self.user_id] = prefs
        _save_runtime_state()
        b.disabled = True
        await i.response.edit_message(
            embed=_make_embed("Snipe reactivado 🔓", "Volviste a snipe: tus mensajes borrados se podrán snipear y ya podés usar `l!snipe` de nuevo.", COLOR_EXITO),
            view=self,
        )


async def _bloquear_si_opt_out_snipe(ctx) -> bool:
    """Si el autor está opted-out de snipe, le avisa (con botón des-opt out) y devuelve True."""
    if _esta_opt_out_snipe(ctx.author.id):
        await ctx.send(
            embed=_make_embed(
                "Estás fuera de snipe 👻",
                "Tenés activado el **opt-out de snipe**, así que no podés usarlo (es recíproco: si tus mensajes no aparecen, tampoco mirás los de otros).\n\n"
                "Reactivalo con el botón de abajo o desde `l!configuracion`.",
                COLOR_ADVERTENCIA,
            ),
            view=SnipeOptInView(ctx.author.id),
        )
        return True
    return False


# ── Comandos del sistema de XP ────────────────────────────────────────────────
@bot.command(aliases=["nivel", "level"])
async def rank(ctx, miembro: discord.Member = None):
    """Muestra tu nivel y XP (o el de otro). Requiere el sistema de niveles activado."""
    cfg = get_config(ctx.guild.id) or {}
    if not cfg.get("sistema_xp"):
        await ctx.send(embed=_make_embed("Niveles desactivados", "El sistema de XP no está activado en este servidor. Actívalo en `l!setup` o el panel web.", COLOR_ADVERTENCIA))
        return
    target = miembro or ctx.author
    g = _xp.get(ctx.guild.id, {})
    total = g.get(target.id, 0)
    lvl = _level_from_total(total)
    base = _total_xp_for_level(lvl)
    cur = total - base
    need = _xp_to_next(lvl)
    orden = sorted(g.items(), key=lambda x: x[1], reverse=True)
    pos = next((i + 1 for i, (uid, _) in enumerate(orden) if uid == target.id), len(orden) + 1)
    embed = _make_embed(f"Nivel de {target.display_name}", color=COLOR_PRIMARIO)
    embed.set_thumbnail(url=target.display_avatar.url)
    embed.add_field(name="Nivel", value=f"**{lvl}**", inline=True)
    embed.add_field(name="Ranking", value=f"#{pos}", inline=True)
    embed.add_field(name="XP total", value=_h_numero(total), inline=True)
    embed.add_field(name=f"Progreso al nivel {lvl + 1}  ({cur}/{need} XP)", value=_barra_progreso(cur, need), inline=False)
    await ctx.send(embed=embed)


@bot.command(aliases=["leaderboard", "niveles", "ranking"])
async def top(ctx):
    """Top 10 de niveles del servidor."""
    cfg = get_config(ctx.guild.id) or {}
    if not cfg.get("sistema_xp"):
        await ctx.send(embed=_make_embed("Niveles desactivados", "El sistema de XP no está activado. Actívalo en `l!setup` o el panel.", COLOR_ADVERTENCIA))
        return
    g = _xp.get(ctx.guild.id, {})
    orden = sorted(g.items(), key=lambda x: x[1], reverse=True)[:10]
    if not orden:
        await ctx.send(embed=_make_embed(f"{EMOJI_SAD} Top de niveles", "Todavía nadie ganó XP. ¡A chatear!", COLOR_INFO))
        return
    lineas = []
    for i, (uid, xp) in enumerate(orden, 1):
        m = ctx.guild.get_member(uid)
        nombre = m.display_name if m else f"Usuario {uid}"
        medalla = ["🥇", "🥈", "🥉"][i - 1] if i <= 3 else f"`#{i}`"
        lineas.append(f"{medalla} **{nombre}** - Nivel {_level_from_total(xp)} · {_h_numero(xp)} XP")
    embed = _make_embed(f"🏆 Top de niveles · {ctx.guild.name}", "\n".join(lineas), COLOR_PRIMARIO)
    embed.set_footer(text="LatamBOT · niveles")
    await ctx.send(embed=embed)


@bot.command(name="xprole", aliases=["nivelrol", "levelrole"])
@commands.check(es_staff)
async def xprole(ctx, nivel: int = None, rol: discord.Role = None):
    """[Staff] Da un rol al llegar a un nivel. `l!xprole <nivel> <@rol>`."""
    cfg = get_config(ctx.guild.id) or {}
    roles = dict(cfg.get("xp_roles", {}) or {})
    if nivel is None:
        if not roles:
            await ctx.send(embed=_make_embed("Recompensas de nivel", "No hay roles por nivel.\nAgregá con `l!xprole <nivel> <@rol>`.", COLOR_INFO))
            return
        lista = "\n".join(f"Nivel **{n}** → <@&{r}>" for n, r in sorted(roles.items(), key=lambda x: int(x[0])))
        await ctx.send(embed=_make_embed("🎁 Recompensas de nivel", lista, COLOR_PRIMARIO))
        return
    if rol is None:
        roles.pop(str(nivel), None)
        update_server_config(ctx.guild.id, "xp_roles", roles)
        await ctx.send(embed=_make_embed("Recompensa quitada", f"El nivel **{nivel}** ya no da rol.", COLOR_EXITO))
        return
    peligro = _rol_verif_peligroso(rol)
    if peligro:
        await ctx.send(embed=_make_error_embed(
            "Rol peligroso",
            f"{rol.mention} tiene el permiso **{peligro}** y no se puede dar por nivel.",
            "Elegí un rol sin permisos de moderación/admin.",
        ))
        return
    roles[str(nivel)] = rol.id
    update_server_config(ctx.guild.id, "xp_roles", roles)
    await ctx.send(embed=_make_embed("Recompensa de nivel", f"Al llegar al **nivel {nivel}** se dará {rol.mention}.", COLOR_EXITO))


