@bot.command()
async def snipe(ctx, *args):
    """Ultimos mensajes borrados (hasta 25). Uso: l!snipe | l!snipe 2 | l!snipe imagen | l!snipe tupper"""
    if await _bloquear_si_opt_out_snipe(ctx):
        return
    cfgp = get_config(ctx.guild.id) or {}
    pref = cfgp.get("prefix", "l!")
    raw = [str(a).lower() for a in args]

    if raw and raw[0] == "tupper":
        data = snipe_cache_tupper.get(ctx.channel.id)
        if not data or data.get("_error"):
            await ctx.send(embed=discord.Embed(
                description=f"{EMOJI_SAD} No hay mensajes de tupper borrados recientes en este canal.",
                color=discord.Color(COLOR_INFO)
            ))
            return
    else:
        hist = list(snipe_history.get(ctx.channel.id, []))
        if not hist:
            try:
                remote = await _pi_archive_snipe_get(ctx.channel.id, SNIPE_HIST_MAX)
                if remote:
                    rebuilt = deque(maxlen=SNIPE_HIST_MAX)
                    for it in reversed(remote):
                        rebuilt.appendleft({
                            "author": it.get("author") or "?",
                            "author_avatar": it.get("author_avatar") or "",
                            "author_id": it.get("author_id"),
                            "content": it.get("content") or "",
                            "attachments": it.get("attachments") or [],
                            "images": it.get("images") or [],
                            "stickers": [],
                            "time": datetime.datetime.now(),
                            "es_tupper": False,
                            "embeds": [],
                        })
                    snipe_history[ctx.channel.id] = rebuilt
                    hist = list(rebuilt)
            except Exception as _se:
                print(f"[SNIPE] pi restore {_se}")
        if raw and raw[0] in ("lista", "list", "historial"):
            if not hist:
                marker = snipe_optout_markers.get(ctx.channel.id)
                if marker:
                    await ctx.send(embed=discord.Embed(description="Hay un mensaje borrado reciente, pero esa persona esta fuera de snipe (opt-out).", color=discord.Color(COLOR_INFO)))
                    return
                await ctx.send(embed=discord.Embed(description=f"{EMOJI_SAD} No hay mensajes borrados recientes en este canal.", color=discord.Color(COLOR_INFO)))
                return
            lineas = []
            for pos, item in enumerate(hist[:min(len(hist), 10)], start=1):
                flags = []
                if item.get("images"):
                    flags.append("img")
                if item.get("attachments"):
                    flags.append("adj")
                if item.get("stickers"):
                    flags.append("sticker")
                if item.get("embeds"):
                    flags.append("embed")
                resumen = _clip_text((item.get("content") or "").replace("\n", " "), 70) or "*sin texto*"
                marca = f" [{', '.join(flags)}]" if flags else ""
                lineas.append(f"`{pos}` **{item.get('author','?')}**{marca}: {resumen}")
            embed = discord.Embed(
                title=f"Snipe reciente en #{ctx.channel.name}",
                description="\n".join(lineas),
                color=discord.Color(COLOR_INFO),
            )
            embed.set_footer(text=f"Usa {pref}snipe <numero> para abrir uno concreto")
            await ctx.reply(embed=embed, mention_author=False)
            return
        idx = 0
        filtro = None
        off = 0
        if raw and raw[0].isdigit():
            n = int(raw[0])
            if n < 1 or n > SNIPE_HIST_MAX:
                await ctx.send(embed=discord.Embed(
                    description=f"Indice invalido. Usa un numero entre **1** y **{SNIPE_HIST_MAX}** (1 = el mas reciente).",
                    color=discord.Color(COLOR_ADVERTENCIA)
                ))
                return
            idx = n - 1
            off = 1
        if off < len(raw):
            filtro = raw[off]

        data = None
        if filtro == "imagen":
            for j in range(idx, len(hist)):
                if hist[j].get("images"):
                    data = hist[j]
                    break
            if not data:
                await ctx.send(embed=discord.Embed(
                    description="No hay mensajes borrados con imagen en ese rango.",
                    color=discord.Color(COLOR_ADVERTENCIA)
                ))
                return
        elif filtro == "texto":
            for j in range(idx, len(hist)):
                if (hist[j].get("content") or "").strip():
                    data = hist[j]
                    break
            if not data:
                await ctx.send(embed=discord.Embed(
                    description="No hay mensajes borrados con texto en ese rango.",
                    color=discord.Color(COLOR_ADVERTENCIA)
                ))
                return
        elif filtro in (None, "normal", "all"):
            marker = snipe_optout_markers.get(ctx.channel.id)
            if idx == 0 and marker and (not hist or marker.get("time") > hist[0].get("time")):
                await ctx.send(embed=discord.Embed(
                    description="El ultimo mensaje borrado de este canal pertenece a alguien fuera de snipe (opt-out). No puedo mostrar contenido ni autor.",
                    color=discord.Color(COLOR_INFO)
                ))
                return
            if idx >= len(hist):
                tupper_data = snipe_cache_tupper.get(ctx.channel.id)
                marker = snipe_optout_markers.get(ctx.channel.id)
                if tupper_data:
                    await ctx.send(embed=discord.Embed(
                        description=(
                            f"No hay tantos mensajes en el historial de snipe (hay **{len(hist)}**).\n"
                            "Hay un tupper borrado: usa `" + pref + "snipe tupper`."
                        ),
                        color=discord.Color(COLOR_INFO)
                    ))
                elif marker:
                    await ctx.send(embed=discord.Embed(
                        description="Hay un mensaje borrado reciente, pero esa persona esta fuera de snipe (opt-out).",
                        color=discord.Color(COLOR_INFO)
                    ))
                else:
                    await ctx.send(embed=discord.Embed(
                        description=(
                            f"No hay mensajes borrados recientes en ese indice (hay **{len(hist)}** en el historial)."
                        ),
                        color=discord.Color(COLOR_INFO)
                    ))
                return
            data = hist[idx]
        else:
            await ctx.send(embed=discord.Embed(
                description=f"Filtro desconocido. Usa `{pref}snipe`, `{pref}snipe lista`, `{pref}snipe 2`, `{pref}snipe imagen`, `{pref}snipe texto` o `{pref}snipe tupper`.",
                color=discord.Color(COLOR_ADVERTENCIA)
            ))
            return

    prefs_sn = user_prefs.get(ctx.author.id, {})
    if prefs_sn.get("tips_minimos"):
        opt_txt = f"Opt-out snipe: `{pref}configuracion`"
    else:
        opt_txt = f"Privacidad: podes ocultar tus borrados con `{pref}configuracion` (opt-out Snipe)."
    es_tupper = data.get("es_tupper", False)
    color = discord.Color.from_rgb(180, 120, 255) if es_tupper else discord.Color.red()
    borrado_dt = discord.utils.format_dt(data["time"], "R")

    embed = discord.Embed(color=color, timestamp=data["time"])

    if es_tupper:
        embed.set_author(
            name=f"🪆 {data['author']}",
            icon_url=data.get("author_avatar")
        )
        embed.set_footer(text=f"Tupper (webhook) • Borrado {borrado_dt} • {opt_txt}")
    else:
        embed.set_author(
            name=data["author"],
            icon_url=data.get("author_avatar")
        )
        uid = data.get("author_id", "")
        embed.set_footer(text=f"ID: {uid} • Borrado {borrado_dt} • {opt_txt}")

    # Contenido del mensaje
    contenido = data.get("content", "")
    if contenido:
        embed.description = contenido[:2000]
    elif not data.get("images") and not data.get("attachments"):
        embed.description = "*Sin texto*"

    # Primera imagen como preview del embed
    imagenes = data.get("images", [])
    if imagenes:
        embed.set_image(url=imagenes[0])
        if len(imagenes) > 1:
            embed.add_field(
                name=f"🖼️ {len(imagenes)} imágenes",
                value="\n".join(f"[Ver imagen {i+1}]({u})" for i, u in enumerate(imagenes[:5])),
                inline=False
            )

    # Adjuntos que no son imágenes
    otros = [a for a in data.get("attachments", []) if a not in imagenes]
    if otros:
        embed.add_field(
            name=f"📎 {len(otros)} adjunto(s)",
            value="\n".join(f"[Archivo {i+1}]({u})" for i, u in enumerate(otros[:5])),
            inline=False
        )

    # Stickers
    if data.get("stickers"):
        embed.add_field(name="🎭 Sticker", value=", ".join(data["stickers"]), inline=True)

    if data.get("embeds"):
        orig = data["embeds"][0]
        partes = []
        if getattr(orig, "title", None):
            partes.append(f"Titulo: {orig.title[:80]}")
        if getattr(orig, "description", None):
            partes.append(f"Desc: {orig.description[:120]}")
        if getattr(orig, "url", None):
            partes.append(f"URL: {orig.url}")
        if partes:
            embed.add_field(name="Embed original", value="\n".join(partes)[:900], inline=False)

    urls = re.findall(r"https?://\S+", contenido or "")
    if urls:
        embed.add_field(name="Links detectados", value="\n".join(urls[:5])[:900], inline=False)
    if data.get("webhook_id"):
        embed.add_field(name="Webhook", value=f"`{data.get('webhook_id')}`", inline=True)

    view = SnipeView(data)
    await ctx.reply(embed=embed, view=view, mention_author=False)


class SnipeView(discord.ui.View):
    """Botones extra para snipe: ver todas las imagenes y hacer 'Make it a Quote'."""
    def __init__(self, data: dict):
        super().__init__(timeout=None)
        self.data = data
        imagenes = data.get("images", [])
        tiene_texto = bool((data.get("content") or "").strip())
        for item in list(self.children):
            cid = getattr(item, "custom_id", None)
            if cid == "latambot_snipe_images" and len(imagenes) <= 1:
                self.remove_item(item)   # sin botón de imágenes si hay 0 o 1
            elif cid == "latambot_snipe_quote" and not tiene_texto:
                self.remove_item(item)   # sin botón de cita si no hay texto

    @discord.ui.button(label="🖼️ Ver todas las imagenes", style=discord.ButtonStyle.secondary, custom_id="latambot_snipe_images")
    async def ver_imgs(self, i: discord.Interaction, b):
        imagenes = self.data.get("images", [])
        if not imagenes:
            await i.response.send_message("No hay imagenes.", ephemeral=True)
            return
        desc = "\n".join(f"[Imagen {idx+1}]({url})" for idx, url in enumerate(imagenes))
        embed = discord.Embed(
            title=f"🖼️ {len(imagenes)} imagenes del mensaje borrado",
            description=desc,
            color=discord.Color.red()
        )
        await i.response.send_message(embed=embed, ephemeral=True)

    @discord.ui.button(label="Cita", emoji="🗯️", style=discord.ButtonStyle.primary, custom_id="latambot_snipe_quote")
    async def hacer_quote(self, i: discord.Interaction, b):
        data = self.data
        contenido = _limpiar_texto_quote(data.get("content", ""), i.guild)
        if not contenido.strip():
            await i.response.send_message("Ese mensaje no tiene texto para citar.", ephemeral=True)
            return
        mem = i.guild.get_member(data.get("author_id")) if (i.guild and data.get("author_id")) else None
        nombre = mem.display_name if mem else str(data.get("author", "Alguien")).split("#")[0]
        usuario = mem.name if mem else str(data.get("author", "alguien"))
        await i.response.defer()
        try:
            await _enviar_quote(i.followup.send, i.user.id, contenido, nombre, usuario, data.get("author_avatar"), user=mem)
        except Exception as e:
            log.warning("snipe quote error: %s", e)
            await i.followup.send("No pude generar la cita.", ephemeral=True)


# Reemplazado por l!casos (modlog con casos numerados). Ya no se registra.
async def cases(ctx, usuario: discord.Member = None):
    """[RETIRADO] Lo reemplaza l!casos."""
    target = usuario or ctx.author
    datos = cargar_datos()
    warns = datos.get("usuarios", {}).get(str(target.id), {}).get("warns", [])
    if not warns:
        await ctx.send(embed=discord.Embed(
            description=f"{target.mention} no tiene casos registrados.",
            color=discord.Color(COLOR_INFO)
        ))
        return
    embed = discord.Embed(
        title=f"📋 Casos de {target.display_name}",
        color=discord.Color.orange(),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed.set_thumbnail(url=target.display_avatar.url)
    for i, w in enumerate(warns[-10:], 1):
        fecha = w.get("fecha", "?")
        razon = w.get("razon", "Sin razón")[:80]
        por = w.get("por", "?")
        embed.add_field(name=f"Caso #{i}", value=f"**Razón:** {razon}\n**Por:** {por}\n**Fecha:** {fecha}", inline=True)
    embed.set_footer(text=f"Total: {len(warns)} casos | LatamBOT")
    await ctx.send(embed=embed)


