@bot.command()
@commands.check(es_staff)
async def sticky(ctx, titulo: str = "Aviso", *, mensaje: str):
    """Stickea un mensaje. Uso: l!sticky [titulo] <mensaje>
    Ej: l!sticky Reglas No hagas spam.\n    Titulo es opcional (1 palabra sin espacios), mensaje es el resto."""
    sticky_contenido[ctx.channel.id] = {
        "titulo": titulo,
        "texto": mensaje,
        "color": discord.Color.yellow().value,
    }
    embed = discord.Embed(
        title=f"📌  {titulo}",
        description=mensaje,
        color=discord.Color.yellow()
    )
    embed.set_footer(text="📌 Mensaje fijado | LatamBOT")
    msg = await ctx.send(embed=embed)
    sticky_mensajes[ctx.channel.id] = msg.id
    try:
        await ctx.message.delete()
    except:
        pass

@bot.command()
@commands.check(es_staff)
async def unsticky(ctx):
    """Remueve el sticky del canal actual."""
    cid = ctx.channel.id
    if cid in sticky_mensajes:
        try:
            old_msg = await ctx.channel.fetch_message(sticky_mensajes[cid])
            await old_msg.delete()
        except:
            pass
        del sticky_mensajes[cid]
    if cid in sticky_contenido:
        del sticky_contenido[cid]
    await ctx.send("Sticky removido.", delete_after=5)

