async def _subir_catbox(filepath: str) -> Optional[str]:
    """Sube un archivo a catbox.moe usando catboxpy.
    Fallback a LitterboxClient (72h) si catbox falla. Sin cuenta necesaria."""
    # Intento 1: catbox.moe permanente con AsyncCatboxClient
    try:
        from catboxpy.catbox import AsyncCatboxClient
        client = AsyncCatboxClient()  # sin userhash = anonimo
        url = await client.upload(filepath)
        if url and url.startswith("https://"):
            print(f"[CATBOX] OK: {url}")
            return url
        print(f"[CATBOX] Respuesta inesperada: {url}")
    except ImportError:
        print("[CATBOX] catboxpy no instalado. Usa: pip install catboxpy")
    except Exception as e:
        print(f"[CATBOX] Error catbox.moe: {e}")

    # Intento 2: litterbox temporal 72h con LitterboxClient (sincrono en executor)
    try:
        from catboxpy import LitterboxClient
        import asyncio
        loop = asyncio.get_running_loop()
        def _litter_upload():
            c = LitterboxClient()
            return c.upload_file(filepath, expire_time="72h")
        url = await loop.run_in_executor(None, _litter_upload)
        if url and url.startswith("https://"):
            print(f"[LITTERBOX] OK: {url}")
            return url
        print(f"[LITTERBOX] Respuesta inesperada: {url}")
    except ImportError:
        print("[CATBOX] catboxpy no instalado.")
    except Exception as e:
        print(f"[LITTERBOX] Error: {e}")

    return None


def _r2_credentials_present() -> bool:
    return bool(
        R2_ACCOUNT_ID
        and R2_BUCKET_NAME
        and R2_PUBLIC_BASE_URL
        and R2_ACCESS_KEY_ID
        and R2_SECRET_ACCESS_KEY
    )


def _r2_client():
    import boto3

    return boto3.client(
        service_name="s3",
        endpoint_url=R2_ENDPOINT_URL,
        aws_access_key_id=R2_ACCESS_KEY_ID,
        aws_secret_access_key=R2_SECRET_ACCESS_KEY,
        region_name="auto",
    )


def _safe_r2_filename(filename: str) -> str:
    stem, ext = os.path.splitext(filename or "archivo")
    stem = unicodedata.normalize("NFKD", stem).encode("ascii", "ignore").decode("ascii")
    stem = re.sub(r"[^A-Za-z0-9._-]+", "-", stem).strip(".-_").lower()
    stem = stem[:72] or "archivo"
    ext = re.sub(r"[^A-Za-z0-9.]+", "", ext.lower())[:12] or ".bin"
    return f"{stem}{ext}"


def _r2_public_url(key: str) -> str:
    return f"{R2_PUBLIC_BASE_URL}/{quote(key, safe='/')}"


async def _subir_r2(filepath: str, filename: str, *, source_url: str = "", requested_by: Optional[int] = None) -> Optional[Dict[str, str]]:
    """Sube a Cloudflare R2 via boto3. upload_file usa multipart automaticamente segun TransferConfig."""
    if not _r2_credentials_present():
        return None
    try:
        from boto3.s3.transfer import TransferConfig
    except ImportError:
        print("[R2] boto3 no instalado. Usa: pip install boto3")
        return None

    safe_name = _safe_r2_filename(filename)
    today = datetime.datetime.now(datetime.timezone.utc).strftime("%Y/%m/%d")
    source_hash = hashlib.sha256((source_url or safe_name).encode("utf-8", errors="ignore")).hexdigest()[:12]
    key_parts = [p for p in (R2_OBJECT_PREFIX, today, f"{source_hash}-{uuid.uuid4().hex[:8]}-{safe_name}") if p]
    key = "/".join(key_parts)
    content_type = mimetypes.guess_type(safe_name)[0] or "application/octet-stream"
    metadata_source = _clip_text(source_url, 300, "").encode("ascii", errors="ignore").decode("ascii")
    extra_args = {
        "ContentType": content_type,
        "CacheControl": R2_CACHE_CONTROL,
        # inline + filename: permite previsualizar y al descargar usa el nombre limpio
        "ContentDisposition": f'inline; filename="{safe_name}"',
        "Metadata": {
            "source": metadata_source,
            "requested-by": str(requested_by or ""),
        },
    }
    config = TransferConfig(
        multipart_threshold=max(R2_MULTIPART_MB, 5) * 1024 * 1024,
        multipart_chunksize=max(R2_MULTIPART_MB, 5) * 1024 * 1024,
    )

    def _upload():
        client = _r2_client()
        client.upload_file(filepath, R2_BUCKET_NAME, key, ExtraArgs=extra_args, Config=config)

    try:
        loop = asyncio.get_running_loop()
        await loop.run_in_executor(None, _upload)
        public_url = _r2_public_url(key)
        print(f"[R2] OK: {public_url}")
        return {"url": public_url, "key": key, "content_type": content_type}
    except Exception as e:
        print(f"[R2] Error: {e}")
        return None


def _r2_presigned_get_url(key: str, expires_in: int = 3600) -> str:
    return _r2_client().generate_presigned_url(
        "get_object",
        Params={"Bucket": R2_BUCKET_NAME, "Key": key},
        ExpiresIn=max(1, min(int(expires_in), 604800)),
    )


def _r2_presigned_put_url(key: str, content_type: str, expires_in: int = 3600) -> str:
    return _r2_client().generate_presigned_url(
        "put_object",
        Params={"Bucket": R2_BUCKET_NAME, "Key": key, "ContentType": content_type},
        ExpiresIn=max(1, min(int(expires_in), 604800)),
    )


@bot.command(name="r2presign")
@commands.check(lambda ctx: ctx.author.id == OWNER_ID)
async def r2presign(ctx, metodo: str = None, key: str = None, expires_in: int = 3600, content_type: str = "application/octet-stream"):
    """Genera URL presignada GET/PUT para R2. Owner-only; envia la URL por DM."""
    if not metodo or not key or metodo.lower() not in {"get", "put"}:
        await ctx.send("Uso: `l!r2presign get|put <key> [segundos] [content-type]`", delete_after=15)
        return
    if not _r2_credentials_present():
        await ctx.send("Descargas no configuradas.", delete_after=15)
        return
    try:
        if metodo.lower() == "get":
            url = _r2_presigned_get_url(key, expires_in)
        else:
            url = _r2_presigned_put_url(key, content_type, expires_in)
        await ctx.author.send(
            f"URL presignada {metodo.upper()} ({max(1, min(int(expires_in), 604800))}s)\n"
            f"Bucket: `{R2_BUCKET_NAME}`\n"
            f"Key: `{key}`\n"
            f"Content-Type: `{content_type}`\n"
            f"{url}"
        )
        await ctx.send("URL presignada enviada por DM.", delete_after=10)
    except Exception as e:
        await ctx.send(f"No pude generar/enviar la URL presignada: `{str(e)[:180]}`", delete_after=15)

