# AVISO DE INCIDENCIA TECNICA (l!sendfixnotif) - SOLO OWNER
# ==============================================================================
FIXNOTIF_MENSAJE = (
    "Hola, soy Attard, creador de LatamBOT. Estamos teniendo problemas tecnicos "
    "con la Rasberry Pi que Aloja a latambot. el bot ahora esta en una version mas "
    "vieja y la base de datos es una nueva. Si vuelve la Pi, todas las configuraciones "
    "que haz hecho volveran, Pero por ahora, hasta que esto no se solucione, tenes que "
    "voolver a configurar todo denuevo. Mil disculpas de antemano, ya que son cosas que "
    "algunas veces pasan y lo queremos arreglar.Ahora si, Perdon por las molestias y "
    "adios. - Attard"
)


def _resolver_canal_fixnotif(guild):
    """Devuelve el canal 'general' donde escribir el aviso, evitando canales de anuncios.

    Prioridad:
      1. El canal general configurado en el setup (canal_general).
      2. Un canal de texto cuyo nombre contenga 'general'.
      3. El canal del sistema, si no es de anuncios.
      4. El primer canal de texto escribible que NO sea de anuncios.
    """
    me = guild.me
    if me is None:
        return None

    def _es_anuncio(ch):
        try:
            if ch.is_news():
                return True
        except Exception:
            pass
        nombre = (ch.name or "").lower()
        return any(p in nombre for p in ("anuncio", "announce", "news", "aviso", "noticias"))

    def _escribible(ch):
        perms = ch.permissions_for(me)
        return perms.send_messages and perms.view_channel

    # 1) Canal general configurado
    try:
        cfg = get_config(guild.id) or {}
        cid = cfg.get("canal_general")
        if cid:
            ch = guild.get_channel(int(cid))
            if isinstance(ch, discord.TextChannel) and _escribible(ch):
                return ch
    except Exception:
        pass

    # 2) Canal llamado "general"
    for ch in guild.text_channels:
        if "general" in (ch.name or "").lower() and not _es_anuncio(ch) and _escribible(ch):
            return ch

    # 3) Canal del sistema (si no es de anuncios)
    sc = guild.system_channel
    if isinstance(sc, discord.TextChannel) and not _es_anuncio(sc) and _escribible(sc):
        return sc

    # 4) Primer canal de texto escribible que no sea de anuncios
    for ch in guild.text_channels:
        if not _es_anuncio(ch) and _escribible(ch):
            return ch

    return None


class _FixNotifView(discord.ui.View):
    """Selector paginado para elegir a que servidores se envia el aviso. Solo owner."""
    PER_PAGE = 25

    def __init__(self, owner_id: int, guilds):
        super().__init__(timeout=300)
        self.owner_id = owner_id
        self.guilds = guilds  # lista de discord.Guild ya ordenada
        self.page = 0
        self.total_pages = max(1, (len(self.guilds) + self.PER_PAGE - 1) // self.PER_PAGE)
        self.selected = {g.id for g in self.guilds}  # por defecto: todos seleccionados
        self.finalizado = False
        self._render()

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message("Este panel es solo del owner.", ephemeral=True)
            return False
        return True

    def _page_guilds(self):
        inicio = self.page * self.PER_PAGE
        return self.guilds[inicio:inicio + self.PER_PAGE]

    def _embed(self):
        con_canal = sum(1 for g in self.guilds if g.id in self.selected and _resolver_canal_fixnotif(g))
        sin_canal = len([g for g in self.guilds if g.id in self.selected]) - con_canal
        emb = discord.Embed(
            title="📢 Enviar aviso de incidencia técnica",
            description=(
                f"Servidores totales: **{len(self.guilds)}**\n"
                f"Seleccionados: **{len(self.selected)}** "
                f"(con canal: **{con_canal}**, sin canal válido: **{sin_canal}**)\n\n"
                "Marcá/desmarcá los servidores en el menú y pulsá **Enviar**.\n"
                "El aviso va al canal *general* de cada servidor (nunca a uno de anuncios)."
            ),
            color=discord.Color(COLOR_ADVERTENCIA),
        )
        emb.add_field(name="Mensaje", value=FIXNOTIF_MENSAJE[:1000], inline=False)
        emb.set_footer(text=f"Página {self.page + 1}/{self.total_pages}")
        return emb

    def _render(self):
        self.clear_items()
        page_guilds = self._page_guilds()
        options = []
        for g in page_guilds:
            ch = _resolver_canal_fixnotif(g)
            desc = f"#{ch.name}" if ch else "⚠️ sin canal disponible"
            options.append(discord.SelectOption(
                label=g.name[:100] or str(g.id),
                value=str(g.id),
                description=desc[:100],
                default=g.id in self.selected,
            ))
        if options:
            select = discord.ui.Select(
                placeholder=f"Servidores a notificar (pág {self.page + 1}/{self.total_pages})",
                options=options,
                min_values=0,
                max_values=len(options),
                row=0,
            )
            select.callback = self._on_select
            self.add_item(select)

        multipag = self.total_pages > 1
        prev_btn = discord.ui.Button(label="◀️", style=discord.ButtonStyle.secondary, row=1, disabled=not multipag)
        prev_btn.callback = self._prev
        next_btn = discord.ui.Button(label="▶️", style=discord.ButtonStyle.secondary, row=1, disabled=not multipag)
        next_btn.callback = self._next
        all_btn = discord.ui.Button(label="Marcar todos", style=discord.ButtonStyle.secondary, row=1)
        all_btn.callback = self._all
        none_btn = discord.ui.Button(label="Desmarcar todos", style=discord.ButtonStyle.secondary, row=1)
        none_btn.callback = self._none
        send_btn = discord.ui.Button(label="✅ Enviar", style=discord.ButtonStyle.success, row=2)
        send_btn.callback = self._send
        cancel_btn = discord.ui.Button(label="✖️ Cancelar", style=discord.ButtonStyle.danger, row=2)
        cancel_btn.callback = self._cancel
        for b in (prev_btn, next_btn, all_btn, none_btn, send_btn, cancel_btn):
            self.add_item(b)

    async def _on_select(self, i: discord.Interaction):
        page_ids = {g.id for g in self._page_guilds()}
        elegidos = {int(v) for v in i.data.get("values", [])}
        self.selected -= page_ids
        self.selected |= elegidos
        self._render()
        await i.response.edit_message(embed=self._embed(), view=self)

    async def _prev(self, i: discord.Interaction):
        self.page = (self.page - 1) % self.total_pages
        self._render()
        await i.response.edit_message(embed=self._embed(), view=self)

    async def _next(self, i: discord.Interaction):
        self.page = (self.page + 1) % self.total_pages
        self._render()
        await i.response.edit_message(embed=self._embed(), view=self)

    async def _all(self, i: discord.Interaction):
        self.selected = {g.id for g in self.guilds}
        self._render()
        await i.response.edit_message(embed=self._embed(), view=self)

    async def _none(self, i: discord.Interaction):
        self.selected = set()
        self._render()
        await i.response.edit_message(embed=self._embed(), view=self)

    async def _cancel(self, i: discord.Interaction):
        self.finalizado = True
        for item in self.children:
            item.disabled = True
        await i.response.edit_message(
            embed=discord.Embed(description="❌ Envío cancelado.", color=discord.Color(COLOR_PELIGRO)),
            view=self,
        )
        self.stop()

    async def _send(self, i: discord.Interaction):
        seleccion = [g for g in self.guilds if g.id in self.selected]
        if not seleccion:
            await i.response.send_message("No seleccionaste ningún servidor.", ephemeral=True)
            return
        self.finalizado = True
        for item in self.children:
            item.disabled = True
        await i.response.edit_message(
            embed=discord.Embed(
                description=f"⏳ Enviando aviso a **{len(seleccion)}** servidor(es)...",
                color=discord.Color(COLOR_INFO),
            ),
            view=self,
        )

        enviados, fallidos = [], []
        for g in seleccion:
            ch = _resolver_canal_fixnotif(g)
            if ch is None:
                fallidos.append((g, "sin canal con permisos"))
                continue
            try:
                await ch.send(FIXNOTIF_MENSAJE)
                enviados.append((g, ch))
            except Exception as e:
                fallidos.append((g, str(e)[:80]))
            await asyncio.sleep(1)  # cortesía con el rate limit

        resumen = discord.Embed(
            title="📢 Aviso enviado",
            description=f"✅ Enviados: **{len(enviados)}**\n❌ Fallidos: **{len(fallidos)}**",
            color=discord.Color(COLOR_EXITO if not fallidos else COLOR_ADVERTENCIA),
        )
        if fallidos:
            detalle = "\n".join(f"• **{g.name}** - {motivo}" for g, motivo in fallidos[:15])
            if len(fallidos) > 15:
                detalle += f"\n… y {len(fallidos) - 15} más."
            resumen.add_field(name="No se pudo enviar a", value=detalle[:1024], inline=False)
        try:
            await i.followup.send(embed=resumen)
        except Exception:
            pass
        self.stop()


@bot.command(name="sendfixnotif")
@commands.check(lambda ctx: ctx.author.id == OWNER_ID)
async def sendfixnotif(ctx):
    """[OWNER] Envía el aviso de incidencia técnica al canal general de los servidores elegidos."""
    guilds = sorted(bot.guilds, key=lambda g: (g.name or "").lower())
