@bot.command(name="announcepanel", aliases=["anunciopanel"])
@commands.check(lambda ctx: ctx.author.id == OWNER_ID)
async def announcepanel(ctx):
    """[OWNER] Anuncia la migración al panel web en el canal de staff de cada servidor."""
    await ctx.send(embed=_make_embed("📣 Enviando anuncio del panel...", "Mandando a los canales de staff configurados.", COLOR_INFO))
    enviados, sin_canal, fallidos = 0, 0, []
    for g in list(bot.guilds):
        cfg = get_config(g.id) or {}
        cid = cfg.get("canal_staff")
        canal = g.get_channel(int(cid)) if cid else None
        if not isinstance(canal, discord.TextChannel) or not canal.permissions_for(g.me).send_messages:
            sin_canal += 1
            continue
        try:
            await canal.send(embed=_embed_anuncio_panel(g))
            enviados += 1
        except Exception as e:
            fallidos.append((g.name, str(e)[:60]))
        await asyncio.sleep(0.6)
    resumen = _make_embed(
        "📣 Anuncio del panel enviado",
        f"✅ Enviados a staff: **{enviados}**\n"
        f"➖ Sin canal de staff configurado: **{sin_canal}**\n"
        f"❌ Fallidos: **{len(fallidos)}**",
        COLOR_EXITO if not fallidos else COLOR_ADVERTENCIA,
    )
    if fallidos:
        resumen.add_field(name="No pude enviar a", value="\n".join(f"• {n} - {m}" for n, m in fallidos[:15])[:1024], inline=False)
    await ctx.send(embed=resumen)


