# ==============================================================================
# QUOTE - "Make it a Quote" (l!quote respondiendo un mensaje o citando un snipe)
# ==============================================================================

# Caches de tipografias para quotes (cmap + instancias FreeType).
_QUOTE_CMAP_CACHE: Dict[str, set] = {}
_QUOTE_FT_CACHE: Dict[tuple, Any] = {}
_QUOTE_EMOJI_PATH = "/usr/share/fonts/truetype/noto/NotoColorEmoji.ttf"
_QUOTE_FALLBACK_PATHS = [
    "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
    "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
    "/usr/share/fonts/truetype/noto/NotoSansSymbols-Bold.ttf",
    "/usr/share/fonts/truetype/noto/NotoSansSymbols-Regular.ttf",
    "/usr/share/fonts/truetype/noto/NotoSansSymbols2-Regular.ttf",
    "/usr/share/fonts/truetype/noto/NotoSansMath-Regular.ttf",
    "/usr/share/fonts/truetype/droid/DroidSansFallbackFull.ttf",
]


def _quote_read_cmap(path: str) -> set:
    """Lee los codepoints con glifo real de un TTF/OTF (formatos cmap 4 y 12)."""
    try:
        with open(path, "rb") as f:
            data = f.read()
    except Exception:
        return set()
    try:
        if data[:4] == b"ttcf":
            off = struct.unpack_from(">I", data, 12)[0]
            data = data[off:]
        num_tables = struct.unpack_from(">H", data, 4)[0]
        cmap_off = None
        for i in range(num_tables):
            tag, _csum, off, _length = struct.unpack_from(">4sIII", data, 12 + i * 16)
            if tag == b"cmap":
                cmap_off = off
                break
        if cmap_off is None:
            return set()
        n_tables = struct.unpack_from(">H", data, cmap_off + 2)[0]
        cps: set = set()
        for i in range(n_tables):
            plat, _enc, off = struct.unpack_from(">HHI", data, cmap_off + 4 + i * 8)
            if plat not in (0, 3):
                continue
            base = cmap_off + off
            fmt = struct.unpack_from(">H", data, base)[0]
            if fmt == 4:
                seg_count = struct.unpack_from(">H", data, base + 6)[0] // 2
                end_off = base + 14
                start_off = end_off + seg_count * 2 + 2
                iddelta_off = start_off + seg_count * 2
                idrange_off = iddelta_off + seg_count * 2
                for s in range(seg_count):
                    end = struct.unpack_from(">H", data, end_off + s * 2)[0]
                    start = struct.unpack_from(">H", data, start_off + s * 2)[0]
                    iddelta = struct.unpack_from(">h", data, iddelta_off + s * 2)[0]
                    idrange = struct.unpack_from(">H", data, idrange_off + s * 2)[0]
                    for c in range(start, end + 1):
                        if idrange == 0:
                            glyph = (c + iddelta) & 0xFFFF
                        else:
                            idx = idrange_off + s * 2 + idrange + (c - start) * 2
                            glyph = struct.unpack_from(">H", data, idx)[0]
                            if glyph != 0:
                                glyph = (glyph + iddelta) & 0xFFFF
                        if glyph != 0:
                            cps.add(c)
            elif fmt == 12:
                n_groups = struct.unpack_from(">I", data, base + 12)[0]
                for g in range(n_groups):
                    start, end, start_glyph = struct.unpack_from(">III", data, base + 16 + g * 12)
                    for c in range(start, end + 1):
                        if (start_glyph + (c - start)) != 0:
                            cps.add(c)
        return cps
    except Exception:
        return set()


def _quote_cmap(path: str) -> set:
    if path not in _QUOTE_CMAP_CACHE:
        _QUOTE_CMAP_CACHE[path] = _quote_read_cmap(path) if path and os.path.exists(path) else set()
    return _QUOTE_CMAP_CACHE[path]


def _quote_ft(path: str, size: int):
    key = (path, int(size))
    font = _QUOTE_FT_CACHE.get(key)
    if font is not None:
        return font
    try:
        font = ImageFont.truetype(path, size)
    except Exception:
        font = None
    _QUOTE_FT_CACHE[key] = font
    return font


def _quote_is_emoji_char(ch: str) -> bool:
    o = ord(ch)
    return (
        0x1F300 <= o <= 0x1FAFF
        or 0x1F000 <= o <= 0x1F0FF
        or 0x1F100 <= o <= 0x1F1FF
        or 0x2600 <= o <= 0x27BF
        or 0x2300 <= o <= 0x23FF
        or 0x2B00 <= o <= 0x2BFF
        or o in (0x200D, 0xFE0E, 0xFE0F, 0x20E3)
        or 0x1F3FB <= o <= 0x1F3FF
        or 0xE0020 <= o <= 0xE007F
    )


def _quote_clusters(text: str) -> List[str]:
    """Separa texto en clusters: secuencias emoji (ZWJ/skin) juntas, resto char a char."""
    chars = list(text or "")
    out: List[str] = []
    i = 0
    n = len(chars)
    while i < n:
        if _quote_is_emoji_char(chars[i]):
            j = i + 1
            while j < n and _quote_is_emoji_char(chars[j]):
                j += 1
            out.append("".join(chars[i:j]))
            i = j
        else:
            out.append(chars[i])
            i += 1
    return out


def _quote_path_has(path: str, cluster: str) -> bool:
    if not cluster or cluster.isspace():
        return True
    cps = _quote_cmap(path)
    if not cps:
        return False
    # Los VS16/ZWJ no necesitan glifo propio si el emoji base esta.
    meaningful = [c for c in cluster if ord(c) not in (0x200D, 0xFE0E, 0xFE0F)]
    if not meaningful:
        return True
    return all(ord(c) in cps for c in meaningful)


def _quote_resolve_cluster(cluster: str, primary_paths: List[str]) -> tuple:
    """Devuelve (path, is_emoji_font) para un cluster."""
    for p in primary_paths:
        if p and _quote_path_has(p, cluster):
            return p, False
    if any(_quote_is_emoji_char(c) for c in cluster) and _quote_path_has(_QUOTE_EMOJI_PATH, cluster):
        return _QUOTE_EMOJI_PATH, True
    for p in _QUOTE_FALLBACK_PATHS:
        if _quote_path_has(p, cluster):
            return p, p.endswith("NotoColorEmoji.ttf")
    # Ultimo recurso: primera primaria existente, aunque pinte tofu.
    for p in primary_paths:
        if p and os.path.exists(p):
            return p, False
    return primary_paths[0] if primary_paths else "", False


def _quote_runs(text: str, primary_paths: List[str]) -> List[tuple]:
    """Agrupa clusters consecutivos con la misma fuente: [(texto, path, is_emoji)]."""
    runs: List[tuple] = []
    for cluster in _quote_clusters(text):
        path, is_emoji = _quote_resolve_cluster(cluster, primary_paths)
        if runs and runs[-1][1] == path and runs[-1][2] == is_emoji:
            runs[-1] = (runs[-1][0] + cluster, path, is_emoji)
        else:
            runs.append((cluster, path, is_emoji))
    return runs


def _quote_run_width(draw: ImageDraw.ImageDraw, run_text: str, path: str, size: int, is_emoji: bool) -> float:
    if not run_text:
        return 0.0
    if is_emoji:
        font = _quote_ft(path, 109)
        if font is None:
            return float(size) * max(1, len(run_text))
        try:
            return float(draw.textlength(run_text, font=font)) * (float(size) / 109.0)
        except Exception:
            return float(size) * max(1, len(run_text))
    font = _quote_ft(path, size)
    if font is None:
        return float(size) * 0.6 * len(run_text)
    try:
        return float(draw.textlength(run_text, font=font))
    except Exception:
        return float(size) * 0.6 * len(run_text)


def _quote_text_width(draw: ImageDraw.ImageDraw, text: str, primary_paths: List[str], size: int) -> float:
    return sum(_quote_run_width(draw, t, p, size, e) for t, p, e in _quote_runs(text, primary_paths))


def _quote_wrap(draw: ImageDraw.ImageDraw, text: str, primary_paths: List[str], size: int, max_w: int) -> List[str]:
    """Envuelve el texto midiendo con fallbacks de fuente (emoji incluidos)."""
    lines: List[str] = []
    for parrafo in (text or "").split("\n"):
        if not parrafo.strip():
            lines.append("")
            continue
        cur = ""
        for palabra in parrafo.split(" "):
            test = (cur + " " + palabra).strip()
            if _quote_text_width(draw, test, primary_paths, size) <= max_w:
                cur = test
                continue
            if cur:
                lines.append(cur)
            if _quote_text_width(draw, palabra, primary_paths, size) > max_w:
                chunk = ""
                for cluster in _quote_clusters(palabra):
                    trial = chunk + cluster
                    if _quote_text_width(draw, trial, primary_paths, size) <= max_w:
                        chunk = trial
                    else:
                        if chunk:
                            lines.append(chunk)
                        chunk = cluster
                cur = chunk
            else:
                cur = palabra
        if cur:
            lines.append(cur)
    return lines or [""]


def _quote_draw_runs(img: Image.Image, draw: ImageDraw.ImageDraw, x: float, y: float,
                     text: str, primary_paths: List[str], size: int, fill) -> None:
    """Dibuja una linea con fuentes mixtas; los emoji van en color y escalados."""
    for run_text, path, is_emoji in _quote_runs(text, primary_paths):
        if not run_text:
            continue
        if is_emoji:
            font = _quote_ft(path, 109)
            if font is None:
                continue
            box = 160
            tmp = Image.new("RGBA", (box * max(1, min(8, len(run_text))), box), (0, 0, 0, 0))
            td = ImageDraw.Draw(tmp)
            try:
                td.text((0, 0), run_text, font=font, embedded_color=True)
            except Exception:
                td.text((0, 0), run_text, font=font, fill=fill)
            bbox = tmp.getbbox()
            if not bbox:
                continue
            tmp = tmp.crop(bbox)
            target_h = max(1, int(size * 1.12))
            ratio = target_h / max(1, tmp.height)
            tmp = tmp.resize((max(1, int(tmp.width * ratio)), target_h), Image.Resampling.LANCZOS)
            paste_y = int(y - (tmp.height - size) * 0.35)
            img.alpha_composite(tmp, (int(x), max(0, paste_y)))
            x += tmp.width + 1
            continue
        font = _quote_ft(path, size)
        if font is None:
            continue
        draw.text((x, y), run_text, font=font, fill=fill)
        try:
            x += float(draw.textlength(run_text, font=font))
        except Exception:
            x += size * 0.6 * len(run_text)


def _limpiar_texto_quote(text: str, guild: discord.Guild = None) -> str:
    """Convierte emojis custom y menciones crudas en algo legible para la imagen."""
    text = re.sub(r"<a?:(\w+):\d+>", r":\1:", text or "")

    def _ru(m):
        mem = guild.get_member(int(m.group(1))) if guild else None
        return "@" + mem.display_name if mem else "@usuario"

    def _rr(m):
        r = guild.get_role(int(m.group(1))) if guild else None
        return "@" + r.name if r else "@rol"

    def _rc(m):
        c = guild.get_channel(int(m.group(1))) if guild else None
        return "#" + c.name if c else "#canal"

    text = re.sub(r"<@!?(\d+)>", _ru, text)
    text = re.sub(r"<@&(\d+)>", _rr, text)
    text = re.sub(r"<#(\d+)>", _rc, text)
    return text.strip()


async def _quote_fetch_avatar(url: str) -> Image.Image:
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(str(url), timeout=aiohttp.ClientTimeout(total=8)) as resp:
                data = await resp.read()
        return Image.open(io.BytesIO(data)).convert("RGBA")
    except Exception:
        return Image.new("RGBA", (512, 512), (88, 101, 242, 255))


# Sets de tipografías para el botón "Cambiar fuente" (gana el primer path que exista).
_DJV = "/usr/share/fonts/truetype/dejavu/"
_LIB = "/usr/share/fonts/truetype/liberation/"
_FREE = "/usr/share/fonts/truetype/freefont/"
QUOTE_FONT_SETS = [
    {"name": "Clásica",  "bold": [_DJV + "DejaVuSans-Bold.ttf"],      "italic": [_DJV + "DejaVuSans-Oblique.ttf", _DJV + "DejaVuSans.ttf"], "regular": [_DJV + "DejaVuSans.ttf"]},
    {"name": "Serif",    "bold": [_DJV + "DejaVuSerif-Bold.ttf"],     "italic": [_DJV + "DejaVuSerif-Italic.ttf", _DJV + "DejaVuSerif.ttf"], "regular": [_DJV + "DejaVuSerif.ttf"]},
    {"name": "Moderna",  "bold": [_LIB + "LiberationSans-Bold.ttf"],  "italic": [_LIB + "LiberationSans-Italic.ttf"],  "regular": [_LIB + "LiberationSans-Regular.ttf"]},
    {"name": "Elegante", "bold": [_LIB + "LiberationSerif-Bold.ttf"], "italic": [_LIB + "LiberationSerif-Italic.ttf"], "regular": [_LIB + "LiberationSerif-Regular.ttf"]},
    {"name": "Máquina",  "bold": [_DJV + "DejaVuSansMono-Bold.ttf"],  "italic": [_DJV + "DejaVuSansMono-Oblique.ttf"],  "regular": [_DJV + "DejaVuSansMono.ttf"]},
    {"name": "Libre",    "bold": [_FREE + "FreeSerifBold.ttf"],       "italic": [_FREE + "FreeSerifItalic.ttf"],       "regular": [_FREE + "FreeSerif.ttf"]},
]


def _qfont(paths, size: int) -> ImageFont.FreeTypeFont:
    for p in list(paths) + [_DJV + "DejaVuSans-Bold.ttf", "arialbd.ttf", "arial.ttf"]:
        font = _quote_ft(p, size) if p else None
        if font is not None:
            return font
        try:
            return ImageFont.truetype(p, size)
        except Exception:
            continue
    return ImageFont.load_default()


def _qpaths(paths) -> List[str]:
    """Paths existentes de un set tipografico, con DejaVu de reserva."""
    out = [p for p in list(paths or []) if p and os.path.exists(p)]
    for p in (_DJV + "DejaVuSans-Bold.ttf", _DJV + "DejaVuSans.ttf"):
        if p not in out and os.path.exists(p):
            out.append(p)
    return out or list(paths or [])


async def _quote_render_base(avatar_url: str) -> Image.Image:
    """Base de la cita: avatar en gris llenando la izquierda + degradado a negro. Sin texto."""
    W, H = 1200, 630
    base = Image.new("RGBA", (W, H), (0, 0, 0, 255))
    av = await _quote_fetch_avatar(avatar_url)
    av = ImageOps.fit(av, (600, H)).convert("L").convert("RGBA")
    base.alpha_composite(av, (0, 0))
    grad = Image.new("L", (W, 1), 0)
    gp = grad.load()
    fade_start, fade_end = 250, 600
    for x in range(W):
        if x <= fade_start:
            a = 0
        elif x >= fade_end:
            a = 255
        else:
            a = int(255 * (x - fade_start) / (fade_end - fade_start))
        gp[x, 0] = a
    black = Image.new("RGBA", (W, H), (0, 0, 0, 255))
    black.putalpha(grad.resize((W, H)))
    return Image.alpha_composite(base, black)

# ── Marca invisible (LSB + HMAC) y generadores de imagen ──
_WM_MAGIC = b"LBWM"
_WM_VERSION = 1
_WM_KINDS = {"quote": 1, "notif": 2, "fakemsg": 3, "fakevc": 4}
_WM_KINDS_REV = {v: k for k, v in _WM_KINDS.items()}
_WM_KIND_ES = {"quote": "cita", "notif": "notificacion", "fakemsg": "mensaje", "fakevc": "voz"}


def _wm_key() -> bytes:
    seed = (TOKEN_DISCORD or "latambot").encode("utf-8", "ignore")
    return hmac.new(seed, b"latambot-wm-v1", hashlib.sha256).digest()


def _wm_positions(w: int, h: int, nbits: int) -> list:
    n = max(w * h, nbits + 8)
    x = (w * 73856093) ^ (h * 19349663) ^ 0xC0FFEE
    used = set()
    pos = []
    while len(pos) < nbits:
        x = (x * 1664525 + 1013904223) & 0xFFFFFFFF
        p = x % n
        while p in used:
            p = (p + 1) % n
        used.add(p)
        pos.append(p)
    return pos


def _wm_embed(img: Image.Image, kind: str, extra: bytes = b"") -> Image.Image:
    """Escribe una marca invisible en el LSB del canal azul. No se ve; se comprueba con /autenticidad."""
    rgb = img.convert("RGB")
    w, h = rgb.size
    if w * h < 600:
        rgb = rgb.resize((max(w, 32), max(h, 32)), Image.NEAREST)
        w, h = rgb.size
    ts = int(time.time()) & 0xFFFFFFFF
    kind_id = _WM_KINDS.get(kind, 0) & 0xFF
    buf = bytearray(rgb.tobytes())
    for i in range(len(buf)):
        buf[i] &= 0xFE
    extra16 = (extra or b"")[:16].ljust(16, b"\0")
    header = _WM_MAGIC + bytes([_WM_VERSION, kind_id]) + struct.pack(">I", ts) + extra16
    mac = hmac.new(_wm_key(), header + bytes(buf), hashlib.sha256).digest()
    payload = (header + mac).ljust(64, b"\0")
    bits = []
    for b in payload:
        for bit in range(7, -1, -1):
            bits.append((b >> bit) & 1)
    for i, pix in enumerate(_wm_positions(w, h, len(bits))):
        bi = pix * 3 + 2
        if 0 <= bi < len(buf):
            buf[bi] = (buf[bi] & 0xFE) | bits[i]
    return Image.frombytes("RGB", (w, h), bytes(buf))


def _wm_extract(img: Image.Image) -> dict:
    try:
        g = _wm_extract_gif(img)
        if g.get("present"):
            return g
    except Exception:
        pass
    rgb = img.convert("RGB")
    w, h = rgb.size
    buf = bytearray(rgb.tobytes())
    nbits = 64 * 8
    if w * h < nbits:
        return {"present": False}
    bits = []
    for pix in _wm_positions(w, h, nbits):
        bi = pix * 3 + 2
        bits.append(buf[bi] & 1 if 0 <= bi < len(buf) else 0)
    payload = bytearray()
    for i in range(0, nbits, 8):
        b = 0
        for bit in bits[i:i + 8]:
            b = (b << 1) | bit
        payload.append(b)
    payload = bytes(payload)
    if payload[:4] != _WM_MAGIC:
        return {"present": False}
    version = payload[4]
    kind_id = payload[5]
    ts = struct.unpack(">I", payload[6:10])[0]
    extra = payload[10:26]
    mac = payload[26:58]
    for i in range(len(buf)):
        buf[i] &= 0xFE
    header = _WM_MAGIC + bytes([version, kind_id]) + struct.pack(">I", ts) + extra
    expected = hmac.new(_wm_key(), header + bytes(buf), hashlib.sha256).digest()
    intact = hmac.compare_digest(mac, expected)
    uid = struct.unpack(">Q", extra[:8])[0] if extra[:8] != b"\0" * 8 else 0
    kind = _WM_KINDS_REV.get(kind_id, "desconocido")
    return {
        "present": True,
        "intact": intact,
        "kind": kind,
        "kind_es": _WM_KIND_ES.get(kind, kind),
        "ts": ts,
        "uid": uid,
        "version": version,
    }


def _wm_png_bytes(img: Image.Image, kind: str, uid: int = 0) -> io.BytesIO:
    extra = struct.pack(">Q", int(uid) & 0xFFFFFFFFFFFFFFFF)
    marked = _wm_embed(img.convert("RGB"), kind, extra)
    bio = io.BytesIO()
    marked.save(bio, format="PNG")
    bio.seek(0)
    return bio


def _dc_font(px: int, bold: bool = False):
    path = "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf" if bold else "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf"
    try:
        return ImageFont.truetype(path, px)
    except Exception:
        return _font(px, bold=bold)


def _dc_tw(draw, text, font) -> int:
    bb = draw.textbbox((0, 0), text, font=font)
    return bb[2] - bb[0]


def _dc_th(draw, text, font) -> int:
    bb = draw.textbbox((0, 0), text, font=font)
    return bb[3] - bb[1]


def _fakeimg_circle(av: Image.Image, size: int) -> Image.Image:
    av = ImageOps.fit(av.convert("RGBA"), (size, size), method=Image.LANCZOS)
    mask = Image.new("L", (size, size), 0)
    ImageDraw.Draw(mask).ellipse((0, 0, size - 1, size - 1), fill=255)
    av.putalpha(mask)
    return av


def _dc_app_icon(size: int) -> Image.Image:
    """Icono de app Discord: squircle blurple + Clyde."""
    im = Image.new("RGBA", (size, size), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    rad = max(int(size * 0.28), 3)
    d.rounded_rectangle((0, 0, size - 1, size - 1), radius=rad, fill=(88, 101, 242, 255))
    m = size / 32.0
    d.rounded_rectangle((5.5 * m, 11.2 * m, 26.5 * m, 23.8 * m), radius=max(int(4.2 * m), 1), fill=(255, 255, 255, 255))
    d.ellipse((9.6 * m, 13.4 * m, 14.6 * m, 18.4 * m), fill=(88, 101, 242, 255))
    d.ellipse((17.4 * m, 13.4 * m, 22.4 * m, 18.4 * m), fill=(88, 101, 242, 255))
    return im


def _dc_line_icon(draw, kind: str, cx: int, cy: int, s: int, color, width: int):
    o = max(int(s * 0.32), 3)
    w = max(width, 2)
    if kind == "x":
        draw.line((cx - o, cy - o, cx + o, cy + o), fill=color, width=w)
        draw.line((cx + o, cy - o, cx - o, cy + o), fill=color, width=w)
    elif kind == "check":
        draw.line((cx - o, cy + int(o * 0.05), cx - int(o * 0.15), cy + o), fill=color, width=w)
        draw.line((cx - int(o * 0.15), cy + o, cx + o, cy - o), fill=color, width=w)
    elif kind == "mic":
        draw.rounded_rectangle((cx - int(s * 0.16), cy - int(s * 0.32), cx + int(s * 0.16), cy + int(s * 0.08)), radius=int(s * 0.16), fill=color)
        draw.arc((cx - int(s * 0.28), cy - int(s * 0.12), cx + int(s * 0.28), cy + int(s * 0.32)), 0, 180, fill=color, width=w)
        draw.line((cx, cy + int(s * 0.32), cx, cy + int(s * 0.42)), fill=color, width=w)
        draw.line((cx - int(s * 0.18), cy + int(s * 0.42), cx + int(s * 0.18), cy + int(s * 0.42)), fill=color, width=w)
    elif kind == "head":
        draw.arc((cx - int(s * 0.34), cy - int(s * 0.28), cx + int(s * 0.34), cy + int(s * 0.28)), 200, 340, fill=color, width=w)
        draw.rounded_rectangle((cx - int(s * 0.38), cy - int(s * 0.08), cx - int(s * 0.18), cy + int(s * 0.28)), radius=2, fill=color)
        draw.rounded_rectangle((cx + int(s * 0.18), cy - int(s * 0.08), cx + int(s * 0.38), cy + int(s * 0.28)), radius=2, fill=color)
    elif kind == "gear":
        draw.ellipse((cx - int(s * 0.22), cy - int(s * 0.22), cx + int(s * 0.22), cy + int(s * 0.22)), outline=color, width=w)
        draw.ellipse((cx - int(s * 0.08), cy - int(s * 0.08), cx + int(s * 0.08), cy + int(s * 0.08)), fill=color)
    elif kind == "phone":
        # Colgar: auricular horizontal (icono Disconnect de Discord).
        x0, y0 = cx - int(s * 0.34), cy - int(s * 0.10)
        x1, y1 = cx + int(s * 0.34), cy + int(s * 0.10)
        draw.rounded_rectangle((x0, y0, x1, y1), radius=int(s * 0.10), fill=color)
        draw.ellipse((x0 - int(s * 0.08), y0 - int(s * 0.12), x0 + int(s * 0.16), y1 + int(s * 0.12)), fill=color)
        draw.ellipse((x1 - int(s * 0.16), y0 - int(s * 0.12), x1 + int(s * 0.08), y1 + int(s * 0.12)), fill=color)
    elif kind == "speaker":
        draw.polygon(
            [
                (cx - int(s * 0.22), cy - int(s * 0.10)),
                (cx - int(s * 0.06), cy - int(s * 0.10)),
                (cx + int(s * 0.14), cy - int(s * 0.28)),
                (cx + int(s * 0.14), cy + int(s * 0.28)),
                (cx - int(s * 0.06), cy + int(s * 0.10)),
                (cx - int(s * 0.22), cy + int(s * 0.10)),
            ],
            fill=color,
        )
        draw.arc((cx + int(s * 0.10), cy - int(s * 0.22), cx + int(s * 0.42), cy + int(s * 0.22)), 300, 60, fill=color, width=max(w - 1, 1))


def _fakeimg_wrap(draw, text: str, font, max_w: int, max_lines: int = 10) -> list:
    text = (text or "").replace("\r", "") or " "
    raw_lines = []
    for chunk in text.split("\n"):
        words = chunk.split() or [""]
        cur = ""
        for w in words:
            trial = (cur + " " + w).strip()
            tw = _dc_tw(draw, trial, font)
            if tw <= max_w or not cur:
                cur = trial
            else:
                raw_lines.append(cur)
                cur = w
                if len(raw_lines) >= max_lines:
                    return raw_lines[:max_lines]
        if cur:
            raw_lines.append(cur)
        if len(raw_lines) >= max_lines:
            break
    return raw_lines[:max_lines] or [" "]


# Tokens Discord dark (2024/2026)
_DC_BG = (49, 51, 56)          # --background-primary #313338
_DC_BG2 = (43, 45, 49)         # --background-secondary #2b2d31
_DC_BG2A = (35, 36, 40)        # --background-secondary-alt #232428
_DC_BG3 = (30, 31, 34)         # --background-tertiary #1e1f22
_DC_HP = (242, 243, 245)       # --header-primary
_DC_HS = (181, 186, 193)       # --header-secondary
_DC_TN = (219, 222, 225)       # --text-normal
_DC_TM = (148, 155, 164)       # --text-muted
_DC_BRAND = (88, 101, 242)
_DC_GREEN = (35, 165, 89)      # --green-360 / voice connected
_DC_RED = (242, 63, 67)
_DC_ACCENT = (78, 80, 88)
_DC_BTN = (43, 45, 49)


async def _render_fakenotif(avatar_url: str, display_name: str, body: str = None, hace: str = "ahora") -> Image.Image:
    """Amigos > Pendiente: toolbar, seccion y fila con botones Ignorar/Aceptar."""
    S = 2
    W = 640 * S
    bar_h = 48 * S
    sec_h = 40 * S
    row_h = 62 * S
    H = bar_h + sec_h + row_h + 8 * S
    img = Image.new("RGB", (W, H), _DC_BG)
    draw = ImageDraw.Draw(img)
    f_title = _dc_font(16 * S, bold=True)
    f_tab = _dc_font(16 * S, bold=True)
    f_tab_off = _dc_font(16 * S)
    f_sec = _dc_font(12 * S, bold=True)
    f_name = _dc_font(16 * S, bold=True)
    f_sub = _dc_font(14 * S)
    f_badge = _dc_font(12 * S, bold=True)
    f_btn = _dc_font(14 * S, bold=True)

    # Icono Amigos (dos siluetas), no el logo de la app.
    ix0, iy0 = 16 * S, (bar_h - 24 * S) // 2
    draw.ellipse((ix0 + 2 * S, iy0, ix0 + 12 * S, iy0 + 10 * S), fill=_DC_HP)
    draw.ellipse((ix0, iy0 + 10 * S, ix0 + 14 * S, iy0 + 24 * S), fill=_DC_HP)
    draw.ellipse((ix0 + 12 * S, iy0 + 2 * S, ix0 + 22 * S, iy0 + 11 * S), fill=_DC_HS)
    draw.ellipse((ix0 + 10 * S, iy0 + 11 * S, ix0 + 24 * S, iy0 + 24 * S), fill=_DC_HS)
    draw.text((48 * S, (bar_h - 22 * S) // 2), "Amigos", font=f_title, fill=_DC_HP)
    div_x = 128 * S
    draw.line((div_x, 14 * S, div_x, bar_h - 14 * S), fill=(66, 70, 77), width=S)
    tabs = [("En línea", False), ("Todos", False), ("Pendiente", True), ("Bloqueados", False)]
    x = 140 * S
    pend_x = pend_w = 0
    tab_y = (bar_h - 22 * S) // 2
    for label, on in tabs:
        font = f_tab if on else f_tab_off
        tw = _dc_tw(draw, label, font)
        draw.text((x, tab_y), label, font=font, fill=_DC_HP if on else _DC_TM)
        if label == "Pendiente":
            bx = x + tw + 6 * S
            bw, bh = 20 * S, 16 * S
            by = tab_y + 2 * S
            draw.rounded_rectangle((bx, by, bx + bw, by + bh), radius=8 * S, fill=_DC_RED)
            nw = _dc_tw(draw, "1", f_badge)
            draw.text((bx + (bw - nw) // 2, by - S), "1", font=f_badge, fill=(255, 255, 255))
            pend_x, pend_w = x, tw
            x = bx + bw + 20 * S
        else:
            x += tw + 20 * S
    add = "Añadir amigo"
    aw = _dc_tw(draw, add, f_btn) + 20 * S
    ah = 32 * S
    ax0 = W - 16 * S - aw
    ay0 = (bar_h - ah) // 2
    draw.rounded_rectangle((ax0, ay0, ax0 + aw, ay0 + ah), radius=3 * S, fill=_DC_GREEN)
    draw.text((ax0 + 10 * S, ay0 + 6 * S), add, font=f_btn, fill=(255, 255, 255))
    draw.line((0, bar_h - S, W, bar_h - S), fill=(66, 70, 77), width=S)
    if pend_w:
        draw.line((pend_x, bar_h - 2 * S, pend_x + pend_w, bar_h - 2 * S), fill=_DC_HP, width=2 * S)

    y = bar_h + 12 * S
    draw.text((16 * S, y), "PENDIENTE — 1", font=f_sec, fill=_DC_HS)
    y = bar_h + sec_h
    draw.line((16 * S, y, W - 16 * S, y), fill=(66, 70, 77), width=S)
    av_s = 32 * S
    av = _fakeimg_circle(await _quote_fetch_avatar(avatar_url), av_s)
    ay = y + (row_h - av_s) // 2
    img.paste(av, (16 * S, ay), av)
    name = (display_name or "alguien")[:32]
    sub = (body or "Solicitud de amistad entrante").strip()
    if len(sub) > 64:
        sub = sub[:63] + "…"
    tx = 16 * S + av_s + 12 * S
    draw.text((tx, y + 12 * S), name, font=f_name, fill=_DC_HP)
    draw.text((tx, y + 34 * S), sub, font=f_sub, fill=_DC_HS)
    bs = 36 * S
    gap = 10 * S
    bx = W - 16 * S - bs
    by = y + (row_h - bs) // 2
    draw.ellipse((bx, by, bx + bs, by + bs), fill=_DC_BG2A)
    _dc_line_icon(draw, "check", bx + bs // 2, by + bs // 2, bs, _DC_HS, max(3 * S // 2, 2))
    bx -= bs + gap
    draw.ellipse((bx, by, bx + bs, by + bs), fill=_DC_BG2A)
    _dc_line_icon(draw, "x", bx + bs // 2, by + bs // 2, bs, _DC_HS, max(3 * S // 2, 2))
    return img


async def _render_fakemsg(avatar_url: str, display_name: str, text: str, hora: str = None, tag_info=None) -> Image.Image:
    """Mensaje cozy-mode: padding 72/48, avatar 40, lh 22, timestamp 12px."""
    S = 2
    W = 540 * S
    f_name = _dc_font(16 * S, bold=True)
    f_time = _dc_font(12 * S)
    f_body = _dc_font(16 * S)
    tmp = Image.new("RGB", (8, 8), _DC_BG)
    d0 = ImageDraw.Draw(tmp)
    max_w = W - 72 * S - 48 * S
    lines = _fakeimg_wrap(d0, text, f_body, max_w, 14)
    # groupStart margin-top 17 + pad 2 + header 22 + lines*22 + pad 2 + crop 8
    header_h = 22 * S
    line_h = 22 * S
    top = (8 + 17 + 2) * S
    H = top + header_h + len(lines) * line_h + (2 + 10) * S
    H = max(H, (8 + 17 + 2 + 44 + 10) * S)
    img = Image.new("RGB", (W, H), _DC_BG)
    draw = ImageDraw.Draw(img)
    av_s = 40 * S
    av = _fakeimg_circle(await _quote_fetch_avatar(avatar_url), av_s)
    img.paste(av, (16 * S, top + 2 * S), av)
    name = (display_name or "alguien")[:32]
    nx = 72 * S
    ny = top
    draw.text((nx, ny), name, font=f_name, fill=_DC_HP)
    nw = _dc_tw(draw, name, f_name)
    if not hora:
        hora = "Hoy a las " + time.strftime("%H:%M")
    else:
        hora = hora.strip()[:28]
    # baseline-ish: timestamp 12px sits slightly lower in Discord (aligned to baseline of 16px name)
    extra_x = 4 * S
    if tag_info and tag_info.get("tag"):
        cw = _quote_draw_tag_chip(img, draw, nx + nw + 6 * S, ny + 2 * S, 16 * S, tag_info)
        extra_x = 6 * S + cw + 8 * S
    draw.text((nx + nw + extra_x, ny + 4 * S), hora, font=f_time, fill=_DC_TM)
    y = ny + header_h
    for ln in lines:
        draw.text((nx, y), ln, font=f_body, fill=_DC_TN)
        y += line_h
    return img


async def _send_fakeimg(ctx, img: Image.Image, kind: str, filename: str):
    buf = _wm_png_bytes(img, kind, getattr(ctx.author, "id", 0) or 0)
    await ctx.send(file=discord.File(buf, filename=filename))


def _quote_avatar_url(user) -> str:
    try:
        av = user.display_avatar
        if getattr(av, "is_animated", False):
            return str(av.replace(format="gif", size=256))
        return str(av.replace(format="png", size=512))
    except Exception:
        try:
            return str(user.display_avatar.with_size(512).url)
        except Exception:
            return ""


def _tag_info_from_user(user):
    if user is None:
        return None
    pg = getattr(user, "primary_guild", None)
    if pg is None:
        return None
    tag = getattr(pg, "tag", None)
    if not tag:
        return None
    if getattr(pg, "identity_enabled", None) is False:
        return None
    badge = getattr(pg, "badge", None)
    badge_url = None
    try:
        if badge is not None and getattr(badge, "url", None):
            badge_url = str(badge.url)
    except Exception:
        badge_url = None
    return {"tag": str(tag)[:8], "badge_url": badge_url, "guild_id": getattr(pg, "id", None), "badge_im": None}


async def _tag_prepare(user):
    info = _tag_info_from_user(user)
    if not info:
        return None
    url = info.get("badge_url")
    if url:
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=aiohttp.ClientTimeout(total=6)) as resp:
                    data = await resp.read()
            info["badge_im"] = Image.open(io.BytesIO(data)).convert("RGBA")
        except Exception:
            info["badge_im"] = None
    return info


async def _quote_load_frames(url: str):
    fallback = [Image.new("RGBA", (512, 512), (88, 101, 242, 255))]
    if not url:
        return fallback, [100], False
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(str(url), timeout=aiohttp.ClientTimeout(total=12)) as resp:
                data = await resp.read()
        im = Image.open(io.BytesIO(data))
    except Exception:
        return fallback, [100], False
    n = int(getattr(im, "n_frames", 1) or 1)
    if n <= 1:
        return [im.convert("RGBA")], [100], False
    n = min(n, 16)
    frames, durs = [], []
    for i in range(n):
        im.seek(i)
        frames.append(im.convert("RGBA"))
        durs.append(max(40, int(im.info.get("duration", 100) or 100)))
    return frames, durs, True


_QUOTE_GRAD = None

def _quote_compose_base(av: Image.Image) -> Image.Image:
    global _QUOTE_GRAD
    W, H = 1200, 630
    base = Image.new("RGBA", (W, H), (0, 0, 0, 255))
    av = ImageOps.fit(av.convert("RGBA"), (600, H)).convert("L").convert("RGBA")
    base.alpha_composite(av, (0, 0))
    if _QUOTE_GRAD is None or _QUOTE_GRAD.size != (W, H):
        grad = Image.new("L", (W, 1), 0)
        gp = grad.load()
        fade_start, fade_end = 250, 600
        for x in range(W):
            if x <= fade_start:
                a = 0
            elif x >= fade_end:
                a = 255
            else:
                a = int(255 * (x - fade_start) / (fade_end - fade_start))
            gp[x, 0] = a
        black = Image.new("RGBA", (W, H), (0, 0, 0, 255))
        black.putalpha(grad.resize((W, H)))
        _QUOTE_GRAD = black
    return Image.alpha_composite(base, _QUOTE_GRAD)


def _quote_draw_tag_chip(img, draw, x, y, height, tag_info) -> int:
    if not tag_info or not tag_info.get("tag"):
        return 0
    tag = str(tag_info.get("tag"))
    badge = tag_info.get("badge_im")
    pad_x, gap = 8, 5
    bs = max(14, height - 8)
    font = _dc_font(max(11, height - 10), bold=True)
    tw = _quote_text_width(draw, tag, [_DJV + "DejaVuSans-Bold.ttf", _DJV + "DejaVuSans.ttf"], max(11, height - 10))
    chip_w = pad_x * 2 + (bs + gap if badge is not None else 0) + int(tw)
    chip_h = height
    draw.rounded_rectangle((x, y, x + chip_w, y + chip_h), radius=6, fill=(30, 31, 34, 255), outline=(66, 70, 77, 255), width=1)
    cx = x + pad_x
    if badge is not None:
        try:
            b = ImageOps.fit(badge.convert("RGBA"), (bs, bs))
            img.paste(b, (int(cx), int(y + (chip_h - bs) / 2)), b)
            cx += bs + gap
        except Exception:
            pass
    _quote_draw_runs(img, draw, cx, y + max(1, (chip_h - (height - 10)) / 2), tag, [_DJV + "DejaVuSans-Bold.ttf"], max(11, height - 10), (242, 243, 245, 255))
    return chip_w

def _quote_paint(base: Image.Image, text: str, display_name: str, username: str, font_idx: int = 0, tag_info=None) -> Image.Image:
    """Dibuja el texto sobre una COPIA de la base. Sin marca ni encode."""
    W, H = base.size
    img = base.copy().convert("RGBA")
    draw = ImageDraw.Draw(img)
    fs = QUOTE_FONT_SETS[font_idx % len(QUOTE_FONT_SETS)]
    bold_paths = _qpaths(fs["bold"])
    italic_paths = _qpaths(fs["italic"])
    regular_paths = _qpaths(fs["regular"])
    tl, tr = 585, 1160
    cx = (tl + tr) // 2
    max_w = tr - tl

    text = (text or "").strip()
    if len(text) > 600:
        text = text[:599].rstrip() + "…"

    max_quote_h = 420
    chosen = None
    for size in range(72, 15, -2):
        lines = _quote_wrap(draw, text, bold_paths, size, max_w)
        lh = int(size * 1.16)
        if len(lines) * lh <= max_quote_h:
            chosen = (lines, lh, size)
            break
    if chosen is None:
        size = 16
        lh = int(size * 1.16)
        lines = _quote_wrap(draw, text, bold_paths, size, max_w)[: max(1, max_quote_h // lh)]
        chosen = (lines, lh, size)
    lines, lh, qsize = chosen

    name_sz = max(20, min(32, int(qsize * 0.52)))
    user_sz = max(18, name_sz - 6)
    name_txt = f"- {display_name}"
    user_txt = f"@{username}"
    quote_h = len(lines) * lh
    name_h = int(name_sz * 1.2)
    user_h = int(user_sz * 1.2)
    gap1, gap2 = 30, 12
    total = quote_h + gap1 + name_h + gap2 + user_h
    y = max(24, (H - total) // 2)

    for ln in lines:
        w = _quote_text_width(draw, ln, bold_paths, qsize)
        _quote_draw_runs(img, draw, cx - w / 2, y, ln, bold_paths, qsize, (245, 245, 245, 255))
        y += lh
    y += gap1
    wn = _quote_text_width(draw, name_txt, italic_paths, name_sz)
    chip_w = 0
    if tag_info and tag_info.get("tag"):
        tmp = Image.new("RGBA", (400, name_h + 4), (0, 0, 0, 0))
        td = ImageDraw.Draw(tmp)
        chip_w = _quote_draw_tag_chip(tmp, td, 0, 0, name_h, tag_info)
    group = wn + (10 + chip_w if chip_w else 0)
    nx = cx - group / 2
    _quote_draw_runs(img, draw, nx, y, name_txt, italic_paths, name_sz, (205, 205, 205, 255))
    if chip_w:
        _quote_draw_tag_chip(img, draw, nx + wn + 10, y, name_h, tag_info)
    y += name_h + gap2
    wu = _quote_text_width(draw, user_txt, regular_paths, user_sz)
    _quote_draw_runs(img, draw, cx - wu / 2, y, user_txt, regular_paths, user_sz, (150, 150, 150, 255))

    foot = "LatamBOT"
    fw = _quote_text_width(draw, foot, regular_paths, 20)
    _quote_draw_runs(img, draw, W - 40 - fw, H - 46, foot, regular_paths, 20, (120, 120, 120, 255))
    return img


def _quote_export(painted_frames, durations, requester_id):
    extra = struct.pack(">Q", int(requester_id or 0) & 0xFFFFFFFFFFFFFFFF)
    if len(painted_frames) <= 1:
        rgb = _wm_embed(painted_frames[0].convert("RGB"), "quote", extra)
        out = io.BytesIO()
        rgb.save(out, format="PNG")
        out.seek(0)
        return out, "quote.png"
    rgb_frames = [p.convert("RGB") for p in painted_frames]
    h = hashlib.sha256()
    for f in rgb_frames:
        h.update(f.tobytes())
    mac = hmac.new(_wm_key(), b"GIF1" + extra + h.digest(), hashlib.sha256).digest()
    comment = b"LBWMG" + base64.b64encode(extra + mac)
    pals = []
    for f in rgb_frames:
        try:
            pals.append(f.quantize(colors=192, method=Image.Quantize.MEDIANCUT))
        except Exception:
            pals.append(f.convert("P", palette=Image.ADAPTIVE, colors=192))
    out = io.BytesIO()
    save_kw = dict(format="GIF", save_all=True, append_images=pals[1:], duration=list(durations)[:len(pals)], loop=0, optimize=False, disposal=2)
    try:
        pals[0].save(out, comment=comment, **save_kw)
    except Exception:
        pals[0].save(out, **save_kw)
    out.seek(0)
    return out, "quote.gif"


def _quote_draw(base: Image.Image, text: str, display_name: str, username: str, font_idx: int = 0, requester_id: int = 0, tag_info=None) -> io.BytesIO:
    painted = _quote_paint(base, text, display_name, username, font_idx, tag_info)
    buf, _ = _quote_export([painted], [100], requester_id)
    return buf


def _wm_extract_gif(img: Image.Image) -> dict:
    if getattr(img, "format", None) not in ("GIF", "gif") and int(getattr(img, "n_frames", 1) or 1) <= 1:
        c = (getattr(img, "info", None) or {}).get("comment")
        if not c:
            return {"present": False}
    c = (getattr(img, "info", None) or {}).get("comment") or b""
    if isinstance(c, str):
        c = c.encode("latin-1", "ignore")
    if not c.startswith(b"LBWMG"):
        return {"present": False}
    try:
        blob = base64.b64decode(c[5:])
        extra, mac = blob[:8], blob[8:40]
        hh = hashlib.sha256()
        n = min(int(getattr(img, "n_frames", 1) or 1), 16)
        for i in range(max(n, 1)):
            try:
                img.seek(i)
            except Exception:
                break
            hh.update(img.convert("RGB").tobytes())
        expected = hmac.new(_wm_key(), b"GIF1" + extra + hh.digest(), hashlib.sha256).digest()
        uid = struct.unpack(">Q", extra)[0] if len(extra) >= 8 else 0
        return {"present": True, "intact": hmac.compare_digest(mac, expected), "kind": "quote", "kind_es": "cita animada", "ts": 0, "uid": uid, "version": 1, "gif": True}
    except Exception:
        return {"present": False}


class QuoteView(discord.ui.View):
    """Cita con botones: cambiar tipografía y eliminar."""

    def __init__(self, author_id, bases, durations, text, display_name, username, font_idx=0, tag_info=None):
        super().__init__(timeout=300)
        self.author_id = author_id
        self.bases = bases if isinstance(bases, list) else [bases]
        self.durations = durations or [100]
        self.text = text
        self.display_name = display_name
        self.username = username
        self.font_idx = font_idx
        self.tag_info = tag_info

    def _puede(self, user) -> bool:
        perms = getattr(user, "guild_permissions", None)
        return user.id == self.author_id or bool(perms and perms.manage_messages)

    def _pack(self):
        painted = [_quote_paint(b, self.text, self.display_name, self.username, self.font_idx, self.tag_info) for b in self.bases]
        return _quote_export(painted, self.durations, self.author_id)

    @discord.ui.button(label="Fuente", emoji="🔤", style=discord.ButtonStyle.secondary)
    async def fuente(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self._puede(interaction.user):
            await interaction.response.send_message("Solo quien pidió la cita (o el staff) puede cambiar la fuente.", ephemeral=True)
            return
        self.font_idx = (self.font_idx + 1) % len(QUOTE_FONT_SETS)
        try:
            buf, fname = self._pack()
        except Exception:
            await interaction.response.send_message("No pude cambiar la fuente.", ephemeral=True)
            return
        await interaction.response.edit_message(attachments=[discord.File(buf, filename=fname)], view=self)

    @discord.ui.button(label="Eliminar", emoji="🗑️", style=discord.ButtonStyle.danger)
    async def eliminar(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not self._puede(interaction.user):
            await interaction.response.send_message("Solo quien pidió la cita (o el staff) puede borrarla.", ephemeral=True)
            return
        try:
            await interaction.message.delete()
        except Exception:
            await interaction.response.send_message("No pude borrar el mensaje.", ephemeral=True)

    async def on_timeout(self):
        for item in self.children:
            item.disabled = True


async def _avisar_fakequote(target, autor, raw: bytes, fname: str, texto: str):
    try:
        clip = (texto or "")[:220]
        embed = _make_embed(
            "Te hicieron una cita falsa",
            f"{autor.mention} (`{autor.id}`) te atribuyó esta frase con una cita falsa.\n\n"
            f"**Texto:** {clip}\n\n"
            "No es un mensaje tuyo: te mando una copia para que quede constancia.",
            COLOR_ADVERTENCIA,
        )
        await target.send(embed=embed, file=discord.File(io.BytesIO(raw), filename=fname))
    except Exception as e:
        log.warning("fakequote dm: %s", e)


async def _enviar_quote(send_fn, requester_id, contenido, display_name, username, avatar_url, user=None, avisado=None, autor=None):
    """Genera la cita (PNG o GIF si la PFP es animada) y la envía."""
    if user is not None:
        avatar_url = _quote_avatar_url(user)
    tag_info = await _tag_prepare(user)
    frames, durs, _anim = await _quote_load_frames(avatar_url)
    bases = [_quote_compose_base(fr) for fr in frames]
    painted = [_quote_paint(b, contenido, display_name, username, 0, tag_info) for b in bases]
    buf, fname = _quote_export(painted, durs, requester_id)
    raw = buf.getvalue()
    view = QuoteView(requester_id, bases, durs, contenido, display_name, username, 0, tag_info)
    result = await send_fn(file=discord.File(io.BytesIO(raw), filename=fname), view=view)
    if avisado is not None and autor is not None and getattr(avisado, "id", None) != getattr(autor, "id", None):
        asyncio.create_task(_avisar_fakequote(avisado, autor, raw, fname, contenido))
    return result

def _quote_uso_embed():
    return _make_embed(
        "Como usar /quote",
        "Discord **no le pasa el mensaje** a un slash: `/quote` solo no sabe a cual citar.\n\n"
        "**Forma que anda (User App y server):**\n"
        "Clic derecho en el mensaje → **Apps** → **Citar**\n\n"
        "**Otras:**\n"
        "• Respondé el mensaje con `l!quote`\n"
        "• `/quote` + **enlace** del mensaje (Copiar enlace del mensaje)\n"
        "• `l!quote` sin responder cita el ultimo snipe del canal (bot en el server)",
        COLOR_INFO,
    )


_QUOTE_MSG_LINK = re.compile(
    r"https?://(?:ptb\.|canary\.)?discord(?:app)?\.com/channels/(\d+|@me)/(\d+)/(\d+)",
    re.I,
)


async def _quote_fetch_linked_message(ctx, text: str):
    m = _QUOTE_MSG_LINK.search(text or "")
    if not m:
        return None
    _gid, chan_id, msg_id = m.group(1), int(m.group(2)), int(m.group(3))
    channel = ctx.bot.get_channel(chan_id) or ctx.channel
    if getattr(channel, "id", None) != chan_id:
        try:
            channel = await ctx.bot.fetch_channel(chan_id)
        except Exception:
            return None
    try:
        return await channel.fetch_message(msg_id)
    except Exception:
        return None


@bot.hybrid_command(name="quote", aliases=["cita", "makeitaquote", "miaq"], description="Citar: clic derecho al mensaje → Apps → Citar. O pega el enlace.")
@app_commands.describe(objetivo="Vacio = ver como usar. O pega el enlace del mensaje (clic derecho → copiar enlace)")
@app_commands.allowed_installs(guilds=True, users=True)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
async def cmd_quote(ctx, *, objetivo: str = None):
    """Convierte un mensaje en una cita estilo Make it a Quote."""
    if ctx.interaction:
        await ctx.defer()
    contenido = display_name = username = avatar_url = None
    quoted_user = None
    objetivo = (objetivo or "").strip() or None

    if ctx.interaction and not objetivo:
        await ctx.send(embed=_quote_uso_embed())
        return

    if objetivo and objetivo.startswith("http"):
        msg = await _quote_fetch_linked_message(ctx, objetivo)
        if msg is None:
            await ctx.send(embed=_make_embed(
                "No pude leer ese enlace",
                "El bot tiene que ver ese canal, o usa **Apps → Citar** (manda el mensaje directo, sin buscarlo).",
                COLOR_ADVERTENCIA,
            ))
            return
        contenido = _limpiar_texto_quote(msg.content, msg.guild or ctx.guild)
        display_name = msg.author.display_name
        username = msg.author.name
        avatar_url = str(msg.author.display_avatar.with_size(512).url)
        quoted_user = msg.author

    ref = getattr(ctx.message, "reference", None)
    if contenido is None and ref and ref.message_id:
        try:
            msg = ref.resolved if isinstance(ref.resolved, discord.Message) else await ctx.channel.fetch_message(ref.message_id)
        except Exception:
            msg = None
        if msg is not None:
            contenido = _limpiar_texto_quote(msg.content, ctx.guild)
            display_name = msg.author.display_name
            username = msg.author.name
            avatar_url = str(msg.author.display_avatar.with_size(512).url)
        quoted_user = msg.author

    if contenido is None:
        # /quote no trae el mensaje citado. El User App va por el menú Citar.
        if ctx.interaction or _is_teaser_ctx(ctx) or ctx.guild is None:
            await ctx.send(embed=_make_embed(
                "Cómo citar",
                "El slash `/quote` no elige un mensaje solo.\n\n"
                "• **Clic derecho** en el mensaje → **Apps** → **Citar**\n"
                "• O **respondé** ese mensaje con `l!quote`\n\n"
                "Snipe (`l!quote` sin responder) solo funciona en un canal del server, con el bot adentro.",
                COLOR_INFO,
            ))
            return
        if await _bloquear_si_opt_out_snipe(ctx):
            return
        hist = list(snipe_history.get(ctx.channel.id, []))
        pos = 0
        if objetivo and objetivo.isdigit():
            pos = int(objetivo) - 1
        if not hist or pos < 0 or pos >= len(hist):
            await ctx.send(embed=_make_embed(
                f"{EMOJI_SAD} Nada para citar",
                "No hay un mensaje respondido ni historial de snipe en este canal.\n"
                "Respondé un mensaje con `l!quote`, o clic derecho → **Apps → Citar**.",
                COLOR_INFO))
            return
        data = hist[pos]
        contenido = _limpiar_texto_quote(data.get("content", ""), ctx.guild)
        mem = ctx.guild.get_member(data.get("author_id")) if data.get("author_id") else None
        display_name = mem.display_name if mem else str(data.get("author", "Alguien")).split("#")[0]
        username = mem.name if mem else str(data.get("author", "alguien"))
        avatar_url = data.get("author_avatar")
        quoted_user = mem

    if not (contenido or "").strip():
        await ctx.send(embed=_make_embed(
            "Sin texto para citar",
            "Ese mensaje no tiene texto (solo imagen/adjunto). Elegí uno con texto.",
            COLOR_ADVERTENCIA))
        return

    async with ctx.typing():
        try:
            await _enviar_quote(ctx.send, ctx.author.id, contenido, display_name, username, avatar_url, user=quoted_user)
        except Exception as e:
            log.warning("quote image error: %s", e)
            await ctx.send(embed=_make_embed("Error", "No pude generar la cita. Probá de nuevo.", COLOR_PELIGRO))




