async def _wm_bytes_from_ctx(ctx, imagen: discord.Attachment = None):
    if imagen is not None:
        return await imagen.read()
    msg = getattr(ctx, "message", None)
    if msg is not None:
        for a in getattr(msg, "attachments", []) or []:
            name = (a.filename or "").lower()
            ctype = (a.content_type or "")
            if ctype.startswith("image/") or name.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
                return await a.read()
        ref = getattr(msg, "reference", None)
        if ref is not None:
            resolved = ref.resolved if isinstance(getattr(ref, "resolved", None), discord.Message) else None
            if resolved is None and getattr(ref, "message_id", None):
                try:
                    resolved = await ctx.channel.fetch_message(ref.message_id)
                except Exception:
                    resolved = None
            if resolved is not None:
                for a in resolved.attachments:
                    name = (a.filename or "").lower()
                    ctype = (a.content_type or "")
                    if ctype.startswith("image/") or name.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif")):
                        return await a.read()
                for e in resolved.embeds:
                    url = None
                    if e.image and e.image.url:
                        url = e.image.url
                    elif e.thumbnail and e.thumbnail.url:
                        url = e.thumbnail.url
                    if url:
                        async with aiohttp.ClientSession() as session:
                            async with session.get(url, timeout=aiohttp.ClientTimeout(total=12)) as resp:
                                return await resp.read()
    return None



@bot.hybrid_command(name="autenticidad", aliases=["firma", "marcaimg", "origenimg"], description="Comprueba si una imagen la genero LatamBOT. No verifica roles.")
@app_commands.describe(imagen="Imagen generada por el bot (o responde al mensaje)")
@app_commands.allowed_installs(guilds=True, users=True)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
async def cmd_autenticidad(ctx, imagen: discord.Attachment = None):
    if ctx.interaction:
        await ctx.defer()
    try:
        raw = await _wm_bytes_from_ctx(ctx, imagen)
    except Exception as e:
        log.warning("autenticidad read: %s", e)
        raw = None
    if not raw:
        await ctx.send(embed=_make_embed(
            "Autenticidad de imagen",
            "Esto **no** verifica miembros ni roles del server.\n\n"
            "Adjunta una imagen que haya generado LatamBOT (cita, notificacion, mensaje), "
            "o **responde** a ese mensaje con `l!autenticidad` / `l!firma`.",
            COLOR_INFO,
        ))
        return
    try:
        im = Image.open(io.BytesIO(raw))
        im.load()
    except Exception:
        await ctx.send(embed=_make_embed("No pude leerla", "Ese archivo no parece una imagen valida.", COLOR_ADVERTENCIA))
        return
    info = _wm_extract(im)
    if not info.get("present"):
        await ctx.send(embed=_make_embed(
            "Sin marca de LatamBOT",
            "No encontre la marca invisible.\n\n"
            "Usa el **archivo original** que mando el bot (PNG o GIF). Un screenshot, un recorte o un JPG recomprimido la pierde.\n\n"
            "_Esto no tiene nada que ver con verificarte para un rol._",
            COLOR_ADVERTENCIA,
        ))
        return
    ts = int(info.get("ts") or 0)
    when = "GIF / metadatos" if info.get("gif") or ts <= 0 else datetime.datetime.fromtimestamp(ts, datetime.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    embed = discord.Embed(color=discord.Color(COLOR_EXITO if info.get("intact") else COLOR_ADVERTENCIA))
    embed.title = "Autenticidad OK" if info.get("intact") else "Marca alterada"
    embed.description = (
        "LatamBOT firmo esta imagen y **sigue intacta**."
        if info.get("intact")
        else "Encontre firma de LatamBOT, pero los pixeles **no coinciden**: alguien edito, recorto o recomprimio el archivo."
    )
    embed.add_field(name="Tipo", value=str(info.get("kind_es") or info.get("kind") or "?"), inline=True)
    if info.get("uid"):
        embed.add_field(name="Pedido por", value="<@%s>" % info["uid"], inline=True)
    embed.set_footer(text="No verifica miembros ni roles. Solo el origen de la imagen.")
