# DESCARGADOR DE VIDEOS (yt-dlp)
# ==============================================================================

async def _run_ytdlp_with_cookie_fallback(cmd_base: List[str], user_id: int, base_args: List[str], tmpdir: str, timeout_s: int = 180):
    candidates = _cookie_candidates(user_id) or [{"source": "none", "cookie_b64": None, "public": False, "user_id": None}]
    # Con proxy las cookies viejas suelen dar 403 en googlevideo.
    # Primero salimos sin cookies; si hace falta, reintentamos con ellas.
    if YTDLP_PROXY:
        none = [c for c in candidates if not c.get("cookie_b64")]
        rest = [c for c in candidates if c.get("cookie_b64")]
        candidates = (none or [{"source": "none", "cookie_b64": None, "public": False, "user_id": None}]) + rest
    last_stdout, last_stderr = b"", b""
    url = next((a for a in reversed(base_args) if isinstance(a, str) and a.startswith("http")), "")
    for cand in candidates:
        cookie_file = None
        args = list(base_args)
        if cand.get("cookie_b64"):
            cookie_file = _write_cookie_tempfile(cand["cookie_b64"])
            args = ["--cookies", cookie_file] + args
        if YTDLP_PROXY:
            args = ["--proxy", YTDLP_PROXY] + args
        if _es_url_youtube(url):
            args = [
                "--extractor-args", "youtube:player_client=android,ios,web",
                "--retries", "3",
                "--fragment-retries", "3",
            ] + args
        cmd = cmd_base + args
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            cwd=tmpdir
        )
        try:
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=timeout_s)
        except asyncio.TimeoutError:
            proc.kill()
            stdout, stderr = b"", b"Timeout"
        finally:
            if cookie_file and os.path.exists(cookie_file):
                try:
                    os.remove(cookie_file)
                except:
                    pass
        if proc.returncode == 0:
            if cand.get("public") and cand.get("user_id"):
                _sync_cookie_supporter(cand["user_id"], True, "cookie-public")
            return proc.returncode, stdout, stderr
        last_stdout, last_stderr = stdout, stderr
        if cand.get("public") and cand.get("user_id"):
            _sync_cookie_supporter(cand["user_id"], False, "cookie-public")
    return 1, last_stdout, last_stderr


def _registrar_descarga(ctx, tipo: str, filename: str, url: str, size_mb) -> None:
    """Guarda en datos.json un registro de cada archivo subido a la CDN por l!dl / l!mp3."""
    try:
        if not url:
            return
        datos = cargar_datos()
        lista = datos.get("descargas")
        if not isinstance(lista, list):
            lista = []
        lista.append({
            "ts": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "guild_id": ctx.guild.id if ctx.guild else None,
            "user_id": ctx.author.id,
            "user_name": str(ctx.author),
            "type": tipo,
            "filename": str(filename)[:160],
            "url": str(url),
            "size_mb": round(float(size_mb or 0), 1),
        })
        datos["descargas"] = lista[-1000:]  # tope para no inflar
        guardar_datos(datos)
    except Exception as e:
        print(f"[DESCARGA] No pude registrar: {e}")


def _embed_descarga_cdn(titulo, cdn_url, size_mb, formato, *, thumbnail=None, autor=None, tipo="video"):
    """Embed de 'revisá y descargá': preview + botón de descarga desde la CDN."""
    icono = "🎵" if tipo == "audio" else "🎬"
    embed = discord.Embed(
        title=f"{icono} {_clip_text(str(titulo), 90)}",
        description="Revisá que sea el correcto y descargá con el botón 👇",
        color=discord.Color.green(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    if thumbnail:
        try:
            embed.set_thumbnail(url=thumbnail)
        except Exception:
            pass
    embed.add_field(name="Tamaño", value=f"{float(size_mb or 0):.1f} MB", inline=True)
    embed.add_field(name="Formato", value=(str(formato or "-").upper()), inline=True)
    if autor is not None:
        embed.add_field(name="Pedido por", value=autor.mention, inline=True)
    embed.set_footer(text="Guardado")
    view = discord.ui.View(timeout=None)
    view.add_item(discord.ui.Button(label="📥 Descargar / Abrir", style=discord.ButtonStyle.link, url=cdn_url))
    return embed, view


# ── Descargas (Pi) vs música (solo EC2) ─────────────────────────────────────
# l!dl / l!mp3: worker yt-dlp en la Pi. Fallback: YTDLP_PROXY.
# Música (/play, l!play, etc.): NUNCA proxy ni Pi; sale por la IP de la EC2.
YTDLP_PROXY = os.getenv("YTDLP_PROXY", "").strip()
PI_WORKER_URL = (os.getenv("PI_WORKER_URL") or "http://100.78.48.59:8788").strip().rstrip("/")
_pi_tok = os.getenv("PI_WORKER_TOKEN", "").strip()
_pi_tok_file = os.getenv("PI_WORKER_TOKEN_FILE", "/data/pi_worker.token").strip()
if not _pi_tok and _pi_tok_file and os.path.isfile(_pi_tok_file):
    try:
        _pi_tok = Path(_pi_tok_file).read_text(encoding="utf-8").strip()
    except Exception:
        _pi_tok = ""
PI_WORKER_TOKEN = _pi_tok

# Aviso en web/status: YouTube de descargas puede fallar si no hay Pi ni proxy.
YOUTUBE_MANTENIMIENTO = not bool(YTDLP_PROXY or PI_WORKER_URL)

async def _pi_worker_download(url: str, mode: str, tmpdir: str, max_mb: int = 50) -> Optional[str]:
    """Pide el archivo al worker de la Pi. Devuelve path local o None."""
    if not PI_WORKER_URL or not PI_WORKER_TOKEN:
        return None
    endpoint = f"{PI_WORKER_URL}/v1/download"
    headers = {"Authorization": f"Bearer {PI_WORKER_TOKEN}", "Content-Type": "application/json"}
    payload = {"url": url, "mode": mode, "max_mb": int(max_mb)}
    timeout = aiohttp.ClientTimeout(total=200)
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(endpoint, json=payload, headers=headers) as resp:
                if resp.status != 200:
                    err = (await resp.text())[:220]
                    print(f"[PI_WORKER] {resp.status} {err}")
                    return None
                name = resp.headers.get("X-Filename") or ("audio.mp3" if mode == "mp3" else "video.mp4")
                name = os.path.basename(name).replace("..", "") or "download.bin"
                dest = os.path.join(tmpdir, name)
                with open(dest, "wb") as fh:
                    async for chunk in resp.content.iter_chunked(256 * 1024):
                        fh.write(chunk)
                if not os.path.isfile(dest) or os.path.getsize(dest) < 32:
                    try:
                        os.remove(dest)
                    except Exception:
                        pass
                    return None
                return dest
    except Exception as exc:
        print(f"[PI_WORKER] fail: {exc}")
        return None


async def _pi_archive_post(path: str, payload: dict) -> None:
    if not PI_WORKER_URL or not PI_WORKER_TOKEN:
        return
    url = f"{PI_WORKER_URL}{path}"
    headers = {"Authorization": f"Bearer {PI_WORKER_TOKEN}", "Content-Type": "application/json"}
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(url, json=payload, headers=headers) as resp:
                if resp.status >= 400:
                    print(f"[PI_ARCHIVE] {path} {resp.status}")
    except Exception as exc:
        print(f"[PI_ARCHIVE] fail {path}: {exc}")


async def _pi_archive_snipe_get(channel_id: int, limit: int = 25) -> list:
    if not PI_WORKER_URL or not PI_WORKER_TOKEN:
        return []
    url = f"{PI_WORKER_URL}/v1/archive/snipe?channel_id={int(channel_id)}&limit={int(limit)}"
    headers = {"Authorization": f"Bearer {PI_WORKER_TOKEN}"}
    try:
        timeout = aiohttp.ClientTimeout(total=8)
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.get(url, headers=headers) as resp:
                if resp.status != 200:
                    return []
                data = await resp.json()
                return list(data.get("items") or [])
    except Exception as exc:
        print(f"[PI_ARCHIVE] get snipe: {exc}")
        return []


def _es_url_youtube(url: str) -> bool:
    u = (url or "").lower()
    return any(d in u for d in ["youtube.com", "youtu.be", "youtube-nocookie.com"])

def _embed_youtube_fallo():
    return _make_embed(
        "⚠️ No pude bajar este YouTube",
        "Lo intenté desde el servidor (el proxy de la Pi no está estable). "
        "Si otro link funciona, se publica igual.\n\n"
        "TikTok, Instagram y el resto suelen andar mejor.",
        COLOR_ADVERTENCIA,
    )


@bot.hybrid_command(name="dl", description="Descarga un video. En MD (User App): 5 por dia.")
@app_commands.describe(url="URL del video")
@app_commands.allowed_installs(guilds=True, users=True)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
async def dl(ctx, url: str = None):
    """Descarga un video de YouTube/redes y lo sube al canal. Max 50MB."""
    if not url:
        await ctx.send(embed=discord.Embed(
            title="📥 l!dl - Descargador de video",
            description=(
                "**Uso:** `l!dl <url>`\n\n"
                "**Soporta:**\n"
                "YouTube • TikTok • Instagram • Facebook\n"
                "Reddit • Twitch (clips) • Vimeo • SoundCloud\n"
                "Dailymotion • Streamable • Bilibili • Niconico\n"
                "Tumblr • Odysee • Rumble • y 1000+ mas via yt-dlp\n\n"
                "**No soporta bien:**\n"
                "~~X/Twitter~~ (requiere auth) • ~~Pinterest~~ (sin videos directos)\n\n"
                "**Limite:** hasta 50MB\n"
                "Si quieres buscar primero, usa `l!ytb <busqueda>`.\n"
                "Para solo audio usa `l!mp3 <url>`."
            ),
            color=discord.Color(COLOR_PRIMARIO)
        ))
        return
    if not re.match(r"^https?://", url.strip(), re.IGNORECASE):
        await ctx.send(embed=discord.Embed(
            description="Pegá una URL valida. Si queres buscar un video primero, usa `l!ytb <busqueda>`.",
            color=discord.Color(COLOR_ADVERTENCIA),
        ))
        return

    teaser_dl = _is_teaser_ctx(ctx)
    if teaser_dl and ctx.guild is not None:
        kwargs = {}
        if ctx.interaction:
            kwargs["ephemeral"] = True
        await ctx.send(
            embed=_invite_embed(
                "Descargas de User App: en MD",
                "Aca el bot no esta en el server. Usa **/dl en un mensaje directo** conmigo (5 al dia) o invita a LatamBOT al servidor.",
                COLOR_ADVERTENCIA,
            ),
            view=_invite_view(),
            **kwargs,
        )
        return
    if teaser_dl:
        usados_dl, _ = _daily_limit_state(userapp_dl_usos, ctx.author.id, USERAPP_DL_DAILY)
        if usados_dl >= USERAPP_DL_DAILY:
            await ctx.send(
                embed=_invite_embed(
                    "Llegaste a las 5 descargas de hoy",
                    "En MD / User App hay **5 descargas por dia**.\n\nInvita a LatamBOT a tu server para seguir descargando, con musica e IA completa.",
                    COLOR_ADVERTENCIA,
                ),
                view=_invite_view(),
            )
            return
    if ctx.interaction:
        await ctx.defer()

    # Detectar plataformas no soportadas antes de intentar
    url_lower = url.lower()
    if any(d in url_lower for d in ["twitter.com", "x.com", "t.co"]):
        await ctx.send(embed=discord.Embed(
            title="❌ X/Twitter no soportado",
            description=(
                "X (Twitter) requiere autenticación para descargar videos y yt-dlp no puede acceder sin cookies.\n\n"
                "**Alternativas:**\n"
                "• Usá [sxtwitter.com](https://sxtwitter.com) - reemplazá `twitter.com` por `sxtwitter.com` en la URL\n"
                "• Usá [fxtwitter.com](https://fxtwitter.com) para embeds\n"
                "• Descargá manualmente desde la app de X"
            ),
            color=discord.Color(COLOR_PELIGRO)
        ))
        return
    if "pinterest" in url_lower:
        await ctx.send(embed=discord.Embed(
            title="❌ Pinterest no soportado",
            description=(
                "Pinterest no tiene videos descargables directamente via yt-dlp.\n\n"
                "**Alternativa:** Abrí el pin, encontrá la URL directa del video y usá `l!dl` con esa URL."
            ),
            color=discord.Color(COLOR_PELIGRO)
        ))
        return

    ytdlp_cmd = _resolve_ytdlp_cmd()
    if not ytdlp_cmd and not PI_WORKER_URL:
        await ctx.send("No pude encontrar el descargador. Contactá al admin del bot.")
        return

    msg_estado = await ctx.send("⏳ Descargando video, espera...")
    _media_debug("DL_START", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, url=url[:160])

    try:
        with tempfile.TemporaryDirectory() as tmpdir:
            output_template = os.path.join(tmpdir, "%(title).50s.%(ext)s")
            worker_file = None
            if PI_WORKER_URL:
                await msg_estado.edit(content="📥 Descargando...")
                worker_file = await _pi_worker_download(url, "video", tmpdir, max_mb=DL_MAX_SIZE_MB)
                if worker_file:
                    _media_debug("DL_WORKER_OK", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id)
                else:
                    await msg_estado.edit(content="⏳ Worker no pudo; intento local + proxy...")

            # Opciones de descarga: max 50MB, preferir mp4
            cmd_base = ytdlp_cmd or ["yt-dlp"]

            base_args = [
                "--no-playlist",
                # Preferir audio m4a (AAC) sobre Opus: los editores (Vegas, Premiere) no
                # leen Opus. Cae a cualquier audio si no hay m4a.
                "-f", "bestvideo[filesize<?50M]+bestaudio[ext=m4a]/bestvideo[filesize<?50M]+bestaudio[acodec!=none]/bestvideo+bestaudio[ext=m4a]/bestvideo+bestaudio[acodec!=none]/best[vcodec!=none][acodec!=none][filesize<?50M]/best*[vcodec!=none][acodec!=none]",
                "--merge-output-format", "mp4",
                "--recode-video", "mp4",
                # Forzar AAC estereo en el merge y el recode -> compatible con editores
                # (aunque haya caido en un audio Opus, aca lo pasa a AAC).
                "--postprocessor-args", "ffmpeg:-c:a aac -b:a 192k -ac 2",
                "--max-filesize", f"{DL_MAX_SIZE_MB}M",
                "-o", output_template,
                "--no-warnings",
                "--socket-timeout", "30",
                url
            ]
            if worker_file:
                proc_rc, stdout, stderr = 0, b"", b""
            else:
                proc_rc, stdout, stderr = await _run_ytdlp_with_cookie_fallback(
                    cmd_base=cmd_base,
                    user_id=ctx.author.id,
                    base_args=base_args,
                    tmpdir=tmpdir,
                    timeout_s=120
                )

            if proc_rc != 0:
                error_msg = stderr.decode('utf-8', errors='ignore')[:600] if stderr else "Error desconocido"
                stdout_msg = stdout.decode('utf-8', errors='ignore')[:200] if stdout else ""
                _metric_bump("media_failures")
                _media_debug("DL_FAIL", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, error=error_msg[:180], stdout=stdout_msg[:120])

                if YOUTUBE_MANTENIMIENTO and _es_url_youtube(url):
                    await msg_estado.edit(content=None, embed=_embed_youtube_fallo())
                    return

                # Clasificar el error para dar mensaje claro
                if "Unsupported URL" in error_msg or "unsupported" in error_msg.lower():
                    desc = "La URL no es compatible con yt-dlp.\n\nUsá `l!dl` sin argumentos para ver las plataformas soportadas."
                    titulo = "❌ URL no compatible"
                elif "File is larger" in error_msg or "filesize" in error_msg.lower() or "too large" in error_msg.lower():
                    desc = f"El video es demasiado grande (límite: {DL_MAX_SIZE_MB}MB).\nIntentá con un video más corto."
                    titulo = "❌ Video demasiado grande"
                elif "Private video" in error_msg or "private" in error_msg.lower():
                    desc = "El video es privado o requiere iniciar sesión para verlo."
                    titulo = "❌ Video privado"
                elif "members-only" in error_msg.lower() or "members only" in error_msg.lower():
                    desc = "El video es exclusivo para miembros (YouTube Members Only)."
                    titulo = "❌ Video para miembros"
                elif "age" in error_msg.lower() and ("restrict" in error_msg.lower() or "gate" in error_msg.lower()):
                    desc = "El video tiene restricción de edad y yt-dlp no puede acceder sin autenticación."
                    titulo = "❌ Restricción de edad"
                elif "copyright" in error_msg.lower() or "removed" in error_msg.lower():
                    desc = "El video fue eliminado o tiene restricción de copyright."
                    titulo = "❌ Video no disponible"
                elif "HTTP Error 403" in error_msg or "403" in error_msg:
                    desc = "El servidor rechazó la descarga (403 Forbidden). La plataforma puede estar bloqueando descargas."
                    titulo = "❌ Acceso denegado (403)"
                elif "HTTP Error 404" in error_msg or "404" in error_msg:
                    desc = "El video no existe o fue eliminado (404 Not Found)."
                    titulo = "❌ Video no encontrado"
                elif "No video formats found" in error_msg or "no formats" in error_msg.lower():
                    desc = "No se encontraron formatos de video con audio descargables en esa URL."
                    titulo = "❌ Sin formatos disponibles"
                elif "rate" in error_msg.lower() and "limit" in error_msg.lower():
                    desc = "La plataforma limitó las descargas temporalmente. Intentá en unos minutos."
                    titulo = "⏱️ Rate limit"
                else:
                    desc = f"Error al descargar el video.\n```{error_msg[:300]}```"
                    titulo = "❌ Error de descarga"

                await msg_estado.edit(content=None, embed=discord.Embed(
                    title=titulo,
                    description=desc,
                    color=discord.Color(COLOR_PELIGRO)
                ))
                return

            # Buscar el archivo descargado
            archivos = [f for f in os.listdir(tmpdir) if os.path.isfile(os.path.join(tmpdir, f))]
            if not archivos:
                await msg_estado.edit(content="No se encontro archivo descargado.")
                return

            preferidos = sorted(
                archivos,
                key=lambda f: (
                    0 if f.lower().endswith(".mp4") else
                    1 if f.lower().endswith(".mkv") else
                    2 if f.lower().endswith(".mov") else
                    3
                )
            )
            archivo_final = preferidos[0]
            archivo = os.path.join(tmpdir, archivo_final)
            if not archivo_final.lower().endswith(".mp4"):
                formato_origen = os.path.splitext(archivo_final)[1].lstrip(".").upper() or "DESCONOCIDO"
                _media_debug(
                    "DL_FORCE_MP4",
                    guild_id=ctx.guild.id if ctx.guild else None,
                    user_id=ctx.author.id,
                    source_format=formato_origen
                )
                await msg_estado.edit(
                    content=f"⏳ Convirtiendo el video de {formato_origen} a MP4..."
                )
                convertido, conv_err = _force_mp4_file(archivo, tmpdir)
                if not convertido:
                    _metric_bump("media_failures")
                    _media_debug(
                        "DL_FORCE_MP4_FAIL",
                        guild_id=ctx.guild.id if ctx.guild else None,
                        user_id=ctx.author.id,
                        source_format=formato_origen,
                        error=conv_err[:180]
                    )
                    await msg_estado.edit(content=None, embed=discord.Embed(
                        title="❌ No pude preparar el video en MP4",
                        description=(
                            f"El video se descargó en **{formato_origen}** y la conversión a MP4 falló.\n"
                            f"```{conv_err}```"
                        ),
                        color=discord.Color(COLOR_PELIGRO)
                    ))
                    return
                archivo = convertido
                archivo_final = os.path.basename(convertido)

            tamano_mb = os.path.getsize(archivo) / (1024 * 1024)

            CATBOX_LIMIT_MB = 6   # Si el archivo supera esto, se sube a catbox
            DISCORD_MAX_MB  = 50  # Limite duro de Discord
            # Tier 🌱+ tienen l!dl sin límite de intentos diarios (ya no hay contador)
            # El limite de tamaño sigue siendo el de Discord/catbox

            if tamano_mb > DISCORD_MAX_MB:
                await msg_estado.edit(content=f"❌ El archivo pesa {tamano_mb:.1f}MB, supera el limite absoluto de {DISCORD_MAX_MB}MB.")
                return

            if _r2_credentials_present():
                await msg_estado.edit(content=f"📤 Subiendo ({tamano_mb:.1f}MB)...")
                r2_obj = await _subir_r2(archivo, archivo_final, source_url=url, requested_by=ctx.author.id)
                if r2_obj:
                    cdn_url = r2_obj["url"]
                    try:
                        await msg_estado.delete()
                    except:
                        pass
                    # Preview reproducible (revisar) + embed con botón de descarga
                    await ctx.send(cdn_url)
                    info_embed, info_view = _embed_descarga_cdn(
                        archivo_final, cdn_url, tamano_mb,
                        os.path.splitext(archivo_final)[1].lstrip("."),
                        autor=ctx.author, tipo="video",
                    )
                    await ctx.send(embed=info_embed, view=info_view)
                    _metric_bump("media_downloads")
                    _media_debug("DL_OK", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, mode="r2", size_mb=f"{tamano_mb:.1f}", key=r2_obj["key"])
                    _registrar_descarga(ctx, "dl", archivo_final, cdn_url, tamano_mb)
                    if teaser_dl:
                        n = _daily_limit_consume(userapp_dl_usos, ctx.author.id, 1)
                        await ctx.send(embed=_invite_embed("Cupo MD", f"Descarga **{n}/{USERAPP_DL_DAILY}** de hoy en MD. Invita el bot a un server para no tener este tope."), view=_invite_view() if n >= 3 else None)
                    return
                await msg_estado.edit(content="⚠️ No disponible; intento subida normal...")

            if tamano_mb > CATBOX_LIMIT_MB:
                # Subir a catbox.moe (API pública, sin auth)
                await msg_estado.edit(content=f"📤 Archivo grande ({tamano_mb:.1f}MB) - subiendo...")
                catbox_url = await _subir_catbox(archivo)
                if catbox_url:
                    es_litterbox = "litterbox" in catbox_url
                    host_txt = "LatamBOT" if not es_litterbox else "LatamBOT"
                    footer_txt = "LatamBOT"
                    # Discord solo hace preview de video si la URL está SOLA, sin embed ni texto.
                    # Mandamos dos mensajes: primero la URL sola (video embed), luego la info.
                    try:
                        await msg_estado.delete()
                    except:
                        pass
                    await ctx.send(catbox_url)  # <- URL sola = Discord hace preview de video
                    info_embed = discord.Embed(
                        title="📦 Video listo para descargar",
                        description=(
                            f"**{archivo_final[:60]}**\n"
                            f"Formato final: **{os.path.splitext(archivo_final)[1].lstrip('.').upper() or 'DESCONOCIDO'}**\n"
                            f"📥 **{tamano_mb:.1f}MB** • {host_txt} • "
                            f"Pedido por {ctx.author.mention}\n"
                            f"🔗 Fuente: `{url[:80]}`"
                        ),
                        color=discord.Color.green()
                    )
                    info_embed.set_footer(text=footer_txt)
                    await ctx.send(embed=info_embed)
                    _metric_bump("media_downloads")
                    _media_debug("DL_OK", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, mode="catbox", size_mb=f"{tamano_mb:.1f}")
                    _registrar_descarga(ctx, "dl", archivo_final, catbox_url, tamano_mb)
                    if teaser_dl:
                        n = _daily_limit_consume(userapp_dl_usos, ctx.author.id, 1)
                        await ctx.send(embed=_invite_embed("Cupo MD", f"Descarga **{n}/{USERAPP_DL_DAILY}** de hoy en MD. Invita el bot a un server para no tener este tope."), view=_invite_view() if n >= 3 else None)
                else:
                    await msg_estado.edit(embed=discord.Embed(
                        title="❌ Error al subir el archivo",
                        description=(
                        "No pude subir el archivo.\n\n"
                        "**Posibles causas:**\n"
                        "• El servidor no tiene acceso a internet\n"
                        "• El servicio de subida no está disponible\n"
                        "• El archivo tiene un formato no soportado\n\n"
                        "Intentá con `l!dl` en un video más corto (menos de 5MB para subir directo a Discord)."
                        ),
                        color=discord.Color(COLOR_PELIGRO)
                    ))
                return

            # Archivo pequeño: subir directo a Discord
            await msg_estado.edit(content=f"📤 Subiendo a Discord ({tamano_mb:.1f}MB)...")
            discord_file = discord.File(archivo, filename=archivo_final)
            embed = discord.Embed(
                title="📥 Video descargado",
                description=f"Fuente: {url[:100]}{'...' if len(url) > 100 else ''}",
                color=discord.Color.green(),
                timestamp=datetime.datetime.now(datetime.timezone.utc),
            )
            embed.add_field(name="Archivo", value=_clip_text(archivo_final, 100), inline=False)
            embed.add_field(name="Tamaño", value=f"{tamano_mb:.1f}MB", inline=True)
            embed.add_field(name="Formato", value=(os.path.splitext(archivo_final)[1].lstrip(".").upper() or "DESCONOCIDO"), inline=True)
            embed.add_field(name="Pedido por", value=ctx.author.mention, inline=True)
            embed.set_footer(text="LatamBOT • Descargado con yt-dlp")
            await ctx.send(embed=embed, file=discord_file)
            _metric_bump("media_downloads")
            _media_debug("DL_OK", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, mode="discord", size_mb=f"{tamano_mb:.1f}")
            if teaser_dl:
                n = _daily_limit_consume(userapp_dl_usos, ctx.author.id, 1)
                await ctx.send(embed=_invite_embed("Cupo MD", f"Descarga **{n}/{USERAPP_DL_DAILY}** de hoy en MD. Invita el bot a un server para no tener este tope."), view=_invite_view() if n >= 3 else None)
            try:
                await msg_estado.delete()
            except:
                pass

    except discord.HTTPException as e:
        if e.status == 413:
            await msg_estado.edit(content=f"❌ Archivo muy grande para Discord. Intenta con `l!dl` en un video más corto.")
        else:
            await msg_estado.edit(content=f"❌ Error al subir: {e}")
    except Exception as e:
        await msg_estado.edit(content=f"❌ Error inesperado: {str(e)[:200]}")
        print(f"[DL] Error: {traceback.format_exc()}")



# ==============================================================================
# EDICION DE IMAGENES (Pillow) - sin API externa
# ==============================================================================

async def _descargar_imagen(ctx) -> Optional[bytes]:
    """Obtiene bytes de imagen desde adjunto, reply o URL en el mensaje."""
    url = None
    # 1. Adjunto directo
    for att in ctx.message.attachments:
        if att.content_type and att.content_type.startswith("image/"):
            url = att.url; break
        ext = att.filename.lower().rsplit(".", 1)[-1] if "." in att.filename else ""
        if ext in ("png","jpg","jpeg","gif","webp"):
            url = att.url; break
    # 2. Reply con imagen
    if not url and ctx.message.reference:
        ref = await obtener_mensaje_referenciado(ctx.message)
        if ref:
            for att in ref.attachments:
                if att.content_type and att.content_type.startswith("image/"):
                    url = att.url; break
            if not url:
                for emb in ref.embeds:
                    if emb.image and emb.image.url:
                        url = emb.image.url; break
                    if emb.thumbnail and emb.thumbnail.url:
                        url = emb.thumbnail.url; break
                    if emb.url and re.search(r"\.(png|jpg|jpeg|gif|webp)(\?|$)", emb.url, re.IGNORECASE):
                        url = emb.url; break
    # 3. URL en el mensaje
    if not url:
        import re as _re
        urls = _re.findall(r'https?://\S+\.(?:png|jpg|jpeg|webp|gif)(?:\?\S*)?', ctx.message.content, _re.IGNORECASE)
        if urls:
            url = urls[0]
    if not url:
        return None
    try:
        async with aiohttp.ClientSession() as s:
            async with s.get(url, timeout=aiohttp.ClientTimeout(total=15)) as r:
                if r.status == 200:
                    return await r.read()
    except:
        pass
    return None


async def _enviar_imagen_editada(ctx, img_bytes: bytes, nombre: str = "resultado.png"):
    """Envia la imagen editada como archivo."""
    import io
    file = discord.File(io.BytesIO(img_bytes), filename=nombre)
    await ctx.reply(file=file, mention_author=False)


def _pil_disponible() -> bool:
    try:
        import PIL
        return True
    except ImportError:
        return False


@bot.command()
async def pixelar(ctx, escala: int = 12):
    """Pixelate una imagen. Uso: l!pixelar [escala=12] (adjunta imagen o responde a una)"""
    if not _pil_disponible():
        await ctx.send(embed=discord.Embed(description="❌ Editor de imágenes no disponible temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        return
    from PIL import Image
    import io
    data = await _descargar_imagen(ctx)
    if not data:
        await ctx.send(embed=discord.Embed(description="❌ Adjunta una imagen o responde a un mensaje con imagen.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    async with ctx.typing():
        escala = max(2, min(escala, 64))
        img = Image.open(io.BytesIO(data)).convert("RGBA")
        w, h = img.size
        small = img.resize((w // escala, h // escala), Image.NEAREST)
        result = small.resize((w, h), Image.NEAREST)
        buf = io.BytesIO()
        result.save(buf, format="PNG")
        await _enviar_imagen_editada(ctx, buf.getvalue(), "pixelado.png")


def _wrap_text_pil(draw, text: str, font, max_width: int) -> List[str]:
    import PIL.ImageFont as _IF
    words = (text or "").replace("\n", " ").split()
    if not words:
        return ["(sin texto)"]
    lines = []
    cur = ""
    for w in words:
        test = (cur + " " + w).strip()
        bbox = draw.textbbox((0, 0), test, font=font)
        if bbox[2] - bbox[0] <= max_width:
            cur = test
        else:
            if cur:
                lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines[:18]

