@bot.command()
async def sepia(ctx):
    """Aplica filtro sepia a una imagen."""
    if not _pil_disponible():
        await ctx.send(embed=discord.Embed(description="❌ Pillow no instalado.", color=discord.Color(COLOR_PELIGRO)))
        return
    from PIL import Image
    import io
    data = await _descargar_imagen(ctx)
    if not data:
        await ctx.send(embed=discord.Embed(description="❌ Adjunta una imagen.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    async with ctx.typing():
        img = Image.open(io.BytesIO(data)).convert("RGB")
        pixels = img.load()
        for y in range(img.height):
            for x in range(img.width):
                r, g, b = pixels[x, y]
                nr = min(255, int(r * 0.393 + g * 0.769 + b * 0.189))
                ng = min(255, int(r * 0.349 + g * 0.686 + b * 0.168))
                nb = min(255, int(r * 0.272 + g * 0.534 + b * 0.131))
                pixels[x, y] = (nr, ng, nb)
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        await _enviar_imagen_editada(ctx, buf.getvalue(), "sepia.png")


@bot.command()
async def deepfry(ctx):
    """Deep-fry una imagen (contraste y saturacion extremos).
    Tambien funciona respondiendo a un mensaje con imagen."""
    if not _pil_disponible():
        await ctx.send(embed=discord.Embed(description="❌ Pillow no instalado.", color=discord.Color(COLOR_PELIGRO)))
        return
    from PIL import Image, ImageEnhance, ImageFilter
    import io
    data = await _descargar_imagen(ctx)
    if not data:
        await ctx.send(embed=discord.Embed(description="❌ Adjunta una imagen o responde a una con `l!deepfry`.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    async with ctx.typing():
        img = Image.open(io.BytesIO(data)).convert("RGB")
        img = ImageEnhance.Sharpness(img).enhance(12.0)
        img = ImageEnhance.Contrast(img).enhance(6.0)
        img = ImageEnhance.Color(img).enhance(8.0)
        img = ImageEnhance.Brightness(img).enhance(1.4)
        img = img.filter(ImageFilter.SHARPEN)
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=3)
        await _enviar_imagen_editada(ctx, buf.getvalue(), "deepfried.jpg")


