@bot.command()
async def clearcookies(ctx):
    """Elimina tus cookies guardadas."""
    if ctx.author.id in _user_cookies:
        del _user_cookies[ctx.author.id]
        if ctx.author.id in _public_cookie_users:
            _public_cookie_users.remove(ctx.author.id)
        _sync_cookie_supporter(ctx.author.id, False, "clearcookies")
        await ctx.send(embed=discord.Embed(description="✅ Cookies cifradas eliminadas.", color=discord.Color(COLOR_EXITO)), delete_after=5)
    else:
        await ctx.send(embed=discord.Embed(description="No tenés cookies guardadas.", color=discord.Color(COLOR_INFO)), delete_after=5)


