# MÚSICA EN VC - l!play, l!skip, l!stop, l!queue, l!pause, l!resume
# Requiere: pip install yt-dlp PyNaCl
# PyNaCl es necesario para que discord.py pueda conectarse a canales de voz
# ==============================================================================

# Cola de música por servidor { guild_id: {"queue": [], "loop": False} }
_music_queues: Dict[int, Dict] = {}
_music_current: Dict[int, Dict] = {}  # {guild_id: {"title": str, "url": str}}

FFMPEG_OPTIONS = {
    "before_options": "-reconnect 1 -reconnect_streamed 1 -reconnect_delay_max 5",
    "options": "-vn -filter:a 'volume=0.5'",
}

# ── Cookies de yt-dlp ────────────────────────────────────────────────────────
# Para evitar restricciones de YouTube (rate limit, age-gate, etc.)
YTDLP_COOKIE_TEST_URL = "https://www.youtube.com/watch?v=dQw4w9WgXcQ"

# Cookies personalizadas por usuario (cifradas en memoria)
# { user_id: ["cookie_token_1", "cookie_token_2", ...] }
_user_cookies: Dict[int, List[str]] = {}
_public_cookie_users: set[int] = set()

def _split_cookie_payload(raw: str) -> List[str]:
    txt = (raw or "").strip()
    if not txt:
        return []
    parts = [p.strip() for p in txt.replace("\r\n", "\n").split("\n---\n") if p.strip()]
    if len(parts) <= 1:
        return [txt]
    return parts

def _write_cookie_tempfile(cookie_b64: str) -> str:
    cookie_data = _cookie_b64_to_text(cookie_b64)
    tmp = tempfile.NamedTemporaryFile(mode='w', suffix='.txt', delete=False, encoding='utf-8')
    tmp.write(cookie_data)
    tmp.close()
    return tmp.name


def _ensure_default_cookies_encrypted() -> None:
    for item in DEFAULT_YTDLP_COOKIES:
        if not isinstance(item, dict):
            continue
        if item.get("content_enc"):
            continue
        legacy_b64 = item.get("content_b64")
        if not legacy_b64:
            continue
        try:
            item["content_enc"] = _cookie_text_to_b64(_legacy_cookie_b64_to_text(legacy_b64))
            item.pop("content_b64", None)
        except Exception:
            continue


_ensure_default_cookies_encrypted()

def _get_default_cookie_b64() -> Optional[str]:
    for item in DEFAULT_YTDLP_COOKIES:
        cookie_b64 = (item or {}).get("content_enc", "") or (item or {}).get("content_b64", "")
        if cookie_b64:
            return cookie_b64
    return None


def _cookie_candidates(user_id: int = None) -> List[Dict[str, Any]]:
    candidates: List[Dict[str, Any]] = []
    if user_id and user_id in _user_cookies:
        for idx, cookie_b64 in enumerate(_user_cookies.get(user_id, []), start=1):
            candidates.append({
                "source": "user",
                "owner": f"user:{user_id}",
                "label": f"Usuario #{idx}",
                "cookie_b64": cookie_b64,
                "user_id": user_id,
                "public": user_id in _public_cookie_users,
            })
    for idx, item in enumerate(DEFAULT_YTDLP_COOKIES, start=1):
        cookie_b64 = (item or {}).get("content_enc", "") or (item or {}).get("content_b64", "")
        if not cookie_b64:
            continue
        owner = (item or {}).get("owner", f"default_{idx}")
        candidates.append({
            "source": "default",
            "owner": owner,
            "label": f"Default {owner}",
            "cookie_b64": cookie_b64,
            "user_id": None,
            "public": False,
        })
    candidates.append({
        "source": "none",
        "owner": "sin-cookie",
        "label": "Sin cookie",
        "cookie_b64": None,
        "user_id": None,
        "public": False,
    })
    return candidates

def _sync_cookie_supporter(user_id: int, is_valid: bool, accepted_by: str = "cookie-public") -> None:
    update_usuario(user_id, "isSupporter", bool(is_valid))
    if is_valid:
        kofi_activos[user_id] = {
            "tier": "kofi",
            "aceptado_por": accepted_by,
            "fecha": datetime.datetime.now(datetime.timezone.utc).isoformat(),
        }
    else:
        if user_id in kofi_activos and kofi_activos[user_id].get("aceptado_por") == "cookie-public":
            kofi_activos.pop(user_id, None)
    _save_runtime_state()

def _resolve_binary_cmd(bin_names: List[str], module_fallback: str = "") -> List[str]:
    """Busca binarios robustamente: PATH + rutas comunes + fallback módulo Python."""
    import shutil
    names = list(dict.fromkeys([n for n in (bin_names or []) if n]))
    candidates: List[str] = []

    for name in names:
        hit = shutil.which(name)
        if hit:
            candidates.append(hit)

    path_dirs = [p for p in (os.environ.get("PATH") or "").split(os.pathsep) if p]
    common_dirs = [
        "/usr/local/bin", "/usr/bin", "/bin",
        os.path.expanduser("~/.local/bin"),
        os.path.expanduser("~/bin"),
        "/home/pi/.local/bin",
        "/opt/homebrew/bin",
    ]
    all_dirs = list(dict.fromkeys(path_dirs + common_dirs))
    for d in all_dirs:
        for name in names:
            candidates.append(os.path.join(d, name))
    for name in names:
        candidates.append(sys.executable.replace("python3", name).replace("python", name))

    for path in dict.fromkeys(candidates):
        try:
            result = subprocess.run([path, "--version"], capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                return [path]
        except (FileNotFoundError, subprocess.TimeoutExpired, PermissionError):
            continue
        except:
            continue

    if module_fallback:
        try:
            result = subprocess.run([sys.executable, "-m", module_fallback, "--version"], capture_output=True, text=True, timeout=5)
            if result.returncode == 0:
                return [sys.executable, "-m", module_fallback]
        except:
            pass
    return []

def _resolve_ytdlp_cmd() -> List[str]:
    return _resolve_binary_cmd(["yt-dlp", "yt_dlp"], module_fallback="yt_dlp")


def _resolve_ffmpeg_cmd() -> List[str]:
    import shutil

    hit = shutil.which("ffmpeg")
    if hit:
        return [hit]

    for path in [
        "/usr/bin/ffmpeg",
        "/usr/local/bin/ffmpeg",
        "/bin/ffmpeg",
        "/snap/bin/ffmpeg",
    ]:
        if os.path.isfile(path):
            return [path]

    # Dejar que subprocess intente resolverlo y devuelva el error real.
    return ["ffmpeg"]


def _force_mp4_file(input_path: str, workdir: str) -> tuple[Optional[str], str]:
    ffmpeg_cmd = _resolve_ffmpeg_cmd()
    output_path = os.path.join(
        workdir,
        f"{os.path.splitext(os.path.basename(input_path))[0]}_latambot.mp4"
    )
    # Copia el video pero SIEMPRE pasa el audio a AAC (evita dejar Opus, que los
    # editores como Vegas no leen). Si el video no entra en mp4 (ej: VP9), falla y
    # cae al re-encode completo de abajo.
    remux_cmd = ffmpeg_cmd + [
        "-y",
        "-i", input_path,
        "-c:v", "copy",
        "-c:a", "aac",
        "-b:a", "192k",
        "-movflags", "+faststart",
        output_path,
    ]
    cmd = ffmpeg_cmd + [
        "-y",
        "-i", input_path,
        "-c:v", "libx264",
        "-preset", "veryfast",
        "-crf", "28",
        "-c:a", "aac",
        "-b:a", "128k",
        "-movflags", "+faststart",
        output_path,
    ]
    try:
        remux_res = subprocess.run(remux_cmd, capture_output=True, text=True, timeout=180)
        if remux_res.returncode == 0 and os.path.exists(output_path):
            return output_path, ""
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=240)
        if res.returncode == 0 and os.path.exists(output_path):
            return output_path, ""
        err = (res.stderr or remux_res.stderr or res.stdout or "Error de conversion").strip().splitlines()
        return None, (err[-1][:220] if err else "Error de conversion")
    except FileNotFoundError:
        return None, "FFmpeg no esta instalado o no se puede ejecutar desde el servicio. En Debian/Ubuntu instala con: sudo apt update && sudo apt install -y ffmpeg"
    except subprocess.TimeoutExpired:
        return None, "La conversion a mp4 tardo demasiado"
    except Exception as e:
        return None, str(e)[:220]

def _probe_cookie_status(cookie_b64: str) -> tuple[bool, str]:
    cookie_file = None
    try:
        ytdlp_cmd = _resolve_ytdlp_cmd()
        if not ytdlp_cmd:
            return False, "yt-dlp no encontrado en PATH"
        cookie_file = _write_cookie_tempfile(cookie_b64)
        proxy_args = ["--proxy", YTDLP_PROXY] if YTDLP_PROXY else []
        cmd = ytdlp_cmd + proxy_args + ["--cookies", cookie_file, "-f", "worst", "--max-filesize", "5M", "-o", os.devnull, YTDLP_COOKIE_TEST_URL]
        res = subprocess.run(cmd, capture_output=True, text=True, timeout=90)
        if res.returncode == 0:
            return True, "Online"
        err = (res.stderr or res.stdout or "Error").strip().splitlines()
        return False, (err[-1][:120] if err else "Fallo desconocido")
    except Exception as e:
        return False, str(e)[:120]
    finally:
        if cookie_file and os.path.exists(cookie_file):
            try:
                os.remove(cookie_file)
            except:
                pass

