@bot.tree.command(name="setcookies", description="Configura cookies de YouTube de forma privada")
@app_commands.describe(
    archivo="Archivo cookies.txt exportado desde el navegador",
    publico="Si es true, activa beneficios de apoyador mientras la cookie funcione",
    cookies_extra="Opcional: varias cookies separadas por una línea `---`"
)
async def setcookies_slash(i: discord.Interaction, archivo: discord.Attachment, publico: bool = False, cookies_extra: str = ""):
    await i.response.defer(ephemeral=True, thinking=True)
    if not archivo:
        await i.followup.send("Adjuntá un archivo de cookies válido.", ephemeral=True)
        return
    if archivo.size > 300_000:
        await i.followup.send("El archivo es demasiado grande (máx 300KB).", ephemeral=True)
        return
    try:
        raw = (await archivo.read()).decode("utf-8", errors="ignore")
        bloques = _split_cookie_payload(raw)
        if cookies_extra.strip():
            bloques.extend(_split_cookie_payload(cookies_extra))
        if not bloques:
            await i.followup.send("No se detectaron cookies en el contenido enviado.", ephemeral=True)
            return
        if len(bloques) > 10:
            await i.followup.send("Máximo permitido: 10 cookies por usuario.", ephemeral=True)
            return
        _user_cookies[i.user.id] = [_cookie_text_to_b64(c) for c in bloques]
        if publico:
            _public_cookie_users.add(i.user.id)
        else:
            _public_cookie_users.discard(i.user.id)
            _sync_cookie_supporter(i.user.id, False, "cookie-public")
        ok, detail = _probe_cookie_status(_user_cookies[i.user.id][0])
        if publico:
            _sync_cookie_supporter(i.user.id, ok, "cookie-public")
        estado = "Online" if ok else f"Fallando ({detail})"
        await i.followup.send(
            embed=discord.Embed(
                title="✅ Cookies actualizadas",
                description=(
                    f"Se guardaron **{len(_user_cookies[i.user.id])}** cookie(s) cifradas para tu usuario.\n"
                    f"{COOKIE_ENCRYPTION_NOTICE}\n"
                    f"Modo publico: **{'Si' if publico else 'No'}**\n"
                    f"Estado inicial: **{estado}**"
                ),
                color=discord.Color(COLOR_EXITO if ok else COLOR_ADVERTENCIA)
            ),
            ephemeral=True
        )
    except Exception as e:
        await i.followup.send(f"❌ Error al procesar cookies: `{e}`", ephemeral=True)

class CookieStatusView(discord.ui.View):
    def __init__(self, owner_id: int, resultados: List[Dict[str, str]], per_page: int = 5):
        super().__init__(timeout=None)
        self.owner_id = owner_id
        self.resultados = resultados
        self.per_page = max(1, per_page)
        self.page = 0
        self.total_pages = max(1, math.ceil(len(resultados) / self.per_page))

    async def interaction_check(self, i: discord.Interaction) -> bool:
        if i.user.id != self.owner_id:
            await i.response.send_message("Este panel no es para vos.", ephemeral=True)
            return False
        return True

    def _embed(self) -> discord.Embed:
        start = self.page * self.per_page
        end = start + self.per_page
        chunk = self.resultados[start:end]
        lines = []
        for row in chunk:
            lines.append(f"Cookie de **{row['owner']}** Status: **{row['status']}**")
            if row.get("detail"):
                lines.append(f"-# Detalle: {row['detail']}")
        emb = discord.Embed(
            title="🍪 Estado de Cookies",
            description=(
                ("\n".join(lines) if lines else "No hay cookies por defecto configuradas.")
                + f"\n\n-# {COOKIE_ENCRYPTION_NOTICE}"
            ),
            color=discord.Color(COLOR_PRIMARIO)
        )
        emb.set_footer(text=f"Página {self.page+1}/{self.total_pages}")
        return emb

    @discord.ui.button(label="◀️", style=discord.ButtonStyle.secondary, custom_id="latambot_cookie_prev")
    async def prev_page(self, i: discord.Interaction, _):
        self.page = (self.page - 1) % self.total_pages
        await i.response.edit_message(embed=self._embed(), view=self)

    @discord.ui.button(label="▶️", style=discord.ButtonStyle.secondary, custom_id="latambot_cookie_next")
    async def next_page(self, i: discord.Interaction, _):
        self.page = (self.page + 1) % self.total_pages
        await i.response.edit_message(embed=self._embed(), view=self)

@bot.command()
async def cookiestatus(ctx):
    """Muestra el estado de las cookies por defecto."""
    async with ctx.typing():
        defaults = [
            (x.get("owner", "desconocido"), x.get("content_enc", "") or x.get("content_b64", ""))
            for x in DEFAULT_YTDLP_COOKIES
            if (x.get("content_enc", "") or x.get("content_b64", ""))
        ]
        if not defaults:
            await ctx.send(embed=discord.Embed(description="No hay cookies por defecto configuradas.", color=discord.Color(COLOR_INFO)))
            return
        resultados = []
        for owner, cookie_b64 in defaults:
            ok, detail = _probe_cookie_status(cookie_b64)
            resultados.append({
                "owner": owner,
                "status": "Online" if ok else "Fallando",
                "detail": "" if ok else detail
            })
    view = CookieStatusView(ctx.author.id, resultados, per_page=5)
    await ctx.send(embed=view._embed(), view=view)

def _get_ydl_opts(user_id: int = None, cookie_b64: str = None, use_default_cookie: bool = True) -> dict:
    """Construye las opciones de yt-dlp y aplica una cookie puntual si se provee."""
    opts = {
        "format": "bestaudio/best",
        "noplaylist": True,
        "quiet": True,
        "no_warnings": True,
        "default_search": "ytsearch",
        "source_address": "0.0.0.0",
    }
    if YTDLP_PROXY:
        opts["proxy"] = YTDLP_PROXY
    selected_cookie = cookie_b64 or (_get_default_cookie_b64() if use_default_cookie else None)
    if selected_cookie:
        try:
            opts["cookiefile"] = _write_cookie_tempfile(selected_cookie)
        except:
            pass
    return opts

YDL_OPTS = _get_ydl_opts(use_default_cookie=False)

async def _get_audio_url(query: str, user_id: int = None) -> dict:
    """Obtiene URL de audio de YouTube u otras plataformas."""
    import yt_dlp as _ydl
    loop = asyncio.get_running_loop()
    candidates = _cookie_candidates(user_id) or [{"source": "none", "cookie_b64": None, "user_id": None, "public": False}]
    def _extract():
        last_exc = None
        for cand in candidates:
            opts = _get_ydl_opts(user_id, cand.get("cookie_b64"), use_default_cookie=cand.get("source") != "none")
            cookie_tmp = opts.get("cookiefile")
            try:
                with _ydl.YoutubeDL(opts) as ydl:
                    if not query.startswith("http"):
                        info = ydl.extract_info(f"ytsearch:{query}", download=False)
                        if "entries" in info and info["entries"]:
                            info = info["entries"][0]
                    else:
                        info = ydl.extract_info(query, download=False)
                    if cand.get("public") and cand.get("user_id"):
                        _sync_cookie_supporter(cand["user_id"], True, "cookie-public")
                    return {
                        "title": info.get("title", "Desconocido"),
                        "url": info.get("url", ""),
                        "duration": info.get("duration", 0),
                        "webpage_url": info.get("webpage_url", query),
                        "thumbnail": info.get("thumbnail", ""),
                    }
            except Exception as e:
                last_exc = e
                if cand.get("public") and cand.get("user_id"):
                    _sync_cookie_supporter(cand["user_id"], False, "cookie-public")
            finally:
                if cookie_tmp and os.path.exists(cookie_tmp):
                    try:
                        os.remove(cookie_tmp)
                    except:
                        pass
        raise last_exc or RuntimeError("No se pudo extraer audio")
    return await loop.run_in_executor(None, _extract)


async def _extract_ytdlp_info(target: str, user_id: int = None) -> dict:
    import yt_dlp as _ydl

    loop = asyncio.get_running_loop()
    candidates = _cookie_candidates(user_id)

    def _extract():
        last_exc = None
        for cand in candidates:
            opts = _get_ydl_opts(user_id, cand.get("cookie_b64"), use_default_cookie=cand.get("source") != "none")
            opts.update({
                "skip_download": True,
                "extract_flat": False,
            })
            cookie_tmp = opts.get("cookiefile")
            try:
                with _ydl.YoutubeDL(opts) as ydl:
                    info = ydl.extract_info(target, download=False)
                    if info and "entries" in info and info["entries"]:
                        info = info["entries"][0]
                    return info
            except Exception as e:
                last_exc = e
            finally:
                if cookie_tmp and os.path.exists(cookie_tmp):
                    try:
                        os.remove(cookie_tmp)
                    except Exception:
                        pass
        raise last_exc or RuntimeError("No pude leer informacion del enlace")

    return await loop.run_in_executor(None, _extract)

def _play_next(guild_id: int, voice_client):
    """Reproduce el siguiente en la cola."""
    queue = _music_queues.get(guild_id, {}).get("queue", [])
    if not queue:
        _music_current.pop(guild_id, None)
        # Auto-desconectar después de 3 minutos de inactividad
        async def _auto_disconnect():
            await asyncio.sleep(180)
            if voice_client.is_connected() and not voice_client.is_playing():
                await voice_client.disconnect()
        asyncio.run_coroutine_threadsafe(
            _auto_disconnect(),
            voice_client.loop
        )
        return
    siguiente = queue.pop(0)
    _music_current[guild_id] = siguiente

    async def _do_play():
        try:
            # Re-extraer URL fresco (los URLs de yt-dlp expiran)
            info_fresh = await _get_audio_url(siguiente.get("webpage_url", siguiente.get("url", "")))
            url = info_fresh.get("url", siguiente["url"])
        except:
            url = siguiente["url"]
        try:
            source = discord.FFmpegPCMAudio(url, **FFMPEG_OPTIONS)
            source = discord.PCMVolumeTransformer(source, volume=0.5)
            if voice_client.is_connected():
                voice_client.play(source, after=lambda e: _play_next(guild_id, voice_client))
        except Exception as ex:
            print(f"[MUSIC] Error reproduciendo: {ex}")
            _play_next(guild_id, voice_client)

    asyncio.run_coroutine_threadsafe(_do_play(), voice_client.loop)


@bot.command(aliases=["p"])
async def play(ctx, *, query: str = None):
    """Reproduce música en el canal de voz.
    Uso: l!play <nombre o URL>
    Ej: l!play never gonna give you up"""
    if not query:
        await ctx.send(embed=discord.Embed(description="**Uso:** `l!play <canción o URL>`", color=discord.Color(COLOR_INFO)))
        return
    _vc_state, voice_error = _voice_precheck(ctx)
    if voice_error:
        await ctx.send(embed=discord.Embed(description="❌ Tenés que estar en un canal de voz.", color=discord.Color(COLOR_PELIGRO)))
        return
    vc = ctx.voice_client
    if not vc:
        try:
            vc = await ctx.author.voice.channel.connect()
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ No pude conectarme al canal de voz: `{e}`\nAsegurate de que tengo permisos.", color=discord.Color(COLOR_PELIGRO)))
            return
    elif vc.channel != ctx.author.voice.channel:
        await vc.move_to(ctx.author.voice.channel)

    msg = await ctx.send(embed=discord.Embed(description=f"🔍 Buscando: `{query}`...", color=discord.Color(COLOR_PRIMARIO)))
    _media_debug("MUSIC_LOOKUP", guild_id=ctx.guild.id if ctx.guild else None, user_id=ctx.author.id, query=query[:120])
    try:
        info = await _get_audio_url(query, user_id=ctx.author.id)
    except Exception as e:
        await msg.edit(embed=discord.Embed(description=f"❌ No encontré el audio: `{str(e)[:100]}`", color=discord.Color(COLOR_PELIGRO)))
        return

    gid = ctx.guild.id
    if gid not in _music_queues:
        _music_queues[gid] = {"queue": [], "loop": False}

    if vc.is_playing() or vc.is_paused():
        _music_queues[gid]["queue"].append(info)
        dur = f"{info['duration']//60}:{info['duration']%60:02d}" if info.get("duration") else "?"
        embed = discord.Embed(
            title="➕ Agregado a la cola",
            description=f"**[{info['title']}]({info['webpage_url']})**",
            color=discord.Color(COLOR_PRIMARIO)
        )
        embed.add_field(name="Duración", value=dur, inline=True)
        embed.add_field(name="Posición", value=str(len(_music_queues[gid]["queue"])), inline=True)
        if info.get("thumbnail"):
            embed.set_thumbnail(url=info["thumbnail"])
        await msg.edit(embed=embed)
        _metric_bump("music_queued")
    else:
        _music_current[gid] = info
        # Usar URL directamente (es fresca, justo extraída)
        try:
            source = discord.FFmpegPCMAudio(info["url"], **FFMPEG_OPTIONS)
            source = discord.PCMVolumeTransformer(source, volume=0.5)
            vc.play(source, after=lambda e: _play_next(gid, vc))
        except Exception as _pe:
            await msg.edit(embed=discord.Embed(
                description=f"❌ Error al reproducir.\n**Causa:** `{str(_pe)[:150]}`\n**Solución:** Verificá que ffmpeg esté instalado en el servidor.",
                color=discord.Color(COLOR_PELIGRO)
            ))
            return
        dur = f"{info['duration']//60}:{info['duration']%60:02d}" if info.get("duration") else "?"
        embed = discord.Embed(
            title="🎵 Reproduciendo",
            description=f"**[{info['title']}]({info['webpage_url']})**",
            color=discord.Color.from_rgb(30, 215, 96)
        )
        embed.add_field(name="Duración", value=dur, inline=True)
        embed.add_field(name="Canal", value=ctx.author.voice.channel.mention, inline=True)
        if info.get("thumbnail"):
            embed.set_thumbnail(url=info["thumbnail"])
        embed.set_footer(text="l!skip | l!stop | l!queue | l!pause")
        await msg.edit(embed=embed)
        _metric_bump("music_started")


