class ImagenSearchView(discord.ui.View):
    """Navegar entre resultados de Google Images."""
    def __init__(self, imgs: list, query: str, nsfw_srv: bool = False):
        super().__init__(timeout=None)
        self.imgs = imgs
        self.query = query
        self.nsfw_srv = nsfw_srv
        self.idx = 0
        # Link button - se actualiza el url al navegar
        img = imgs[0] if imgs else {}
        link_url = img.get("link", img.get("original", "https://google.com"))
        self._link_btn = discord.ui.Button(
            label="🔗 Abrir fuente",
            style=discord.ButtonStyle.link,
            url=link_url,
            row=1
        )
        self.add_item(self._link_btn)

    def _make_embed(self) -> discord.Embed:
        img = self.imgs[self.idx]
        embed = discord.Embed(
            title=f"🖼️ {self.query[:60]}",
            color=discord.Color(COLOR_PRIMARIO)
        )
        embed.set_image(url=img.get("original", img.get("thumbnail", "")))
        titulo_img = img.get("title", "")[:100]
        fuente = img.get("source", "")
        link = img.get("link", "")
        if titulo_img:
            embed.description = f"[{titulo_img}]({link})" if link else titulo_img
        pie = f"LatamBOT | Imagenes {self.idx+1}/{len(self.imgs)} • Fuente: {fuente}"
        if not self.nsfw_srv:
            pie += " • Busqueda segura activa"
        embed.set_footer(text=pie[:2048])
        return embed

    def _update_link(self):
        img = self.imgs[self.idx]
        new_url = img.get("link", img.get("original", "https://google.com"))
        # Recrear el link button con la nueva URL (discord.py no permite editar url in-place)
        self.remove_item(self._link_btn)
        self._link_btn = discord.ui.Button(
            label="🔗 Abrir fuente",
            style=discord.ButtonStyle.link,
            url=new_url,
            row=1
        )
        self.add_item(self._link_btn)

    @discord.ui.button(label="◀️", style=discord.ButtonStyle.secondary, row=0, custom_id="latambot_img_prev")
    async def anterior(self, i: discord.Interaction, b):
        self.idx = (self.idx - 1) % len(self.imgs)
        self._update_link()
        await i.response.edit_message(embed=self._make_embed(), view=self)

    @discord.ui.button(label="▶️", style=discord.ButtonStyle.secondary, row=0, custom_id="latambot_img_next")
    async def siguiente(self, i: discord.Interaction, b):
        self.idx = (self.idx + 1) % len(self.imgs)
        self._update_link()
        await i.response.edit_message(embed=self._make_embed(), view=self)




