@bot.command()
@commands.check(es_staff)
async def giveaway(ctx, tiempo: str, ganadores: int, *, premio: str):
    seg = convertir_duracion(tiempo)
    if not seg:
        await ctx.send("Ej: `l!giveaway 1h 1 Premio epico`")
        return
    if ganadores < 1:
        await ctx.send("Minimo 1 ganador.")
        return
    fin_timestamp = int(time.time() + seg)
    embed = discord.Embed(title=f"SORTEO: {premio}", color=discord.Color.gold())
    embed.add_field(name="Organizado por", value=ctx.author.mention)
    embed.add_field(name="Ganadores", value=str(ganadores))
    embed.add_field(name="Termina", value=f"<t:{fin_timestamp}:R>")
    embed.set_footer(text="Presiona el boton para participar!")
    msg = await ctx.send(embed=embed)
    sorteos_activos[msg.id] = {
        "premio": premio, "ganadores": ganadores,
        "fin": time.time() + seg, "canal_id": ctx.channel.id,
        "participantes": [], "organizador": ctx.author.id
    }
    await msg.edit(view=GiveawayView(msg.id))

async def terminar_sorteo(msg_id: int):
    if msg_id not in sorteos_activos:
        return
    sorteo = sorteos_activos.pop(msg_id)
    canal = bot.get_channel(sorteo["canal_id"])
    if not canal:
        return
    try:
        msg = await canal.fetch_message(msg_id)
    except:
        return
    participantes = sorteo["participantes"]
    if not participantes:
        await canal.send(f"El sorteo **{sorteo['premio']}** termino sin participantes.")
        return
    num_gan = min(sorteo["ganadores"], len(participantes))
    ganadores_ids = random.sample(participantes, num_gan)
    menciones = " ".join(f"<@{uid}>" for uid in ganadores_ids)
    embed = discord.Embed(title="Sorteo Terminado!", color=discord.Color.gold())
    embed.add_field(name="Premio", value=sorteo["premio"])
    embed.add_field(name=f"Ganadores ({num_gan})", value=menciones, inline=False)
    await msg.edit(embed=embed, view=None)
    await canal.send(f"Felicitaciones {menciones}! Ganaron **{sorteo['premio']}**!")

