@bot.command()
async def poll(ctx, *, contenido: str):
    partes = [p.strip() for p in contenido.split("|")]
    if len(partes) < 3:
        await ctx.send("Formato: `l!poll Pregunta | Opcion 1 | Opcion 2 ...` (min. 2 opciones)")
        return
    pregunta = partes[0]
    opciones = partes[1:6]
    embed = discord.Embed(title=f"{pregunta}", color=discord.Color.blue())
    desc = ""
    for i, op in enumerate(opciones):
        desc += f"**{op}**\n`{'░'*10}` 0 (0.0%)\n\n"
    embed.description = desc
    embed.set_footer(text=f"Por {ctx.author.display_name} | 0 votos")
    msg = await ctx.send(embed=embed)
    await msg.edit(view=PollView(opciones, msg.id))
    try: await ctx.message.delete()
    except: pass

