def _render_sortalg_gif(algoritmo: str, cantidad: int, fps: int, tema: str, valid_themes: Dict[str, Dict[str, tuple[int, int, int]]]) -> io.BytesIO:
    steps: List[Dict[str, Any]] = []

    def _record(snapshot: List[int], a: Optional[int] = None, b: Optional[int] = None, done: int = -1) -> None:
        if len(steps) < 900:
            steps.append({"arr": snapshot[:], "a": a, "b": b, "sorted_upto": done})

    values = [random.randint(12, 260) for _ in range(cantidad)]
    arr = values[:]
    _record(arr, done=-1)
    if algoritmo == "bubble":
        n = len(arr)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                _record(arr, j, j + 1, n - i - 1 if i else -1)
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
                    swapped = True
                    _record(arr, j, j + 1, n - i - 1)
            if not swapped:
                break
    elif algoritmo == "selection":
        for i in range(len(arr)):
            min_idx = i
            for j in range(i + 1, len(arr)):
                _record(arr, min_idx, j, i - 1)
                if arr[j] < arr[min_idx]:
                    min_idx = j
                    _record(arr, i, min_idx, i - 1)
            arr[i], arr[min_idx] = arr[min_idx], arr[i]
            _record(arr, i, min_idx, i)
    elif algoritmo == "quick":
        def _quick(lo: int, hi: int) -> None:
            if lo >= hi:
                return
            pivot = arr[hi]
            i = lo
            for j in range(lo, hi):
                _record(arr, j, hi, lo - 1)
                if arr[j] <= pivot:
                    arr[i], arr[j] = arr[j], arr[i]
                    _record(arr, i, j, lo - 1)
                    i += 1
            arr[i], arr[hi] = arr[hi], arr[i]
            _record(arr, i, hi, i)
            _quick(lo, i - 1)
            _quick(i + 1, hi)
        _quick(0, len(arr) - 1)
    else:
        for i in range(1, len(arr)):
            j = i
            while j > 0 and arr[j - 1] > arr[j]:
                _record(arr, j - 1, j, i - 1)
                arr[j - 1], arr[j] = arr[j], arr[j - 1]
                _record(arr, j - 1, j, i)
                j -= 1
            _record(arr, j, i, i)
    _record(arr, done=len(arr) - 1)

    theme_cfg = valid_themes[tema]
    width, height = 640, 360
    margin_x, margin_y = 20, 42
    bar_space = max(1, (width - margin_x * 2) // len(values))
    bar_w = max(1, bar_space - 1)
    max_val = max(values) or 1
    stride = max(1, len(steps) // 120)
    sampled_steps = steps[::stride]
    if sampled_steps[-1]["arr"] != arr:
        sampled_steps.append({"arr": arr[:], "a": None, "b": None, "sorted_upto": len(arr) - 1})

    frames = []
    for step in sampled_steps:
        img = Image.new("RGB", (width, height), theme_cfg["bg"])
        draw = ImageDraw.Draw(img)
        draw.rectangle((0, height - margin_y, width, height - margin_y + 2), fill=theme_cfg["axis"])
        progress = int((max(step.get("sorted_upto", -1), -1) + 1) / len(values) * width)
        if progress > 0:
            draw.rectangle((0, 0, progress, 7), fill=theme_cfg["sorted"])
        for idx, val in enumerate(step["arr"][:len(values)]):
            h = int(((height - margin_y * 2) * (val / max_val)))
            x0 = margin_x + idx * bar_space
            y0 = height - margin_y - h
            color = theme_cfg["active"] if idx in {step.get("a"), step.get("b")} else theme_cfg["sorted"] if idx <= int(step.get("sorted_upto", -1)) else theme_cfg["idle"]
            draw.rectangle((x0, y0, x0 + bar_w, height - margin_y), fill=color)
        frames.append(img)
    out = io.BytesIO()
    frames[0].save(out, format="GIF", save_all=True, append_images=frames[1:], duration=max(20, int(1000 / fps)), loop=0, optimize=True)
    out.seek(0)
    return out


@bot.command(name="sortalg")
async def sortalg(ctx, algoritmo: str = "random", cantidad: int = 52, fps: int = 24, tema: str = "classic"):
    """Genera un video de sorting.
    Uso: l!sortalg [algoritmo] [cantidad] [fps] [tema]
    Algoritmos: random, bubble, insertion, selection, quick
    Temas: classic, sunset, ice, mono
    """
    algoritmo = (algoritmo or "random").strip().lower()
    tema = (tema or "classic").strip().lower()
    valid_algorithms = {"random", "bubble", "insertion", "selection", "quick"}
    valid_themes = {
        "classic": {"bg": (8, 8, 8), "idle": (235, 235, 235), "active": (230, 60, 60), "sorted": (60, 255, 85), "axis": (70, 70, 70)},
        "sunset": {"bg": (24, 8, 18), "idle": (255, 214, 165), "active": (255, 99, 71), "sorted": (255, 203, 107), "axis": (120, 72, 92)},
        "ice": {"bg": (8, 20, 28), "idle": (220, 244, 255), "active": (78, 172, 255), "sorted": (112, 255, 214), "axis": (60, 110, 135)},
        "mono": {"bg": (16, 16, 16), "idle": (210, 210, 210), "active": (255, 255, 255), "sorted": (140, 140, 140), "axis": (80, 80, 80)},
    }
    if algoritmo not in valid_algorithms:
        await ctx.send(embed=_make_error_embed("Algoritmo invalido", f"`{algoritmo}` no existe.", "Usa `random`, `bubble`, `insertion`, `selection` o `quick`."))
        return
    if tema not in valid_themes:
        await ctx.send(embed=_make_error_embed("Tema invalido", f"`{tema}` no existe.", "Usa `classic`, `sunset`, `ice` o `mono`."))
        return
    try:
        cantidad = max(8, min(int(cantidad), 96))
        fps = max(8, min(int(fps), 30))
    except (TypeError, ValueError):
        await ctx.send(embed=_make_error_embed("Parametros invalidos", "Cantidad y FPS deben ser numeros.", "Ejemplo: `l!sortalg quick 48 18 ice`."))
        return
    if algoritmo == "random":
        algoritmo = random.choice(["bubble", "insertion", "selection", "quick"])

    await ctx.send(embed=_make_embed("SortAlg", f"Renderizando `{algoritmo}` con `{cantidad}` barras a `{fps}` FPS y tema `{tema}`...", COLOR_INFO))
    try:
        gif_data = await asyncio.wait_for(
            asyncio.to_thread(_render_sortalg_gif, algoritmo, cantidad, fps, tema, valid_themes),
            timeout=90,
        )
        meta = _make_embed("SortAlg listo", f"Algoritmo: `{algoritmo}`\nBarras: `{cantidad}`\nFPS: `{fps}`\nTema: `{tema}`", COLOR_EXITO)
        await ctx.send(embed=meta, file=discord.File(gif_data, filename=f"sortalg_{algoritmo}.gif"))
    except asyncio.TimeoutError:
        await ctx.send(embed=_make_error_embed("SortAlg tardo demasiado", "El render excedio el tiempo maximo y fue cancelado.", "Prueba con menos barras o menos FPS. Ejemplo: `l!sortalg quick 40 15`."))
    except Exception as e:
        await ctx.send(embed=_make_error_embed("SortAlg fallo", _safe_exc_text(e), _exception_fix_hint(e)))

