# Cache de URLs (nekosbest) para no pegarle a la API en cada comando
_nekos_cache: Dict[str, List[str]] = {}
_nekos_cache_meta: Dict[str, Dict[str, str]] = {}  # url -> anime_name
_nekos_cache_time: Dict[str, float] = {}
_nekos_last_gif: Dict[str, str] = {}
_nekos_client = None
NEKOS_CACHE_TTL = 1800  # 30 minutos


def _nekos_get_client():
    """Cliente singleton del wrapper oficial nekosbest."""
    global _nekos_client
    if _nekos_client is None:
        try:
            from nekosbest import Client as NekosBestClient
            _nekos_client = NekosBestClient()
        except Exception as e:
            print(f"[NEKOS] No pude iniciar el cliente: {e}")
            return None
    return _nekos_client


def _nekos_pick(categoria: str, candidates: List[str]) -> Optional[str]:
    valid = [u for u in candidates if isinstance(u, str) and u.startswith("https://")]
    if not valid:
        return None
    ultimo = _nekos_last_gif.get(categoria)
    if len(valid) > 1 and ultimo in valid:
        valid = [u for u in valid if u != ultimo]
    elegido = random.choice(valid)
    _nekos_last_gif[categoria] = elegido
    return elegido


async def _get_rp_gif(accion: str) -> str:
    """GIF de roleplay desde nekos.best (wrapper oficial). Evita repetir el ultimo."""
    url, _anime = await _get_rp_gif_meta(accion)
    return url


async def _get_rp_gif_meta(accion: str) -> tuple:
    """Devuelve (url, anime_name) desde nekos.best."""
    import time as _time

    categoria = NEKOS_MAP.get(accion, accion)
    ahora = _time.time()

    if (
        categoria in _nekos_cache
        and _nekos_cache[categoria]
        and ahora - _nekos_cache_time.get(categoria, 0) < NEKOS_CACHE_TTL
    ):
        cached = _nekos_pick(categoria, _nekos_cache[categoria])
        if cached:
            return cached, _nekos_cache_meta.get(categoria, {}).get(cached, "")

    client = _nekos_get_client()
    if client is not None:
        try:
            result = await client.get_image(categoria, 12)
            items = result if isinstance(result, list) else [result]
            urls = []
            meta = _nekos_cache_meta.setdefault(categoria, {})
            for item in items:
                url = getattr(item, "url", None) or (item.get("url") if isinstance(item, dict) else None)
                if not (isinstance(url, str) and url.startswith("https://")):
                    continue
                urls.append(url)
                anime = getattr(item, "anime_name", None) or (item.get("anime_name") if isinstance(item, dict) else None)
                if anime:
                    meta[url] = str(anime)[:80]
            if urls:
                merged = (_nekos_cache.get(categoria, []) + urls)[-80:]
                _nekos_cache[categoria] = merged
                _nekos_cache_time[categoria] = ahora
                elegido = _nekos_pick(categoria, merged)
                if elegido:
                    return elegido, meta.get(elegido, "")
        except Exception as e:
            print(f"[NEKOS] Error ({categoria}): {e}")

    # Fallback HTTP directo (sin wrapper) por si el paquete fallo al arrancar
    try:
        async with aiohttp.ClientSession(headers={"User-Agent": "LatamBOT/59 (nekos.best)"}) as session:
            async with session.get(
                f"https://nekos.best/api/v2/{categoria}",
                params={"amount": 12},
                timeout=aiohttp.ClientTimeout(total=8),
            ) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    urls = []
                    meta = _nekos_cache_meta.setdefault(categoria, {})
                    for item in data.get("results") or []:
                        if not isinstance(item, dict):
                            continue
                        url = str(item.get("url") or "")
                        if url.startswith("https://"):
                            urls.append(url)
                            if item.get("anime_name"):
                                meta[url] = str(item["anime_name"])[:80]
                    if urls:
                        merged = (_nekos_cache.get(categoria, []) + urls)[-80:]
                        _nekos_cache[categoria] = merged
                        _nekos_cache_time[categoria] = ahora
                        elegido = _nekos_pick(categoria, merged)
                        if elegido:
                            return elegido, meta.get(elegido, "")
                else:
                    print(f"[NEKOS] HTTP {resp.status} para '{categoria}'")
    except Exception as e:
        print(f"[NEKOS] Fallback HTTP fallo ({categoria}): {e}")

    # Ultimo recurso: otra categoria conocida de nekos (nunca Tenor)
    if categoria != "hug" and _nekos_cache.get("hug"):
        elegido = _nekos_pick("hug", _nekos_cache["hug"])
        if elegido:
            return elegido, _nekos_cache_meta.get("hug", {}).get(elegido, "")
    return "https://nekos.best/api/v2/hug/e549230e-34a7-4834-86a9-c4c76df0531d.gif", "Hayate no Gotoku"

