def _clip_text(value: str, limit: int = 1024, fallback: str = "Sin datos") -> str:
    txt = _fix_mojibake_text((value or "").strip())
    if not txt:
        return _fix_mojibake_text(fallback)
    return txt[: limit - 3] + "..." if len(txt) > limit else txt


def _human_file_size(value: Optional[int]) -> str:
    if value is None:
        return "?"
    size = float(max(value, 0))
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024 or unit == "GB":
            return f"{size:.1f}{unit}" if unit != "B" else f"{int(size)}B"
        size /= 1024
    return f"{int(size)}B"


_UWU_ACTIONS = [
    "*mueve su colita*",
    "*se acomoda las orejitas*",
    "*da un saltito*",
    "*mira brillante*",
]
_UWU_SUFFIXES = [" nya~", "... nya", " >w<", " uwu", " NYA!!!"]


def _uwufy_word(word: str, rng: random.Random) -> str:
    if not word or re.match(r"^(https?://|<[@#:&]|:\w+:)", word):
        return word
    base = word
    if re.search(r"[A-Za-zÁÉÍÓÚáéíóúÑñ]", base):
        base = re.sub(r"[rl]", "w", base)
        base = re.sub(r"[RL]", "W", base)
        base = re.sub(r"n([aeiouáéíóú])", r"ny\1", base, flags=re.IGNORECASE)
        if len(re.sub(r"[^A-Za-zÁÉÍÓÚáéíóúÑñ]", "", word)) >= 3 and rng.random() < 0.33:
            first = next((c for c in word if c.isalpha()), "")
            if first:
                base = f"{first}-{base}"
    return base


def _uwufy_text(text: str) -> str:
    clean = (text or "").strip()
    if not clean:
        return ""
    rng = random.Random(f"uwu::{clean.lower()}")
    tokens = re.split(r"(\s+)", clean)
    transformed = []
    inserted_action = False
    non_space_seen = 0
    for token in tokens:
        if not token or token.isspace():
            transformed.append(token)
            continue
        uwu_token = _uwufy_word(token, rng)
        transformed.append(uwu_token)
        non_space_seen += 1
        if not inserted_action and non_space_seen >= 2 and rng.random() < 0.45:
            transformed.append(f" {_UWU_ACTIONS[rng.randrange(len(_UWU_ACTIONS))]}")
            inserted_action = True
    result = "".join(transformed)
    if not inserted_action and len(result) > 10:
        result = f"{result} {_UWU_ACTIONS[rng.randrange(len(_UWU_ACTIONS))]}"
    if not re.search(r"(nya|uwu|>w<)", result, re.IGNORECASE):
        result = result.rstrip(".!? ") + _UWU_SUFFIXES[rng.randrange(len(_UWU_SUFFIXES))]
    return result


def _get_uwu_targets(guild_id: int) -> set[int]:
    cfg = get_config(guild_id) or {}
    return {int(x) for x in cfg.get("uwu_users", []) if str(x).isdigit()}


def _set_uwu_state(guild_id: int, user_id: int, enabled: bool) -> None:
    targets = _get_uwu_targets(guild_id)
    if enabled:
        targets.add(user_id)
    else:
        targets.discard(user_id)
    update_server_config(guild_id, "uwu_users", sorted(targets))


async def _get_or_create_relay_webhook(channel: Union[discord.TextChannel, discord.Thread]) -> tuple[Optional[discord.Webhook], Dict[str, Any]]:
    target_channel = channel.parent if isinstance(channel, discord.Thread) else channel
    send_kwargs: Dict[str, Any] = {}
    if isinstance(channel, discord.Thread):
        send_kwargs["thread"] = channel
    if not target_channel or not hasattr(target_channel, "webhooks"):
        return None, send_kwargs
    try:
        hooks = await target_channel.webhooks()
        for hook in hooks:
            if hook.user and hook.user.id == bot.user.id and hook.name == "LatamBOT Relay":
                return hook, send_kwargs
        hook = await target_channel.create_webhook(name="LatamBOT Relay", reason="Relay uwufiy")
        return hook, send_kwargs
    except Exception:
        return None, send_kwargs


async def _relay_uwu_message(msg: discord.Message) -> bool:
    webhook, send_kwargs = await _get_or_create_relay_webhook(msg.channel)
    if not webhook:
        return False
    files: List[discord.File] = []
    try:
        for att in msg.attachments[:8]:
            try:
                files.append(await att.to_file(use_cached=True))
            except Exception:
                pass
        content = _uwufy_text(msg.content or "")
        # Fallback: si el filtro deja vacío pero había texto, usar el original con sufijo
        if not content and (msg.content or "").strip():
            content = f"{msg.content.strip()} uwu"
        if msg.stickers:
            sticker_urls = " ".join(s.url for s in msg.stickers if getattr(s, "url", None))
            if sticker_urls:
                content = f"{content}\n{sticker_urls}".strip()
        if not content and not files:
            return False
        # OJO: no pasar files=None - discord.py lo trata como "provisto" e intenta
        # iterarlo ('NoneType' object is not iterable). Solo incluir el kwarg si hay.
        if files:
            send_kwargs["files"] = files
        try:
            await webhook.send(
                content=content or None,
                username=msg.author.display_name,
                avatar_url=msg.author.display_avatar.url,
                allowed_mentions=discord.AllowedMentions.none(),
                wait=False,
                **send_kwargs,
            )
        except Exception as e:
            print(f"[UWU] webhook.send fallo (texto={bool(content)}, files={len(files)}): {e}")
            return False
        _uwu_deleted_messages.add(msg.id)
        try:
            await msg.delete()
        except Exception:
            _uwu_deleted_messages.discard(msg.id)
            return False
        return True
    finally:
        for f in files:
            try:
                f.close()
            except Exception:
                pass


def _format_roles_preview(member: discord.Member, limit: int = 10) -> str:
    roles = [r.mention for r in member.roles if r.name != "@everyone"]
    if not roles:
        return "Ninguno"
    txt = " ".join(roles[:limit])
    if len(roles) > limit:
        txt += f" ... (+{len(roles) - limit})"
    return txt


def _bot_latency_ms() -> int:
    """Latencia del gateway en ms. Si aun no hay heartbeat, discord.py usa inf."""
    try:
        raw = float(bot.latency) * 1000.0
        if raw != raw or raw == float("inf") or raw < 0:  # NaN / inf
            return -1
        return int(round(raw))
    except Exception:
        return -1


def _latency_color(latency_ms: int) -> discord.Color:
    if latency_ms < 0:
        return discord.Color.light_grey()
    if latency_ms < 120:
        return discord.Color.green()
    if latency_ms < 250:
        return discord.Color.orange()
    return discord.Color.red()


def _robloxify_text(style: str, text: str) -> str:
    normalized = (style or "").strip().lower()
    source = (text or "").strip()
    if not source:
        return ""
    if normalized == "candado":
        return "🔒:" + "".join("•" if not ch.isspace() else ch for ch in source)
    if normalized == "hashtag":
        return "".join("#" if not ch.isspace() else ch for ch in source)
    return ""

