@bot.command()
async def info(ctx):
    if ctx.author.id != OWNER_ID and not es_staff(ctx):
        await ctx.send("Solo Staff.")
        return
    try:
        cpu_percent = psutil.cpu_percent(interval=0.5)
        ram = psutil.virtual_memory()
        disco = psutil.disk_usage('/')
        uptime_seg = int(time.time() - psutil.boot_time())
        python_ver = sys.version.split()[0]
        os_info = f"{platform.system()} {platform.release()}"
        cpu_info = platform.processor() or platform.machine()
        embed = discord.Embed(
            title="Info del Sistema",
            color=discord.Color.dark_green(),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.add_field(name="CPU", value=f"{cpu_percent}% uso\n`{cpu_info[:40]}`", inline=True)
        embed.add_field(name="RAM", value=f"{ram.percent}% uso\n{ram.used//1024//1024}MB / {ram.total//1024//1024}MB", inline=True)
        embed.add_field(name="Disco", value=f"{disco.percent}% uso\n{disco.used//1024//1024//1024}GB / {disco.total//1024//1024//1024}GB", inline=True)
        embed.add_field(name="Python", value=python_ver, inline=True)
        embed.add_field(name="OS", value=os_info, inline=True)
        embed.add_field(name="Uptime SO", value=formato_tiempo(uptime_seg), inline=True)
        _lat = _bot_latency_ms()
        embed.add_field(name="Bot Ping", value=("n/d" if _lat < 0 else f"{_lat}ms"), inline=True)
        embed.add_field(name="Servidores", value=str(len(bot.guilds)), inline=True)
        embed.add_field(name="Web", value=PUBLIC_BASE_URL or "self-hosted", inline=True)
        embed.set_footer(text=BOT_VERSION)
        await ctx.send(embed=embed)
    except ImportError:
        await ctx.send("❌ Módulo de sistema no disponible.")
    except Exception as e:
        await ctx.send(f"Error obteniendo info: {e}")

@bot.command()
async def note(ctx, *, texto: str):
    user_data = get_usuario(ctx.author.id)
    notas = user_data.get("notas", [])
    texto = _clip_text(texto, 350, "")
    notas.append({"texto": texto, "fecha": datetime.datetime.now().strftime("%d/%m/%Y %H:%M")})
    if len(notas) > 10:
        notas = notas[-10:]
    update_usuario(ctx.author.id, "notas", notas)
    embed = discord.Embed(
        title="Nota guardada",
        description=f"Se guardo tu nota **{len(notas)}/10**.\nUsa `l!notes` para verla completa.",
        color=discord.Color.teal(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.add_field(name="Vista previa", value=_clip_text(texto, 200), inline=False)
    await ctx.send(embed=embed, delete_after=10)
    try: await ctx.message.delete()
    except: pass

@bot.command()
async def notes(ctx):
    user_data = get_usuario(ctx.author.id)
    notas = user_data.get("notas", [])
    if not notas:
        await ctx.send(embed=discord.Embed(description="Todavia no guardaste ninguna nota. Usa `l!note <texto>` y te la dejo lista.", color=discord.Color(COLOR_INFO)))
        return
    embed = discord.Embed(title="Tus notas", color=discord.Color.teal(), timestamp=datetime.datetime.now(datetime.timezone.utc))
    desc = ""
    for i, nota in enumerate(notas, 1):
        texto = nota if isinstance(nota, str) else nota.get("texto", str(nota))
        fecha = "" if isinstance(nota, str) else f" • `{nota.get('fecha', '')}`"
        desc += f"**{i}.** {_clip_text(texto, 180)}{fecha}\n"
    embed.description = desc
    embed.set_footer(text=f"Total: {len(notas)} nota(s) • Maximo 10")
    await ctx.send(embed=embed)

@bot.command()
async def reminder(ctx, tiempo: str, *, texto: str):
    seg = convertir_duracion(tiempo)
    if not seg or seg > 86400 * 7:
        await ctx.send(embed=discord.Embed(description="No pude tomar ese tiempo. Usa algo como `30m`, `2h` o `1d` y un maximo de 7 dias.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    texto = _clip_text(texto, 500, "")
    due_ts = int((datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(seconds=seg)).timestamp())
    embed = discord.Embed(
        title="Recordatorio configurado",
        description=f"Quedo agendado. Te aviso <t:{due_ts}:R>.",
        color=discord.Color.orange(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.add_field(name="Mensaje", value=_clip_text(texto, 250), inline=False)
    await ctx.send(embed=embed)
    await asyncio.sleep(seg)
    try:
        embed = discord.Embed(title="Recordatorio", description=texto, color=discord.Color.orange())
        embed.set_footer(text=f"Pedido por {ctx.author.display_name}")
        await ctx.author.send(embed=embed)
        await ctx.channel.send(f"{ctx.author.mention} te dejo el recordatorio que pediste: `{texto}`")
    except:
        pass


@bot.command()
async def robloxify(ctx, estilo: str = None, *, texto: str = None):
    """Censura un texto al estilo Roblox.
    Uso: l!robloxify <candado|hashtag> <texto>"""
    estilo = (estilo or "").strip().lower()
    if estilo not in {"candado", "hashtag"} or not texto:
        await ctx.send(embed=discord.Embed(
            title="l!robloxify",
            description=(
                "Uso: `l!robloxify <candado|hashtag> <texto>`\n\n"
                "`candado` → `🔒:` + puntos\n"
                "`hashtag` → texto convertido a `#`"
            ),
            color=discord.Color(COLOR_INFO)
        ))
        return
    resultado = _robloxify_text(estilo, texto)
    if not resultado:
        await ctx.send(embed=discord.Embed(description="No pude transformar ese texto.", color=discord.Color(COLOR_PELIGRO)))
        return
    embed = discord.Embed(
        title="Robloxify",
        color=discord.Color.blurple(),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.add_field(name="Estilo", value=estilo.capitalize(), inline=True)
    embed.add_field(name="Original", value=_clip_text(texto, 200), inline=False)
    embed.add_field(name="Resultado", value=_clip_text(resultado, 1000), inline=False)
    await ctx.send(content=resultado[:1900], embed=embed)

@bot.command()
@commands.check(es_staff)
async def say(ctx, *, args: str = None):
    """Comandos de mensajes del bot.
    Uso:
      l!say <texto>                   - Envia texto plano
      l!say embed <texto>             - Envia embed simple
      l!say embed <titulo> | <desc>   - Embed con titulo y descripcion
      l!say dm @user <texto>          - Envia DM a un usuario
      l!say edit <msg_id> <texto>     - Edita un mensaje del bot
      l!say react <msg_id> <emoji>    - Agrega reaccion a un mensaje
      l!say canal <#canal> <texto>    - Envia mensaje a otro canal
    """
    if not args:
        await ctx.send(embed=discord.Embed(
            title="l!say - Uso",
            description=(
                "`l!say <texto>` - Texto plano\n"
                "`l!say embed <titulo> | <descripcion>` - Embed\n"
                "`l!say dm @user <texto>` - DM a usuario\n"
                "`l!say edit <msg_id> <nuevo texto>` - Editar mensaje del bot\n"
                "`l!say react <msg_id> <emoji>` - Reaccionar a mensaje\n"
                "`l!say canal <#canal> <texto>` - Enviar a otro canal"
            ),
            color=discord.Color(COLOR_INFO)
        ), delete_after=15)
        return

    try: await ctx.message.delete()
    except: pass

    partes = args.split(" ", 1)
    subcomando = partes[0].lower()

    # l!say embed
    if subcomando == "embed":
        contenido = partes[1] if len(partes) > 1 else ""
        if "|" in contenido:
            titulo, desc = contenido.split("|", 1)
            embed = discord.Embed(title=titulo.strip(), description=desc.strip(), color=discord.Color(COLOR_PRIMARIO))
        else:
            embed = discord.Embed(description=contenido.strip(), color=discord.Color(COLOR_PRIMARIO))
        embed.set_footer(text=ctx.guild.name)
        await ctx.send(embed=embed)

    # l!say dm @user texto
    elif subcomando == "dm":
        resto = partes[1] if len(partes) > 1 else ""
        if not ctx.message.mentions:
            await ctx.send(embed=discord.Embed(description="Menciona a alguien. Ej: `l!say dm @user texto`", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        target = ctx.message.mentions[0]
        texto_dm = resto.replace(target.mention, "").strip()
        if not texto_dm:
            await ctx.send(embed=discord.Embed(description="Escribe el mensaje a enviar.", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        try:
            embed_dm = discord.Embed(
                title=f"Mensaje de {ctx.guild.name}",
                description=texto_dm,
                color=discord.Color(COLOR_PRIMARIO)
            )
            embed_dm.set_footer(text=f"Enviado por el Staff de {ctx.guild.name}")
            await target.send(embed=embed_dm)
            await ctx.send(embed=discord.Embed(description=f"✅ DM enviado a {target.mention}", color=discord.Color(COLOR_EXITO)), delete_after=5)
        except discord.Forbidden:
            await ctx.send(embed=discord.Embed(description=f"❌ {target.mention} tiene los DMs cerrados.", color=discord.Color(COLOR_PELIGRO)), delete_after=8)

    # l!say edit <msg_id> <nuevo texto>
    elif subcomando == "edit":
        resto = partes[1].split(" ", 1) if len(partes) > 1 else []
        if len(resto) < 2 or not resto[0].isdigit():
            await ctx.send(embed=discord.Embed(description="Uso: `l!say edit <ID_mensaje> <nuevo texto>`", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        try:
            msg_id = int(resto[0])
            msg_target = await ctx.channel.fetch_message(msg_id)
            if msg_target.author.id != bot.user.id:
                await ctx.send(embed=discord.Embed(description="Solo puedo editar mis propios mensajes.", color=discord.Color(COLOR_PELIGRO)), delete_after=8)
                return
            await msg_target.edit(content=resto[1])
            await ctx.send(embed=discord.Embed(description="✅ Mensaje editado.", color=discord.Color(COLOR_EXITO)), delete_after=5)
        except discord.NotFound:
            await ctx.send(embed=discord.Embed(description="❌ Mensaje no encontrado.", color=discord.Color(COLOR_PELIGRO)), delete_after=8)

    # l!say react <msg_id> <emoji>
    elif subcomando == "react":
        resto = partes[1].split(" ", 1) if len(partes) > 1 else []
        if len(resto) < 2 or not resto[0].isdigit():
            await ctx.send(embed=discord.Embed(description="Uso: `l!say react <ID_mensaje> <emoji>`", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        try:
            msg_id = int(resto[0])
            emoji = resto[1].strip()
            msg_target = await ctx.channel.fetch_message(msg_id)
            await msg_target.add_reaction(emoji)
            await ctx.send(embed=discord.Embed(description=f"✅ Reaccion {emoji} agregada.", color=discord.Color(COLOR_EXITO)), delete_after=5)
        except (discord.NotFound, discord.HTTPException) as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: `{e}`", color=discord.Color(COLOR_PELIGRO)), delete_after=8)

    # l!say canal <#canal> <texto>
    elif subcomando == "canal":
        resto = partes[1] if len(partes) > 1 else ""
        if not ctx.message.channel_mentions:
            await ctx.send(embed=discord.Embed(description="Menciona el canal. Ej: `l!say canal #general Hola!`", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        canal_dest = ctx.message.channel_mentions[0]
        texto_canal = resto.replace(canal_dest.mention, "").strip()
        if not texto_canal:
            await ctx.send(embed=discord.Embed(description="Escribe el mensaje a enviar.", color=discord.Color(COLOR_ADVERTENCIA)), delete_after=8)
            return
        await canal_dest.send(texto_canal)
        await ctx.send(embed=discord.Embed(description=f"✅ Enviado en {canal_dest.mention}", color=discord.Color(COLOR_EXITO)), delete_after=5)

    # l!say <texto plano>
    else:
        await ctx.send(args)


