@bot.command()
async def help(ctx, *, comando: str = None):
    cfg = get_config(ctx.guild.id) or {}
    prefix = cfg.get("prefix", "l!")
    if comando:
        key = comando.strip().lower()
        if key.startswith(prefix.lower()):
            key = key[len(prefix) :].strip()
        key = key.replace("!", "").strip()
        det = HELP_CMD_DETALLE.get(key)
        if det:
            det = det.format(p=prefix)
        elif bot.get_command(key):
            c = bot.get_command(key)
            h = (c.help or getattr(c, "brief", None) or "Sin descripcion extendida.").strip()
            det = f"**`{prefix}{key}`**\n\n{h}"
        else:
            await ctx.send(
                embed=discord.Embed(
                    description=f"No hay ayuda para `{comando}`. Proba `{prefix}help` o `{prefix}help snipe`.",
                    color=discord.Color(COLOR_ADVERTENCIA),
                )
            )
            return
        embed = discord.Embed(
            title=f"Ayuda: {key}",
            description=det[:4096],
            color=discord.Color(COLOR_PRIMARIO),
        )
        _brand_footer(embed, extra=f"{prefix}help <comando>")
        await ctx.send(embed=embed)
        return

    embed = _build_help_home_embed(prefix)
    await ctx.send(embed=embed, view=HelpView())
    return

    embed = discord.Embed(
        title="LatamBOT - Ayuda",
        description=(
            f"**Prefix:** `{prefix}`\n"
            f"**IA:** activa en este servidor (`{MODELO_PRINCIPAL}`)\n\n"
            "Elige una **categoria** en el menu para ver comandos por tema.\n"
            f"**Detalle:** `{prefix}help snipe`, `{prefix}help ytb`, `{prefix}help ask`, etc."
        ),
        color=discord.Color(COLOR_PRIMARIO),
    )
    embed.set_thumbnail(url=bot.user.avatar.url if bot.user.avatar else None)
    embed.set_footer(text=f"LatamBOT {BOT_VERSION} | Comunidad y soporte en el panel del bot")
    await ctx.send(embed=embed, view=HelpView())



