async def _get_referenced_text(ctx) -> str:
    if not getattr(ctx.message, "reference", None):
        return ""
    ref = await obtener_mensaje_referenciado(ctx.message)
    if not ref:
        return ""
    if ref.content:
        return ref.content.strip()
    if ref.embeds:
        for emb in ref.embeds:
            if emb.description:
                return emb.description.strip()
    return ""


def _ai_embed_color_for(user_id: int) -> discord.Color:
    return discord.Color.from_rgb(255, 102, 0) if es_kofi(user_id) else discord.Color(COLOR_PRIMARIO)


