@bot.command()
async def resumir(ctx, cantidad: int = 20):
    """Resume los ultimos N mensajes del chat con IA.
    Uso: l!resumir [cantidad=20]"""
    if not await _ensure_ai_ready(ctx, "Este resumen"):
        return
    lims_res = get_limites(ctx.author.id)
    max_resumir = lims_res[3] if len(lims_res) > 3 else 50
    cantidad = max(5, min(cantidad, max_resumir))
    msgs = []
    async for m in ctx.channel.history(limit=cantidad + 1):
        if m.author.bot:
            continue
        if not (m.content or "").strip():
            continue
        msgs.append(f"{m.author.display_name}: {m.content[:220]}")
    msgs.reverse()
    if not msgs:
        await ctx.send(embed=discord.Embed(description="No hay mensajes recientes para resumir.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    chat_texto = "\n".join(msgs[-cantidad:])
    prompt = (
        AI_TASK_PROMPTS["resumir"] + "\n\n"
        "Resume esta conversacion de Discord con este formato:\n"
        "1. Panorama general (1-2 lineas)\n"
        "2. Puntos clave (3-5 bullets)\n"
        "3. Pendientes o decisiones, solo si existen\n\n"
        "No inventes nada y evita mencionar usuarios salvo que sea indispensable.\n\n"
        f"{chat_texto}"
    )
    async with ctx.typing():
        res = await generar_respuesta_groq(
            ctx.guild.id,
            [{"role": "user", "content": prompt}],
            user_id_ctx=ctx.author.id,
        )
    if not res:
        await ctx.send(embed=discord.Embed(description="No pude generar el resumen.", color=discord.Color(COLOR_PELIGRO)))
        return
    embed = discord.Embed(
        title=f"📋 Resumen - ultimos {len(msgs)} mensajes",
        description=_clip_text(res, 4000),
        color=_ai_embed_color_for(ctx.author.id),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_footer(text=f"Resumido por LatamBOT • Pedido por {ctx.author.display_name}")
    await ctx.send(embed=embed)


# Legacy: NO se registra como comando (lo reemplaza `l!traducir`). Antes se colaba como l!traducir_ia_legacy.
async def traducir_ia_legacy(ctx, idioma: str, *, texto: str = None):
    """Traduce texto al idioma especificado con IA.
    Uso: l!traducir ingles Hola como estas
         l!traducir portugues <responder a un mensaje>"""
    if not await _ensure_ai_ready(ctx, "Esta traduccion"):
        return
    if not texto:
        texto = await _get_referenced_text(ctx)
    if not texto:
        await ctx.send(embed=discord.Embed(
            description=f"Uso: `l!traducir <idioma> <texto>`\nEjemplo: `l!traducir ingles Hola mundo`",
            color=discord.Color(COLOR_ADVERTENCIA)
        ))
        return
    prompt = _make_translation_prompt(idioma, texto)
    async with ctx.typing():
        res = await generar_respuesta_groq(
            ctx.guild.id,
            [{"role": "user", "content": prompt}],
            sistema_extra="No suenes mecanico. Prioriza claridad y evita repetir el mismo punto con otras palabras.",
            user_id_ctx=ctx.author.id,
        )
    if not res:
        await ctx.send(embed=discord.Embed(description="No pude traducir el texto.", color=discord.Color(COLOR_PELIGRO)))
        return
    embed = discord.Embed(
        title=f"🌐 Traduccion a {idioma}",
        color=_ai_embed_color_for(ctx.author.id),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.add_field(name="Original", value=_clip_text(texto, 900), inline=False)
    embed.add_field(name="Traduccion", value=_clip_text(res, 1800), inline=False)
    embed.set_footer(text=f"LatamBOT Traduccion • Pedido por {ctx.author.display_name}")
    await ctx.send(embed=embed)


