class TicketCloseView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="Cerrar ticket", style=discord.ButtonStyle.danger, emoji="🎫", custom_id="latambot_ticket_close")
    async def cerrar(self, i: discord.Interaction, _button: discord.ui.Button):
        if not i.channel or "ticket-" not in i.channel.name:
            await i.response.send_message("Este boton solo sirve dentro de un ticket.", ephemeral=True)
            return
        opener_tag = f"ticket_owner:{i.user.id}"
        if not _check_admin(i) and opener_tag not in (getattr(i.channel, "topic", "") or ""):
            await i.response.send_message("Solo staff o quien abrio el ticket puede cerrarlo.", ephemeral=True)
            return
        await i.response.send_message("Cierro el ticket en 3 segundos.", ephemeral=True)
        await _log_staff_action(
            i.guild,
            title="Ticket cerrado",
            color=COLOR_PELIGRO,
            actor=i.user,
            reason=f"Cierre desde boton en {i.channel.mention}",
            fields=[("Canal", i.channel.mention, True)],
            notify_owner=False,
            tag="TICKET_CLOSE",
        )
        await asyncio.sleep(3)
        try:
            await i.channel.delete()
        except Exception as e:
            _console_log("TICKET_CLOSE", "No se pudo borrar el ticket", level="ERROR", channel_id=getattr(i.channel, "id", None), error=e)

@bot.command()
async def ticket(ctx, *, razon="Soporte General"):
    guild = ctx.guild
    cfg = get_config(guild.id)
    cat = guild.get_channel(cfg.get("cat_tickets")) if cfg and cfg.get("cat_tickets") else None
    if not cat:
        cat = discord.utils.get(guild.categories, name="TICKETS") or await guild.create_category("TICKETS")
    ticket_existente = discord.utils.get(guild.text_channels, name=f"ticket-{ctx.author.name}")
    if ticket_existente:
        await ctx.send(embed=_make_embed("Ticket existente", f"Ya tenes un ticket abierto en {ticket_existente.mention}.", COLOR_ADVERTENCIA), delete_after=10)
        return
    overwrites = {
        guild.default_role: discord.PermissionOverwrite(read_messages=False),
        ctx.author: discord.PermissionOverwrite(read_messages=True, send_messages=True),
        guild.me: discord.PermissionOverwrite(read_messages=True, send_messages=True)
    }
    if cfg and cfg.get("roles_staff"):
        for rid in cfg["roles_staff"]:
            rol = guild.get_role(rid)
            if rol:
                overwrites[rol] = discord.PermissionOverwrite(read_messages=True, send_messages=True)
    channel = await guild.create_text_channel(
        f"ticket-{ctx.author.name}",
        category=cat,
        overwrites=overwrites,
        topic=f"ticket_owner:{ctx.author.id} | abierto_por:{ctx.author} | razon:{_clip_text(razon, 120)}",
    )
    embed = discord.Embed(
        title="Ticket abierto",
        description=(
            f"**Usuario:** {ctx.author.mention}\n"
            f"**Motivo:** {_clip_text(razon, 900)}\n\n"
            "Explica lo que necesitas con el mayor detalle posible. "
            "Cuando ya este resuelto puedes usar `l!close` o el boton de abajo."
        ),
        color=discord.Color.green(),
    )
    await channel.send(embed=embed, view=TicketCloseView())
    await ctx.send(embed=_make_embed("Ticket creado", f"Listo. Tu ticket es {channel.mention}.", COLOR_EXITO), delete_after=8)
    _metric_bump("tickets_created")
    await _log_staff_action(
        guild,
        title="Ticket creado",
        color=COLOR_INFO,
        actor=ctx.author,
        reason=razon,
        fields=[("Canal", channel.mention, True)],
        notify_owner=False,
        tag="TICKET_OPEN",
    )

@bot.command()
async def close(ctx):
    if "ticket-" not in ctx.channel.name:
        await ctx.send(embed=_make_embed("Canal invalido", "Este comando solo funciona dentro de un ticket.", COLOR_ADVERTENCIA))
        return
    opener_tag = f"ticket_owner:{ctx.author.id}"
    if not _check_admin_ctx(ctx) and opener_tag not in (getattr(ctx.channel, "topic", "") or ""):
        await ctx.send(embed=_make_embed("Sin permisos", "Solo staff o quien abrio el ticket puede cerrarlo.", COLOR_PELIGRO), delete_after=8)
        return
    embed = discord.Embed(
        title="Ticket Cerrado",
        description="Este canal se eliminara en 3 segundos.",
        color=discord.Color.red()
    )
    embed.set_footer(text=f"Cerrado por {ctx.author}")
    await ctx.send(embed=embed)
    await _log_staff_action(
        ctx.guild,
        title="Ticket cerrado",
        color=COLOR_PELIGRO,
        actor=ctx.author,
        reason=f"Cierre manual en {ctx.channel.mention}",
        fields=[("Canal", ctx.channel.mention, True)],
        notify_owner=False,
        tag="TICKET_CLOSE",
    )
    await asyncio.sleep(3)
    await ctx.channel.delete()

