@bot.command()
@commands.check(es_staff)
async def setstaffroles(ctx, rol: discord.Role):
    # Solo admin/manage_guild/owner: un rol staff no puede ampliar la lista de staff.
    if not (
        ctx.author.id == OWNER_ID
        or ctx.author.id == getattr(ctx.guild, "owner_id", None)
        or getattr(ctx.author.guild_permissions, "administrator", False)
        or getattr(ctx.author.guild_permissions, "manage_guild", False)
    ):
        await ctx.send(embed=_make_error_embed(
            "Sin permisos",
            "Solo un administrador puede agregar o quitar roles de staff.",
            "Pedile a un admin que use este comando.",
        ))
        return
    cfg = get_config(ctx.guild.id) or {}
    lista = cfg.get("roles_staff", [])
    if not isinstance(lista, list): lista = []
    if rol.id in lista:
        lista.remove(rol.id)
        accion_txt = "Removido del Staff"
        color = discord.Color.red()
    else:
        lista.append(rol.id)
        accion_txt = "Anadido al Staff"
        color = discord.Color.green()
    update_server_config(ctx.guild.id, "roles_staff", lista)
    embed = discord.Embed(
        title=accion_txt,
        description=f"{rol.mention} fue {accion_txt.lower()}.",
        color=color
    )
    await ctx.send(embed=embed)

@bot.hybrid_command(name="ia", aliases=["ask"], description="Preguntale algo a la IA de LatamBOT.")
@app_commands.describe(p="Tu pregunta")
@app_commands.allowed_installs(guilds=True, users=True)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
async def ask(ctx, *, p: str = None):
    """Pregunta directamente a la IA con contexto de conversacion."""
    if ctx.interaction and p:
        await ctx.defer()
    if not await _ensure_ai_ready(ctx, "Esta respuesta"):
        return

    uid = ctx.author.id
    teaser = _is_teaser_ctx(ctx)
    vip = es_kofi(uid)
    limite = USERAPP_IA_DAILY if teaser else get_limites(uid)[0]
    ai_choice = _get_user_ai_model_choice(uid) or "flash"
    ai_cost = _ai_daily_cost_for_choice(ai_choice) if _ai_provider() == AI_PROVIDER_OPENROUTER else 1
    usos, restantes = _daily_limit_state(userapp_ia_usos if teaser else ask_usos_diarios, uid, limite)
    if usos + ai_cost > limite:
        embed_lim = discord.Embed(
            title="☕ Límite Diario Alcanzado",
            description=(
                f"Usaste **{usos}/{limite}** preguntas hoy.\n"
                f"El limite se reinicia a medianoche.\n\n"
                + ("" if vip else KOFI_BENEFICIOS + "\n\n**¿Querés más usos?** Apoyá en [☕ Ko-Fi](https://ko-fi.com/latambot) o [🎭 Patreon](https://patreon.com/latambot)\nReclamá tus beneficios con `l!feedback` → **Ko-Fi**.")
            ),
            color=discord.Color(COLOR_ADVERTENCIA)
        )
        embed_lim.set_footer(text=f"☕ https://ko-fi.com/latambot • 🎭 https://patreon.com/latambot" if not vip else "☕ Supporter activo")
        await ctx.send(embed=embed_lim)
        return
    if not p:
        embed = discord.Embed(
            description="Escribe una pregunta. Ej: `l!ask cual es la capital de Argentina?`",
            color=discord.Color(COLOR_INFO)
        )
        await ctx.send(embed=embed)
        return
    pregunta_limpia = _sanitize_ai_prompt_text(p)
    pregunta_limpia = _append_user_context(pregunta_limpia, [u for u in ctx.message.mentions if u.id != bot.user.id])
    ask_emojis = re.findall(r"<a?:(\w+):\d+>", ctx.message.content or "")
    if ask_emojis:
        pregunta_limpia = _sanitize_ai_prompt_text(f"{pregunta_limpia}\n\nUsa bien estos emojis si sirven: {', '.join(ask_emojis)}", max_chars=ASK_MAX_CHARS)
    rechazo = _detect_bad_ai_request(pregunta_limpia)
    if rechazo:
        await ctx.send(
            embed=discord.Embed(
                title="Pedido rechazado",
                description=rechazo,
                color=discord.Color(COLOR_ADVERTENCIA),
            )
        )
        return
    usos = _daily_limit_consume(userapp_ia_usos if teaser else ask_usos_diarios, uid, ai_cost)
    restantes = max(limite - usos, 0)

    ctx_key = (getattr(ctx.channel, "id", 0), uid)
    reply_context = _sanitize_ai_prompt_text(await _get_referenced_text(ctx), max_chars=800)
    prompt_usuario = pregunta_limpia
    if reply_context:
        prompt_usuario = (
            "Mensaje al que responde el usuario:\n"
            f"{reply_context[:1000]}\n\n"
            "Solicitud del usuario:\n"
            f"{pregunta_limpia}"
        )
    historial_ia = _build_ai_messages(ctx_key, prompt_usuario, reply_to_bot=bool(reply_context), reply_context="")
    imagen_url = _extraer_imagen_de_mensaje(ctx.message)
    if not imagen_url and ctx.message.reference:
        ref_msg_img = await obtener_mensaje_referenciado(ctx.message)
        if ref_msg_img:
            imagen_url = _extraer_imagen_de_mensaje(ref_msg_img)

    wiki = None
    if not imagen_url:
        try:
            wiki = await _wiki_lookup(pregunta_limpia) if _wiki_should_lookup(pregunta_limpia) else None
        except Exception as e:
            log.warning("wiki lookup: %s", e)
            wiki = None
    wiki_extra = _wiki_sistema_extra(wiki) if wiki else ""

    try:
        status_embed = discord.Embed(
            description="Generando respuesta...",
            color=discord.Color(COLOR_INFO),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        status_msg = await ctx.reply(embed=status_embed, mention_author=False) if ctx.message.reference else await ctx.send(embed=status_embed)
        async with ctx.typing():
            res = await generar_respuesta_groq(
                getattr(ctx.guild, "id", 0) or 0,
                historial_ia,
                sistema_extra=(
                    AI_TASK_PROMPTS["ask"] + " "
                    + ("Responde claro y breve (hasta unas 350 palabras). " if teaser else "Si la pregunta pide detalle, explayate de verdad y evita quedarte corto. ")
                    + "Si mencionan usuarios, usa sus nombres de forma natural sin hacer ping. "
                    "Usa la memoria solo cuando sea claramente una continuacion o seguimiento."
                    + wiki_extra
                ),
                imagen_url=imagen_url,
                user_id_ctx=uid,
            )
    except Exception as e:
        await ctx.send(embed=_make_error_embed("No pude responder ahora", _safe_exc_text(e), _exception_fix_hint(e)))
        return

    if not res:
        res = "No pude generar una respuesta. Intenta de nuevo."

    if wiki and wiki.get("title") and not str(res).startswith("-#"):
        res = f"-# 📚 {wiki['title']}\n{res}"

    _remember_ai_exchange(ctx_key, prompt_usuario, res)

    tier_actual = get_tier(uid)
    badge = TIER_BADGES.get(tier_actual, "") if tier_actual else ""
    embed_ask = discord.Embed(
        title="Respuesta IA",
        description=_clip_text(res, 4096),
        color=_ai_embed_color_for(uid),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    autor_name = f"{badge} {ctx.author.display_name}".strip() if badge else ctx.author.display_name
    embed_ask.set_author(name=autor_name, icon_url=ctx.author.display_avatar.url)
    tier_label = TIER_NOMBRES.get(tier_actual, "LatamBOT IA") if tier_actual else "LatamBOT IA"
    embed_ask.add_field(name="Pregunta", value=_clip_text(pregunta_limpia, 500), inline=False)
    footer = f"{tier_label} | {restantes}/{limite} usos restantes hoy | costo x{ai_cost}"
    if teaser:
        footer = f"User App {restantes}/{limite} hoy · Invita el bot a un server para IA completa"
    embed_ask.set_footer(text=footer)
    feedback_view = AIOpinionView(
        guild_id=getattr(ctx.guild, "id", 0) or 0,
        user_id=uid,
        question=pregunta_limpia,
        answer=res,
        source="ask",
    )
    if ctx.message.reference:
        await status_msg.edit(embed=embed_ask, view=feedback_view)
    else:
        await status_msg.edit(embed=embed_ask, view=feedback_view)
    if teaser and (usos % 5 == 0 or restantes <= 3):
        try:
            await ctx.send(embed=_invite_embed("Llevate LatamBOT al server", "En User App la IA esta topeada. En un servidor tenes IA completa, musica y descargas."), view=_invite_view())
        except Exception:
            pass
    _metric_bump("ai_requests")


@bot.command()
async def crear(ctx, *, prompt: str = None):
    """Genera una imagen con OpenRouter."""
    if not await _ensure_ai_ready(ctx, "Crear imagenes con IA"):
        return
    if _ai_provider() != AI_PROVIDER_OPENROUTER:
        await ctx.send(embed=_make_embed("Crear no disponible", "OpenRouter esta desactivado por fallback a Groq. iiattard debe reactivarlo cuando haya creditos.", COLOR_ADVERTENCIA))
        return
    if not prompt:
        await ctx.send(embed=_make_embed("Falta prompt", f"Usa `{ctx.prefix}crear [prompt]`.", COLOR_INFO))
        return
    prompt_limpio = _sanitize_ai_prompt_text(prompt, max_chars=1200)
    rechazo = _detect_bad_ai_request(prompt_limpio)
    if rechazo:
        await ctx.send(embed=_make_embed("Pedido rechazado", rechazo, COLOR_ADVERTENCIA))
        return
    uid = ctx.author.id
    limite = _crear_limit(uid)
    usados, _ = _daily_limit_state(crear_usos_diarios, uid, limite)
    if usados >= limite:
        await ctx.send(embed=_build_ai_limit_embed(uid, usados, limite, title="Limite diario de imagenes alcanzado"))
        return
    status = await ctx.reply(embed=_make_embed("Creando imagen", "Generando con OpenRouter...", COLOR_INFO), mention_author=False)
    try:
        data = await _openrouter_chat_completion(
            [{"role": "user", "content": prompt_limpio}],
            MODELO_OPENROUTER_IMAGEN,
            temperature=1.0,
            max_tokens=256,
            modalities=["image"],
        )
        image_urls = _extract_openrouter_images(data)
        if not image_urls:
            raise RuntimeError("OpenRouter no devolvio imagenes")
        used = _daily_limit_consume(crear_usos_diarios, uid, 1)
        restantes = max(limite - used, 0)
        image_url = image_urls[0]
        embed = discord.Embed(
            title="Imagen creada",
            description=_clip_text(prompt_limpio, 800),
            color=discord.Color(COLOR_EXITO),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        embed.set_author(name=ctx.author.display_name, icon_url=ctx.author.display_avatar.url)
        embed.set_footer(text=f"{restantes}/{limite} usos de l!crear restantes hoy")
        if image_url.startswith("data:image/"):
            header, b64data = image_url.split(",", 1)
            ext = "png"
            if "jpeg" in header or "jpg" in header:
                ext = "jpg"
            raw = base64.b64decode(b64data)
            file = discord.File(io.BytesIO(raw), filename=f"latambot_crear.{ext}")
            embed.set_image(url=f"attachment://latambot_crear.{ext}")
            await status.edit(embed=embed, attachments=[file])
        else:
            embed.set_image(url=image_url)
            await status.edit(embed=embed)
        _metric_bump("ai_requests")
    except Exception as e:
        await _switch_to_groq_fallback(str(e))
        await status.edit(embed=_make_embed("OpenRouter sin creditos o con error", "Cambie automaticamente a Groq para todos. `l!crear` queda deshabilitado hasta que iiattard reactive OpenRouter.", COLOR_ADVERTENCIA))

