@bot.command()
async def modo(ctx, tipo: str = None):
    global votos_modo
    if not tipo:
        cfg = get_config(ctx.guild.id)
        modo_actual = cfg.get("modo", "LEGACY") if cfg else "LEGACY"
        embed = discord.Embed(title="Modos Disponibles", color=discord.Color.blurple())
        embed.add_field(name="Modo actual", value=f"`{modo_actual}`", inline=False)
        embed.add_field(name="LEGACY", value="Modo normal. El bot responde cuando lo mencionan.", inline=False)
        embed.add_field(name="GEN", value=f"Bot genera resumen del chat cada {GEN_INTERVALO} mensajes con GIF.", inline=False)
        embed.add_field(name="MOLESTO", value="El bot corrige todos los mensajes aunque estén bien. `l!modoMolesto`", inline=False)
        await ctx.send(embed=embed)
        return
    tipo = tipo.lower()
    guild_id = ctx.guild.id
    cfg = get_config(guild_id)
    modo_actual = cfg.get("modo", "LEGACY") if cfg else "LEGACY"
    if guild_id not in votos_modo:
        votos_modo[guild_id] = {'rp': set(), 'legacy': set(), 'gen': set()}
    if tipo in ("legacy", "gen"):
        modo_objetivo = tipo.upper()
        if modo_actual == modo_objetivo:
            await ctx.send(f"Ya estas en modo **{modo_objetivo}**.")
            return
        votos_modo[guild_id][tipo].add(ctx.author.id)
        total = len(votos_modo[guild_id][tipo])
        if total >= 2 or es_staff(ctx):
            update_server_config(guild_id, "modo", modo_objetivo)
            if modo_objetivo == "GEN":
                update_server_config(guild_id, "sistema_gen", True)
            votos_modo[guild_id][tipo].clear()
            emoji = {"RP": "🎭", "LEGACY": "💾", "GEN": "🤖"}.get(modo_objetivo, "✅")
            embed_modo = discord.Embed(
                title=f"{emoji} Modo {modo_objetivo} Activado",
                description=f"El servidor ahora opera en modo **{modo_objetivo}**.",
                color=discord.Color.blurple()
            )
            await ctx.send(embed=embed_modo)
        else:
            embed_voto = discord.Embed(
                title="Voto Registrado",
                description=f"Voto para Modo **{modo_objetivo}** ({total}/2 votos necesarios).\nEl Staff puede cambiarlo directamente.",
                color=discord.Color.gold()
            )
            await ctx.send(embed=embed_voto)
    else:
        await ctx.send(embed=discord.Embed(description="Opciones validas: `legacy`, `gen`.", color=discord.Color(COLOR_ADVERTENCIA)))

