# ==============================================================================

def _rol_verif_peligroso(rol) -> Optional[str]:
    """Nombre del primer permiso peligroso del rol, o None si es seguro.
    Un rol de verificacion NUNCA deberia dar moderacion/admin: si lo hace, cualquiera
    que apriete 'Verificarme' se auto-asigna ese poder (escalada de privilegios)."""
    if rol is None:
        return None
    try:
        p = rol.permissions
    except Exception:
        return None
    peligrosos = [
        ("administrator", "Administrador"),
        ("manage_guild", "Gestionar servidor"),
        ("manage_roles", "Gestionar roles"),
        ("manage_channels", "Gestionar canales"),
        ("ban_members", "Banear miembros"),
        ("kick_members", "Expulsar miembros"),
        ("moderate_members", "Aislar miembros"),
        ("manage_messages", "Gestionar mensajes"),
        ("manage_webhooks", "Gestionar webhooks"),
        ("mention_everyone", "Mencionar @everyone"),
    ]
    for attr, nombre in peligrosos:
        if getattr(p, attr, False):
            return nombre
    return None


class VerificacionBotonView(discord.ui.View):
    """Vista persistente con el boton de verificacion. Se envia en el canal de verificacion."""
    def __init__(self, rol_id: int = None):
        super().__init__(timeout=None)
        self.rol_id = rol_id

    @discord.ui.button(label="✅ Verificarme", style=discord.ButtonStyle.success, custom_id="latambot_verificar")
    async def verificar(self, i: discord.Interaction, b: discord.ui.Button):
        try:
            cfg = get_config(i.guild_id) or {}
            # Obtener rol desde config (no desde self, porque tras reiniciar self.rol_id es None)
            rol_id = cfg.get("verificacion_rol")
            if not rol_id:
                await i.response.send_message(
                    embed=discord.Embed(
                        description="⚠️ No hay un rol de verificacion configurado.\nPide a un administrador que use `l!setverificrol @rol`.",
                        color=discord.Color(COLOR_ADVERTENCIA)
                    ),
                    ephemeral=True
                )
                return
            rol = i.guild.get_role(rol_id)
            if not rol:
                await i.response.send_message(
                    embed=discord.Embed(
                        description="❌ El rol de verificacion no existe. Puede haber sido eliminado.\nContacta a un administrador.",
                        color=discord.Color(COLOR_PELIGRO)
                    ),
                    ephemeral=True
                )
                return
            if rol in i.user.roles:
                await i.response.send_message(
                    embed=discord.Embed(
                        title="Ya estas verificado ✅",
                        description=f"Ya tenes el rol {rol.mention}. Tenes acceso completo al servidor.",
                        color=discord.Color(COLOR_INFO)
                    ),
                    ephemeral=True
                )
                return
            # Seguridad: nunca autoasignar un rol con permisos de moderacion/admin
            # (si el rol de verificacion quedo mal configurado, esto evita que
            # cualquiera se verifique y se lleve permisos peligrosos).
            peligro = _rol_verif_peligroso(rol)
            if peligro:
                await i.response.send_message(
                    embed=discord.Embed(
                        description=(f"⚠️ Por seguridad no puedo asignarte ese rol: tiene el permiso "
                                     f"**{peligro}**. Un rol de verificación no debería dar permisos de "
                                     f"moderación o administración. Avisá a un administrador."),
                        color=discord.Color(COLOR_PELIGRO)),
                    ephemeral=True)
                try:
                    await enviar_log(i.guild, discord.Embed(
                        title="⚠️ Verificación bloqueada por seguridad",
                        description=(f"El rol de verificación {rol.mention} tiene el permiso peligroso "
                                     f"**{peligro}**. Bloqueé la autoasignación para evitar escalada de "
                                     f"privilegios. Cambien el rol por uno sin permisos de moderación/admin "
                                     f"(`l!setverificrol @rol`)."),
                        color=discord.Color(COLOR_PELIGRO)))
                except Exception:
                    pass
                return
            await i.user.add_roles(rol, reason="Verificacion LatamBOT")
            embed_ok = discord.Embed(
                title="✅ Verificacion exitosa!",
                description=(
                    f"Bienvenido/a a **{i.guild.name}**!\n"
                    f"Recibiste el rol {rol.mention} y ahora tenes acceso completo al servidor."
                ),
                color=discord.Color(COLOR_EXITO)
            )
            embed_ok.set_thumbnail(url=i.user.display_avatar.url)
            embed_ok.set_footer(text=f"{i.guild.name} | LatamBOT")
            await i.followup.send(embed=embed_ok, ephemeral=True)
            # Log
            embed_log = discord.Embed(
                title="✅ Usuario Verificado",
                color=discord.Color(COLOR_EXITO),
                timestamp=datetime.datetime.now(datetime.timezone.utc)
            )
            embed_log.set_author(name=str(i.user), icon_url=i.user.display_avatar.url)
            embed_log.add_field(name="Usuario", value=f"{i.user.mention} `({i.user.id})`", inline=True)
            embed_log.add_field(name="Rol asignado", value=rol.mention, inline=True)
            embed_log.set_footer(text=f"ID: {i.user.id}")
            await enviar_log(i.guild, embed_log)
        except discord.Forbidden:
            await i.response.send_message(
                embed=discord.Embed(
                    description="❌ No puedo asignarte el rol.\nEl rol del bot es mas bajo que el rol de verificacion. Pide a un admin que lo arregle.",
                    color=discord.Color(COLOR_PELIGRO)
                ),
                ephemeral=True
            )
        except Exception as e:
            try:
                await i.response.send_message(
                    embed=discord.Embed(
                        description=f"❌ Error inesperado al verificar: `{e}`\nContacta a un administrador.",
                        color=discord.Color(COLOR_PELIGRO)
                    ),
                    ephemeral=True
                )
            except:
                pass
            print(f"[VERIF] Error en boton verificar: {e}")

@bot.command(aliases=["setverifirol", "setverificacionrol"])
@commands.check(es_staff)
async def setverificrol(ctx, rol: discord.Role):
    """Configura el rol que se da al verificarse."""
    peligro = _rol_verif_peligroso(rol)
    if peligro:
        await ctx.send(embed=discord.Embed(
            title="Rol no permitido",
            description=(f"**{rol.name}** tiene el permiso **{peligro}**. Por seguridad no puede ser el "
                         f"rol de verificación: cualquiera que se verifique se auto-daría ese permiso. "
                         f"Elegí un rol sin permisos de moderación/administración."),
            color=discord.Color(COLOR_PELIGRO)))
        return
    update_server_config(ctx.guild.id, "verificacion_rol", rol.id)
    embed = discord.Embed(
        title="Rol de Verificacion Configurado",
        description=(
            f"Los usuarios verificados recibiran {rol.mention}.\n\n"
            "Tambien podes cambiarlo desde `l!setup` -> Verificacion -> Rol."
        ),
        color=discord.Color(COLOR_EXITO)
    )
    await ctx.send(embed=embed)

@bot.command()
@commands.check(es_staff)
async def verificacion(ctx, subcomando: str = "setup", *, valor: str = ""):
    """Configurar el sistema de verificacion.
    Subcomandos: setup | titulo <texto> | desc <texto> | color <hex>"""
    cfg = get_config(ctx.guild.id) or {}

    if subcomando == "setup":
        # Crear canal y embed usando la misma logica del boton
        class FakeInteraction:
            guild = ctx.guild
            guild_id = ctx.guild.id
            async def followup_send(self, **kwargs): pass
        fi = FakeInteraction()
        fi.followup = type('obj', (object,), {'send': lambda **kw: ctx.send(**kw)})()
        await _setup_verificacion_ctx(ctx)

    elif subcomando == "titulo":
        if not valor:
            await ctx.send(embed=discord.Embed(description="Uso: `l!verificacion titulo <titulo>`", color=COLOR_ADVERTENCIA))
            return
        update_server_config(ctx.guild.id, "verificacion_titulo", valor)
        await ctx.send(embed=discord.Embed(description=f"Titulo de verificacion: **{valor}**", color=COLOR_EXITO))

    elif subcomando == "desc":
        if not valor:
            await ctx.send(embed=discord.Embed(description="Uso: `l!verificacion desc <descripcion>`", color=COLOR_ADVERTENCIA))
            return
        update_server_config(ctx.guild.id, "verificacion_descripcion", valor)
        await ctx.send(embed=discord.Embed(description=f"Descripcion de verificacion actualizada.", color=COLOR_EXITO))

    elif subcomando == "color":
        try:
            color_int = int(valor.strip("#"), 16)
            update_server_config(ctx.guild.id, "verificacion_color", color_int)
            await ctx.send(embed=discord.Embed(description=f"Color actualizado.", color=discord.Color(color_int)))
        except ValueError:
            await ctx.send(embed=discord.Embed(description="Color invalido. Usa formato hex: `#2ecc71`", color=COLOR_PELIGRO))
    else:
        await ctx.send(embed=discord.Embed(description="Subcomandos: `setup` | `titulo` | `desc` | `color`", color=COLOR_ADVERTENCIA))



async def _setup_verificacion_interaction(i: discord.Interaction):
    """Version del setup de verificacion para Interactions (botones del dashboard)."""
    guild = i.guild
    cfg = get_config(guild.id) or {}
    titulo = cfg.get("verificacion_titulo", "Verificacion de Miembros")
    descripcion = cfg.get("verificacion_descripcion", "Presiona el boton para verificarte y acceder al servidor.")
    color_val = cfg.get("verificacion_color", COLOR_EXITO)
    rol_id = cfg.get("verificacion_rol")
    rol_verif = guild.get_role(rol_id) if rol_id else None

    canal_id = cfg.get("verificacion_canal")
    canal_v = guild.get_channel(canal_id) if canal_id else None

    if not canal_v:
        overwrites_verif = {
            guild.default_role: discord.PermissionOverwrite(
                read_messages=True, send_messages=False, add_reactions=False
            ),
            guild.me: discord.PermissionOverwrite(
                read_messages=True, send_messages=True, manage_messages=True
            )
        }
        try:
            canal_v = await guild.create_text_channel(
                "✅-verificacion",
                overwrites=overwrites_verif,
                topic="Verificate aqui para acceder al servidor."
            )
            update_server_config(guild.id, "verificacion_canal", canal_v.id)
        except discord.Forbidden:
            await i.followup.send(
                embed=discord.Embed(description="❌ Sin permisos para crear canales.", color=discord.Color(COLOR_PELIGRO)),
                ephemeral=True
            )
            return

    canales_ocultados = 0
    if rol_verif:
        for ch in guild.text_channels:
            if ch.id == canal_v.id:
                continue
            try:
                await ch.set_permissions(guild.default_role, read_messages=False)
                await ch.set_permissions(rol_verif, read_messages=True)
                canales_ocultados += 1
            except:
                pass
        for ch in guild.voice_channels:
            try:
                await ch.set_permissions(guild.default_role, connect=False, view_channel=False)
                await ch.set_permissions(rol_verif, connect=True, view_channel=True)
                canales_ocultados += 1
            except:
                pass

    embed_v = discord.Embed(
        title=titulo,
        description=descripcion,
        color=discord.Color(color_val),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    if guild.icon:
        embed_v.set_thumbnail(url=guild.icon.url)
    embed_v.add_field(
        name="📋 Instrucciones",
        value="Presiona el boton **✅ Verificarme** para obtener acceso al servidor.",
        inline=False
    )
    if rol_verif:
        embed_v.add_field(name="🎭 Rol que obtendras", value=rol_verif.mention, inline=True)
        embed_v.add_field(name="🔓 Acceso a", value=f"{canales_ocultados} canales", inline=True)
    embed_v.set_footer(text=f"{guild.name} | LatamBOT - Sistema de Verificacion")

    try:
        await canal_v.purge(limit=10)
    except:
        pass
    await canal_v.send(embed=embed_v, view=VerificacionBotonView(rol_id))
    update_server_config(guild.id, "verificacion_activa", True)

    await i.followup.send(
        embed=discord.Embed(
            title="✅ Verificacion Configurada",
            description=(
                f"Canal: {canal_v.mention}\n"
                f"Rol asignado: {rol_verif.mention if rol_verif else '`sin configurar - usa l!setverificrol @rol`'}\n"
                f"Canales privatizados: **{canales_ocultados}**\n\n"
                "Los nuevos miembros solo veran el canal de verificacion hasta verificarse."
            ),
            color=discord.Color(COLOR_EXITO)
        ),
        ephemeral=True
    )

async def _setup_verificacion_ctx(ctx):
    """Version del setup de verificacion para comandos de texto."""
    guild = ctx.guild
    cfg = get_config(guild.id) or {}
    titulo = cfg.get("verificacion_titulo", "Verificacion de Miembros")
    descripcion = cfg.get("verificacion_descripcion", "Presiona el boton para verificarte y acceder al servidor.")
    color_val = cfg.get("verificacion_color", COLOR_EXITO)
    rol_id = cfg.get("verificacion_rol")
    rol_verif = guild.get_role(rol_id) if rol_id else None

    canal_id = cfg.get("verificacion_canal")
    canal_v = guild.get_channel(canal_id) if canal_id else None

    if not canal_v:
        # Canal de verificacion: visible para todos, solo el bot puede escribir
        overwrites_verif = {
            guild.default_role: discord.PermissionOverwrite(
                read_messages=True,
                send_messages=False,
                add_reactions=False
            ),
            guild.me: discord.PermissionOverwrite(
                read_messages=True,
                send_messages=True,
                manage_messages=True
            )
        }
        canal_v = await guild.create_text_channel(
            "✅-verificacion",
            overwrites=overwrites_verif,
            topic="Verificate aqui para acceder al servidor."
        )
        update_server_config(guild.id, "verificacion_canal", canal_v.id)

    # Si hay rol de verificacion, ocultar todos los demas canales a @everyone
    # y darles acceso solo a los verificados
    canales_ocultados = 0
    if rol_verif:
        for ch in guild.text_channels:
            if ch.id == canal_v.id:
                continue
            try:
                # @everyone no puede ver; verificados si
                await ch.set_permissions(guild.default_role, read_messages=False)
                await ch.set_permissions(rol_verif, read_messages=True)
                canales_ocultados += 1
            except:
                pass
        for ch in guild.voice_channels:
            try:
                await ch.set_permissions(guild.default_role, connect=False, view_channel=False)
                await ch.set_permissions(rol_verif, connect=True, view_channel=True)
                canales_ocultados += 1
            except:
                pass

    embed_v = discord.Embed(
        title=titulo,
        description=descripcion,
        color=discord.Color(color_val),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    if guild.icon:
        embed_v.set_thumbnail(url=guild.icon.url)
    embed_v.add_field(
        name="📋 Instrucciones",
        value="Presiona el boton **✅ Verificarme** para obtener acceso al servidor.",
        inline=False
    )
    if rol_verif:
        embed_v.add_field(name="🎭 Rol que obtendras", value=rol_verif.mention, inline=True)
        embed_v.add_field(name="🔓 Acceso a", value=f"{canales_ocultados} canales", inline=True)
    embed_v.set_footer(text=f"{guild.name} | LatamBOT - Sistema de Verificacion")

    await canal_v.purge(limit=10)
    await canal_v.send(embed=embed_v, view=VerificacionBotonView(rol_id))
    update_server_config(guild.id, "verificacion_activa", True)

    await ctx.send(embed=discord.Embed(
        title="✅ Verificacion Configurada",
        description=(
            f"Canal de verificacion: {canal_v.mention}\n"
            f"Rol asignado: {rol_verif.mention if rol_verif else '`sin configurar`'}\n"
            f"Canales privatizados: **{canales_ocultados}**\n\n"
            "Los nuevos miembros solo veran el canal de verificacion hasta verificarse."
        ),
        color=discord.Color(COLOR_EXITO)
    ))

