@bot.command()
@commands.check(es_staff)
async def triggercreate(ctx, palabra: str, *, respuesta: str):
    """Crea un trigger: cuando alguien escriba la palabra, el bot responde.
    Uso: l!triggercreate hola Hola! Como estas?"""
    cfg = get_config(ctx.guild.id) or {}
    triggers = cfg.get("triggers", {})
    triggers[palabra.lower()] = respuesta
    update_server_config(ctx.guild.id, "triggers", triggers)
    embed = discord.Embed(
        title="Trigger Creado",
        color=discord.Color(COLOR_EXITO)
    )
    embed.add_field(name="Palabra", value=f"`{palabra.lower()}`", inline=True)
    embed.add_field(name="Respuesta", value=respuesta[:100], inline=True)
    embed.set_footer(text=f"Total triggers: {len(triggers)}")
    await ctx.send(embed=embed)

@bot.command()
@commands.check(es_staff)
async def triggerdelete(ctx, *, palabra: str):
    """Elimina un trigger existente."""
    cfg = get_config(ctx.guild.id) or {}
    triggers = cfg.get("triggers", {})
    key = palabra.lower()
    if key not in triggers:
        await ctx.send(embed=discord.Embed(description=f"No existe el trigger `{key}`.", color=discord.Color(COLOR_PELIGRO)))
        return
    del triggers[key]
    update_server_config(ctx.guild.id, "triggers", triggers)
    await ctx.send(embed=discord.Embed(description=f"Trigger `{key}` eliminado.", color=discord.Color(COLOR_EXITO)))

@bot.command()
async def triggerlist(ctx):
    """Lista todos los triggers del servidor."""
    cfg = get_config(ctx.guild.id) or {}
    triggers = cfg.get("triggers", {})
    if not triggers:
        await ctx.send(embed=discord.Embed(description="No hay triggers configurados.", color=discord.Color(COLOR_INFO)))
        return
    desc = "\n".join([f"`{k}` → {v[:60]}" for k, v in list(triggers.items())[:20]])
    embed = discord.Embed(title=f"Triggers del Servidor ({len(triggers)})", description=desc, color=discord.Color(COLOR_INFO))
    await ctx.send(embed=embed)

