@bot.command()
@commands.check(es_staff)
async def ban(ctx, m: discord.Member, days: int = 1, *, r="Sin razon especificada"):
    error = _validate_member_action(ctx, m, "banear")
    if error:
        await ctx.send(embed=_make_embed("Accion bloqueada", error, COLOR_PELIGRO))
        return
    try:
        try:
            await m.send(embed=discord.Embed(
                title=f"🔨 Has sido baneado de {ctx.guild.name}",
                description=f"**Razon:** {r}\n**Moderador:** {ctx.author}",
                color=discord.Color(COLOR_PELIGRO)
            ))
        except:
            pass
        days = max(0, min(days, 7))
        await m.ban(reason=f"{r} | Por: {ctx.author}", delete_message_days=days)
        await crear_caso(ctx.guild, "ban", m, ctx.author, r)
        embed = discord.Embed(title="🔨 Usuario Baneado", color=discord.Color(COLOR_PELIGRO), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed.set_thumbnail(url=m.display_avatar.url)
        embed.add_field(name="Usuario", value=f"{m.mention}\n`{m} ({m.id})`", inline=True)
        embed.add_field(name="Staff", value=f"{ctx.author.mention}\n`{ctx.author}`", inline=True)
        embed.add_field(name="Motivo", value=_clip_text(r, 900), inline=False)
        embed.add_field(name="Mensajes borrados", value=f"{days} dia(s)", inline=True)
        embed.add_field(name="Cuenta creada", value=f"<t:{int(m.created_at.timestamp())}:R>", inline=True)
        embed.set_footer(text=f"ID del usuario: {m.id}")
        await ctx.send(embed=embed)
        _metric_bump("moderation_actions")
        await _log_staff_action(
            ctx.guild,
            title="Ban aplicado",
            color=COLOR_PELIGRO,
            actor=ctx.author,
            target=m,
            reason=r,
            fields=[("Mensajes borrados", f"{days} dia(s)", True), ("Canal", ctx.channel.mention, True)],
            notify_owner=True,
            tag="BAN",
        )
        # Log detallado
        embed_log = discord.Embed(title="🔨 Ban ejecutado", color=discord.Color(COLOR_PELIGRO), timestamp=datetime.datetime.now(datetime.timezone.utc))
        embed_log.add_field(name="Usuario baneado", value=f"{m} (`{m.id}`)", inline=True)
        embed_log.add_field(name="Por", value=f"{ctx.author} (`{ctx.author.id}`)", inline=True)
        embed_log.add_field(name="Razon", value=r, inline=False)
        embed_log.set_thumbnail(url=m.display_avatar.url)
        await enviar_log(ctx.guild, embed_log)
    except discord.Forbidden:
        await ctx.send(embed=_make_embed("Sin permisos", "No pude completar el ban. Revisa jerarquia de roles y permisos del bot.", COLOR_PELIGRO))
    except Exception as e:
        await ctx.send(embed=_make_embed("Ban fallido", f"No pude completar el ban.\n`{str(e)[:250]}`", COLOR_PELIGRO))

