@bot.command()
@commands.check(es_staff)
async def purge(ctx, cantidad: int = 10, *, filtro: str = ""):
    """Borrar mensajes con filtros. Uso: l!purge 20 [bot|links|images|embeds|human]"""
    if cantidad < 1 or cantidad > 200:
        await ctx.send(embed=discord.Embed(description="Entre 1 y 200 mensajes.", color=discord.Color(COLOR_ADVERTENCIA)))
        return

    check_fn = None
    if filtro == "bot":
        check_fn = lambda m: m.author.bot
    elif filtro == "links":
        check_fn = lambda m: "http" in m.content
    elif filtro == "images":
        check_fn = lambda m: bool(m.attachments) and any(a.content_type and a.content_type.startswith("image/") for a in m.attachments)
    elif filtro == "embeds":
        check_fn = lambda m: bool(m.embeds)
    elif filtro == "human":
        check_fn = lambda m: not m.author.bot
    else:
        check_fn = None

    deleted = await ctx.channel.purge(limit=cantidad + 1, check=check_fn)
    embed = discord.Embed(
        description=f"🧹 {len(deleted)-1} mensajes eliminados" + (f" (filtro: `{filtro}`)" if filtro else ""),
        color=discord.Color(COLOR_EXITO)
    )
    await ctx.send(embed=embed, delete_after=5)

@bot.command()
async def inviteinfo(ctx):
    """Informacion de las invitaciones activas del servidor."""
    if not es_staff(ctx):
        await ctx.send(embed=discord.Embed(description="Solo Staff.", color=discord.Color(COLOR_PELIGRO)))
        return
    try:
        invites = await ctx.guild.invites()
        if not invites:
            await ctx.send(embed=discord.Embed(description="No hay invitaciones activas.", color=discord.Color(COLOR_INFO)))
            return
        invites_sorted = sorted(invites, key=lambda x: x.uses, reverse=True)[:10]
        desc = "\n".join([
            f"[`{inv.code}`](https://discord.gg/{inv.code}) - {inv.uses} usos - por {inv.inviter} - {'Permanente' if inv.max_age == 0 else formato_tiempo(inv.max_age)}"
            for inv in invites_sorted
        ])
        embed = discord.Embed(title=f"Invitaciones ({len(invites)})", description=desc, color=discord.Color(COLOR_INFO))
        await ctx.send(embed=embed)
    except discord.Forbidden:
        await ctx.send(embed=discord.Embed(description="No tengo permiso para ver invitaciones.", color=discord.Color(COLOR_PELIGRO)))

