@bot.command()
async def enlarge(ctx, emoji_str: str):
    """Amplia un emoji personalizado."""
    match = re.match(r"<a?:(\w+):(\d+)>", emoji_str)
    if not match:
        await ctx.send(embed=discord.Embed(description="Solo funciona con emojis personalizados del servidor.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    nombre, eid = match.group(1), match.group(2)
    ext = "gif" if emoji_str.startswith("<a") else "png"
    url = f"https://cdn.discordapp.com/emojis/{eid}.{ext}?size=256"
    embed = discord.Embed(title=f":{nombre}:", color=discord.Color(COLOR_INFO))
    embed.set_image(url=url)
    embed.add_field(name="ID", value=eid)
    await ctx.send(embed=embed)

