# ==============================================================================
# MODERACION AVANZADA
# ==============================================================================

@bot.command()
@commands.check(es_staff)
async def warn(ctx, m: discord.Member, *, r="Sin razon"):
    """Advierte a un usuario. Suma puntos y dispara sanciones automáticas por umbral."""
    if ctx.guild.me.top_role <= m.top_role:
        await ctx.send(embed=discord.Embed(description="Mi rol es demasiado bajo.", color=discord.Color(COLOR_PELIGRO)))
        return
    if m.bot:
        await ctx.send(embed=_make_embed("Accion invalida", "No puedo advertir a un bot.", COLOR_ADVERTENCIA))
        return
    total, extra = await aplicar_warn(ctx.guild, m, ctx.author, r)
    cfg = get_config(ctx.guild.id) or {}
    proximas = sorted(
        [a for a in (cfg.get("warn_acciones") or []) if int(a.get("puntos", 0)) > total],
        key=lambda a: int(a.get("puntos", 0)),
    )
    embed = discord.Embed(
        title="⚠️ Advertencia registrada",
        color=discord.Color(COLOR_ADVERTENCIA),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_thumbnail(url=m.display_avatar.url)
    embed.add_field(name="Usuario", value=f"{m.mention}\n`{m} ({m.id})`", inline=True)
    embed.add_field(name="Staff", value=ctx.author.mention, inline=True)
    embed.add_field(name="Puntos", value=f"**{total}** {('🟢' if total < 3 else '🟡' if total < 6 else '🔴')}", inline=True)
    embed.add_field(name="Motivo", value=_clip_text(r, 900), inline=False)
    if extra:
        embed.add_field(name="🚨 Sancion automatica", value=extra, inline=False)
    elif proximas:
        prox = proximas[0]
        falta = int(prox["puntos"]) - total
        embed.add_field(
            name="Proximo umbral",
            value=f"A **{prox['puntos']}** puntos → `{prox.get('accion')}` (le faltan {falta})",
            inline=False,
        )
    embed.set_footer(text=f"Historial: l!warns @{m.display_name}")
    await ctx.send(embed=embed)
    _metric_bump("moderation_actions")
    await _log_staff_action(
        ctx.guild,
        title="Warn registrado",
        color=COLOR_ADVERTENCIA,
        actor=ctx.author,
        target=m,
        reason=r,
        fields=[("Puntos totales", str(total), True), ("Canal", ctx.channel.mention, True)],
        notify_owner=True,
        tag="WARN",
    )

