@bot.command(name="automod", aliases=["automodsetup", "discordautomod"])
@commands.check(es_staff)
async def automod_setup_cmd(ctx):
    """[Staff] Configura reglas nativas de AutoMod de Discord (invites, menciones, etc.)."""
    if not ctx.author.guild_permissions.manage_guild and ctx.author.id != OWNER_ID:
        await ctx.send(embed=_make_error_embed(
            "Sin permisos",
            "Necesitas permiso **Gestionar servidor** (o ser admin) para esto.",
            "Pedile a un admin que lo corra.",
        ))
        return
    async with ctx.typing():
        res = await _discord_automod_setup(ctx.guild)
    if res.get("sin_permiso"):
        await ctx.send(embed=_make_error_embed(
            "Me falta un permiso",
            "Necesito **Gestionar servidor** para crear reglas de AutoMod.",
            "Dámelo en Roles del server y volvé a intentar.",
        ))
        return
    emb = _make_embed(
        "AutoMod de Discord",
        (
            f"**Nuevas:** {res['creadas']}\n"
            f"**Ya existían:** {res['existentes']}\n"
            f"**Total en este server:** {res['total_guild']}"
        ),
        COLOR_EXITO if res["creadas"] or res["existentes"] else COLOR_ADVERTENCIA,
    )
    if res["errores"]:
        emb.add_field(name="Avisos", value="\n".join(res["errores"][:5])[:1000], inline=False)
    emb.set_footer(text="Estas reglas cuentan para el badge Uses AutoMod del bot.")
    await ctx.send(embed=emb)


@bot.command(name="automodbadge", aliases=["automodstats"])
async def automod_badge_cmd(ctx):
    """Progreso del badge Uses AutoMod (reglas en toda la red)."""
    if ctx.author.id != OWNER_ID and not es_staff(ctx):
        await ctx.send(embed=discord.Embed(description="Solo staff/owner.", color=discord.Color(COLOR_PELIGRO)))
        return
    status = await ctx.send(embed=_make_embed("Contando reglas AutoMod...", "Esto puede tardar unos segundos.", COLOR_INFO))
    stats = await _contar_automod_red()
    falta = max(0, stats["meta"] - stats["total"])
    emb = _make_embed(
        "Badge Uses AutoMod",
        (
            f"**Reglas totales:** {stats['total']} / {stats['meta']}\n"
            f"**De LatamBOT:** {stats['latambot']}\n"
            f"**Servers leídos:** {stats['guilds']}\n"
            f"**Faltan:** {falta if falta else '¡meta alcanzada!'}"
        ),
        COLOR_EXITO if stats["total"] >= stats["meta"] else COLOR_PRIMARIO,
    )
    await status.edit(embed=emb)


@bot.command(name="automodred")
async def automod_red_cmd(ctx):
    """[Owner] Aplica AutoMod nativo en todos los servers donde el bot pueda."""
    if ctx.author.id != OWNER_ID:
        await ctx.send(embed=discord.Embed(description="Solo el owner.", color=discord.Color(COLOR_PELIGRO)))
        return
    status = await ctx.send(embed=_make_embed("AutoMod red", "Arrancando...", COLOR_INFO))
    creadas = existentes = fallos = sin_perm = 0
    for idx, g in enumerate(list(bot.guilds), start=1):
        try:
            r = await _discord_automod_setup(g)
            if r.get("sin_permiso"):
                sin_perm += 1
            else:
                creadas += r["creadas"]
                existentes += r["existentes"]
                if r["errores"]:
                    fallos += 1
        except Exception:
            fallos += 1
        if idx % 8 == 0:
            try:
                await status.edit(embed=_make_embed(
                    "AutoMod red",
                    f"Progreso {idx}/{len(bot.guilds)} · nuevas {creadas}",
                    COLOR_INFO,
                ))
            except Exception:
                pass
        await asyncio.sleep(0.4)
    stats = await _contar_automod_red()
    await status.edit(embed=_make_embed(
        "AutoMod red listo",
        (
            f"**Nuevas:** {creadas}\n**Ya estaban:** {existentes}\n"
            f"**Sin permiso:** {sin_perm}\n**Con error:** {fallos}\n\n"
            f"**Total red:** {stats['total']} / {stats['meta']}"
        ),
        COLOR_EXITO,
    ))


@bot.command()
@commands.check(es_staff)
async def banword(ctx, *, palabra: str):
    """Agrega una palabra prohibida (el bot borra mensajes que la contengan)."""
    cfg = get_config(ctx.guild.id) or {}
    palabras = cfg.get("palabras_prohibidas", [])
    palabra = re.sub(r"\s+", " ", palabra.strip().lower())
    if not palabra:
        await ctx.send(embed=discord.Embed(description="Decime una palabra o frase para bloquear.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    existentes = {_banword_forms(item)[1] for item in palabras}
    if _banword_forms(palabra)[1] not in existentes:
        palabras.append(palabra)
    update_server_config(ctx.guild.id, "palabras_prohibidas", palabras)
    await ctx.send(embed=_make_embed("Banword agregada", f"La entrada quedo guardada. Total configuradas: `{len(palabras)}`.", COLOR_EXITO))

@bot.command()
@commands.check(es_staff)
async def unbanword(ctx, *, palabra: str):
    """Elimina una palabra de la lista de prohibidas."""
    cfg = get_config(ctx.guild.id) or {}
    palabras = cfg.get("palabras_prohibidas", [])
    palabra = re.sub(r"\s+", " ", palabra.strip().lower())
    objetivo = _banword_forms(palabra)[1]
    original = next((item for item in palabras if _banword_forms(item)[1] == objetivo), None)
    if original:
        palabras.remove(original)
        update_server_config(ctx.guild.id, "palabras_prohibidas", palabras)
        await ctx.send(embed=_make_embed("Banword removida", "La entrada fue quitada de la lista.", COLOR_EXITO))
    else:
        await ctx.send(embed=_make_embed("Banword no encontrada", "No habia una entrada equivalente en la lista.", COLOR_ADVERTENCIA))

@bot.command()
@commands.check(es_staff)
async def banwordlist(ctx):
    """Ver la lista de palabras prohibidas."""
    cfg = get_config(ctx.guild.id) or {}
    palabras = cfg.get("palabras_prohibidas", [])
    desc = "\n".join(f"`{p}`" for p in palabras) if palabras else "Sin palabras prohibidas."
    embed = discord.Embed(title=f"Palabras Prohibidas ({len(palabras)})", description=desc, color=discord.Color(COLOR_INFO))
    await ctx.send(embed=embed)

