@bot.command()
@commands.check(es_staff)
async def antiraid(ctx, activar: str = "on"):
    """Activa/desactiva modo anti-raid (bloquea el servidor al instante)."""
    activar_bool = activar.lower() in ("on", "true", "activar", "1")
    update_server_config(ctx.guild.id, "modo_antiraid", activar_bool)
    if activar_bool:
        # Bloquear todos los canales
        count = 0
        for ch in ctx.guild.text_channels:
            try:
                await ch.set_permissions(ctx.guild.default_role, send_messages=False)
                count += 1
            except: pass
        embed = discord.Embed(title="🚨 MODO ANTI-RAID ACTIVADO", description=f"{count} canales bloqueados.\nUsa `l!antiraid off` para desactivar.", color=discord.Color(COLOR_PELIGRO))
    else:
        for ch in ctx.guild.text_channels:
            try:
                await ch.set_permissions(ctx.guild.default_role, send_messages=None)
            except: pass
        embed = discord.Embed(title="✅ Modo Anti-Raid Desactivado", description="Canales desbloqueados.", color=discord.Color(COLOR_EXITO))
    embed.set_footer(text=f"Por {ctx.author}")
    await ctx.send(embed=embed)

