class FeedbackModal(discord.ui.Modal):
    def __init__(self, categoria: str):
        super().__init__(title=f"Feedback: {categoria.title()}")
        self.categoria = categoria
        self.texto = discord.ui.TextInput(
            label="Describe tu feedback en detalle",
            style=discord.TextStyle.paragraph,
            placeholder="Mientras mas detalles, mejor podemos ayudarte...",
            min_length=10,
            max_length=1000
        )
        self.add_item(self.texto)

    async def on_submit(self, i: discord.Interaction):
        canal_notif = await _get_notif_channel()

        colores = {"bug": COLOR_PELIGRO, "sugerencia": COLOR_PRIMARIO, "reclamo": COLOR_ADVERTENCIA,
                   "elogio": COLOR_EXITO, "abuso": 0xFF6B35, "kofi": 0xFF5E00, "otro": COLOR_INFO}
        emojis = {"bug": "🐛", "sugerencia": "💡", "reclamo": "😤", "elogio": "🌟", "abuso": "⚠️", "kofi": "☕", "otro": "📝"}

        embed = discord.Embed(
            title=f"{emojis.get(self.categoria,'📝')} Feedback: {self.categoria.title()}",
            description=self.texto.value,
            color=discord.Color(colores.get(self.categoria, COLOR_INFO)),
            timestamp=datetime.datetime.now(datetime.timezone.utc)
        )
        embed.add_field(name="Usuario", value=f"{i.user} (`{i.user.id}`)", inline=True)
        if i.guild:
            embed.add_field(name="Servidor", value=f"{i.guild.name} (`{i.guild.id}`)", inline=True)
        embed.set_thumbnail(url=i.user.display_avatar.url)
        embed.set_footer(text="LatamBOT Feedback System")

        enviado = False
        if canal_notif:
            try:
                # Ko-Fi: mandar con botones de Aceptar/Rechazar
                if self.categoria == "kofi":
                    embed.title = "☕ Solicitud de Beneficios Ko-Fi"
                    embed.add_field(
                        name="¿Qué obtiene si se acepta?",
                        value=KOFI_BENEFICIOS,
                        inline=False
                    )
                    await canal_notif.send(embed=embed, view=KoFiReviewView(i.user.id, str(i.user)))
                else:
                    await canal_notif.send(embed=embed)
                enviado = True
            except Exception as e:
                print(f"[FEEDBACK] Error: {e}")

        msg_ok = "☕ Solicitud enviada!\nApoyá el proyecto en [Ko-Fi](https://ko-fi.com/latambot) o [Patreon](https://patreon.com/latambot) si aún no lo hiciste.\nEl equipo revisará tu apoyo y te avisará por DM." if self.categoria == "kofi" else "Gracias! Tu feedback fue enviado al equipo de desarrollo."
        if enviado:
            _metric_bump("feedback_sent")
            await i.response.send_message(
                embed=discord.Embed(
                    title="✅ Enviado",
                    description=msg_ok,
                    color=discord.Color(COLOR_EXITO)
                ),
                ephemeral=True
            )
        else:
            await i.response.send_message(
                embed=discord.Embed(description="No pude enviar el feedback. Intenta mas tarde.", color=discord.Color(COLOR_PELIGRO)),
                ephemeral=True
            )


class AIOpinionNoModal(discord.ui.Modal):
    def __init__(self, *, guild_id: int, user_id: int, question: str, answer: str, source: str):
        super().__init__(title="Contame qué falló")
        self.guild_id = guild_id
        self.user_id = user_id
        self.question = question
        self.answer = answer
        self.source = source
        self.reason = discord.ui.TextInput(
            label="Explicación opcional",
            style=discord.TextStyle.paragraph,
            required=False,
            max_length=400,
            placeholder="Ej: fue muy corto, entendió mal la pregunta, inventó algo..."
        )
        self.add_item(self.reason)

    async def on_submit(self, i: discord.Interaction):
        feedback_id = _store_ai_feedback(
            guild_id=self.guild_id,
            user_id=self.user_id,
            question=self.question,
            answer=self.answer,
            useful=False,
            note=self.reason.value,
            source=self.source,
        )
        canal_notif = await _get_notif_channel()
        if canal_notif:
            embed = discord.Embed(
                title="Feedback IA: no útil",
                description=_clip_text(self.reason.value or "Sin explicación adicional.", 800),
                color=discord.Color(COLOR_ADVERTENCIA),
                timestamp=datetime.datetime.now(datetime.timezone.utc),
            )
            embed.add_field(name="Pregunta", value=_clip_text(self.question or "Sin pregunta", 600), inline=False)
            embed.add_field(name="Respuesta", value=_clip_text(self.answer or "Sin respuesta", 1000), inline=False)
            embed.add_field(name="Contexto", value=f"Usuario `{self.user_id}` • Servidor `{self.guild_id}` • Fuente `{self.source}`", inline=False)
            embed.set_footer(text=f"ID feedback: {feedback_id}")
