@bot.command()
async def console(ctx, lineas: int = 30):
    """[OWNER] Ver las ultimas lineas de la consola del bot."""
    if ctx.author.id != OWNER_ID:
        return
    lineas = min(lineas, CONSOLE_BUFFER_SIZE)
    ultimas = list(console_buffer)[-lineas:]
    if not ultimas:
        await ctx.send(embed=discord.Embed(description="La consola esta vacia.", color=discord.Color(COLOR_INFO)))
        return
    texto = "\n".join(ultimas)
    # Dividir si es muy largo
    partes = [texto[i:i+1900] for i in range(0, len(texto), 1900)]
    for idx, parte in enumerate(partes[:3]):
        embed = discord.Embed(
            title=f"🖥️ Consola ({idx+1}/{len(partes[:3])})" if len(partes) > 1 else "🖥️ Consola",
            description=f"```\n{parte}\n```",
            color=discord.Color(COLOR_OSCURO),
            timestamp=datetime.datetime.now(datetime.timezone.utc)
        )
        embed.set_footer(text=f"Ultimas {len(ultimas)} lineas | Buffer: {len(console_buffer)}/{CONSOLE_BUFFER_SIZE}")
        await ctx.author.send(embed=embed)
    if ctx.guild:
        await ctx.send(embed=discord.Embed(description="Te mande la consola por DM.", color=discord.Color(COLOR_INFO)), delete_after=5)





# ==============================================================================
# l!ytb - Buscar videos en YouTube con buscador integrado
# ==============================================================================

@bot.hybrid_command(name="ytb", description="Busca videos en YouTube. User App: cupo diario.")
@app_commands.describe(query="Que buscar en YouTube")
@app_commands.allowed_installs(guilds=True, users=True)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
async def ytb(ctx, *, query: str = None):
    """Busca videos en YouTube usando el buscador integrado.
    Uso: l!ytb <busqueda>
    Ej: l!ytb musica latina 2025
    Muestra los resultados con botones para descargar con l!dl o l!mp3."""
    if ctx.interaction and query:
        await ctx.defer()
    if not query:
        await ctx.send(embed=discord.Embed(
            title="▶️ l!ytb - Buscar en YouTube",
            description=(
                "**Uso:** `l!ytb <busqueda>`\n"
                "Ej: `l!ytb musica latina 2025`\n\n"
                "Despues eliges un resultado y descargas en MP3 o MP4."
            ),
            color=discord.Color(COLOR_INFO)
        ))
        return
    if not SERPAPI_KEY or SERPAPI_KEY.startswith("PON_"):
        await ctx.send(embed=discord.Embed(
            description="❌ Búsqueda no disponible temporalmente.",
            color=discord.Color(COLOR_PELIGRO)
        ))
        return
    if not await _ensure_userapp_search(ctx):
        return

    uid = ctx.author.id
    vip = es_kofi(uid)
    limite_ytb = get_limites(uid)[1]
    hoy = datetime.date.today().isoformat()
    if uid not in ytb_usos_diarios or ytb_usos_diarios[uid].get("fecha") != hoy:
        ytb_usos_diarios[uid] = {"count": 0, "fecha": hoy}
    usos_ytb = ytb_usos_diarios[uid]["count"]
    if usos_ytb >= limite_ytb:
        embed_lim = discord.Embed(
            title="⏱️ Límite de búsquedas alcanzado",
            description=(
                f"Usaste **{usos_ytb}/{limite_ytb}** búsquedas de YouTube hoy.\n"
                f"El límite se reinicia a medianoche.\n\n"
                + ("" if vip else KOFI_BENEFICIOS + "\n\n**¿Querés más usos?** Apoyá en [☕ Ko-Fi](https://ko-fi.com/latambot) o [🎭 Patreon](https://patreon.com/latambot)\nReclamá tus beneficios con `l!feedback` → **Ko-Fi**.")
            ),
            color=discord.Color(COLOR_ADVERTENCIA)
        )
        await ctx.send(embed=embed_lim)
        return
    ytb_usos_diarios[uid]["count"] += 1
    _media_debug("YTB_SEARCH", guild_id=ctx.guild.id if ctx.guild else None, user_id=uid, query=query[:120])
    serp = _get_serpapi_user_settings(uid, ctx.guild.id if ctx.guild else None)

    async with ctx.typing():
        data = await _serpapi_request({
            "engine": "youtube",
            "search_query": query,
            "hl": serp["hl"],
            "gl": serp["gl"],
        })
        if not data or data.get("_error"):
            await ctx.send(embed=discord.Embed(
                description="❌ No pude obtener resultados de YouTube.",
                color=discord.Color(COLOR_PELIGRO)
            ))
            return

        videos = data.get("video_results", [])
        if not videos:
            await ctx.send(embed=discord.Embed(
                description=f"Sin resultados para `{query}`.",
                color=discord.Color(COLOR_ADVERTENCIA)
            ))
            return

        videos = videos[:8]
        embed = discord.Embed(
            title=f"▶️ YouTube: {query[:50]}",
            color=discord.Color.from_rgb(255, 0, 0),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        )
        for i, v in enumerate(videos, 1):
            titulo = v.get("title", "Sin titulo")[:80]
            canal = v.get("channel", {}).get("name", "Desconocido") if isinstance(v.get("channel"), dict) else v.get("channel", "?")
            duracion = v.get("length", "?")
            vistas = v.get("views", "")
            link = v.get("link", "")
            publicado = v.get("published_date") or v.get("uploaded") or ""
            snippet = _clip_text(v.get("snippet") or v.get("description") or "", 110)
            vistas_txt = f" • {vistas:,} vistas" if isinstance(vistas, int) else (f" • {vistas}" if vistas else "")
            embed.add_field(
                name=f"{i}. {titulo}",
                value=(
                    f"📺 {canal} • ⏱️ {duracion}{vistas_txt}\n"
                    f"{('🗓️ ' + publicado + chr(10)) if publicado else ''}"
                    f"{(snippet + chr(10)) if snippet else ''}"
                    f"[▶️ Ver en YouTube]({link})"
                ),
                inline=False
            )

        restantes_ytb = limite_ytb - ytb_usos_diarios[uid]["count"]
        badge = "☕ " if vip else ""
        embed.set_footer(text=f"{badge}LatamBOT | Elige un resultado abajo | {restantes_ytb}/{limite_ytb} búsquedas hoy")
        view = YTBResultsView(videos, ctx.author.id)
        await ctx.send(embed=embed, view=view)


class YTBResultsView(discord.ui.View):
    """Elegir video y luego MP3 o MP4 (descarga en el canal)."""
    def __init__(self, videos: list, requester_id: int):
        super().__init__(timeout=None)
        self.videos = videos
        self.requester_id = requester_id
        self.link: str = ""
        self.titulo: str = ""
        opciones = []
        for i, v in enumerate(self.videos):
            titulo = v.get("title", f"Video {i+1}")[:80]
            opciones.append(discord.SelectOption(label=titulo[:100], value=str(i), emoji="▶️"))
        sel = discord.ui.Select(
            placeholder="Elegi un video...",
            options=opciones,
            custom_id="latambot_ytb_select",
        )
        sel.callback = self._on_select
        self.add_item(sel)

    async def interaction_check(self, i: discord.Interaction) -> bool:
        if i.user.id != self.requester_id:
            await i.response.send_message("Solo quien busco puede descargar.", ephemeral=True)
            return False
        return True

    async def _on_select(self, i: discord.Interaction):
        idx = int(i.data["values"][0])
        video = self.videos[idx]
        self.link = video.get("link", "") or ""
        self.titulo = (video.get("title", "Video") or "Video")[:90]
        if not self.link:
            await i.response.send_message("Sin enlace valido para ese video.", ephemeral=True)
            return
        self.clear_items()
        b_mp3 = discord.ui.Button(
            label="MP3 (audio)",
            style=discord.ButtonStyle.primary,
            emoji="🎵",
            row=0,
            custom_id="latambot_ytb_mp3",
        )
        b_mp4 = discord.ui.Button(
            label="MP4 (video)",
            style=discord.ButtonStyle.success,
            emoji="🎬",
            row=0,
            custom_id="latambot_ytb_mp4",
        )
        b_link = discord.ui.Button(label="Abrir en YouTube", style=discord.ButtonStyle.link, url=self.link, row=1)

        async def cb_mp3(inter: discord.Interaction):
            await inter.response.defer()
            mem = inter.guild.get_member(inter.user.id) if inter.guild else None
            if not mem:
                await inter.followup.send("No se pudo resolver tu usuario.", ephemeral=True)
                return
            st = await inter.followup.send("Descargando **MP3**...", wait=True)
            await _ytb_descargar_en_canal(inter.channel, mem, self.link, True, st)

        async def cb_mp4(inter: discord.Interaction):
            await inter.response.defer()
            mem = inter.guild.get_member(inter.user.id) if inter.guild else None
            if not mem:
                await inter.followup.send("No se pudo resolver tu usuario.", ephemeral=True)
                return
            st = await inter.followup.send("Descargando **MP4**...", wait=True)
            await _ytb_descargar_en_canal(inter.channel, mem, self.link, False, st)

        b_mp3.callback = cb_mp3
        b_mp4.callback = cb_mp4
        self.add_item(b_mp3)
        self.add_item(b_mp4)
        self.add_item(b_link)
        emb = discord.Embed(
            title="Elegi formato",
            description=f"**{self.titulo}**\n{self.link}\n\n**MP3** = solo audio | **MP4** = video",
            color=discord.Color.from_rgb(255, 0, 0),
        )
        emb.set_footer(text="La descarga se publica en este canal")
        await i.response.edit_message(embed=emb, view=self)



