def _resolve_tier_alias(raw: str) -> Optional[str]:
    value = (raw or "").strip().lower()
    aliases = {
        "kofi": "kofi",
        "tier1": "kofi",
        "1": "kofi",
        "apoyador": "kofi",
        "supporter1": "kofi",
        "tier2": "tier2",
        "2": "tier2",
        "seguidor": "tier2",
        "tier3": "tier3",
        "3": "tier3",
        "fanatico": "tier3",
        "fanático": "tier3",
        "tier4": "tier4",
        "4": "tier4",
        "supporter": "tier4",
        "vip": "tier4",
    }
    return aliases.get(value)


@bot.command(aliases=["uwuify"])
@commands.check(es_staff)
async def uwufiy(ctx, usuario: discord.Member = None):
    """Activa el relay uwu por webhook para un usuario del servidor."""
    target = usuario
    if not target and ctx.message.reference:
        try:
            ref_msg = ctx.message.reference.cached_message or await ctx.channel.fetch_message(ctx.message.reference.message_id)
            if isinstance(ref_msg.author, discord.Member):
                target = ref_msg.author
        except Exception:
            target = None
    if not target:
        await ctx.send(embed=_make_embed("Falta usuario", "Usa `l!uwufiy @usuario` o responde a un mensaje suyo.", COLOR_ADVERTENCIA))
        return
    if target.bot:
        await ctx.send(embed=_make_embed("Accion bloqueada", "No voy a activar uwufiy sobre bots.", COLOR_PELIGRO))
        return
    if user_prefs.get(target.id, {}).get("uwu_opt_out", False):
        await ctx.send(embed=_make_embed("Accion bloqueada", f"{target.mention} tiene bloqueado `uwufiy` desde su configuracion.", COLOR_ADVERTENCIA))
        return
    perms = ctx.channel.permissions_for(ctx.guild.me)
    if not perms.manage_webhooks:
        await ctx.send(embed=_make_embed("Falta permiso", "Necesito `Manage Webhooks` en este canal para usar `uwufiy`.", COLOR_PELIGRO))
        return
    if target.id in _get_uwu_targets(ctx.guild.id):
        await ctx.send(embed=_make_embed("Ya estaba activo", f"{target.mention} ya está en modo uwu en este servidor.", COLOR_INFO))
        return
    _set_uwu_state(ctx.guild.id, target.id, True)
    como_desactivar = (
        "**¿Cómo se saca?**\n"
        f"• Staff: `l!unuwu {target.name}` (o respondiendo a un mensaje suyo).\n"
        f"• {target.mention}: `l!configuracion` → **uwufiy** para bloquearlo vos mismo."
    )
    await ctx.send(embed=_make_embed(
        f"{EMOJI_FBLAUGH} Modo uwu activado 🐾",
        f"Ahora reenvío los mensajes de {target.mention} (texto **e** imágenes) con filtro uwu.\n\n{como_desactivar}",
        COLOR_EXITO,
    ))
    # Avisar al usuario por DM cómo desactivarlo
    try:
        await target.send(embed=_make_embed(
            "Te activaron el modo uwu 🐾",
            f"En **{ctx.guild.name}** el staff activó `uwufiy` en tus mensajes (se reenvían con onda uwu).\n\n"
            "Si no querés, podés **bloquearlo vos** con `l!configuracion` → **uwufiy**, "
            "o pedile al staff que use `l!unuwu`.",
            COLOR_INFO,
        ))
    except Exception:
        pass


