@bot.command()
@commands.check(lambda ctx: ctx.author.id == OWNER_ID)
async def tiergive(ctx, usuario: discord.User = None, tier: str = None):
    """[OWNER] Da un tier manual a un usuario."""
    if not usuario or not tier:
        await ctx.send(embed=_make_embed("Uso", "Usa `l!tiergive @usuario <kofi|tier2|tier3|tier4>`.", COLOR_INFO))
        return
    tier_real = _resolve_tier_alias(tier)
