def es_kofi(user_id: int) -> bool:
    """True si el usuario tiene cualquier tier activo (o votó en top.gg)."""
    if user_id == OWNER_ID:
        return True
    if _es_votante(user_id):
        return True
    if user_id not in kofi_activos:
        return False
    datos = kofi_activos[user_id]
    # Verificar expiracion si existe
    if "expira" in datos:
        try:
            expira = datetime.datetime.fromisoformat(datos["expira"])
            if datetime.datetime.now() > expira:
                del kofi_activos[user_id]
                return False
        except:
            pass
    return True



# ==============================================================================
# QR CODE - l!qr
# ==============================================================================

@bot.command()
async def qr(ctx, *, texto: str = None):
    """Genera un código QR de cualquier texto o URL.
    Uso: l!qr <texto/url>
    Ej: l!qr https://discord.gg/latam"""
    if not texto:
        # Si respondió a un mensaje, usar ese contenido
        if ctx.message.reference and ctx.message.reference.cached_message:
            texto = ctx.message.reference.cached_message.content
        if not texto:
            await ctx.send(embed=discord.Embed(description="Uso: `l!qr <texto o URL>`", color=discord.Color(COLOR_INFO)))
            return
    async with ctx.typing():
        try:
            import qrcode as _qr
            import io as _io
            qr_img = _qr.QRCode(version=None, error_correction=_qr.constants.ERROR_CORRECT_H, box_size=10, border=4)
            qr_img.add_data(texto)
            qr_img.make(fit=True)
            img = qr_img.make_image(fill_color="black", back_color="white")
            buf = _io.BytesIO()
            img.save(buf, format="PNG")
            buf.seek(0)
            embed = discord.Embed(title="📱 Código QR generado", color=discord.Color(COLOR_PRIMARIO))
            embed.set_footer(text=f"Contenido: {texto[:80]}{'...' if len(texto)>80 else ''}")
            await ctx.send(embed=embed, file=discord.File(buf, filename="qr.png"))
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ QR no disponible temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error generando QR: `{e}`", color=discord.Color(COLOR_PELIGRO)))


@bot.command()
async def qrinvite(ctx):
    """Genera un QR con la invitación del servidor."""
    try:
        invites = await ctx.guild.invites()
        invite = invites[0] if invites else await ctx.channel.create_invite(max_age=0, max_uses=0)
        await ctx.invoke(bot.get_command("qr"), texto=invite.url)
    except discord.Forbidden:
        await ctx.send(embed=discord.Embed(description="❌ No tengo permisos para crear invitaciones.", color=discord.Color(COLOR_PELIGRO)))


