@bot.command(name="traducir", aliases=["translate", "tr"])
async def traducir(ctx, idioma: str = None, *, texto: str = None):
    """Traduce texto gratis sin gastar tokens de IA.
    Uso: l!traducir <idioma> <texto>
    Ej: l!traducir en Hola mundo
    Idiomas: es, en, pt, fr, de, it, ja, ko, zh, ar, ru...
    Sin texto: traduce el mensaje al que respondiste."""
    if not idioma:
        await ctx.send(embed=discord.Embed(
            description="**Uso:** `l!traducir <idioma> <texto>`\nEj: `l!traducir en Hola mundo`\n\nIdiomas comunes: `es` `en` `pt` `fr` `de` `it` `ja` `ko` `zh` `ar` `ru`",
            color=discord.Color(COLOR_INFO)
        ))
        return
    # Si no hay texto, usar mensaje referenciado
    if not texto and ctx.message.reference:
        ref_t = await obtener_mensaje_referenciado(ctx.message)
        if ref_t:
            texto = ref_t.content
    if not texto:
        await ctx.send(embed=discord.Embed(description="❌ No hay texto para traducir. Respondé a un mensaje o escribí el texto.", color=discord.Color(COLOR_PELIGRO)))
        return
    async with ctx.typing():
        try:
            from deep_translator import GoogleTranslator as _GT
            traduccion = _GT(source="auto", target=idioma).translate(texto[:5000])
            embed = discord.Embed(color=discord.Color(COLOR_PRIMARIO))
            embed.add_field(name="📝 Original", value=texto[:500], inline=False)
            embed.add_field(name=f"🌐 Traducción ({idioma})", value=traduccion[:500], inline=False)
            embed.set_footer(text="LatamBOT | Traducción")
            await ctx.reply(embed=embed, mention_author=False)
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ Traducción no disponible temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error al traducir: `{e}`\nVerificá el código de idioma.", color=discord.Color(COLOR_PELIGRO)))


@bot.command()
async def detectar(ctx, *, texto: str = None):
    """Detecta el idioma de un texto.
    Uso: l!detectar <texto>"""
    if not texto and ctx.message.reference and ctx.message.reference.cached_message:
        texto = ctx.message.reference.cached_message.content
    if not texto:
        await ctx.send(embed=discord.Embed(description="Uso: `l!detectar <texto>`", color=discord.Color(COLOR_INFO)))
        return
    try:
        from deep_translator import single_detection as _sd
        lang = _sd(texto, api_key=None)
        nombres = {"es":"Español","en":"Inglés","pt":"Portugués","fr":"Francés","de":"Alemán","it":"Italiano","ja":"Japonés","ko":"Coreano","zh-CN":"Chino","ar":"Árabe","ru":"Ruso"}
        nombre = nombres.get(lang, lang)
        embed = discord.Embed(description=f"**Idioma detectado:** {nombre} (`{lang}`)", color=discord.Color(COLOR_PRIMARIO))
        await ctx.send(embed=embed)
    except ImportError:
        await ctx.send(embed=discord.Embed(description="❌ `pip install deep-translator langdetect`", color=discord.Color(COLOR_PELIGRO)))
    except Exception as e:
        try:
            from langdetect import detect as _det
            lang = _det(texto)
            await ctx.send(embed=discord.Embed(description=f"**Idioma detectado:** `{lang}`", color=discord.Color(COLOR_PRIMARIO)))
        except:
            await ctx.send(embed=discord.Embed(description=f"❌ No pude detectar el idioma: `{e}`", color=discord.Color(COLOR_PELIGRO)))


# ==============================================================================
# TTS - l!tts (Google TTS)
# ==============================================================================

@bot.command()
async def tts(ctx, idioma_o_texto: str = None, *, texto: str = None):
    """Convierte texto a voz y lo sube como audio MP3.
    Uso: l!tts <texto>
         l!tts <idioma> <texto>
    Ej: l!tts Hola a todos!
        l!tts en Hello everyone!
        l!tts pt Olá galera!"""
    if not idioma_o_texto:
        await ctx.send(embed=discord.Embed(description="**Uso:** `l!tts <texto>` o `l!tts <idioma> <texto>`\nIdiomas: `es` `en` `pt` `fr` `ja` `ko`", color=discord.Color(COLOR_INFO)))
        return
    # Detectar si el primer argumento es un código de idioma (2-5 chars)
    LANGS_VALIDOS = {"es","en","pt","fr","de","it","ja","ko","zh","ar","ru","pl","nl","tr","hi"}
    if idioma_o_texto.lower() in LANGS_VALIDOS and texto:
        lang = idioma_o_texto.lower()
    else:
        lang = "es"
        texto = idioma_o_texto + (" " + texto if texto else "")
    if not texto or not texto.strip():
        await ctx.send(embed=discord.Embed(description="❌ No hay texto para leer.", color=discord.Color(COLOR_PELIGRO)))
        return
    if len(texto) > 500:
        await ctx.send(embed=discord.Embed(description="❌ Máximo 500 caracteres.", color=discord.Color(COLOR_ADVERTENCIA)))
        return
    async with ctx.typing():
        try:
            from gtts import gTTS as _gTTS
            import io as _io
            tts_obj = _gTTS(text=texto, lang=lang, slow=False)
            buf = _io.BytesIO()
            tts_obj.write_to_fp(buf)
            buf.seek(0)
            embed = discord.Embed(
                title="🔊 Texto a Voz",
                description=f"`{texto[:100]}{'...' if len(texto)>100 else ''}`",
                color=discord.Color(COLOR_PRIMARIO)
            )
            embed.add_field(name="Idioma", value=lang, inline=True)
            embed.add_field(name="Pedido por", value=ctx.author.mention, inline=True)
            embed.set_footer(text="LatamBOT | TTS")
            await ctx.send(embed=embed, file=discord.File(buf, filename=f"tts_{lang}.mp3"))
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ TTS no disponible temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error TTS: `{e}`", color=discord.Color(COLOR_PELIGRO)))


