# OCR - l!leer (pytesseract)
# ==============================================================================

@bot.command(aliases=["ocr"])
async def leer(ctx):
    """Extrae texto de una imagen usando OCR.
    Respondé a una imagen o adjuntá una.
    Uso: l!leer (con imagen adjunta o respondiendo a una)"""
    img_url = None
    # Buscar imagen en adjuntos
    for att in ctx.message.attachments:
        if att.content_type and att.content_type.startswith("image/"):
            img_url = att.url
            break
    # Buscar en mensaje referenciado
    if not img_url and ctx.message.reference:
        ref = await obtener_mensaje_referenciado(ctx.message)
        if ref:
            for att in ref.attachments:
                if att.content_type and att.content_type.startswith("image/"):
                    img_url = att.url
                    break
            if not img_url and ref.embeds and ref.embeds[0].image:
                img_url = ref.embeds[0].image.url
    if not img_url:
        await ctx.send(embed=discord.Embed(description="❌ Adjuntá una imagen o respondé a una.", color=discord.Color(COLOR_PELIGRO)))
        return
    async with ctx.typing():
        try:
            import pytesseract as _tess
            from PIL import Image as _PILImg
            import io as _io
            if not _scam_url_segura(img_url):
                await ctx.send(embed=discord.Embed(description="❌ URL de imagen no permitida.", color=discord.Color(COLOR_PELIGRO)))
                return
            async with aiohttp.ClientSession() as session:
                async with session.get(img_url, allow_redirects=False) as resp:
                    img_bytes = await resp.read()
            img = _PILImg.open(_io.BytesIO(img_bytes))
            texto = _tess.image_to_string(img, lang="spa+eng").strip()
            if not texto:
                await ctx.send(embed=discord.Embed(description="No encontré texto en la imagen.", color=discord.Color(COLOR_ADVERTENCIA)))
                return
            embed = discord.Embed(title="📄 Texto extraído", color=discord.Color(COLOR_PRIMARIO))
            # Dividir si es muy largo
            if len(texto) > 1000:
                embed.description = texto[:1000] + f"\\n\\n*...+{len(texto)-1000} caracteres más*"
            else:
                embed.description = f"```{texto}```"
            embed.set_footer(text="LatamBOT | OCR")
            await ctx.reply(embed=embed, mention_author=False)
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ OCR no disponible temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error OCR: `{e}`", color=discord.Color(COLOR_PELIGRO)))


