@bot.command()
async def actividad(ctx, dias: int = 7):
    """Gráfico de los usuarios más activos del servidor.
    Uso: l!actividad [días]
    Ej: l!actividad 7"""
    if dias < 1 or dias > 30:
        dias = 7
    async with ctx.typing():
        try:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as _plt
            import io as _io
            # Usar datos de actividad_usuarios si existen
            datos = cargar_datos()
            usuarios_raw = datos.get("usuarios", {})
            # Recopilar mensajes por usuario en el server
            conteos = {}
            for uid_str, udata in usuarios_raw.items():
                mensajes = udata.get("mensajes_hoy", 0) + udata.get("mensajes_total", 0)
                if mensajes > 0:
                    try:
                        uid_i = int(uid_str)
                        if user_prefs.get(uid_i, {}).get("ocultar_rank", False):
                            continue
                        member = ctx.guild.get_member(uid_i)
                        if member:
                            conteos[member.display_name[:15]] = mensajes
                    except:
                        pass
            if len(conteos) < 2:
                await ctx.send(embed=discord.Embed(description="No hay suficientes datos de actividad aún.", color=discord.Color(COLOR_ADVERTENCIA)))
                return
            # Top 10
            top = sorted(conteos.items(), key=lambda x: x[1], reverse=True)[:10]
            nombres, valores = zip(*top)
            fig, ax = _plt.subplots(figsize=(10, 5))
            bars = ax.barh(list(reversed(nombres)), list(reversed(valores)), color="#5865F2")
            ax.set_xlabel("Mensajes")
            ax.set_title(f"👥 Usuarios más activos - {ctx.guild.name}", fontsize=13, pad=12)
            ax.bar_label(bars, padding=4)
            fig.patch.set_facecolor("#2B2D31")
            ax.set_facecolor("#313338")
            ax.tick_params(colors="white")
            ax.title.set_color("white")
            ax.xaxis.label.set_color("white")
            for spine in ax.spines.values():
                spine.set_edgecolor("#404249")
            _plt.tight_layout()
            buf = _io.BytesIO()
            _plt.savefig(buf, format="png", dpi=120, facecolor=fig.get_facecolor())
            _plt.close(fig)
            buf.seek(0)
            embed = discord.Embed(title=f"📊 Actividad - {ctx.guild.name}", color=discord.Color(COLOR_PRIMARIO))
            embed.set_footer(text="LatamBOT | Actividad")
            await ctx.send(embed=embed, file=discord.File(buf, filename="actividad.png"))
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ Gráficos no disponibles temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error generando gráfico: `{e}`", color=discord.Color(COLOR_PELIGRO)))


@bot.command()
async def topcanales(ctx):
    """Muestra los canales más activos del servidor como gráfico."""
    async with ctx.typing():
        try:
            import matplotlib
            matplotlib.use("Agg")
            import matplotlib.pyplot as _plt
            import io as _io
            # Contar mensajes por canal
            conteos = {}
            msg_estado = await ctx.send("📊 Analizando canales...")
            for canal in ctx.guild.text_channels[:20]:
                try:
                    count = 0
                    async for _ in canal.history(limit=200, after=datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=7)):
                        count += 1
                    if count > 0:
                        conteos[f"#{canal.name[:15]}"] = count
                except:
                    pass
            await msg_estado.delete()
            if not conteos:
                await ctx.send(embed=discord.Embed(description="No hay datos de actividad en los canales.", color=discord.Color(COLOR_ADVERTENCIA)))
                return
            top = sorted(conteos.items(), key=lambda x: x[1], reverse=True)[:8]
            nombres, valores = zip(*top)
            fig, ax = _plt.subplots(figsize=(10, 5))
            colors = ["#5865F2","#57F287","#FEE75C","#ED4245","#EB459E","#3BA55D","#FAA61A","#9B59B6"]
            bars = ax.barh(list(reversed(nombres)), list(reversed(valores)), color=colors[:len(nombres)])
            ax.set_xlabel("Mensajes (últimos 7 días)")
            ax.set_title(f"💬 Canales más activos - {ctx.guild.name}", fontsize=13, pad=12)
            ax.bar_label(bars, padding=4)
            fig.patch.set_facecolor("#2B2D31")
            ax.set_facecolor("#313338")
            ax.tick_params(colors="white")
            ax.title.set_color("white")
            ax.xaxis.label.set_color("white")
            for spine in ax.spines.values():
                spine.set_edgecolor("#404249")
            _plt.tight_layout()
            buf = _io.BytesIO()
            _plt.savefig(buf, format="png", dpi=120, facecolor=fig.get_facecolor())
            _plt.close(fig)
            buf.seek(0)
            embed = discord.Embed(title=f"📊 Canales más activos - {ctx.guild.name}", color=discord.Color(COLOR_PRIMARIO))
            embed.set_footer(text="LatamBOT | Actividad semanal")
            await ctx.send(embed=embed, file=discord.File(buf, filename="canales.png"))
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ Gráficos no disponibles temporalmente.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: `{e}`", color=discord.Color(COLOR_PELIGRO)))


