# --- Wordle ---
WORDLE_PALABRAS = [
    "gatos","perro","casas","libro","reloj","playa","norte","verde","blanco","fuego",
    "agua","tierra","cielo","noche","tarde","llama","monte","campo","selva","bosque",
    "flota","plaza","brisa","cargo","danza","elote","finca","golpe","hueco","jaula",
    "karma","lunar","marco","nieve","orden","punta","queso","radio","salto","torre",
    "ultra","vapor","texto","yermo","zumo","banco","cinco","delta","enero","fosil",
    "guion","hongo","indio","justo","kiosk","llave","mundo","nadie","omega","papel",
]

class WordleView(discord.ui.View):
    def __init__(self, palabra: str, autor_id: int):
        super().__init__(timeout=300)
        self.palabra = palabra.lower()
        self.autor_id = autor_id
        self.intentos = []
        self.max_intentos = 6

    def render(self) -> str:
        lineas = []
        for intento in self.intentos:
            linea = ""
            for i, letra in enumerate(intento):
                if letra == self.palabra[i]:
                    linea += "🟩"
                elif letra in self.palabra:
                    linea += "🟨"
                else:
                    linea += "⬛"
            linea += f"  `{intento.upper()}`"
            lineas.append(linea)
        vacias = self.max_intentos - len(self.intentos)
        for _ in range(vacias):
            lineas.append("⬜⬜⬜⬜⬜")
        return "\n".join(lineas)

    @discord.ui.button(label="✏️ Adivinar", style=discord.ButtonStyle.primary)
    async def adivinar(self, i: discord.Interaction, b):
        if i.user.id != self.autor_id:
            await i.response.send_message("No es tu partida.", ephemeral=True); return
        modal = WordleModal(self)
        await i.response.send_modal(modal)

    @discord.ui.button(label="🏳️ Rendirse", style=discord.ButtonStyle.danger)
    async def rendirse(self, i: discord.Interaction, b):
        if i.user.id != self.autor_id:
            await i.response.send_message("No es tu partida.", ephemeral=True); return
        self.stop()
        for item in self.children: item.disabled = True
        await i.response.edit_message(
            embed=discord.Embed(title="😞 Te rendiste", description=f"La palabra era: **{self.palabra.upper()}**\n\n{self.render()}", color=discord.Color.red()),
            view=self
        )


class WordleModal(discord.ui.Modal, title="Wordle - Adivina la palabra"):
    intento = discord.ui.TextInput(label="Palabra (5 letras)", min_length=5, max_length=5, placeholder="Escribe tu intento...")

    def __init__(self, view: WordleView):
        super().__init__()
        self.game_view = view

    async def on_submit(self, i: discord.Interaction):
        palabra = self.intento.value.lower().strip()
        if len(palabra) != 5 or not palabra.isalpha():
            await i.response.send_message("❌ Debe ser una palabra de exactamente 5 letras.", ephemeral=True); return
        self.game_view.intentos.append(palabra)
        ganado = palabra == self.game_view.palabra
        perdido = len(self.game_view.intentos) >= self.game_view.max_intentos and not ganado
        embed = discord.Embed(title="🟩 Wordle", color=discord.Color(COLOR_PRIMARIO))
        embed.description = self.game_view.render()
        if ganado:
            embed.color = discord.Color.green()
            embed.set_footer(text=f"¡Ganaste en {len(self.game_view.intentos)} intento(s)! 🎉")
            for item in self.game_view.children: item.disabled = True
            self.game_view.stop()
        elif perdido:
            embed.color = discord.Color.red()
            embed.set_footer(text=f"Perdiste 😞 La palabra era: {self.game_view.palabra.upper()}")
            for item in self.game_view.children: item.disabled = True
            self.game_view.stop()
        else:
            embed.set_footer(text=f"Intento {len(self.game_view.intentos)}/{self.game_view.max_intentos} - Presioná Adivinar")
        await i.response.edit_message(embed=embed, view=self.game_view)


@bot.command()
async def wordle(ctx):
    """Juega Wordle - adivina la palabra de 5 letras en 6 intentos."""
    palabra = random.choice(WORDLE_PALABRAS)
