# --- Ta-Te-Ti ---
class TaTeTiView(discord.ui.View):
    def __init__(self, jugador1: discord.Member, jugador2: discord.Member):
        super().__init__(timeout=300)
        self.j1 = jugador1  # X
        self.j2 = jugador2  # O
        self.turno = jugador1
        self.tablero = ["⬜"] * 9
        self._build_buttons()

    def _build_buttons(self):
        self.clear_items()
        for idx in range(9):
            btn = discord.ui.Button(
                label=self.tablero[idx] if self.tablero[idx] != "⬜" else "​",
                style=discord.ButtonStyle.secondary if self.tablero[idx]=="⬜" else
                      (discord.ButtonStyle.danger if self.tablero[idx]=="❌" else discord.ButtonStyle.success),
                row=idx//3, disabled=self.tablero[idx]!="⬜",
                custom_id=f"tateti_{idx}"
            )
            btn.callback = self._make_callback(idx)
            self.add_item(btn)

    def _make_callback(self, idx):
        async def callback(i: discord.Interaction):
            if i.user.id != self.turno.id:
                await i.response.send_message(f"Es el turno de {self.turno.mention}.", ephemeral=True); return
            simbolo = "❌" if self.turno == self.j1 else "🔵"
            self.tablero[idx] = simbolo
            ganador = self._check_winner()
            empate = "⬜" not in self.tablero and not ganador
            self.turno = self.j2 if self.turno == self.j1 else self.j1
            self._build_buttons()
            if ganador or empate:
                for item in self.children: item.disabled = True
            titulo = f"Ta-Te-Ti - {'🎉 ' + (self.j1 if simbolo=='❌' else self.j2).display_name + ' ganó!' if ganador else ('Empate 🤝' if empate else f'Turno de {self.turno.display_name}')}"
            color = discord.Color.green() if ganador else (discord.Color.yellow() if empate else discord.Color(COLOR_PRIMARIO))
            await i.response.edit_message(embed=discord.Embed(title=titulo, color=color), view=self)
        return callback

    def _check_winner(self):
        wins = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]
        for a,b,c in wins:
            if self.tablero[a] != "⬜" and self.tablero[a]==self.tablero[b]==self.tablero[c]:
                return self.tablero[a]
        return None


@bot.command(aliases=["ttt","tic"])
async def tateti(ctx, rival: discord.Member = None):
    """Juega Ta-Te-Ti contra otro usuario.
    Uso: l!tateti @usuario"""
