@bot.command(aliases=["birthday","bd"])
async def cumple(ctx, fecha: str = None):
    """Registra tu cumpleaños para que el bot te felicite.
    Uso: l!cumple <DD/MM>
    Ej: l!cumple 15/03"""
    datos = cargar_datos()
    uid = str(ctx.author.id)
    if not fecha:
        # Ver cumpleaños registrado
        bd = datos.get("usuarios", {}).get(uid, {}).get("cumple")
        if bd:
            await ctx.send(embed=discord.Embed(description=f"🎂 Tu cumpleaños está registrado: **{bd}**", color=discord.Color(COLOR_PRIMARIO)))
        else:
            await ctx.send(embed=discord.Embed(description="No tenés cumpleaños registrado.\nUsá `l!cumple DD/MM` para registrarlo.", color=discord.Color(COLOR_INFO)))
        return
    import re as _re
    if not _re.match(r"^(0?[1-9]|[12][0-9]|3[01])/(0?[1-9]|1[0-2])$", fecha):
        await ctx.send(embed=discord.Embed(description="❌ Formato inválido. Usá `DD/MM` Ej: `15/03`", color=discord.Color(COLOR_PELIGRO))); return
    update_usuario(int(uid), "cumple", fecha)
    await ctx.send(embed=discord.Embed(
        title="🎂 Cumpleaños registrado",
        description=f"Registré tu cumpleaños: **{fecha}**\nTe voy a felicitar ese día en el servidor.",
        color=discord.Color(COLOR_EXITO)
    ))


@bot.command()
async def cumples(ctx):
    """Ver los próximos cumpleaños del servidor."""
    datos = cargar_datos()
    import datetime as _dt
    hoy = _dt.date.today()
    proximos = []
    for uid_str, udata in datos.get("usuarios", {}).items():
        bd = udata.get("cumple")
        if not bd: continue
        try:
            dia, mes = map(int, bd.split("/"))
            member = ctx.guild.get_member(int(uid_str))
            if not member: continue
            fecha_este_anio = _dt.date(hoy.year, mes, dia)
            if fecha_este_anio < hoy:
                fecha_este_anio = _dt.date(hoy.year + 1, mes, dia)
            dias_faltan = (fecha_este_anio - hoy).days
            proximos.append((dias_faltan, member.display_name, bd))
        except: continue
    if not proximos:
        await ctx.send(embed=discord.Embed(description="No hay cumpleaños registrados en este servidor.", color=discord.Color(COLOR_INFO))); return
    proximos.sort()
    embed = discord.Embed(title=f"🎂 Próximos cumpleaños - {ctx.guild.name}", color=discord.Color(COLOR_PRIMARIO))
    for dias, nombre, fecha in proximos[:10]:
        txt = "¡HOY! 🎉" if dias == 0 else (f"mañana 🎁" if dias == 1 else f"en {dias} días")
        embed.add_field(name=f"🎂 {nombre}", value=f"{fecha} - {txt}", inline=True)
    await ctx.send(embed=embed)


