# RECORDATORIO - l!recordatorio
# ==============================================================================

@bot.command(aliases=["remind","rem"])
async def recordatorio(ctx, tiempo: str = None, *, mensaje: str = "Sin mensaje"):
    """Te manda un DM con un recordatorio después del tiempo especificado.
    Uso: l!recordatorio <tiempo> <mensaje>
    Tiempo: 10s, 5m, 2h, 1d
    Ej: l!recordatorio 30m Revisar el horno"""
    if not tiempo:
        await ctx.send(embed=discord.Embed(description="**Uso:** `l!recordatorio <tiempo> <mensaje>`\nEj: `l!recordatorio 30m Revisar el horno`", color=discord.Color(COLOR_INFO))); return
    import re as _re
    match = _re.match(r"^(\\d+)([smhd])$", tiempo.lower())
    if not match:
        await ctx.send(embed=discord.Embed(description="❌ Formato de tiempo inválido.\nUsar: `10s`, `5m`, `2h`, `1d`", color=discord.Color(COLOR_PELIGRO))); return
    valor, unidad = int(match.group(1)), match.group(2)
    mult = {"s":1,"m":60,"h":3600,"d":86400}
    segundos = valor * mult[unidad]
    if segundos > 604800:  # max 7 días
        await ctx.send(embed=discord.Embed(description="❌ Máximo 7 días.", color=discord.Color(COLOR_PELIGRO))); return
    nombres = {"s":"segundo(s)","m":"minuto(s)","h":"hora(s)","d":"día(s)"}
    await ctx.send(embed=discord.Embed(
        description=f"⏰ Te voy a recordar en **{valor} {nombres[unidad]}**: `{mensaje[:100]}`",
        color=discord.Color(COLOR_EXITO)
    ), delete_after=10)
    async def _remind():
        await asyncio.sleep(segundos)
        try:
            embed_dm = discord.Embed(
                title="⏰ Recordatorio",
                description=mensaje,
                color=discord.Color(COLOR_PRIMARIO),
                timestamp=datetime.datetime.now(datetime.timezone.utc)
            )
            embed_dm.set_footer(text=f"Pedido en {ctx.guild.name} | #{ctx.channel.name}")
            await ctx.author.send(embed=embed_dm)
        except:
            try:
                await ctx.channel.send(f"⏰ {ctx.author.mention} - Recordatorio: {mensaje}", delete_after=30)
            except: pass
    asyncio.create_task(_remind())


