# ==============================================================================
# HORA - l!hora
# ==============================================================================

@bot.command()
async def hora(ctx, *, ciudad: str = None):
    """Muestra la hora actual en cualquier ciudad del mundo.
    Uso: l!hora <ciudad>
    Ej: l!hora Tokyo"""
    if not ciudad:
        await ctx.send(embed=discord.Embed(description="**Uso:** `l!hora <ciudad>`\nEj: `l!hora Tokyo`", color=discord.Color(COLOR_INFO))); return
    async with ctx.typing():
        try:
            import urllib.parse as _up
            url = f"https://worldtimeapi.org/api/timezone"
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as resp:
                    zonas = await resp.json()
            # Buscar zona que coincida
            ciudad_lower = ciudad.lower().replace(" ", "_")
            zona = next((z for z in zonas if ciudad_lower in z.lower()), None)
            if not zona:
                # Fallback: buscar por abreviatura
                zona = next((z for z in zonas if ciudad.split()[-1].lower() in z.lower()), None)
            if not zona:
                await ctx.send(embed=discord.Embed(description=f"❌ No encontré la zona horaria para `{ciudad}`.\nProbá con el nombre en inglés.", color=discord.Color(COLOR_PELIGRO))); return
            async with aiohttp.ClientSession() as session:
                async with session.get(f"https://worldtimeapi.org/api/timezone/{zona}") as resp:
                    data = await resp.json()
            dt_str = data.get("datetime","")[:19]
            tz_abbr = data.get("abbreviation","")
            offset = data.get("utc_offset","")
            embed = discord.Embed(
                title=f"🕐 Hora en {zona.replace('_',' ')}",
                description=f"**{dt_str.replace('T',' ')}** {tz_abbr}",
                color=discord.Color(COLOR_PRIMARIO)
            )
            embed.add_field(name="Zona", value=zona, inline=True)
            embed.add_field(name="UTC offset", value=offset, inline=True)
            embed.set_footer(text="LatamBOT | Hora mundial")
            await ctx.send(embed=embed)
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: `{e}`", color=discord.Color(COLOR_PELIGRO)))


