# CRYPTO - l!crypto (CoinGecko, gratis)
# ==============================================================================

@bot.command(aliases=["cripto","precio"])
async def crypto(ctx, moneda: str = "bitcoin"):
    """Precio de criptomonedas en tiempo real.
    Uso: l!crypto <moneda>
    Ej: l!crypto bitcoin | l!crypto ethereum | l!crypto solana"""
    async with ctx.typing():
        try:
            url = f"https://api.coingecko.com/api/v3/coins/{moneda.lower()}?localization=false&tickers=false&community_data=false&developer_data=false"
            async with aiohttp.ClientSession() as session:
                async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as resp:
                    if resp.status == 404:
                        # Buscar por símbolo
                        search_url = f"https://api.coingecko.com/api/v3/search?query={moneda}"
                        async with session.get(search_url) as sresp:
                            sdata = await sresp.json()
                        coins = sdata.get("coins", [])
                        if coins:
                            moneda = coins[0]["id"]
                            async with session.get(f"https://api.coingecko.com/api/v3/coins/{moneda}?localization=false&tickers=false&community_data=false&developer_data=false") as resp2:
                                data = await resp2.json()
                        else:
                            await ctx.send(embed=discord.Embed(description=f"❌ Moneda `{moneda}` no encontrada.", color=discord.Color(COLOR_PELIGRO))); return
                    else:
                        data = await resp.json()
            mkt = data["market_data"]
            precio = mkt["current_price"]["usd"]
            cambio24h = mkt["price_change_percentage_24h"] or 0
            cap = mkt["market_cap"]["usd"]
            vol = mkt["total_volume"]["usd"]
            high = mkt["high_24h"]["usd"]
            low = mkt["low_24h"]["usd"]
            nombre = data["name"]
            simbolo = data["symbol"].upper()
            icono = "📈" if cambio24h >= 0 else "📉"
            color = discord.Color.green() if cambio24h >= 0 else discord.Color.red()
            embed = discord.Embed(title=f"{icono} {nombre} ({simbolo})", color=color)
            embed.add_field(name="💵 Precio", value=f"**${precio:,.4f}**", inline=True)
            embed.add_field(name="24h", value=f"{'▲' if cambio24h>=0 else '▼'} **{cambio24h:.2f}%**", inline=True)
            embed.add_field(name="🏔️ Máx 24h", value=f"${high:,.4f}", inline=True)
            embed.add_field(name="🏔️ Mín 24h", value=f"${low:,.4f}", inline=True)
            embed.add_field(name="📊 Market Cap", value=f"${cap:,.0f}", inline=True)
            embed.add_field(name="💹 Volumen 24h", value=f"${vol:,.0f}", inline=True)
            embed.set_footer(text="LatamBOT | Crypto")
            if data.get("image",{}).get("small"):
                embed.set_thumbnail(url=data["image"]["small"])
            await ctx.send(embed=embed)
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: `{e}`", color=discord.Color(COLOR_PELIGRO)))


