async def _ia_rapida(prompt: str, max_tokens: int = 300) -> str:
    """Helper para llamadas rápidas a la IA sin historial."""
    if _ai_provider() == AI_PROVIDER_GROQ and not client_groq:
        return "IA no disponible."
    try:
        if _openrouter_available():
            data = await _openrouter_chat_completion(
                [{"role": "user", "content": prompt}],
                MODELO_OPENROUTER_FLASH,
                temperature=0.9,
                max_tokens=max_tokens,
            )
            return _extract_openrouter_text(data).strip()
        r = client_groq.chat.completions.create(
            messages=[{"role":"user","content":prompt}],
            model="groq/compound",
            temperature=0.9,
            max_tokens=max_tokens,
        )
        return r.choices[0].message.content.strip()
    except Exception as e:
        if _ai_provider() == AI_PROVIDER_OPENROUTER:
            await _switch_to_groq_fallback(str(e))
        return f"Error IA: {e}"


