# HIGHLIGHT - l!highlight (guardar mensajes con ⭐)
# ==============================================================================

@bot.command(aliases=["hl","star"])
async def highlight(ctx):
    """Guarda el mensaje al que respondés en el canal de highlights.
    Respondé a un mensaje y usá l!highlight para guardarlo."""
    if not ctx.message.reference:
        await ctx.send(embed=discord.Embed(description="❌ Respondé a un mensaje para guardarlo como highlight.", color=discord.Color(COLOR_PELIGRO))); return
    cfg = get_config(ctx.guild.id)
    canal_hl_id = cfg.get("canal_highlights") if cfg else None
    if not canal_hl_id:
        await ctx.send(embed=discord.Embed(description="❌ No hay canal de highlights configurado.\nUsá `l!setup` → Canales para configurarlo.", color=discord.Color(COLOR_PELIGRO))); return
    canal_hl = ctx.guild.get_channel(canal_hl_id)
    if not canal_hl:
        await ctx.send(embed=discord.Embed(description="❌ Canal de highlights no encontrado.", color=discord.Color(COLOR_PELIGRO))); return
    try:
        ref_msg = ctx.message.reference.cached_message or await ctx.channel.fetch_message(ctx.message.reference.message_id)
    except:
        await ctx.send(embed=discord.Embed(description="❌ No pude obtener el mensaje.", color=discord.Color(COLOR_PELIGRO))); return
    embed = discord.Embed(
        description=ref_msg.content or "*(sin texto)*",
        color=discord.Color.gold(),
        timestamp=ref_msg.created_at
    )
    embed.set_author(name=ref_msg.author.display_name, icon_url=ref_msg.author.display_avatar.url)
    if ref_msg.attachments:
        img = next((a for a in ref_msg.attachments if (a.content_type or "").startswith("image/")), None)
        if img:
            embed.set_image(url=img.url)
    embed.add_field(name="Canal", value=ref_msg.channel.mention, inline=True)
    embed.add_field(name="Guardado por", value=ctx.author.mention, inline=True)
    embed.add_field(name="Ir al mensaje", value=f"[Click aquí]({ref_msg.jump_url})", inline=True)
    embed.set_footer(text="⭐ Highlight | LatamBOT")
    await canal_hl.send(embed=embed)
    await ctx.send(embed=discord.Embed(description=f"⭐ Guardado en {canal_hl.mention}!", color=discord.Color.gold()), delete_after=5)
    try:
        await ctx.message.delete()
    except:
        pass


