# ==============================================================================
# IMAGEN CREATIVA (Pillow) - l!wanted, l!banner
# ==============================================================================

@bot.command()
async def wanted(ctx, usuario: discord.Member = None):
    """Genera un póster de 'Se Busca' con el avatar de un usuario."""
    target = usuario or ctx.author
    async with ctx.typing():
        try:
            from PIL import Image as _Im, ImageDraw as _Id, ImageFont as _If
            import io as _io
            # Descargar avatar
            async with aiohttp.ClientSession() as session:
                async with session.get(str(target.display_avatar.replace(size=256, format="png"))) as resp:
                    av_bytes = await resp.read()
            av_img = _Im.open(_io.BytesIO(av_bytes)).convert("RGBA").resize((300,300))
            # Crear cartel
            w, h = 400, 550
            cartel = _Im.new("RGB", (w, h), color=(210, 180, 140))
            draw = _Id.Draw(cartel)
            # Borde
            draw.rectangle([8,8,w-8,h-8], outline=(101,67,33), width=6)
            draw.rectangle([18,18,w-18,h-18], outline=(101,67,33), width=3)
            # Texto WANTED
            try:
                font_big = _If.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 52)
                font_med = _If.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", 24)
                font_sm  = _If.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf", 18)
            except:
                font_big = font_med = font_sm = _If.load_default()
            draw.text((w//2, 50), "SE BUSCA", fill=(101,67,33), font=font_big, anchor="mm")
            draw.text((w//2, 82), "DEAD OR ALIVE", fill=(139,0,0), font=font_sm, anchor="mm")
            # Avatar
            cartel.paste(av_img, (50, 100), av_img if av_img.mode=="RGBA" else None)
            # Nombre
            draw.text((w//2, 430), target.display_name[:20], fill=(101,67,33), font=font_med, anchor="mm")
            # Recompensa
            draw.text((w//2, 470), "RECOMPENSA", fill=(101,67,33), font=font_sm, anchor="mm")
            draw.text((w//2, 500), "$100,000", fill=(139,0,0), font=font_med, anchor="mm")
            buf = _io.BytesIO()
            cartel.save(buf, format="PNG")
            buf.seek(0)
            await ctx.send(file=discord.File(buf, filename="wanted.png"))
        except ImportError:
            await ctx.send(embed=discord.Embed(description="❌ Pillow no disponible.", color=discord.Color(COLOR_PELIGRO)))
        except Exception as e:
            await ctx.send(embed=discord.Embed(description=f"❌ Error: `{e}`", color=discord.Color(COLOR_PELIGRO)))


