@bot.command(aliases=["bl"])
@commands.check(lambda ctx: ctx.author.id == OWNER_ID)
async def blacklist(ctx, accion: str = None, usuario: discord.User = None, *, razon: str = "Sin razón"):
    """[OWNER] Gestiona la blacklist del bot.
    Uso:
      l!blacklist add @usuario [razon]
      l!blacklist add <id> [razon]
      l!blacklist remove @usuario
      l!blacklist list
    También: respondé a un mensaje con l!blacklist add"""
    if not accion:
        await ctx.send(embed=discord.Embed(
            description="**Uso:** `l!blacklist add/remove/list @usuario [razon]`",
            color=discord.Color(COLOR_INFO)
        ))
        return

    accion = accion.lower()

    if accion == "list":
        if not bot_blacklist:
            await ctx.send(embed=discord.Embed(description="La blacklist está vacía.", color=discord.Color(COLOR_INFO)))
            return
        desc = ""
        for uid, datos in list(bot_blacklist.items())[:20]:
            user = bot.get_user(uid)
            nombre = str(user) if user else f"ID: {uid}"
            desc += f"• **{nombre}** - {datos.get('razon','Sin razon')} *(por {datos.get('por','?')})*\n"
        embed = discord.Embed(title=f"🚫 Blacklist ({len(bot_blacklist)} usuarios)", description=desc, color=discord.Color.red())
        await ctx.send(embed=embed)
        return

    # Resolver usuario - desde mención, ID, o reply
    target = usuario
    if not target and ctx.message.reference:
        try:
            ref = ctx.message.reference.cached_message or await ctx.channel.fetch_message(ctx.message.reference.message_id)
            target = ref.author
        except:
            pass
    if not target and razon:
        # Intentar parsear ID del primer token de razon
        tokens = razon.split()
        try:
            target = await bot.fetch_user(int(tokens[0]))
            razon = " ".join(tokens[1:]) or "Sin razón"
        except:
            pass
    if not target:
        await ctx.send(embed=discord.Embed(description="❌ No encontré el usuario. Mencionalo, pasá su ID, o respondé a su mensaje.", color=discord.Color(COLOR_PELIGRO)))
        return

    if accion == "add":
        if target.id == OWNER_ID:
            await ctx.send(embed=discord.Embed(description="❌ No podés bloquear al owner.", color=discord.Color(COLOR_PELIGRO)))
            return
        bot_blacklist[target.id] = {
            "razon": razon,
            "por": str(ctx.author),
            "fecha": datetime.datetime.now().strftime("%d/%m/%Y %H:%M"),
        }
        _save_runtime_state()
        embed = discord.Embed(
            title="🚫 Usuario bloqueado",
            color=discord.Color.red(),
            timestamp=datetime.datetime.now(datetime.timezone.utc)
        )
        embed.add_field(name="Usuario", value=f"{target} (`{target.id}`)", inline=True)
        embed.add_field(name="Por", value=str(ctx.author), inline=True)
        embed.add_field(name="Razón", value=razon, inline=False)
        embed.set_thumbnail(url=target.display_avatar.url)
        await ctx.send(embed=embed)
        # Intentar DM al usuario
        try:
            await target.send(embed=discord.Embed(
                title="🚫 Acceso restringido",
                description="Tu acceso a LatamBOT ha sido restringido.",
                color=discord.Color.red()
            ))
        except:
            pass

    elif accion in ("remove", "del", "rm"):
        if target.id not in bot_blacklist:
            await ctx.send(embed=discord.Embed(description=f"**{target}** no está en la blacklist.", color=discord.Color(COLOR_ADVERTENCIA)))
            return
        del bot_blacklist[target.id]
        _save_runtime_state()
        embed = discord.Embed(
            title="✅ Usuario desbloqueado",
            description=f"**{target}** fue removido de la blacklist.",
            color=discord.Color.green()
        )
        await ctx.send(embed=embed)
        try:
            await target.send(embed=discord.Embed(
                title="✅ Acceso restaurado",
                description="Tu acceso a LatamBOT fue restaurado.",
                color=discord.Color.green()
            ))
        except:
            pass
    else:
        await ctx.send(embed=discord.Embed(description="❌ Acción inválida. Usá `add`, `remove` o `list`.", color=discord.Color(COLOR_PELIGRO)))


