# MODO MOLESTO - corrige mensajes aunque estén bien
# ==============================================================================

# { guild_id: bool }
_modo_molesto_activo: Dict[int, bool] = {}

CORRECCIONES_MOLESTAS = [
    ("hola", ["Técnicamente debería ser 'salutaciones', ¿no?", "¿'Hola'? Creo que quisiste decir 'buenos días/tardes/noches' dependiendo la zona horaria.", "Mmm... 'hola' tiene solo 4 letras. ¿Seguro no te faltó una?"]),
    ("jaja", ["La risa se escribe 'ja ja', con espacio.", "Técnicamente 'jaja' no es una palabra reconocida por la RAE.", "'jaja' o 'jeje'? Hay que elegir uno y ser consistente."]),
    ("ok", ["*'OK'* es un anglicismo, deberías decir 'de acuerdo' o 'entendido'.", "¿'ok'? Se escribe 'okey' según la RAE.", "Mmm, 'ok' es técnicamente informal. ¿No querías decir 'conforme'?"]),
    ("bye", ["'Bye' es inglés, ¿no ibas a hablar en español?", "La despedida correcta sería 'adiós' o 'hasta luego'.", "'bye' con b minúscula parece un error tipográfico."]),
    ("pq", ["Creo que quisiste escribir 'porque' o 'por qué'.", "¿'pq'? No logro encontrar esa palabra en el diccionario.", "Abreviación detectada. Por favor usar la palabra completa."]),
    ("q", ["¿'q'? ¿Quisiste decir 'que'?", "La letra sola no es suficiente para comunicarse correctamente.", "Mmm, la 'q' sola no tiene significado gramatical."]),
    ("xd", ["'xd' no es una emoción reconocida.", "'XD' va en mayúsculas si es acrónimo.", "Creo que quisiste expresar alegría, pero 'xd' es ambiguo."]),
    ("si", ["¿'si' o 'sí'? El acento cambia todo el significado.", "'si' sin tilde es conjunción condicional. ¿Seguro no quisiste decir 'sí'?", "Hmm, falta el tilde para afirmar correctamente."]),
    ("no se", ["¿'no se' o 'no sé'? El acento en 'sé' es importante.", "'no se' sin tilde indica reflexividad, no ignorancia.", "Si querés expresar ignorancia, necesitás el tilde: 'no sé'."]),
    ("k", ["¿'k'? Eso no es una palabra...", "La letra 'k' sola no tiene definición en español.", "Creo que te saltaste algunas letras ahí."]),
    ("ta bien", ["¿'ta bien'? ¿No quisiste decir 'está bien'?", "Parece que te comiste las primeras letras.", "'ta' no es una contracción aceptada formalmente."]),
    ("bn", ["'bn' no es una abreviatura estándar.", "¿'bn'? Quizás quisiste decir 'bien'.", "Hmm, faltan 2 letras para completar 'bien'."]),
    ("porfa", ["La forma correcta es 'por favor'.", "¿'porfa'? Eso es muy informal.", "'porfa' técnicamente no existe en el diccionario."]),
    ("tmb", ["¿'tmb'? Quizás quisiste escribir 'también'.", "Abreviación no reconocida detectada: 'tmb'.", "'tmb' le faltan 5 letras para ser 'también'."]),
    ("re", ["¿'re' como prefijo intensificador? Eso es muy rioplatense.", "Hmm, 're' solo es un prefijo, no debería usarse como intensificador independiente.", "'re bueno' vs 'muy bueno' - hay diferencias estilísticas importantes."]),
]

async def _aplicar_modo_molesto(msg: discord.Message):
    """Si el modo molesto está activo, corrige aleatoriamente el mensaje."""
    if not _modo_molesto_activo.get(msg.guild.id):
        return
    if msg.author.bot or not msg.content or msg.content.startswith(("l!", "/")):
        return

    contenido = msg.content.lower()
    posibles = []
    for palabra, correcciones in CORRECCIONES_MOLESTAS:
        if palabra in contenido.split() or f" {palabra} " in f" {contenido} " or contenido.strip() == palabra:
            posibles.extend(correcciones)

    # Si no encontró nada específico, usar corrección genérica con probabilidad
    if not posibles:
        if random.random() < 0.25:  # 25% de probabilidad para mensajes sin trigger
            posibles = [
                "Hmm, eso podría estar mejor redactado.",
                "¿Estás seguro de la ortografía de ese mensaje?",
                "Técnicamente eso no está del todo correcto gramaticalmente.",
                "Interesante forma de expresarlo... aunque no es la más correcta.",
                "La puntuación de ese mensaje deja mucho que desear.",
                "¿Revisaste el mensaje antes de enviarlo?",
                "Mmm, yo lo hubiese escrito diferente.",
                "Falta un punto al final de esa oración.",
                "Eso suena a frase incompleta.",
                "¿'{}' es una palabra? No estoy seguro.".format(msg.content.split()[0] if msg.content.split() else "eso"),
            ]
        else:
            return

    correccion = random.choice(posibles)
    try:
        await msg.reply(f"📝 {correccion}", mention_author=False, delete_after=15)
    except:
        pass


