def _label_from_pair_list(value: str, options: list[tuple[str, str]], default: str) -> str:
    for label, code in options:
        if code == value:
            return label
    return default


def _next_pair_value(current: str, options: list[tuple[str, str]], default: str) -> str:
    values = [code for _, code in options]
    current = current if current in values else default
    idx = values.index(current)
    return values[(idx + 1) % len(values)]


def _get_serpapi_user_settings(user_id: int, guild_id: Optional[int] = None) -> Dict[str, str]:
    prefs = user_prefs.get(user_id, {})
    hl = prefs.get("serp_hl", "es")
    gl = prefs.get("serp_gl", "ar")
    cfg = get_config(guild_id) if guild_id else None
    safe = "off" if (cfg or {}).get("sistema_nsfw") else "active"
    return {"hl": hl, "gl": gl, "safe": safe}



def _mention_texto_vacio(msg) -> bool:
    """True si la mencion/reply al bot no trae texto util (solo @bot o vacio)."""
    p = msg.content or ""
    if bot.user:
        p = p.replace(f"<@{bot.user.id}>", "").replace(f"<@!{bot.user.id}>", "")
    p = re.sub(r"<@!?\d+>", "", p)
    p = re.sub(r"<a?:\w+:\d+>", "", p)
    p = re.sub(r"\s+", " ", p).strip()
    return not p


async def _fetch_msg_ref(msg):
    if not msg.reference or not msg.reference.message_id:
        return None
    if isinstance(getattr(msg.reference, "resolved", None), discord.Message):
        return msg.reference.resolved
    try:
        return await msg.channel.fetch_message(msg.reference.message_id)
    except Exception:
        return None


async def _handle_ia_mencion(msg, es_reply_al_bot: bool = False):
    """Flujo de IA por mencion (antes iba inline en on_message)."""
    if _ai_provider() == AI_PROVIDER_OPENROUTER and _get_user_ai_model_choice(msg.author.id) is None:
        embed = _make_embed(
            "Elige modelo de IA",
            (
                "Esta actualizacion agrega dos modelos. Solo te lo pregunto una vez.\n\n"
                f"**Grok 4.3** (`{MODELO_OPENROUTER_PREMIUM}`): gasta **x2** de IA diaria.\n"
                f"**DeepSeek V4 Flash** (`{MODELO_OPENROUTER_FLASH}`): gasta **x1** de IA diaria.\n\n"
                f"Despues podes cambiarlo con `{_prefijo_guild(msg.guild)}configuracion`."
            ),
            COLOR_INFO,
        )
        await msg.reply(embed=embed, view=AIModelChoiceView(msg.author.id), mention_author=False)
        return
    ahora = time.time()
    if ahora - ia_rate_limit.get(msg.channel.id, 0) < IA_COOLDOWN:
        await msg.add_reaction("⏳")
        return
    ia_rate_limit[msg.channel.id] = ahora
    await intentar_escribir(msg.channel)
    limpiar_memoria_contexto()

    ctx_key = (msg.channel.id, msg.author.id)
    if ctx_key not in memoria_contexto:
        memoria_contexto[ctx_key] = []

    p = msg.content or ""
    if bot.user:
        p = p.replace(f"<@{bot.user.id}>", "").replace(f"<@!{bot.user.id}>", "").strip()
    mentioned_users = [u for u in msg.mentions if bot.user is None or u.id != bot.user.id]
    p = re.sub(r"<@!?\d+>", "", p).strip() or "hola"
    p = _sanitize_ai_prompt_text(p)
    p = _append_user_context(p, mentioned_users)
    rechazo = _detect_bad_ai_request(p)
    if rechazo:
        await msg.reply(
            embed=discord.Embed(
                title="Pedido rechazado",
                description=rechazo,
                color=discord.Color(COLOR_ADVERTENCIA),
            ),
            mention_author=False,
        )
        return

    limite = get_limites(msg.author.id)[0]
    ai_choice = _get_user_ai_model_choice(msg.author.id) or "flash"
    ai_cost = _ai_daily_cost_for_choice(ai_choice) if _ai_provider() == AI_PROVIDER_OPENROUTER else 1
    usos, _restantes = _daily_limit_state(ask_usos_diarios, msg.author.id, limite)
    if usos + ai_cost > limite:
        await msg.reply(embed=_build_ai_limit_embed(msg.author.id, usos, limite), mention_author=False)
        return

    emojis_custom = re.findall(r"<a?:(\w+):\d+>", msg.content or "")
    if emojis_custom:
        p = _sanitize_ai_prompt_text(f"{p} [usa los emojis: {', '.join(emojis_custom)}]")

    reply_context = ""
    if msg.reference:
        ref_msg = msg.reference.cached_message
        if ref_msg is None:
            try:
                ref_msg = await msg.channel.fetch_message(msg.reference.message_id)
            except Exception:
                ref_msg = None
        if ref_msg and bot.user and ref_msg.author.id == bot.user.id:
            if ref_msg.embeds:
                reply_context = ref_msg.embeds[0].description or ""
            elif ref_msg.content:
                reply_context = ref_msg.content.split("\n\n-# Comprame")[0].strip()

    imagen_url = _extraer_imagen_de_mensaje(msg)
    if not imagen_url and msg.reference:
        ref_msg2 = msg.reference.cached_message
        if ref_msg2:
            imagen_url = _extraer_imagen_de_mensaje(ref_msg2)

    prompt_usuario = p
    if reply_context:
        prompt_usuario = (
            "Mensaje anterior del bot:\n"
            f"{_clip_text(reply_context, 900)}\n\n"
            "Nueva consulta del usuario:\n"
            f"{p}"
        )
    historial_ia = _build_ai_messages(ctx_key, prompt_usuario, reply_to_bot=es_reply_al_bot, reply_context="")
    usos = _daily_limit_consume(ask_usos_diarios, msg.author.id, ai_cost)
    restantes = max(limite - usos, 0)

    wiki = None
    if not imagen_url:
        try:
            wiki = await _wiki_lookup(p) if _wiki_should_lookup(p) else None
        except Exception as e:
            log.warning("wiki mention: %s", e)
            wiki = None

    status_msg = await msg.reply(
        embed=discord.Embed(
            description="Generando respuesta...",
            color=discord.Color(COLOR_INFO),
            timestamp=datetime.datetime.now(datetime.timezone.utc),
        ),
        mention_author=False,
    )
    res = await generar_respuesta_groq(
        msg.guild.id,
        historial_ia,
        imagen_url=imagen_url,
        sistema_extra=AI_TASK_PROMPTS["ask"] + (_wiki_sistema_extra(wiki) if wiki else ""),
        user_id_ctx=msg.author.id,
    )
    if wiki and wiki.get("title") and res and not str(res).startswith("-#"):
        res = f"-# 📚 {wiki['title']}\n{res}"
    _remember_ai_exchange(ctx_key, prompt_usuario, res)
    respuesta_final = f"{res}\n\n-# Quedan {restantes}/{limite} usos de IA hoy. Costo: x{ai_cost}."
    embed_resp = discord.Embed(description=respuesta_final, color=discord.Color.blurple())
    embed_resp.set_footer(text="LatamBOT | https://ko-fi.com/latambot")
    feedback_view = AIOpinionView(guild_id=msg.guild.id, user_id=msg.author.id, question=p, answer=res, source="mention")
    await status_msg.edit(embed=embed_resp, view=feedback_view)


def _prefijo_guild(guild) -> str:
    try:
        if guild:
            return prefixes_servidores.get(guild.id) or "l!"
    except Exception:
        pass
    return "l!"


class MentionActionView(discord.ui.View):
    """Menu cuando mencionan al bot sin texto: IA / Quote / Resumir / Traducir / Ayuda."""

    def __init__(self, source_msg: discord.Message):
        super().__init__(timeout=90)
        self.user_id = source_msg.author.id
        self.channel_id = source_msg.channel.id
        self.message_id = source_msg.id
        self.guild_id = source_msg.guild.id if source_msg.guild else None

    async def interaction_check(self, i: discord.Interaction) -> bool:
        if i.user.id != self.user_id:
            await i.response.send_message("Este menu es para quien menciono al bot.", ephemeral=True)
            return False
        return True

    async def _source(self, i: discord.Interaction):
        ch = i.channel
        try:
            return await ch.fetch_message(self.message_id)
        except Exception:
            return None

    async def _close_menu(self, i: discord.Interaction, texto: str):
        try:
            await i.response.edit_message(
                embed=discord.Embed(description=texto, color=discord.Color(COLOR_INFO)),
                view=None,
            )
        except Exception:
            try:
                await i.response.defer()
            except Exception:
                pass

    @discord.ui.button(label="IA", style=discord.ButtonStyle.primary, emoji="🤖", row=0)
    async def btn_ia(self, i: discord.Interaction, _b: discord.ui.Button):
        await self._close_menu(i, "Ok, te respondo con IA...")
        msg = await self._source(i)
        if not msg:
            await i.followup.send("No encontre el mensaje original.", ephemeral=True)
            return
        # Simular texto para que la IA tenga algo que contestar
        if _mention_texto_vacio(msg):
            msg.content = (msg.content or "") + " hola"
        es_reply = bool(
            msg.reference
            and bot.user
            and (
                (msg.reference.cached_message and msg.reference.cached_message.author.id == bot.user.id)
                or False
            )
        )
        await _handle_ia_mencion(msg, es_reply)

    @discord.ui.button(label="Quote", style=discord.ButtonStyle.secondary, emoji="💬", row=0)
    async def btn_quote(self, i: discord.Interaction, _b: discord.ui.Button):
        await i.response.defer()
        msg = await self._source(i)
        if not msg:
            await i.followup.send("No encontre el mensaje original.", ephemeral=True)
            return
        try:
            await i.message.edit(view=None)
        except Exception:
            pass
        ref = await _fetch_msg_ref(msg)
        contenido = display_name = username = avatar_url = None
        if ref is not None:
            contenido = _limpiar_texto_quote(ref.content, msg.guild)
            display_name = ref.author.display_name
            username = ref.author.name
            avatar_url = str(ref.author.display_avatar.with_size(512).url)
        if contenido is None:
            hist = list(snipe_history.get(msg.channel.id, []))
            if not hist:
                await i.followup.send(
                    embed=_make_embed(
                        "Nada para citar",
                        "Responde a un mensaje y mencioname, o usa `l!quote` sobre un snipe.",
                        COLOR_INFO,
                    ),
                    ephemeral=True,
                )
                return
            data = hist[0]
            contenido = _limpiar_texto_quote(data.get("content", ""), msg.guild)
            mem = msg.guild.get_member(data.get("author_id")) if data.get("author_id") else None
            display_name = mem.display_name if mem else str(data.get("author", "Alguien")).split("#")[0]
            username = mem.name if mem else str(data.get("author", "alguien"))
            avatar_url = data.get("author_avatar")
        if not (contenido or "").strip():
            await i.followup.send("Ese mensaje no tiene texto para citar.", ephemeral=True)
            return
        try:
            await _enviar_quote(i.followup.send, i.user.id, contenido, display_name, username, avatar_url, user=ref.author if ref is not None else None)
        except Exception as e:
            await i.followup.send(f"No pude generar la cita: {str(e)[:80]}", ephemeral=True)

    @discord.ui.button(label="Resumir", style=discord.ButtonStyle.secondary, emoji="📋", row=0)
    async def btn_resumir(self, i: discord.Interaction, _b: discord.ui.Button):
        await i.response.defer()
        msg = await self._source(i)
        if not msg:
            await i.followup.send("No encontre el mensaje original.", ephemeral=True)
            return
        try:
            await i.message.edit(view=None)
        except Exception:
            pass
        if not server_permitido(msg.guild.id):
            await i.followup.send("La IA no esta disponible en este servidor.", ephemeral=True)
            return
        ref = await _fetch_msg_ref(msg)
        if ref and (ref.content or "").strip():
            chat_texto = f"{ref.author.display_name}: {(ref.content or '')[:800]}"
            titulo = "Resumen del mensaje"
        else:
            msgs = []
            async for m in msg.channel.history(limit=25):
                if m.author.bot or not (m.content or "").strip():
                    continue
                msgs.append(f"{m.author.display_name}: {m.content[:220]}")
            msgs.reverse()
            if not msgs:
                await i.followup.send("No hay mensajes recientes para resumir.", ephemeral=True)
                return
            chat_texto = "\n".join(msgs[-20:])
            titulo = "Resumen del chat"
        prompt = (
            AI_TASK_PROMPTS["resumir"] + "\n\n"
            "Resume con panorama breve y puntos clave. No inventes.\n\n"
            f"{chat_texto}"
        )
        res = await generar_respuesta_groq(
            msg.guild.id,
            [{"role": "user", "content": prompt}],
            user_id_ctx=i.user.id,
        )
        if not res:
            await i.followup.send("No pude generar el resumen.", ephemeral=True)
            return
        emb = discord.Embed(
            title=f"📋 {titulo}",
            description=_clip_text(res, 4000),
            color=_ai_embed_color_for(i.user.id),
        )
        await i.followup.send(embed=emb)

    @discord.ui.button(label="Traducir", style=discord.ButtonStyle.secondary, emoji="🌐", row=1)
    async def btn_traducir(self, i: discord.Interaction, _b: discord.ui.Button):
        await i.response.defer()
        msg = await self._source(i)
        if not msg:
            await i.followup.send("No encontre el mensaje original.", ephemeral=True)
            return
        try:
            await i.message.edit(view=None)
        except Exception:
            pass
        if not server_permitido(msg.guild.id):
            await i.followup.send("La IA no esta disponible en este servidor.", ephemeral=True)
            return
        ref = await _fetch_msg_ref(msg)
        texto = (ref.content if ref else "") or ""
        if not texto.strip():
            await i.followup.send(
                "Responde a un mensaje y mencioname, o usa `l!traducir <idioma> <texto>`.",
                ephemeral=True,
            )
            return
        # Idioma destino: si el server esta en es, traducir a en; si no, a es
        lang_server = (get_config(msg.guild.id) or {}).get("idioma", "es") or "es"
        destino = "ingles" if lang_server == "es" else "español"
        prompt = _make_translation_prompt(destino, texto[:1800])
        res = await generar_respuesta_groq(
            msg.guild.id,
            [{"role": "user", "content": prompt}],
            user_id_ctx=i.user.id,
        )
        if not res:
            await i.followup.send("No pude traducir.", ephemeral=True)
            return
        emb = discord.Embed(
            title=f"🌐 Traducción ({destino})",
            description=_clip_text(res, 4000),
            color=_ai_embed_color_for(i.user.id),
        )
        await i.followup.send(embed=emb)

    @discord.ui.button(label="Ayuda", style=discord.ButtonStyle.secondary, emoji="❔", row=1)
    async def btn_ayuda(self, i: discord.Interaction, _b: discord.ui.Button):
        p = _prefijo_guild(i.guild)
        emb = discord.Embed(
            title="Ayuda rápida",
            description=(
                f"**Panel:** `{p}panel` · {PANEL_URL or 'configurá PANEL_URL'}\n"
                f"**Docs:** {DOCS_URL or 'configurá DOCS_URL'}\n"
                f"**IA:** mencioname con una pregunta, o `{p}ask`\n"
                f"**Quote:** responde un mensaje + `{p}quote`\n"
                f"**Empezar:** `{p}empezar` (config de un toque)\n"
                f"**Soporte:** https://discord.gg/XF6jtCjgyf"
            ),
            color=discord.Color(COLOR_PRIMARIO),
        )
        await i.response.edit_message(embed=emb, view=None)

    @discord.ui.button(label="Cancelar", style=discord.ButtonStyle.danger, row=1)
    async def btn_cancel(self, i: discord.Interaction, _b: discord.ui.Button):
        await self._close_menu(i, "Listo, cancelado.")


