class _ComandosSelect(discord.ui.Select):
    """Select para activar/desactivar comandos. Usa subclase para que self.values funcione."""
    def __init__(self, guild_id: int, pagina: int, opciones: list, total_pages: int):
        self.guild_id = guild_id
        self.pagina = pagina
        self.total_pages = total_pages
        super().__init__(
            placeholder=f"Toggle comandos (pag {pagina+1}/{total_pages})...",
            options=opciones,
            min_values=1,
            max_values=len(opciones),
            row=0
        )

    async def callback(self, i: discord.Interaction):
        cfg = get_config(self.guild_id) or {}
        desactivados = list(cfg.get("comandos_desactivados", []))
        for cmd in self.values:
            if cmd in desactivados:
                desactivados.remove(cmd)
            else:
                desactivados.append(cmd)
        update_server_config(self.guild_id, "comandos_desactivados", desactivados)
        estado_txt = "\n".join([
            f"{'❌ Desactivado' if c in desactivados else '✅ Activado'}: `{c}`"
            for c in self.values
        ])
        await i.response.send_message(
            embed=discord.Embed(
                title="Comandos Actualizados",
                description=estado_txt,
                color=discord.Color(COLOR_EXITO)
            ),
            ephemeral=True
        )


class ComandosActivarView(discord.ui.View):
    def __init__(self, guild_id: int, pagina: int = 0):
        super().__init__(timeout=None)
        self.guild_id = guild_id
        self.pagina = pagina
        cfg = get_config(guild_id) or {}
        desactivados = cfg.get("comandos_desactivados", [])

        items = list(COMANDOS_CONFIGURABLES.items())
        total_pages = max(1, (len(items) + 19) // 20)
        page_items = items[pagina * 20: pagina * 20 + 20]

        opciones = [
            discord.SelectOption(
                label=nombre,
                description=desc[:50],
                value=nombre,
                emoji="❌" if nombre in desactivados else "✅"
            )
            for nombre, desc in page_items
        ]
        if opciones:
            self.add_item(_ComandosSelect(guild_id, pagina, opciones, total_pages))

        if pagina > 0:
            btn_prev = discord.ui.Button(label="◀ Anterior", style=discord.ButtonStyle.secondary, row=1)
            async def _prev(i: discord.Interaction, _p=pagina-1):
                await i.response.edit_message(embed=_embed_comandos(self.guild_id), view=ComandosActivarView(self.guild_id, _p))
            btn_prev.callback = _prev
            self.add_item(btn_prev)

        if pagina < total_pages - 1:
            btn_next = discord.ui.Button(label="Siguiente ▶", style=discord.ButtonStyle.secondary, row=1)
            async def _next(i: discord.Interaction, _p=pagina+1):
                await i.response.edit_message(embed=_embed_comandos(self.guild_id), view=ComandosActivarView(self.guild_id, _p))
            btn_next.callback = _next
            self.add_item(btn_next)

    @discord.ui.button(label="⬅️ Volver", style=discord.ButtonStyle.secondary, row=2)
    async def volver(self, i: discord.Interaction, b):
        cfg = get_config(i.guild_id) or {}
        await i.response.edit_message(embed=_setup_embed_principal(cfg, i.guild), view=SetupMainView(owner_id=i.user.id))


def _embed_comandos(guild_id: int) -> discord.Embed:
    cfg = get_config(guild_id) or {}
    desactivados = cfg.get("comandos_desactivados", [])
    activos = sum(1 for c in COMANDOS_CONFIGURABLES if c not in desactivados)
    embed = discord.Embed(
        title=f"⚡ Comandos ({activos}/{len(COMANDOS_CONFIGURABLES)} activos)",
        description="Selecciona comandos para activar/desactivar en este servidor:",
        color=discord.Color(COLOR_INFO)
    )
    if desactivados:
        embed.add_field(name="Desactivados", value=" ".join(f"`{c}`" for c in desactivados[:20]), inline=False)
    return embed

# ==============================================================================
# SELECCION CON MENCIONES (canales y roles por mencion ademas de select)
# ==============================================================================

async def _pedir_canal_o_rol(ctx, tipo: str = "canal", timeout: float = 30.0):
    """Espera que el usuario mencione un canal/rol O escriba un ID. Retorna el objeto o None."""
    await ctx.send(
        embed=discord.Embed(
            description=f"Menciona el {tipo} (#{tipo} o @rol) o escribe su ID. Tienes {int(timeout)}s.",
            color=discord.Color(COLOR_INFO)
        ),
        delete_after=timeout
    )
    def check(m):
        return m.author == ctx.author and m.channel == ctx.channel

    try:
        msg = await bot.wait_for("message", check=check, timeout=timeout)
        try: await msg.delete()
        except: pass

        if tipo == "canal":
            if msg.channel_mentions:
                return msg.channel_mentions[0]
            if msg.content.strip().isdigit():
                ch = ctx.guild.get_channel(int(msg.content.strip()))
                return ch
        elif tipo == "rol":
            if msg.role_mentions:
                return msg.role_mentions[0]
            if msg.content.strip().isdigit():
                r = ctx.guild.get_role(int(msg.content.strip()))
                return r
            # Buscar por nombre
            r = discord.utils.find(lambda ro: ro.name.lower() == msg.content.strip().lower(), ctx.guild.roles)
            return r
    except asyncio.TimeoutError:
        return None
    return None


