@bot.command(name="debug")
async def debug_cmd(ctx):
    """[OWNER] Ejecuta diagnostico completo del bot."""
    if ctx.author.id != OWNER_ID:
        return

    msg = await ctx.author.send(embed=discord.Embed(description="Iniciando diagnostico...", color=discord.Color(COLOR_INFO)))
    resultados = []

    async def test(nombre: str, coro):
        try:
            resultado = await coro
            resultados.append(f"✅ **{nombre}:** {resultado}")
        except Exception as e:
            resultados.append(f"❌ **{nombre}:** {type(e).__name__}: {str(e)[:80]}")

    # Tests
    resultados.append("```")
    resultados.append(f"LatamBOT Debug Suite - {datetime.datetime.now().strftime('%d/%m/%Y %H:%M:%S')}")
    resultados.append("=" * 50)
    resultados.append("```")
    resultados.append(f"✅ **Modo debug:** {'activo' if LATAM_DEBUG else 'apagado'}")

    # 1. Conectividad
    lat = _bot_latency_ms()
    if lat < 0:
        resultados.append("⚠️ **Latencia WS:** n/d (sin heartbeat)")
    else:
        resultados.append(f"{'✅' if lat < 200 else '⚠️'} **Latencia WS:** {lat}ms")

    # 2. Base de datos
    try:
        datos = cargar_datos()
        servers = len(datos.get("servers", {}))
        usuarios = len(datos.get("usuarios", {}))
        sqlite_stats = get_sqlite_snapshot_stats(ARCHIVO_SQLITE)
        resultados.append(f"✅ **DB:** {servers} servers, {usuarios} usuarios | SQLite: {sqlite_stats['servers']} / {sqlite_stats['usuarios']} / {sqlite_stats['notas']}")
    except Exception as e:
        resultados.append(f"❌ **DB:** {e}")

    # 3. IA
    if _openrouter_available():
        try:
            await _openrouter_chat_completion(
                [{"role": "user", "content": "responde solo: ok"}],
                MODELO_OPENROUTER_FLASH,
                max_tokens=5,
                temperature=0,
            )
            resultados.append(f"✅ **OpenRouter:** ok ({MODELO_OPENROUTER_FLASH})")
        except Exception as e:
            resultados.append(f"❌ **OpenRouter:** {e}")
    elif client_groq:
        try:
            r = client_groq.chat.completions.create(
                messages=[{"role":"user","content":"responde solo: ok"}],
                model="groq/compound", max_tokens=5, temperature=0
            )
            resultados.append(f"✅ **Groq fallback:** ok ({MODELO_MODERACION})")
        except Exception as e:
            resultados.append(f"❌ **Groq fallback:** {e}")
    else:
        resultados.append("❌ **IA:** OpenRouter sin clave y Groq no inicializado")

    # 4. Servidores
    servidores_ok = sum(1 for g in bot.guilds if bot.get_guild(g.id))
    resultados.append(f"✅ **Servidores:** {servidores_ok}/{len(bot.guilds)} accesibles")

    # 5. Contextos de IA activos
    resultados.append(f"✅ **Contextos IA activos:** {len(memoria_contexto)}")

    # 6. Console buffer
    resultados.append(f"✅ **Console buffer:** {len(console_buffer)}/{CONSOLE_BUFFER_SIZE} lineas")

    # 7. Memoria IA
    resultados.append(f"✅ **Contextos IA en memoria:** {len(memoria_contexto)}")

    # 8. Sorteos activos
    resultados.append(f"✅ **Sorteos activos:** {len(sorteos_activos)}")

    # 9. Sticky messages
    resultados.append(f"✅ **Sticky messages:** {len(sticky_contenido)}")

    # 10. Tareas en loop
    tareas = [finalizar_sorteos]
    for t in tareas:
        try:
            estado = "corriendo" if t.is_running() else "DETENIDA"
            icon = "✅" if t.is_running() else "❌"
            resultados.append(f"{icon} **Task {t.coro.__name__}:** {estado}")
        except Exception as e:
            resultados.append(f"⚠️ **Task:** error al verificar - {e}")

    # 11. Permisos en server notif
    notif_guild = bot.get_guild(SERVER_NOTIF_ID)
    if notif_guild:
        canal_n = await _get_notif_channel()
        resultados.append(f"{'✅' if canal_n else '❌'} **Canal notif:** {'encontrado' if canal_n else 'NO encontrado'}")
    else:
        resultados.append(f"❌ **Server notif:** No accesible (ID: {SERVER_NOTIF_ID})")

    # 12. yt-dlp
    try:
        ytdlp_cmd = _resolve_ytdlp_cmd()
        if ytdlp_cmd:
            r2 = subprocess.run(ytdlp_cmd + ["--version"], capture_output=True, text=True, timeout=5)
            ver = (r2.stdout or r2.stderr or "").strip()[:30] or "ok"
            via = "módulo Python" if ytdlp_cmd[:3] == [sys.executable, "-m", "yt_dlp"] else ytdlp_cmd[0]
            resultados.append(f"{'✅' if r2.returncode == 0 else '⚠️'} **yt-dlp:** {ver} (via {via})")
        else:
            resultados.append("⚠️ **yt-dlp:** no encontrado (PATH/rutas comunes/módulo)")
    except Exception as e:
        resultados.append(f"⚠️ **yt-dlp:** error al verificar - {e}")

    # 13. Sistema
    try:
        cpu = psutil.cpu_percent(interval=0.3)
        ram = psutil.virtual_memory()
        resultados.append(f"{'✅' if cpu < 80 else '⚠️'} **CPU:** {cpu}% | **RAM:** {ram.percent}% ({ram.used//1024//1024}MB/{ram.total//1024//1024}MB)")
    except:
        resultados.append("⚠️ **Sistema:** psutil no disponible")

    resultados.append(
        f"✅ **Runtime:** IA={runtime_metrics.get('ai_requests', 0)} | Descargas={runtime_metrics.get('media_downloads', 0)} | Tickets={runtime_metrics.get('tickets_created', 0)} | Moderacion={runtime_metrics.get('moderation_actions', 0)}"
    )

    # Resumen
    ok_count = sum(1 for r in resultados if r.startswith("✅"))
    warn_count = sum(1 for r in resultados if r.startswith("⚠️"))
    err_count = sum(1 for r in resultados if r.startswith("❌"))

    embed = discord.Embed(
        title=f"🔧 Debug Report - {'✅ Todo OK' if err_count == 0 else f'❌ {err_count} errores'}",
        description="\n".join(resultados),
        color=discord.Color(COLOR_EXITO if err_count == 0 else COLOR_PELIGRO),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed.set_footer(text=f"OK: {ok_count} | Warn: {warn_count} | Error: {err_count} | LatamBOT {BOT_VERSION}")
    await msg.edit(embed=embed)

    if ctx.guild:
        await ctx.send(embed=discord.Embed(description="Reporte enviado por DM.", color=discord.Color(COLOR_INFO)), delete_after=5)






