def _reaction_roles_for_message(rr_list: list, message_id: int) -> list:
    return [rr for rr in rr_list if str(rr.get("msg_id")) == str(message_id)]


def _build_reaction_role_panel_embed(guild: discord.Guild, rr_list: list, *, message_id: int = None, titulo: str = "Reaction Roles", descripcion: str = "Reacciona para obtener o quitar roles.") -> discord.Embed:
    panel_roles = _reaction_roles_for_message(rr_list, message_id) if message_id else [rr for rr in rr_list if rr.get("guild_id") == guild.id]
    embed = discord.Embed(
        title=titulo,
        description=descripcion,
        color=discord.Color(COLOR_PRIMARIO),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    if guild.icon:
        embed.set_thumbnail(url=guild.icon.url)
    if panel_roles:
        roles_txt = "\n".join(f"{rr['emoji']} → <@&{rr['rol_id']}>" for rr in panel_roles[:20])
        embed.add_field(name="Roles disponibles", value=roles_txt, inline=False)
        if len(panel_roles) > 20:
            embed.add_field(name="Extra", value=f"Hay {len(panel_roles) - 20} roles mas guardados para este panel.", inline=False)
    else:
        embed.add_field(
            name="Como usarlo",
            value="Agrega combinaciones con `/reactionroleadd`. Cuando alguien reacciona, recibe o pierde el rol asociado.",
            inline=False,
        )
    embed.set_footer(text=f"LatamBOT | {guild.name} | Reacciona para gestionar roles")
    return embed


async def _apply_reaction_roles_to_message(guild, channel, message_id, pairs, *, titulo=None, descripcion=None, replace=True):
    """Adjunta pares emoji→rol a un mensaje existente (reemplaza los de ese mensaje si replace)."""
    msg = await channel.fetch_message(int(message_id))
    cfg = get_config(guild.id) or {}
    rr_list = list(cfg.get("reaction_roles", []) or [])
    mid = int(message_id)
    if replace:
        rr_list = [rr for rr in rr_list if int(rr.get("msg_id") or 0) != mid]
    agregados = 0
    for par in (pairs or []):
        emoji = str(par.get("emoji", "")).strip()
        try:
            rol_id = int(par.get("rol_id"))
        except (TypeError, ValueError):
            continue
        rol = guild.get_role(rol_id)
        if not emoji or not rol:
            continue
        if _rol_verif_peligroso(rol):
            continue
        rr_list.append({"msg_id": mid, "emoji": emoji, "rol_id": rol_id, "guild_id": guild.id})
        try:
            await msg.add_reaction(emoji)
            agregados += 1
        except Exception as e:
            print(f"[RR] No pude reaccionar {emoji}: {e}")
    update_server_config(guild.id, "reaction_roles", rr_list)
    # Si el mensaje ya es un panel RR (tiene embed), actualizamos la lista visible.
    if msg.embeds:
        old = msg.embeds[0]
        try:
            await msg.edit(embed=_build_reaction_role_panel_embed(
                guild, rr_list, message_id=mid,
                titulo=titulo or old.title or "Reaction Roles",
                descripcion=descripcion or old.description or "Reacciona para obtener o quitar un rol.",
            ))
        except Exception:
            pass
    _console_log("RR_APPLY", "Reaction roles aplicados a mensaje", guild_id=guild.id, channel_id=channel.id, message_id=mid, pares=agregados)
    return msg, agregados


async def _publish_reaction_role_panel(guild, channel, titulo, descripcion, pairs):
    """Publica un panel de reaction roles en un mensaje nuevo y registra los pares emoji→rol."""
    titulo = (titulo or "Reaction Roles")[:256]
    descripcion = (descripcion or "Reacciona para obtener o quitar un rol.")[:2000]
    embed = _build_reaction_role_panel_embed(guild, [], titulo=titulo, descripcion=descripcion)
    msg = await channel.send(embed=embed)
    return await _apply_reaction_roles_to_message(
        guild, channel, msg.id, pairs, titulo=titulo, descripcion=descripcion, replace=True,
    )


async def _procesar_starboard(payload, cfg):
    """Manda al canal de destacados los mensajes que superan el umbral de ⭐."""
    if not cfg.get("starboard_activo") or not cfg.get("starboard_canal"):
        return
    emoji_cfg = cfg.get("starboard_emoji", "⭐")
    if str(payload.emoji) != emoji_cfg:
        return
    guild = bot.get_guild(payload.guild_id)
    if not guild or payload.channel_id == cfg.get("starboard_canal"):
        return
    canal_orig = guild.get_channel(payload.channel_id)
    canal_star = guild.get_channel(cfg.get("starboard_canal"))
    if not canal_orig or not canal_star:
        return
    try:
        msg = await canal_orig.fetch_message(payload.message_id)
    except Exception:
        return
    if msg.author.bot:
        return
    count = next((r.count for r in msg.reactions if str(r.emoji) == emoji_cfg), 0)
    if count < int(cfg.get("starboard_umbral", 3) or 3):
        return
    datos = cargar_datos()
    posts = datos.get("starboard_posts", {})
    key = str(msg.id)
    embed = discord.Embed(description=msg.content or "", color=discord.Color.gold(), timestamp=msg.created_at)
    embed.set_author(name=msg.author.display_name, icon_url=msg.author.display_avatar.url)
    img = next((a.url for a in msg.attachments if (a.content_type or "").startswith("image")), None)
    if img:
        embed.set_image(url=img)
    embed.add_field(name="Mensaje", value=f"[Ir al mensaje]({msg.jump_url})", inline=False)
    embed.set_footer(text=f"⭐ {count} · #{canal_orig.name}")
    contenido = f"{emoji_cfg} **{count}**"
    if key in posts:
        try:
            star_msg = await canal_star.fetch_message(posts[key])
            await star_msg.edit(content=contenido, embed=embed)
            return
        except Exception:
            posts.pop(key, None)  # se borró en el starboard → re-postear abajo
    try:
        sm = await canal_star.send(content=contenido, embed=embed)
        posts[key] = sm.id
        datos["starboard_posts"] = posts
        guardar_datos(datos)
    except Exception as e:
        print(f"[STARBOARD] {e}")


@bot.event
async def on_raw_reaction_add(payload: discord.RawReactionActionEvent):
    if payload.user_id == bot.user.id:
        return
    cfg = get_config(payload.guild_id)
    if not cfg:
        return
    try:
        await _procesar_starboard(payload, cfg)
    except Exception as e:
        print(f"[STARBOARD] {e}")
    rr_list = cfg.get("reaction_roles", [])
    emoji_str = str(payload.emoji)
    for rr in rr_list:
        if rr.get("guild_id") == payload.guild_id and str(rr.get("msg_id")) == str(payload.message_id) and rr.get("emoji") == emoji_str:
            guild = bot.get_guild(payload.guild_id)
            if not guild:
                return
            rol = guild.get_role(rr["rol_id"])
            member = guild.get_member(payload.user_id)
            if not member:
                try:
                    member = await guild.fetch_member(payload.user_id)
                except Exception:
                    member = None
            if rol and member:
                if _rol_verif_peligroso(rol):
                    _console_log(
                        "RR_ADD",
                        "Reaction role bloqueado: rol con permisos peligrosos",
                        level="WARN",
                        guild_id=payload.guild_id,
                        role_id=rol.id,
                    )
                    break
                try:
                    await member.add_roles(rol, reason="Reaction Role LatamBOT")
                    _console_log("RR_ADD", "Rol entregado por reaccion", guild_id=payload.guild_id, user_id=payload.user_id, role_id=rol.id, message_id=payload.message_id)
                except Exception as e:
                    _console_log("RR_ADD", "No pude entregar un reaction role", level="ERROR", guild_id=payload.guild_id, user_id=payload.user_id, role_id=rol.id if rol else None, error=e)
            break


@bot.event
async def on_raw_reaction_remove(payload: discord.RawReactionActionEvent):
    if payload.user_id == bot.user.id:
        return
    cfg = get_config(payload.guild_id)
    if not cfg:
        return
    rr_list = cfg.get("reaction_roles", [])
    emoji_str = str(payload.emoji)
    for rr in rr_list:
        if rr.get("guild_id") == payload.guild_id and str(rr.get("msg_id")) == str(payload.message_id) and rr.get("emoji") == emoji_str:
            guild = bot.get_guild(payload.guild_id)
            if not guild:
                return
            rol = guild.get_role(rr["rol_id"])
            member = guild.get_member(payload.user_id)
            if not member:
                try:
                    member = await guild.fetch_member(payload.user_id)
                except Exception:
                    member = None
            if rol and member:
                try:
                    await member.remove_roles(rol, reason="Reaction Role removido LatamBOT")
                    _console_log("RR_REMOVE", "Rol retirado por reaccion", guild_id=payload.guild_id, user_id=payload.user_id, role_id=rol.id, message_id=payload.message_id)
                except Exception as e:
                    _console_log("RR_REMOVE", "No pude retirar un reaction role", level="ERROR", guild_id=payload.guild_id, user_id=payload.user_id, role_id=rol.id if rol else None, error=e)
            break


