async def _send_pet_drop_to_channel(channel: discord.TextChannel, cfg: Dict[str, Any]) -> bool:
    tipo = (cfg.get("mascotas_tipo") or "gatos").strip().lower()
    choice = tipo
    if tipo == "mix":
        choice = random.choice(["gatos", "perros"])
    try:
        if choice == "perros":
            async with aiohttp.ClientSession() as session:
                async with session.get("https://dog.ceo/api/breeds/image/random", timeout=aiohttp.ClientTimeout(total=12)) as resp:
                    data = await resp.json()
            image_url = data.get("message")
            if not image_url:
                return False
            embed = discord.Embed(title="🐶 Hora de perros", color=discord.Color.from_rgb(255, 196, 87))
            embed.set_image(url=image_url)
            embed.set_footer(text="LatamBOT")
        else:
            pet = await _fetch_cat_image(args=None)
            embed = discord.Embed(title="🐱 Hora de gatos", color=discord.Color.from_rgb(255, 165, 0))
            embed.set_image(url=pet["url"])
            embed.set_footer(text=f"Fuente: {pet['source']}")
        await channel.send(embed=embed)
        return True
    except Exception as e:
        _console_log("PET_DROP", "No pude publicar mascotas", level="ERROR", guild_id=getattr(channel.guild, "id", None), channel_id=channel.id, error=e)
        return False


@tasks.loop(minutes=5)
async def publicar_mascotas_programadas():
    ahora = datetime.datetime.now(datetime.timezone.utc)
    for guild in list(bot.guilds):
        cfg = get_config(guild.id) or {}
        if not cfg.get("sistema_mascotas_auto"):
            continue
        channel_id = cfg.get("canal_mascotas")
        if not channel_id:
            continue
        canal = guild.get_channel(channel_id)
        if not canal:
            continue
        intervalo = max(30, int(cfg.get("mascotas_intervalo_min", 180) or 180))
        ultimo_raw = cfg.get("mascotas_ultimo_envio") or ""
        try:
            ultimo = datetime.datetime.fromisoformat(ultimo_raw) if ultimo_raw else None
        except Exception:
            ultimo = None
        if ultimo and (ahora - ultimo).total_seconds() < intervalo * 60:
            continue
        if await _send_pet_drop_to_channel(canal, cfg):
            update_server_config(guild.id, "mascotas_ultimo_envio", ahora.isoformat())

