# ── Heartbeat EC2 → Pi (fallback) ───────────────────────────────────────────
# El EC2 (activo) manda un "ping" de vida a este canal. La Pi en modo standby
# (standby.py) lo lee por REST y responde cada 50 min, y de paso sincroniza datos.
HEARTBEAT_CHANNEL_ID = 1522970907683983561


def _pings_pi_activos() -> bool:
    """Si el owner apagó los pings con l!pingspi, el heartbeat no manda nada."""
    try:
        return bool(cargar_datos().get("pings_pi_activos", True))
    except Exception:
        return True


def _set_pings_pi(activo: bool) -> None:
    d = cargar_datos()
    d["pings_pi_activos"] = bool(activo)
    guardar_datos(d)


@tasks.loop(minutes=30)
async def heartbeat_ec2():
    """Manda un 'ping' de vida para que la Pi (standby) sepa que el EC2 sigue activo."""
    if os.getenv("LATAMBOT_STANDBY"):
        return  # una instancia standby nunca manda pings
    if not _pings_pi_activos():
        return  # apagado con l!pingspi
    try:
        ch = bot.get_channel(HEARTBEAT_CHANNEL_ID)
        if ch is not None:
            ahora = datetime.datetime.now(datetime.timezone.utc)
            await ch.send(f"🛰️ `ping` · EC2 vivo · {ahora:%Y-%m-%d %H:%M} UTC · {BOT_VERSION} · {len(bot.guilds)} servers")
    except Exception as e:
        print(f"[HEARTBEAT] {e}")


@heartbeat_ec2.before_loop
async def _antes_heartbeat():
    await bot.wait_until_ready()


_pi_alerta_enviada = False


@tasks.loop(minutes=15)
async def vigilar_pi():
    """Vigila que la Pi (standby) siga contestando. Si se calla >70 min, avisa al owner por DM."""
    global _pi_alerta_enviada
    if os.getenv("LATAMBOT_STANDBY") or not _pings_pi_activos():
        return
    try:
        ch = bot.get_channel(HEARTBEAT_CHANNEL_ID)
        if ch is None:
            return
        ultimo = None
        async for m in ch.history(limit=50):
            if m.author.id == bot.user.id and "Pi standby" in (m.content or ""):
                ultimo = m
                break
        if ultimo is None:
            return
        edad = (datetime.datetime.now(datetime.timezone.utc) - ultimo.created_at).total_seconds()
        if edad > 70 * 60:
            if not _pi_alerta_enviada:
                _pi_alerta_enviada = True
                mins = int(edad // 60)
                txt = (
                    f"⚠️ **La Pi no responde hace {mins} min** (última señal: {discord.utils.format_dt(ultimo.created_at, 'f')}).\n"
                    f"Posibles causas: corte de luz, WiFi caído, SD corrupta o el servicio murió.\n"
                    f"Cuando vuelva va a avisar el motivo en {ch.mention}."
                )
                try:
                    owner = bot.get_user(OWNER_ID) or await bot.fetch_user(OWNER_ID)
                    await owner.send(txt)
                except Exception:
                    try:
                        await ch.send(f"<@{OWNER_ID}> " + txt)
                    except Exception:
                        pass
        else:
            _pi_alerta_enviada = False  # la Pi volvió → rearmar la alerta
    except Exception as e:
        print(f"[VIGILAR_PI] {e}")


@vigilar_pi.before_loop
async def _antes_vigilar_pi():
    await bot.wait_until_ready()
    await asyncio.sleep(180)  # dar tiempo a que haya historial de la Pi


class PingsPiView(discord.ui.View):
    """Botones para prender/apagar los pings de heartbeat a la Pi. Solo owner."""

    def __init__(self):
        super().__init__(timeout=120)

    async def _refrescar(self, interaction: discord.Interaction):
        activo = _pings_pi_activos()
        estado = "🟢 Activados" if activo else "🔴 Desactivados"
        embed = _make_embed(
            "🛰️ Pings a la Pi (heartbeat)",
            f"Estado actual: **{estado}**\n\nCuando están activos, el EC2 manda un `ping` cada 10 min al canal de la Pi.",
            COLOR_EXITO if activo else COLOR_PELIGRO,
        )
        await interaction.response.edit_message(embed=embed, view=self)

    @discord.ui.button(label="Activar", emoji="🟢", style=discord.ButtonStyle.success)
    async def activar(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != OWNER_ID:
            await interaction.response.send_message("Solo el owner puede tocar esto.", ephemeral=True)
            return
        _set_pings_pi(True)
        await self._refrescar(interaction)

    @discord.ui.button(label="Desactivar", emoji="🔴", style=discord.ButtonStyle.danger)
    async def desactivar(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != OWNER_ID:
            await interaction.response.send_message("Solo el owner puede tocar esto.", ephemeral=True)
            return
        _set_pings_pi(False)
        await self._refrescar(interaction)


@bot.command(name="pingspi")
async def pingspi(ctx):
    """[Owner] Prende/apaga los pings de heartbeat a la Pi."""
    if ctx.author.id != OWNER_ID:
        return
    activo = _pings_pi_activos()
    estado = "🟢 Activados" if activo else "🔴 Desactivados"
    embed = _make_embed(
        "🛰️ Pings a la Pi (heartbeat)",
        f"Estado actual: **{estado}**\n\nCuando están activos, el EC2 manda un `ping` cada 10 min al canal de la Pi.",
        COLOR_EXITO if activo else COLOR_PELIGRO,
    )
    await ctx.send(embed=embed, view=PingsPiView())


# ── Alertas sociales de YouTube (feedparser / RSS) - 1 por servidor ──────────
@tasks.loop(minutes=10)
async def revisar_youtube():
    """Avisa cuando el canal de YouTube configurado sube un video nuevo."""
    if _feedparser is None:
        return
    for guild in list(bot.guilds):
        cfg = get_config(guild.id) or {}
        yt_id = cfg.get("alerta_yt_canal_id")
        disc_ch_id = cfg.get("alerta_yt_discord")
        if not yt_id or not disc_ch_id:
            continue
        try:
            url = f"https://www.youtube.com/feeds/videos.xml?channel_id={yt_id}"
            feed = await bot.loop.run_in_executor(None, _feedparser.parse, url)
            if not feed.entries:
                continue
            ultimo = feed.entries[0]
            vid = ultimo.get("yt_videoid")
            visto = cfg.get("alerta_yt_ultimo")
            if not vid:
                continue
            if not visto:
                update_server_config(guild.id, "alerta_yt_ultimo", vid)  # baseline, no spamear el viejo
                continue
            if vid != visto:
                canal = guild.get_channel(disc_ch_id)
                if canal:
                    autor = ultimo.get("author", "El canal")
                    await canal.send(
                        f"📺 **{autor}** subió un video nuevo!\n**{ultimo.get('title', 'Sin título')}**\n{ultimo.get('link', '')}"
                    )
                update_server_config(guild.id, "alerta_yt_ultimo", vid)
        except Exception as ex:
            print(f"[YT_ALERT] guild {guild.id}: {ex}")


@revisar_youtube.before_loop
async def _antes_youtube():
    await bot.wait_until_ready()


@bot.command(name="ytalert", aliases=["youtubealert", "alertayt"])
@commands.has_permissions(manage_guild=True)
async def ytalert(ctx, canal_yt: str = None, canal_discord: discord.TextChannel = None):
    """Avisa cuando un canal de YouTube sube video. `l!ytalert <ID_del_canal_UC...> [#canal]` · `l!ytalert off`."""
    cfg = get_config(ctx.guild.id) or {}
    if not canal_yt:
        actual = cfg.get("alerta_yt_canal_id")
        if actual:
            ch = ctx.guild.get_channel(cfg.get("alerta_yt_discord"))
            desc = f"Vigilando `{actual}` → avisa en {ch.mention if ch else '?'}.\n\nPara desactivar: `{cfg.get('prefix','l!')}ytalert off`."
        else:
            desc = ("No hay alerta de YouTube configurada.\n\n"
                    f"Usá `{cfg.get('prefix','l!')}ytalert <ID del canal> [#canal-discord]`.\n"
                    "El **ID del canal** empieza con `UC...` (lo sacás de la URL del canal, o en la fuente de su página buscando `channelId`).")
        await ctx.send(embed=_make_embed("📺 Alerta de YouTube", desc, COLOR_INFO))
        return
    if canal_yt.lower() in ("off", "no", "desactivar", "apagar"):
        update_server_config(ctx.guild.id, "alerta_yt_canal_id", None)
        update_server_config(ctx.guild.id, "alerta_yt_discord", None)
        update_server_config(ctx.guild.id, "alerta_yt_ultimo", None)
        await ctx.send(embed=_make_embed("📺 Alerta de YouTube", "Desactivada.", COLOR_EXITO))
        return
    m = re.search(r"(UC[\w-]{20,})", canal_yt)
    yt_id = m.group(1) if m else canal_yt.strip()
    if not yt_id.startswith("UC"):
        await ctx.send(embed=_make_embed(
            "ID inválido",
            "Necesito el **ID del canal** (empieza con `UC...`), no el @handle ni el nombre.\n"
            "Entrá al canal de YouTube → compartir → copiar link, o mirá el `channelId` en el código fuente de su página.",
            COLOR_ADVERTENCIA))
        return
    dest = canal_discord or ctx.channel
    update_server_config(ctx.guild.id, "alerta_yt_canal_id", yt_id)
    update_server_config(ctx.guild.id, "alerta_yt_discord", dest.id)
    update_server_config(ctx.guild.id, "alerta_yt_ultimo", None)
    await ctx.send(embed=_make_embed(
        "📺 Alerta de YouTube activada",
        f"Voy a avisar en {dest.mention} cuando `{yt_id}` suba un video nuevo (chequeo cada 10 min).",
        COLOR_EXITO))


@bot.command(name="palabra", aliases=["palabras", "bloquear", "badword"])
@commands.has_permissions(manage_guild=True)
async def palabra(ctx, accion: str = None, *, texto: str = None):
    """Filtro de palabras. `l!palabra add <palabra>` · `list` · `remove <palabra>`."""
    cfg = get_config(ctx.guild.id) or {}
    pref = cfg.get("prefix", "l!")
    lista = list(cfg.get("palabras_bloqueadas", []) or [])
    if accion is None or accion.lower() in ("list", "lista", "ver"):
        estado = "🟢 activo" if cfg.get("automod_palabras") else f"🔴 apagado (prendelo en `{pref}setup`)"
        cuerpo = ", ".join(f"`{w}`" for w in lista) if lista else "*(vacía)*"
        await ctx.send(embed=_make_embed(
            f"🚫 Palabras bloqueadas - {estado}",
            f"{cuerpo}\n\n`{pref}palabra add <palabra>` · `{pref}palabra remove <palabra>`",
            COLOR_INFO))
        return
    if accion.lower() in ("add", "agregar", "añadir", "sumar") and texto:
        w = texto.strip().lower()
        if w and w not in lista:
            lista.append(w)
            update_server_config(ctx.guild.id, "palabras_bloqueadas", lista[:300])
        await ctx.send(embed=_make_embed(
            "🚫 Palabra agregada",
            f"«{w}» ahora está bloqueada. Activá el filtro con `{pref}setup` si aún no lo hiciste.",
            COLOR_EXITO))
        return
    if accion.lower() in ("remove", "quitar", "sacar", "del", "borrar") and texto:
        w = texto.strip().lower()
        lista = [x for x in lista if x != w]
        update_server_config(ctx.guild.id, "palabras_bloqueadas", lista)
        await ctx.send(embed=_make_embed("🚫 Palabra quitada", f"«{w}» ya no está bloqueada.", COLOR_EXITO))
        return
    await ctx.send(embed=_make_embed(
        "Uso del filtro de palabras",
        f"`{pref}palabra add <palabra>` · `{pref}palabra list` · `{pref}palabra remove <palabra>`",
        COLOR_INFO))


def _cargar_notify():
    """Carga el mapa de notificaciones por keyword a memoria (guild → {palabra: [uids]})."""
    _notify_cache.clear()
    try:
        nd = cargar_datos().get("notify", {}) or {}
        for gk, wm in nd.items():
            try:
                _notify_cache[int(gk)] = {w: list(u) for w, u in (wm or {}).items()}
            except Exception:
                continue
    except Exception as e:
        print(f"[NOTIFY] carga: {e}")


@bot.command(name="notify", aliases=["notificar", "avisame"])
async def notify(ctx, accion: str = None, *, palabra: str = None):
    """Te aviso por DM cuando alguien menciona una palabra. `l!notify add <palabra>` · `list` · `remove` · `clear`."""
    if not ctx.guild:
        return
    datos = cargar_datos()
    nd = datos.setdefault("notify", {})
    gk = str(ctx.guild.id)
    gmap = nd.setdefault(gk, {})
    uid = ctx.author.id
    pref = (get_config(ctx.guild.id) or {}).get("prefix", "l!")
    if accion is None or accion.lower() in ("list", "lista"):
        mias = [w for w, users in gmap.items() if uid in users]
        cuerpo = ", ".join(f"`{w}`" for w in mias) if mias else "*(ninguna)*"
        try:
            await ctx.author.send(embed=_make_embed("🔔 Tus notificaciones acá", f"{cuerpo}\n\n`{pref}notify add <palabra>` para sumar.", COLOR_INFO))
            await ctx.message.add_reaction("📬")
        except Exception:
            await ctx.send("No te puedo mandar DM (revisá tu privacidad).")
        return
    if accion.lower() in ("add", "agregar", "añadir") and palabra:
        w = palabra.strip().lower()[:60]
        if len(w) < 2:
            await ctx.send(embed=_make_embed("Muy corta", "La palabra tiene que tener al menos 2 letras.", COLOR_ADVERTENCIA))
            return
        gmap.setdefault(w, [])
        if uid not in gmap[w]:
            gmap[w].append(uid)
        guardar_datos(datos)
        _cargar_notify()
        try:
            await ctx.message.add_reaction("✅")
            await ctx.author.send(f"🔔 Listo, te aviso cuando mencionen **{w}** en **{ctx.guild.name}**.")
        except Exception:
            pass
        return
    if accion.lower() in ("remove", "quitar", "sacar", "del") and palabra:
        w = palabra.strip().lower()
        if w in gmap and uid in gmap[w]:
            gmap[w].remove(uid)
            if not gmap[w]:
                del gmap[w]
            guardar_datos(datos)
            _cargar_notify()
        try:
            await ctx.message.add_reaction("✅")
        except Exception:
            pass
        return
    if accion.lower() in ("clear", "limpiar", "borrar"):
        for w in list(gmap):
            if uid in gmap[w]:
                gmap[w].remove(uid)
                if not gmap[w]:
                    del gmap[w]
        guardar_datos(datos)
        _cargar_notify()
        await ctx.send(embed=_make_embed("🔔 Notificaciones", "Borré todas tus palabras de este server.", COLOR_EXITO))
        return
    await ctx.send(embed=_make_embed("Uso de notificaciones", f"`{pref}notify add <palabra>` · `{pref}notify list` · `{pref}notify remove <palabra>` · `{pref}notify clear`", COLOR_INFO))


@bot.command(name="starboard", aliases=["destacados"])
@commands.has_permissions(manage_guild=True)
async def starboard(ctx, arg: str = None, *, extra: str = None):
    """Mensajes con ⭐ van a un canal de destacados. `l!starboard #canal` · `off` · `umbral <n>` · `emoji <e>`."""
    cfg = get_config(ctx.guild.id) or {}
    pref = cfg.get("prefix", "l!")
    if arg is None:
        estado = "🟢 activo" if cfg.get("starboard_activo") else "🔴 apagado"
        ch = ctx.guild.get_channel(cfg.get("starboard_canal")) if cfg.get("starboard_canal") else None
        desc = (f"Estado: **{estado}**\nCanal: {ch.mention if ch else '-'}\n"
                f"Emoji: {cfg.get('starboard_emoji', '⭐')} · Umbral: **{cfg.get('starboard_umbral', 3)}** reacciones\n\n"
                f"`{pref}starboard #canal` activar · `{pref}starboard off` · `{pref}starboard umbral <n>` · `{pref}starboard emoji <e>`")
        await ctx.send(embed=_make_embed("⭐ Starboard", desc, COLOR_INFO))
        return
    a = arg.lower()
    if a in ("off", "desactivar", "apagar"):
        update_server_config(ctx.guild.id, "starboard_activo", False)
        await ctx.send(embed=_make_embed("⭐ Starboard", "Desactivado.", COLOR_EXITO))
        return
    if a in ("umbral", "threshold") and extra:
        try:
            n = max(1, int(extra.strip()))
        except Exception:
            n = 3
        update_server_config(ctx.guild.id, "starboard_umbral", n)
        await ctx.send(embed=_make_embed("⭐ Starboard", f"Umbral = **{n}** ⭐.", COLOR_EXITO))
        return
    if a == "emoji" and extra:
        update_server_config(ctx.guild.id, "starboard_emoji", extra.strip().split()[0])
        await ctx.send(embed=_make_embed("⭐ Starboard", f"Emoji = {extra.strip().split()[0]}.", COLOR_EXITO))
        return
    ch = ctx.message.channel_mentions[0] if ctx.message.channel_mentions else None
    if not ch:
        await ctx.send(embed=_make_embed("Uso", f"`{pref}starboard #canal` para activar en ese canal.", COLOR_ADVERTENCIA))
        return
    update_server_config(ctx.guild.id, "starboard_canal", ch.id)
    update_server_config(ctx.guild.id, "starboard_activo", True)
    await ctx.send(embed=_make_embed("⭐ Starboard activado", f"Los mensajes con {cfg.get('starboard_emoji', '⭐')} ({cfg.get('starboard_umbral', 3)}+) van a {ch.mention}.", COLOR_EXITO))


