# ==============================================================================
# l!getinvi - Obtener invitacion de un servidor (SOLO OWNER EN SERVER NOTIF)
# ==============================================================================

@bot.command(name="getinvi")
async def getinvi(ctx, server_id: int = None):
    """[OWNER] Busca una invitacion valida del servidor especificado y la envia al canal."""
    if ctx.author.id != OWNER_ID or ctx.guild.id != SERVER_NOTIF_ID:
        return
    if not server_id:
        embed = _make_embed("Uso correcto", "`l!getinvi <ID del servidor>`", COLOR_INFO)
        await ctx.send(embed=embed)
        return
    target = bot.get_guild(server_id)
    if not target:
        embed = _make_error_embed("Servidor no encontrado", f"No estoy en el servidor `{server_id}`.", "Verifica que el ID sea correcto y que el bot este en el.")
        await ctx.send(embed=embed)
        return
    invite_link = None
    try:
        invites = await target.invites()
        for inv in invites:
            if inv.max_age == 0 and not inv.revoked:
                invite_link = inv.url
                break
        if not invite_link and invites:
            invite_link = invites[0].url
    except:
        pass
    if not invite_link:
        for channel in target.text_channels:
            perms = channel.permissions_for(target.me)
            if perms.create_instant_invite:
                try:
                    inv = await channel.create_invite(max_age=0, max_uses=1)
                    invite_link = inv.url
                    _getinvi_invites[inv.code] = target.id
                    break
                except:
                    continue
    if not invite_link:
        embed = _make_error_embed("Sin invitacion", f"No se encontro ni se pudo crear una invitacion en `{target.name}` (`{target.id}`).", "Asegurate de que el bot tenga permisos para ver/crear invites.")
        await ctx.send(embed=embed)
        return
    embed = _make_embed(
        f"Invitacion: {target.name}",
        f"**ID:** `{target.id}`\n**Link:** {invite_link}\n**Miembros:** {target.member_count}",
        COLOR_EXITO,
    )
    await ctx.send(embed=embed)

