@bot.command(name="casos", aliases=["cases", "historial"])
@commands.check(es_staff)
async def casos_cmd(ctx, m: discord.Member = None):
    """Historial de sanciones de un usuario. Uso: l!casos @usuario"""
    m = m or ctx.author
    casos = _casos_guild(cargar_datos(), ctx.guild.id)
    suyos = sorted(
        [c for c in casos.values() if int(c.get("usuario", 0)) == m.id],
        key=lambda c: int(c["numero"]),
        reverse=True,
    )
    if not suyos:
        await ctx.send(embed=_make_embed("Sin antecedentes", f"{m.mention} no tiene casos registrados.", COLOR_EXITO))
        return
    cfg = get_config(ctx.guild.id) or {}
    data = _warn_data(cargar_datos(), ctx.guild.id, m.id)
    puntos = _warn_puntos_vigentes(cfg, data)
    lineas = []
    for c in suyos[:15]:
        emoji, etiqueta, _ = CASO_TIPOS.get(c.get("tipo", "warn"), ("📋", "Caso", 0))
        ts = int(datetime.datetime.fromisoformat(c["creado"]).timestamp())
        lineas.append(f"{emoji} **#{c['numero']}** · {etiqueta} · <t:{ts}:R>\n┗ {_clip_text(c.get('motivo') or 'Sin motivo', 70)}")
    embed = _make_embed(
        f"Historial de {m.display_name}",
        "\n".join(lineas) + (f"\n\n*(+{len(suyos) - 15} casos más)*" if len(suyos) > 15 else ""),
        COLOR_INFO,
    )
    embed.set_thumbnail(url=m.display_avatar.url)
    embed.add_field(name="Total de casos", value=str(len(suyos)), inline=True)
    embed.add_field(name="Puntos de warn", value=str(puntos), inline=True)
    embed.set_footer(text="Ver un caso: l!caso <numero>")
    await ctx.send(embed=embed)


