@bot.command(name="warns", aliases=["miswarns", "mywarns"])
async def warns_cmd(ctx, m: discord.Member = None):
    """Ver las advertencias y puntos de alguien (o tuyas). Uso: l!warns [@usuario]"""
    objetivo = m or ctx.author
    if m and m != ctx.author and not es_staff(ctx):
        await ctx.send(embed=_make_embed("Solo las tuyas", "Solo el staff puede ver las advertencias de otros.", COLOR_ADVERTENCIA))
        return
    cfg = get_config(ctx.guild.id) or {}
    data = _warn_data(cargar_datos(), ctx.guild.id, objetivo.id)
    puntos = _warn_puntos_vigentes(cfg, data)
    hist = list(reversed(data.get("historial", [])))[:10]
    if not hist:
        await ctx.send(embed=_make_embed("Sin advertencias", f"{objetivo.mention} no tiene advertencias.", COLOR_EXITO))
        return
    lineas = []
    for h in hist:
        ts = int(datetime.datetime.fromisoformat(h["fecha"]).timestamp())
        lineas.append(f"**+{h['puntos']}** · {_clip_text(h.get('motivo') or 'Sin motivo', 60)} · <t:{ts}:R>")
    embed = _make_embed(f"Advertencias de {objetivo.display_name}", "\n".join(lineas), COLOR_ADVERTENCIA)
    embed.set_thumbnail(url=objetivo.display_avatar.url)
    embed.add_field(name="Puntos acumulados", value=f"**{puntos}**", inline=True)
    proximas = sorted(
        [a for a in (cfg.get("warn_acciones") or []) if int(a.get("puntos", 0)) > puntos],
        key=lambda a: int(a.get("puntos", 0)),
    )
    if proximas:
        p = proximas[0]
        embed.add_field(name="Proximo umbral", value=f"{p['puntos']} pts → `{p.get('accion')}`", inline=True)
    if int(cfg.get("warn_expira_dias", 0) or 0) > 0:
        embed.set_footer(text=f"Los puntos caducan a los {cfg['warn_expira_dias']} dias")
    await ctx.send(embed=embed)


@bot.command(name="warnaccion", aliases=["warnaction"])
@commands.has_permissions(manage_guild=True)
async def warnaccion_cmd(ctx, puntos: int = None, accion: str = None, minutos: int = 60):
    """Define una sancion automatica por umbral de puntos.
    Uso: l!warnaccion 5 timeout 120  ·  l!warnaccion 10 ban  ·  l!warnaccion (ver lista)  ·  l!warnaccion 5 quitar
    """
    cfg = get_config(ctx.guild.id) or {}
    acciones = list(cfg.get("warn_acciones") or [])
    if puntos is None:
        if not acciones:
            await ctx.send(embed=_make_embed(
                "Sin acciones automaticas",
                "No hay umbrales configurados.\n\n**Ejemplos:**\n"
                "`l!warnaccion 3 timeout 60` - a los 3 puntos, 1h de silencio\n"
                "`l!warnaccion 5 kick` - a los 5 puntos, expulsion\n"
                "`l!warnaccion 10 ban` - a los 10 puntos, baneo",
                COLOR_INFO))
            return
        lineas = []
        for a in sorted(acciones, key=lambda x: int(x["puntos"])):
            extra = f" ({a.get('minutos', 60)} min)" if a.get("accion") == "timeout" else ""
            lineas.append(f"**{a['puntos']} puntos** → `{a['accion']}`{extra}")
        await ctx.send(embed=_make_embed("Sanciones automaticas", "\n".join(lineas), COLOR_INFO))
        return
    if accion and accion.lower() in ("quitar", "remove", "borrar"):
        acciones = [a for a in acciones if int(a["puntos"]) != puntos]
        update_server_config(ctx.guild.id, "warn_acciones", acciones)
        await ctx.send(embed=_make_embed("Accion quitada", f"Ya no pasa nada al llegar a **{puntos}** puntos.", COLOR_EXITO))
        return
    if not accion or accion.lower() not in ("timeout", "kick", "ban"):
        await ctx.send(embed=_make_error_embed(
            "Accion invalida", "Las acciones validas son: `timeout`, `kick`, `ban`.",
            "Ejemplo: `l!warnaccion 5 timeout 120`"))
        return
    if puntos < 1 or puntos > 1000:
        await ctx.send(embed=_make_error_embed("Puntos invalidos", "Elegí un número entre 1 y 1000.", "Ejemplo: `l!warnaccion 5 kick`"))
        return
    acciones = [a for a in acciones if int(a["puntos"]) != puntos]
    acciones.append({"puntos": puntos, "accion": accion.lower(), "minutos": max(1, min(40320, minutos))})
    update_server_config(ctx.guild.id, "warn_acciones", acciones)
    extra = f" durante **{minutos} min**" if accion.lower() == "timeout" else ""
    await ctx.send(embed=_make_embed(
        "Sancion automatica configurada",
        f"Al llegar a **{puntos} puntos** → `{accion.lower()}`{extra}.",
        COLOR_EXITO))


@bot.command(name="warnmotivo", aliases=["warnreason"])
@commands.has_permissions(manage_guild=True)
async def warnmotivo_cmd(ctx, motivo: str = None, puntos: int = None):
    """Motivos predefinidos con puntos fijos. Uso: l!warnmotivo spam 2 · l!warnmotivo (lista) · l!warnmotivo spam 0 (quitar)"""
    cfg = get_config(ctx.guild.id) or {}
    motivos = dict(cfg.get("warn_motivos") or {})
    if not motivo:
        if not motivos:
            await ctx.send(embed=_make_embed(
                "Sin motivos predefinidos",
                "Podés fijar cuántos puntos vale cada motivo.\n\n**Ejemplo:** `l!warnmotivo spam 2`\n"
                "Después, `l!warn @user spam` suma 2 puntos automáticamente.",
                COLOR_INFO))
            return
        lineas = [f"**{k}** → {v} punto(s)" for k, v in sorted(motivos.items(), key=lambda x: -x[1])]
        await ctx.send(embed=_make_embed("Motivos predefinidos", "\n".join(lineas), COLOR_INFO))
        return
    clave = motivo.strip().lower()[:40]
    if puntos is None:
        await ctx.send(embed=_make_error_embed("Falta el puntaje", "Decime cuántos puntos vale ese motivo.", "Ejemplo: `l!warnmotivo spam 2`"))
        return
    if puntos <= 0:
        motivos.pop(clave, None)
        update_server_config(ctx.guild.id, "warn_motivos", motivos)
        await ctx.send(embed=_make_embed("Motivo quitado", f"`{clave}` ya no tiene puntos fijos.", COLOR_EXITO))
        return
    motivos[clave] = max(1, min(100, puntos))
    update_server_config(ctx.guild.id, "warn_motivos", motivos)
    await ctx.send(embed=_make_embed("Motivo configurado", f"`{clave}` ahora vale **{motivos[clave]}** punto(s).", COLOR_EXITO))


# ==============================================================================
# ALIAS de comandos por servidor
# ==============================================================================

@bot.command(name="alias")
@commands.has_permissions(manage_guild=True)
async def alias_cmd(ctx, accion: str = None, nombre: str = None, *, comando: str = None):
    """Atajos propios del servidor. Uso: l!alias add sancion warn · l!alias list · l!alias del sancion"""
    cfg = get_config(ctx.guild.id) or {}
    aliases = dict(cfg.get("alias") or {})
    accion = (accion or "list").lower()

    if accion in ("list", "lista", "ver"):
        if not aliases:
            await ctx.send(embed=_make_embed(
                "Sin alias",
                "Este servidor no tiene atajos.\n\n**Ejemplo:** `l!alias add sancion warn`\n"
                "Después `l!sancion @user spam` funciona igual que `l!warn @user spam`.",
                COLOR_INFO))
            return
        lineas = [f"`{ctx.prefix}{k}` → `{ctx.prefix}{v}`" for k, v in sorted(aliases.items())]
        await ctx.send(embed=_make_embed("Alias del servidor", "\n".join(lineas), COLOR_INFO))
        return

    if accion in ("add", "agregar", "crear"):
        if not nombre or not comando:
            await ctx.send(embed=_make_error_embed("Faltan datos", "Decime el alias y a qué comando apunta.", "Ejemplo: `l!alias add sancion warn`"))
            return
        clave = nombre.strip().lower().lstrip(ctx.prefix)[:30]
        destino = comando.strip().lstrip(ctx.prefix)
        base = destino.split()[0].lower() if destino else ""
        if bot.get_command(clave):
            await ctx.send(embed=_make_error_embed("Nombre ocupado", f"`{clave}` ya es un comando del bot.", "Elegí otro nombre para el alias."))
            return
        if not bot.get_command(base):
            await ctx.send(embed=_make_error_embed("Comando inexistente", f"`{base}` no es un comando de LatamBOT.", "Mirá los comandos con `l!help`."))
            return
        if len(aliases) >= 50:
            await ctx.send(embed=_make_error_embed("Límite alcanzado", "Máximo 50 alias por servidor.", "Borrá alguno con `l!alias del <nombre>`."))
            return
        aliases[clave] = destino
        update_server_config(ctx.guild.id, "alias", aliases)
        await ctx.send(embed=_make_embed("Alias creado", f"`{ctx.prefix}{clave}` ahora ejecuta `{ctx.prefix}{destino}`.", COLOR_EXITO))
        return

    if accion in ("del", "delete", "borrar", "quitar", "remove"):
        clave = (nombre or "").strip().lower()
        if clave not in aliases:
            await ctx.send(embed=_make_error_embed("No existe", f"No hay ningún alias `{clave}`.", "Mirá la lista con `l!alias list`."))
            return
        aliases.pop(clave, None)
        update_server_config(ctx.guild.id, "alias", aliases)
        await ctx.send(embed=_make_embed("Alias borrado", f"`{clave}` ya no existe.", COLOR_EXITO))
        return

    await ctx.send(embed=_make_error_embed("Acción inválida", "Usá `add`, `list` o `del`.", "Ejemplo: `l!alias add sancion warn`"))


