@bot.command(name="reportar", aliases=["report", "reporte"])
@commands.cooldown(1, 60, commands.BucketType.user)
async def reportar_cmd(ctx, m: discord.Member = None, *, motivo: str = None):
    """Reportá a un usuario al staff. Uso: l!reportar @usuario spameando links"""
    if not m or not motivo:
        await ctx.send(embed=_make_embed(
            "Reportar a un usuario",
            "**Uso:** `l!reportar @usuario <motivo>`\n\n"
            "El reporte le llega al staff de forma privada. Usalo con responsabilidad: "
            "los reportes falsos también quedan registrados.",
            COLOR_INFO))
        return
    if m.bot or m.id == ctx.author.id:
        await ctx.send(embed=_make_embed("Reporte inválido", "No podés reportarte a vos mismo ni a un bot.", COLOR_ADVERTENCIA))
        return

    cfg = get_config(ctx.guild.id) or {}
    cid = cfg.get("reportes_canal") or cfg.get("canal_staff") or cfg.get("canal_logs")
    canal = ctx.guild.get_channel(int(cid)) if cid else None
    if not canal or not canal.permissions_for(ctx.guild.me).send_messages:
        await ctx.send(embed=_make_error_embed(
            "Reportes no configurados", "Este servidor no tiene canal de reportes.",
            "Un admin puede configurarlo en el panel (Canales → Reportes) o con `l!setcanal staff #canal`."))
        return

    embed = discord.Embed(
        title="🚩 Reporte de usuario",
        color=discord.Color(COLOR_ADVERTENCIA),
        timestamp=datetime.datetime.now(datetime.timezone.utc),
    )
    embed.set_thumbnail(url=m.display_avatar.url)
    embed.add_field(name="Reportado", value=f"{m.mention}\n`{m} ({m.id})`", inline=True)
    embed.add_field(name="Reporta", value=f"{ctx.author.mention}\n`{ctx.author.id}`", inline=True)
    embed.add_field(name="Canal", value=ctx.channel.mention, inline=True)
    embed.add_field(name="Motivo", value=_clip_text(motivo, 1000), inline=False)
    embed.add_field(name="Acciones", value=f"`l!warn {m.id} <motivo>` · `l!casos @{m.display_name}`", inline=False)
    embed.set_footer(text=f"{ctx.guild.name} · reporte de usuario")
    try:
        await canal.send(embed=embed)
    except Exception as e:
        await ctx.send(embed=_make_error_embed("No pude enviar el reporte", _safe_exc_text(e), "Avisale al staff por otro medio."))
        return

    try:
        await ctx.message.delete()
    except Exception:
        pass
    try:
        await ctx.author.send(embed=_make_embed(
            "Reporte enviado",
            f"Tu reporte sobre **{m.display_name}** en **{ctx.guild.name}** llegó al staff. Gracias.",
            COLOR_EXITO))
    except Exception:
        await ctx.send(embed=_make_embed("Reporte enviado", "El staff ya lo tiene.", COLOR_EXITO), delete_after=8)

