@tasks.loop(hours=24)
async def chequear_cumples():
    """Felicita a los usuarios que cumplen años hoy."""
    import datetime as _dt
    hoy = _dt.date.today()
    hoy_fmt = f"{hoy.day:02d}/{hoy.month:02d}"
    datos = cargar_datos()
    for uid_str, udata in datos.get("usuarios", {}).items():
        if udata.get("cumple") == hoy_fmt:
            # Buscar en qué servers está el usuario
            uid = int(uid_str)
            for guild in bot.guilds:
                member = guild.get_member(uid)
                if not member:
                    continue
                cfg = get_config(guild.id)
                if not cfg:
                    continue
                canal_id = cfg.get("bienvenida_canal") or cfg.get("canal_general")
                if not canal_id:
                    continue
                canal = guild.get_channel(canal_id)
                if canal:
                    try:
                        embed = discord.Embed(
                            title="🎂 ¡Feliz Cumpleaños!",
                            description=f"¡Hoy es el cumpleaños de {member.mention}! 🎉\n¡Que la pases genial!",
                            color=discord.Color.from_rgb(255, 192, 203)
                        )
                        embed.set_thumbnail(url=member.display_avatar.url)
                        await canal.send(embed=embed)
                    except:
                        pass

@chequear_cumples.before_loop
async def before_cumples():
    await bot.wait_until_ready()




@bot.command()
async def status(ctx):
    """Muestra el estado del bot y los servicios externos."""
    async with ctx.typing():
        uptime_secs = int((datetime.datetime.now(datetime.timezone.utc) - BOT_STARTED_AT).total_seconds())
        lat = _bot_latency_ms()
        sqlite_stats = get_sqlite_snapshot_stats(ARCHIVO_SQLITE)

        checks = {
            "IA": "https://openrouter.ai",
            "Búsqueda": "https://serpapi.com",
            "Subida": "https://catbox.moe",
            "Imágenes": "https://nekos.best",
            "Crypto": "https://api.coingecko.com",
        }
        resultados = {}
        async with aiohttp.ClientSession() as s:
            for nombre, url in checks.items():
                try:
                    async with s.get(url, timeout=aiohttp.ClientTimeout(total=4)) as r:
                        resultados[nombre] = "🟢 Operacional" if r.status < 500 else f"🔴 Error {r.status}"
                except:
                    resultados[nombre] = "🔴 Sin respuesta"

        if lat < 0:
            lat_emoji, lat_txt = "⚪", "n/d"
        elif lat < 150:
            lat_emoji, lat_txt = "🟢", f"{lat}ms"
        elif lat < 300:
            lat_emoji, lat_txt = "🟡", f"{lat}ms"
        else:
            lat_emoji, lat_txt = "🔴", f"{lat}ms"
        embed = discord.Embed(
            title="📡 Estado de LatamBOT",
            color=discord.Color(COLOR_PRIMARIO),
            timestamp=datetime.datetime.now(datetime.timezone.utc)
        )
        embed.add_field(
            name="🤖 Bot",
            value=(
                f"{lat_emoji} Latencia: **{lat_txt}**\n"
                f"🏠 Servidores: **{len(bot.guilds)}**\n"
                f"⏱️ Uptime: **{formato_tiempo(uptime_secs)}**"
            ),
            inline=False
        )
        embed.add_field(
            name="Persistencia",
            value=(
                f"SQLite: **{sqlite_stats['servers']}** servers\n"
                f"Usuarios: **{sqlite_stats['usuarios']}**\n"
                f"Notas: **{sqlite_stats['notas']}**"
            ),
            inline=True
        )
        embed.add_field(
            name="Actividad runtime",
            value=(
                f"IA: **{runtime_metrics.get('ai_requests', 0)}**\n"
                f"Descargas: **{runtime_metrics.get('media_downloads', 0)}**\n"
                f"Tickets: **{runtime_metrics.get('tickets_created', 0)}**"
            ),
            inline=True
        )
        servicios_txt = "\n".join(f"{v} **{k}**" for k, v in resultados.items())
        embed.title = "Estado actual del bot"
        embed.description = "Resumen rapido de latencia y servicios."
        embed.add_field(name="Servicios externos", value=servicios_txt, inline=False)
        embed.set_footer(text=f"LatamBOT {BOT_VERSION} | actualizado a las {datetime.datetime.now(datetime.timezone.utc).strftime('%H:%M UTC')}")
        await ctx.send(embed=embed)



# ==============================================================================
#  MÓDULO DE MÚSICA - slash + prefix (l!play / l!search / l!skip / l!previous / l!stop)
#  Streaming via yt-dlp en la EC2. Sin proxy de la Pi.
# ==============================================================================

import yt_dlp as _yt_dlp
try:
    if not discord.opus.is_loaded():
        discord.opus.load_opus("libopus.so.0")
except Exception as _opus_exc:
    print("[MUSIC] No pude cargar libopus:", _opus_exc)
print("[MUSIC] opus_loaded=", discord.opus.is_loaded())

# Prefix viejo (l!play con _get_audio_url + proxy) no debe convivir con el módulo v2.
for _old_music in ("play", "skip", "stop", "pause", "resume", "queue", "volume", "nowplaying", "search"):
    try:
        bot.remove_command(_old_music)
    except Exception:
        pass

# Discord voice = EC2. YouTube extract/stream = proxy de la Pi (AWS está bloqueado).
_MUSIC_YTDL_OPTS: dict = {
    "format": "bestaudio/best",
    "noplaylist": True,
    "quiet": True,
    "no_warnings": True,
    "default_search": "ytsearch5",
    "extractor_args": {"youtube": {"player_client": ["android", "ios", "web"]}},
}
if YTDLP_PROXY:
    _MUSIC_YTDL_OPTS["proxy"] = YTDLP_PROXY
else:
    _MUSIC_YTDL_OPTS["source_address"] = "0.0.0.0"

_ff_before = "-reconnect 1 -reconnect_streamed 1 -reconnect_delay_max 5"
if YTDLP_PROXY:
    _ff_before = f"-http_proxy {YTDLP_PROXY} {_ff_before}"
_MUSIC_FFMPEG_OPTS: dict = {
    "before_options": _ff_before,
    "options": "-vn",
}


# ── Estado por servidor ───────────────────────────────────────────────────────

class _GuildMusicState:
    """Cola, historial y estado de reproducción para un servidor."""

    def __init__(self) -> None:
        self.queue:   deque[dict] = deque()   # canciones pendientes
        self.history: deque[dict] = deque(maxlen=50)   # canciones ya reproducidas
        self.current: Optional[dict] = None   # canción que suena ahora
        self.lock:    asyncio.Lock = asyncio.Lock()


_music_states: Dict[int, _GuildMusicState] = {}


def _get_music_state(guild_id: int) -> _GuildMusicState:
    if guild_id not in _music_states:
        _music_states[guild_id] = _GuildMusicState()
    return _music_states[guild_id]


# ── Helpers ───────────────────────────────────────────────────────────────────

def _music_entry_to_track(entry: dict) -> dict:
    webpage = entry.get("webpage_url") or entry.get("original_url") or ""
    vid = entry.get("id") or ""
    if not webpage and vid:
        webpage = f"https://www.youtube.com/watch?v={vid}"
    return {
        "url":      webpage or entry.get("url") or "",
        "title":    entry.get("title", "Sin título"),
        "uploader": entry.get("uploader") or entry.get("channel", "Desconocido"),
        "webpage":  webpage,
        "duration": entry.get("duration", 0),
        "file":     None,
    }


async def _music_fetch_one(query: str) -> Optional[dict]:
    """Busca metadatos (sin descargar). El audio se baja al reproducir."""
    loop = asyncio.get_running_loop()
    target = query if query.startswith("http") else f"ytsearch1:{query}"
    opts = dict(_MUSIC_YTDL_OPTS, default_search="ytsearch1", skip_download=True)
    try:
        with _yt_dlp.YoutubeDL(opts) as ydl:
            data = await loop.run_in_executor(
                None, lambda: ydl.extract_info(target, download=False)
            )
        if data and "entries" in data:
            entry = data["entries"][0] if data["entries"] else None
        else:
            entry = data
        if not entry:
            return None
        track = _music_entry_to_track(entry)
        print(f"[MUSIC] fetch ok title={track['title']!r} webpage={track['webpage']}")
        return track
    except Exception as exc:
        print(f"[MUSIC] _music_fetch_one error: {exc}")
        log.warning("_music_fetch_one error: %s", exc)
        return None


async def _music_search_five(query: str) -> List[dict]:
    """Devuelve hasta 5 resultados de búsqueda sin descargar audio."""
    loop = asyncio.get_running_loop()
    opts = dict(_MUSIC_YTDL_OPTS, default_search="ytsearch5")
    try:
        with _yt_dlp.YoutubeDL(opts) as ydl:
            data = await loop.run_in_executor(
                None, lambda: ydl.extract_info(f"ytsearch5:{query}", download=False)
            )
        entries = data.get("entries", []) if data else []
        results = []
        for e in entries:
            if not e:
                continue
            results.append(_music_entry_to_track(e))
        return results[:5]
    except Exception as exc:
        log.warning("_music_search_five error: %s", exc)
        return []


def _fmt_duration(secs: int) -> str:
    if not secs:
        return "?:??"
    m, s = divmod(int(secs), 60)
    h, m = divmod(m, 60)
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m}:{s:02d}"


def _music_cleanup_file(track: Optional[dict]) -> None:
    if not track:
        return
    path = track.get("file")
    if not path:
        return
    try:
        parent = os.path.dirname(path)
        if parent and os.path.isdir(parent) and os.path.basename(parent).startswith("latam_music_"):
            import shutil
            shutil.rmtree(parent, ignore_errors=True)
        elif os.path.exists(path):
            os.remove(path)
    except Exception as exc:
        print(f"[MUSIC] cleanup fail: {exc}")


def _music_download_sync(track: dict) -> Optional[str]:
    """Baja el audio por el proxy de la Pi a un archivo local en la EC2."""
    target = track.get("webpage") or track.get("url") or ""
    if not target:
        return None
    tmpdir = tempfile.mkdtemp(prefix="latam_music_")
    opts = dict(_MUSIC_YTDL_OPTS)
    opts.update({
        "outtmpl": os.path.join(tmpdir, "audio.%(ext)s"),
        "noplaylist": True,
        "quiet": True,
        "no_warnings": True,
        "noprogress": True,
        "overwrites": True,
    })
    opts.pop("default_search", None)
    opts.pop("skip_download", None)
    try:
        with _yt_dlp.YoutubeDL(opts) as ydl:
            info = ydl.extract_info(target, download=True)
            if info and info.get("entries"):
                info = info["entries"][0]
            if not info:
                return None
            filename = ydl.prepare_filename(info)
            if filename and os.path.exists(filename):
                return filename
        for name in os.listdir(tmpdir):
            return os.path.join(tmpdir, name)
        return None
    except Exception as exc:
        print(f"[MUSIC] download fail: {exc}")
        try:
            import shutil
            shutil.rmtree(tmpdir, ignore_errors=True)
        except Exception:
            pass
        return None


def _music_source_file(path: str) -> discord.FFmpegOpusAudio:
    return discord.FFmpegOpusAudio(
        path,
        options="-vn -filter:a volume=0.8",
    )


async def _music_play_next(guild: discord.Guild) -> None:
    """Descarga la siguiente canción y la reproduce desde archivo local."""
    state = _get_music_state(guild.id)
    vc: Optional[discord.VoiceClient] = guild.voice_client

    if not vc or not vc.is_connected():
        print("[MUSIC] play_next: sin voice client")
        return

    async with state.lock:
        if not state.queue:
            state.current = None
            print("[MUSIC] play_next: cola vacía")
            return
        track = state.queue.popleft()
        state.current = track

    def after_play(error):
        if error:
            print(f"[MUSIC] after error: {error}")
            log.error("Error de reproducción: %s", error)
        else:
            print(f"[MUSIC] terminó: {track.get('title')}")
        _music_cleanup_file(track)
        try:
            asyncio.run_coroutine_threadsafe(_music_play_next(guild), bot.loop)
        except Exception as exc:
            print(f"[MUSIC] after schedule fail: {exc}")

    try:
        conn = getattr(vc, "_connection", None)
        print(
            "[MUSIC] dave proto=", getattr(conn, "dave_protocol_version", None),
            "can_encrypt=", getattr(conn, "can_encrypt", None),
            "channel=", getattr(vc.channel, "name", None),
        )
        loop = asyncio.get_running_loop()
        print(f"[MUSIC] descargando {track.get('title')!r} {track.get('webpage')}")
        path = await loop.run_in_executor(None, _music_download_sync, track)
        if not path:
            print("[MUSIC] no se pudo descargar, salto")
            state.current = None
            asyncio.create_task(_music_play_next(guild))
            return
        track["file"] = path
        print(f"[MUSIC] archivo {path} size={os.path.getsize(path)}")
        if not vc.is_connected():
            print("[MUSIC] se desconectó durante la descarga")
            _music_cleanup_file(track)
            return
        if vc.is_playing() or vc.is_paused():
            vc.stop()
            await asyncio.sleep(0.4)
        source = _music_source_file(path)
        vc.play(source, after=after_play)
        state.history.append(track)
        print(f"[MUSIC] play() ok is_playing={vc.is_playing()} is_opus={source.is_opus()}")
    except Exception as exc:
        print(f"[MUSIC] _music_play_next falló: {exc}")
        log.error("_music_play_next falló: %s", exc)
        _music_cleanup_file(track)
        asyncio.create_task(_music_play_next(guild))


async def _interaction_reply(interaction: discord.Interaction, **kwargs):
    """Responde o hace followup si la interaccion ya fue diferida."""
    if interaction.response.is_done():
        return await interaction.followup.send(**kwargs)
    return await interaction.response.send_message(**kwargs)


async def _music_reply(src, **kwargs):
    """Responde igual desde Interaction (select) o Context (hybrid/prefix)."""
    if isinstance(src, discord.Interaction):
        return await _interaction_reply(src, **kwargs)
    kwargs.pop("ephemeral", None)
    return await src.send(**kwargs)


async def _music_ensure_voice(src) -> Optional[discord.VoiceClient]:
    """
    Conecta al canal de voz del usuario si no está conectado.
    Acepta Interaction (menú de búsqueda) o Context (slash/prefix hybrid).
    """
    if isinstance(src, discord.Interaction):
        member, guild = src.user, src.guild
    else:
        member, guild = src.author, src.guild
    if not isinstance(member, discord.Member) or not member.voice or not member.voice.channel:
        await _music_reply(
            src,
            embed=_make_embed("Sin canal de voz", "Tenés que estar en un canal de voz para usar este comando.", COLOR_ADVERTENCIA),
            ephemeral=True,
        )
        return None

    vc: Optional[discord.VoiceClient] = guild.voice_client if guild else None

    if vc and vc.channel != member.voice.channel:
        await vc.move_to(member.voice.channel)
    elif not vc:
        try:
            vc = await member.voice.channel.connect()
        except discord.ClientException as exc:
            await _music_reply(
                src,
                embed=_make_embed("Error de conexión", str(exc), COLOR_PELIGRO),
                ephemeral=True,
            )
            return None

    return vc


# ── Vista: menú desplegable de resultados ─────────────────────────────────────

class _MusicSearchSelect(discord.ui.Select):
    def __init__(self, results: List[dict]) -> None:
        self._results_map: Dict[str, dict] = {}
        options = []
        for i, r in enumerate(results):
            label = r["title"][:95]
            desc  = f"{r['uploader']} · {_fmt_duration(r['duration'])}"[:100]
            value = str(i)
            self._results_map[value] = r
            options.append(discord.SelectOption(label=label, description=desc, value=value))
        super().__init__(placeholder="Elegí una canción…", options=options, min_values=1, max_values=1)

    async def callback(self, interaction: discord.Interaction) -> None:
        track = self._results_map[self.values[0]]
        self.view.stop()
        self.disabled = True
        await interaction.response.defer()

        vc = await _music_ensure_voice(interaction)
        if not vc:
            return

        state = _get_music_state(interaction.guild_id)
        state.queue.append(track)

        if not vc.is_playing() and not vc.is_paused():
            await interaction.edit_original_response(
                embed=_make_embed(
                    "▶️ Reproduciendo",
                    f"**{track['title']}**\n{track['uploader']} · {_fmt_duration(track['duration'])}",
                    COLOR_EXITO,
                ),
                view=self.view,
            )
            await _music_play_next(interaction.guild)
        else:
            pos = len(state.queue)
            await interaction.edit_original_response(
                embed=_make_embed(
                    "➕ Agregado a la cola",
                    f"**{track['title']}**\n{track['uploader']} · {_fmt_duration(track['duration'])}\nPosición en cola: **#{pos}**",
                    COLOR_INFO,
                ),
                view=self.view,
            )


class _MusicSearchView(discord.ui.View):
    def __init__(self, results: List[dict]) -> None:
        super().__init__(timeout=60)
        self.add_item(_MusicSearchSelect(results))

    async def on_timeout(self) -> None:
        for item in self.children:
            item.disabled = True


# ── Slash + prefix (hybrid). Misma cola. Nunca Pi / YTDLP_PROXY. ─────────────

def _music_guild(src):
    if isinstance(src, discord.Interaction):
        return src.guild
    return src.guild


@bot.hybrid_command(name="search", description="Busca una canción en YouTube y muestra 5 resultados para elegir.")
@app_commands.describe(texto="Nombre o frase a buscar")
async def music_search(ctx: commands.Context, *, texto: str = None) -> None:
    if not texto:
        await ctx.send(embed=_make_embed("Uso", "`l!search <canción>` o `/search`", COLOR_INFO))
        return
    if ctx.interaction:
        await ctx.defer()

    results = await _music_search_five(texto)
    if not results:
        await ctx.send(
            embed=_make_embed("Sin resultados", f"No encontré nada para «{texto}».", COLOR_ADVERTENCIA)
        )
        return

    embed = _make_embed(
        "🔍 Resultados de búsqueda",
        f"Resultados para **{texto}** - elegí una canción del menú:",
        COLOR_INFO,
    )
    for i, r in enumerate(results, 1):
        embed.add_field(
            name=f"{i}. {r['title'][:60]}",
            value=f"{r['uploader']} · {_fmt_duration(r['duration'])}",
            inline=False,
        )

    view = _MusicSearchView(results)
    await ctx.send(embed=embed, view=view)


@bot.hybrid_command(name="play", aliases=["p", "reproducir"], description="Reproduce una canción (URL o búsqueda).")
@app_commands.describe(texto="URL de YouTube o texto a buscar")
async def music_play(ctx: commands.Context, *, texto: str = None) -> None:
    if not texto:
        await ctx.send(embed=_make_embed("Uso", "`l!play <canción o URL>` o `/play`", COLOR_INFO))
        return
    if ctx.interaction:
        await ctx.defer()

    vc = await _music_ensure_voice(ctx)
    if not vc:
        return

    track = await _music_fetch_one(texto)
    if not track:
        await ctx.send(
            embed=_make_embed("Sin resultados", f"No encontré nada para «{texto}».", COLOR_ADVERTENCIA)
        )
        return

    guild = _music_guild(ctx)
    state = _get_music_state(guild.id)
    state.queue.append(track)

    if not vc.is_playing() and not vc.is_paused():
        await ctx.send(
            embed=_make_embed(
                "⏳ Preparando audio",
                f"**{track['title']}**\n{track['uploader']} · {_fmt_duration(track['duration'])}\nDescargando por la Pi y después suena en el canal.",
                COLOR_INFO,
            )
        )
        await _music_play_next(guild)
    else:
        pos = len(state.queue)
        await ctx.send(
            embed=_make_embed(
                "➕ Agregado a la cola",
                f"**{track['title']}**\n{track['uploader']} · {_fmt_duration(track['duration'])}\nPosición en cola: **#{pos}**",
                COLOR_INFO,
            )
        )


@bot.hybrid_command(name="skip", aliases=["saltar"], description="Salta a la siguiente canción en la cola.")
async def music_skip(ctx: commands.Context) -> None:
    guild = _music_guild(ctx)
    vc: Optional[discord.VoiceClient] = guild.voice_client if guild else None

    if not vc or not vc.is_connected():
        await ctx.send(
            embed=_make_embed("Sin música", "El bot no está reproduciendo nada.", COLOR_ADVERTENCIA),
            ephemeral=True,
        )
        return

    state = _get_music_state(guild.id)

    if not vc.is_playing() and not vc.is_paused():
        await ctx.send(
            embed=_make_embed("Sin música", "No hay nada reproduciéndose.", COLOR_ADVERTENCIA),
            ephemeral=True,
        )
        return

    if not state.queue:
        await ctx.send(
            embed=_make_embed("Cola vacía", "No hay más canciones en la cola. Usá `l!stop` o `/stop` para desconectar.", COLOR_INFO),
            ephemeral=True,
        )
        vc.stop()
        return

    next_track = state.queue[0]
    vc.stop()

    await ctx.send(
        embed=_make_embed(
            "⏭️ Saltando",
            f"Siguiente: **{next_track['title']}**\n{next_track['uploader']} · {_fmt_duration(next_track['duration'])}",
            COLOR_INFO,
        )
    )


@bot.hybrid_command(name="previous", aliases=["prev"], description="Vuelve a reproducir la canción anterior del historial.")
async def music_previous(ctx: commands.Context) -> None:
    if ctx.interaction:
        await ctx.defer()
    vc = await _music_ensure_voice(ctx)
    if not vc:
        return

    guild = _music_guild(ctx)
    state = _get_music_state(guild.id)

    if len(state.history) < 2:
        await ctx.send(
            embed=_make_embed("Sin historial", "No hay canciones anteriores en el historial.", COLOR_ADVERTENCIA),
            ephemeral=True,
        )
        return

    prev_track = state.history[-2]
    state.queue.appendleft(prev_track)

    if vc.is_playing() or vc.is_paused():
        vc.stop()
    else:
        await _music_play_next(guild)

    await ctx.send(
        embed=_make_embed(
            "⏮️ Volviendo",
            f"**{prev_track['title']}**\n{prev_track['uploader']} · {_fmt_duration(prev_track['duration'])}",
            COLOR_EXITO,
        )
    )


@bot.hybrid_command(name="stop", aliases=["parar"], description="Detiene la música, limpia la cola y desconecta al bot.")
async def music_stop(ctx: commands.Context) -> None:
    guild = _music_guild(ctx)
    vc: Optional[discord.VoiceClient] = guild.voice_client if guild else None

    if not vc or not vc.is_connected():
        await ctx.send(
            embed=_make_embed("Sin conexión", "El bot no está en ningún canal de voz.", COLOR_ADVERTENCIA),
            ephemeral=True,
        )
        return

    state = _get_music_state(guild.id)
    state.queue.clear()
    state.current = None

    if vc.is_playing() or vc.is_paused():
        vc.stop()

    await vc.disconnect()

    await ctx.send(
        embed=_make_embed("⏹️ Detenido", "Música detenida, cola limpiada y bot desconectado.", COLOR_EXITO)
    )

