@bot.command(name="purge")
@commands.check(es_staff)
async def purge_v2(ctx, cantidad: int = 10, *, filtro: str = ""):
    if cantidad < 1 or cantidad > 200:
        await ctx.send(embed=_make_error_embed("Cantidad invalida", "Solo puedo borrar entre 1 y 200 mensajes.", "Usa algo como `l!purge 20` o `l!purge 50 links`."))
        return
    filtro = (filtro or "").strip().lower()
    aliases = {"bot": "bot", "bots": "bot", "link": "links", "links": "links", "image": "images", "images": "images", "img": "images", "embed": "embeds", "embeds": "embeds", "human": "human", "humans": "human", "dup": "duplicados", "dups": "duplicados", "duplicados": "duplicados", "duplicates": "duplicados", "repetidos": "duplicados"}
    filtro = aliases.get(filtro, filtro)
    if filtro and filtro not in {"bot", "links", "images", "embeds", "human", "duplicados"}:
        await ctx.send(embed=_make_error_embed("Filtro invalido", f"No reconozco el filtro `{filtro}`.", "Filtros validos: `bot`, `links`, `images`, `embeds`, `human`, `duplicados`."))
        return

    _vistos = set()

    def match_filter(message: discord.Message) -> bool:
        if message.id == ctx.message.id:
            return True
        if not filtro:
            return True
        if filtro == "bot":
            return message.author.bot
        if filtro == "links":
            contenido = (message.content or "").lower()
            return "http://" in contenido or "https://" in contenido
        if filtro == "images":
            return bool(message.attachments) and any((a.content_type or "").startswith("image/") for a in message.attachments)
        if filtro == "embeds":
            return bool(message.embeds)
        if filtro == "duplicados":
            # Borra las repeticiones y deja el primero de cada mensaje igual (mismo autor + mismo texto).
            texto = (message.content or "").strip().lower()
            if not texto:
                return False
            clave = (message.author.id, texto)
            if clave in _vistos:
                return True
            _vistos.add(clave)
            return False
        return not message.author.bot

    try:
        deleted = await ctx.channel.purge(limit=cantidad + 1, check=match_filter)
        deleted_count = sum(1 for message in deleted if message.id != ctx.message.id)
        descripcion = f"Elimine **{deleted_count}** mensaje(s)."
        if filtro:
            descripcion += f"\nFiltro aplicado: `{filtro}`."
        await ctx.send(embed=_make_embed("Purge completado", descripcion, COLOR_EXITO), delete_after=5)
        await _log_staff_action(ctx.guild, title="Purge ejecutado", color=COLOR_ADVERTENCIA, actor=ctx.author, reason=f"cantidad={cantidad} filtro={filtro or 'sin filtro'}", fields=[("Canal", ctx.channel.mention, True), ("Mensajes eliminados", str(deleted_count), True)], notify_owner=True, tag="PURGE")
    except Exception as e:
        await ctx.send(embed=_make_error_embed("No pude borrar mensajes", _safe_exc_text(e), _exception_fix_hint(e)))


