# Prefijo /imagen lo registra el hybrid mas arriba; este duplicado no se registra.
async def imagen_v2(ctx, *, query: str):
    if not SERPAPI_KEY or SERPAPI_KEY.startswith("PON_"):
        await ctx.send(embed=_make_error_embed("Busqueda de imagenes no disponible", "La integracion de imagenes no esta configurada.", "Revisa la clave de SerpAPI del bot."))
        return
    uid_imagen = ctx.author.id
    vip_imagen = es_kofi(uid_imagen)
    limite_serpapi = get_limites(uid_imagen)[2]
    hoy_imagen = datetime.date.today().isoformat()
    if uid_imagen not in serpapi_usos_diarios or serpapi_usos_diarios[uid_imagen].get("fecha") != hoy_imagen:
        serpapi_usos_diarios[uid_imagen] = {"count": 0, "fecha": hoy_imagen}
    if serpapi_usos_diarios[uid_imagen]["count"] >= limite_serpapi:
        embed_slm = discord.Embed(title="Limite de imagenes alcanzado", description=f"Usaste **{serpapi_usos_diarios[uid_imagen]['count']}/{limite_serpapi}** busquedas de imagenes hoy.\nEl limite se reinicia a medianoche.", color=discord.Color(COLOR_ADVERTENCIA))
        await ctx.send(embed=embed_slm)
        return
    serpapi_usos_diarios[uid_imagen]["count"] += 1
    import re as _re
    serp = _get_serpapi_user_settings(uid_imagen, ctx.guild.id if ctx.guild else None)
    nsfw_srv = serp["safe"] == "off"
    params = {"engine": "google_images", "q": query, "hl": serp["hl"], "gl": serp["gl"], "safe": serp["safe"]}
    color_m = _re.search(r"-color:(\w+)", query)
    tipo_m = _re.search(r"-tipo:(\w+)", query)
    size_m = _re.search(r"-tama[ñn]o:(\w+)", query)
    if color_m:
        params["image_color"] = color_m.group(1)
        params["q"] = params["q"].replace(color_m.group(0), "").strip()
    if tipo_m:
        params["image_type"] = tipo_m.group(1)
        params["q"] = params["q"].replace(tipo_m.group(0), "").strip()
    if size_m:
        params["imgsz"] = size_m.group(1)
        params["q"] = params["q"].replace(size_m.group(0), "").strip()
    async with ctx.typing():
        data = await _serpapi_request(params)
        if not data or data.get("_error"):
            await ctx.send(embed=_make_error_embed("Busqueda de imagenes no disponible", (data or {}).get("_message", "No pude obtener imagenes."), "Espera un momento y vuelve a probar. Si hubo 429, deja pasar un rato."))
            return
        imgs = data.get("images_results", [])
        if not imgs:
            await ctx.send(embed=_make_error_embed("Sin imagenes", f"No encontre imagenes para `{params['q']}`.", "Prueba con otra palabra o quita filtros."))
            return
        img = imgs[0]
        embed = discord.Embed(title=f"Imagen: {params['q'][:60]}", color=discord.Color(COLOR_PRIMARIO))
        embed.set_image(url=img.get("original", img.get("thumbnail", "")))
        titulo_img = img.get("title", "")[:100]
        fuente = img.get("source", "")
        if titulo_img:
            embed.description = titulo_img
        footer = f"Fuente: {fuente}" if fuente else "Busqueda de imagenes"
        if not nsfw_srv:
            footer += " | SafeSearch activo"
        embed.set_footer(text=footer[:2048])
        await ctx.send(embed=embed, view=ImagenSearchView(imgs[:10], params["q"], nsfw_srv))


@bot.event
async def on_command_error(ctx, error):
    _metric_bump("command_failures")
    try:
        if ctx.message:
            _cmd_invocation_audit.pop(ctx.message.id, None)
    except Exception:
        pass
    original_error = getattr(error, "original", error)

    async def _err(title, desc, color=discord.Color.red(), solution=None):
        try:
            await ctx.send(embed=_make_error_embed(title, desc, solution or "", color=color), delete_after=15)
        except Exception:
            pass

    if isinstance(error, commands.CommandNotFound):
        return
    if isinstance(error, commands.CheckFailure):
        await _err("Sin permisos", "No tienes permisos para usar este comando.", discord.Color.orange())
        return
    if isinstance(error, commands.MissingRequiredArgument):
        cfg = get_config(ctx.guild.id) or {}
        prefix = cfg.get("prefix", "l!")
        await _err("Argumento faltante", f"Falta el argumento `{error.param.name}`.", discord.Color.orange(), f"Usa `{prefix}help {ctx.command}` para ver el formato.")
        return
    if isinstance(error, commands.BadArgument):
        await _err("Argumento invalido", "Uno de los datos enviados no tiene el formato esperado.", discord.Color.orange(), "Revisa menciones, IDs y tiempos.")
        return
    if isinstance(error, commands.MemberNotFound):
        await _err("Usuario no encontrado", f"No encontre a `{error.argument}` en este servidor.", discord.Color.orange(), "Prueba con una mencion o un ID valido.")
        return
    if isinstance(error, commands.CommandOnCooldown):
        await _err("Comando en espera", f"Vuelve a intentarlo en **{error.retry_after:.1f}s**.", discord.Color.orange())
        return
    if isinstance(error, commands.MissingPermissions):
        perms = ", ".join(f"`{p.replace('_', ' ').title()}`" for p in error.missing_permissions)
        await _err("Permisos insuficientes", f"No tienes permisos para usar `{ctx.command}`.\nFaltan: {perms}", discord.Color.orange(), "Pide esos permisos a un admin.")
        return
    if isinstance(error, commands.BotMissingPermissions):
        perms = ", ".join(f"`{p.replace('_', ' ').title()}`" for p in error.missing_permissions)
        await _err("Permisos faltantes del bot", f"No puedo ejecutar `{ctx.command}`.\nFaltan: {perms}", discord.Color.orange(), "Activa esos permisos en el rol o canal del bot.")
        return
    if isinstance(error, commands.NoPrivateMessage):
        await _err("Solo en servidores", "Este comando no se puede usar por mensaje privado.", discord.Color.orange())
        return
    if isinstance(error, commands.DisabledCommand):
        await _err("Comando desactivado", f"El comando `{ctx.command}` esta desactivado en este servidor.", discord.Color.orange())
        return
    if isinstance(original_error, discord.Forbidden):
        await _err("Accion denegada", "Discord rechazo la accion por permisos o jerarquia.", discord.Color.red(), _exception_fix_hint(original_error))
        return
    if isinstance(original_error, asyncio.TimeoutError):
        await _err("Tiempo agotado", "La accion o el servicio externo tardaron demasiado.", discord.Color.orange(), _exception_fix_hint(original_error))
        return
    if isinstance(original_error, aiohttp.ClientError):
        await _err("Error de red", f"No pude completar la conexion externa.\n`{_safe_exc_text(original_error)}`", discord.Color.orange(), _exception_fix_hint(original_error))
        return
    if isinstance(original_error, discord.HTTPException):
        await _err("Error de Discord", f"Discord devolvio un error al completar el comando.\n`{_safe_exc_text(original_error)}`", discord.Color.orange(), _exception_fix_hint(original_error))
        return
    tb_str = traceback.format_exc()
    print(f"[ERROR] {ctx.command}: {original_error}")
    print(tb_str)
    await _err("Error interno", "Paso algo que no estaba previsto. Intenta otra vez en unos segundos.", discord.Color.red())
    asyncio.create_task(_notificar_error_critico(ctx, original_error, tb_str))

try:
    if not TOKEN_DISCORD:
        raise SystemExit(
            "[CONFIG] Falta DISCORD_TOKEN. Copia .env.example a .env y definí el token del bot."
        )
    bot.run(TOKEN_DISCORD)
except discord.LoginFailure:
    print("TOKEN INVALIDO.")
except KeyboardInterrupt:
    print("Bot detenido manualmente.")
except Exception as e:
    print(f"Error fatal: {e}")
    print(traceback.format_exc())
